import React, { useState, useEffect } from 'react';
import { CampaignService } from '../../services/CampaignService';
import { CharacterSyncService, SyncedCharacter } from '../../services/CharacterSyncService';
import { CharacterSheetData } from '../../types/character';
import { RulesData } from '../../types/rules';
import { useCampaignLabels } from '../hooks/useCampaignLabels';
import { useNotification } from '../../context/NotificationContext';
import ImportWizardModal from '../components/import-wizard/ImportWizardModal';
import { ImageSyncResolver } from '../../services/ImageSyncResolver';
import { logger } from '../../utils/logger';

// Sub Components
import { ReadOnlyHeader } from './readonly/ReadOnlyHeader';
import { ReadOnlyIdentity } from './readonly/ReadOnlyIdentity';
import { ReadOnlySuggestions } from './readonly/ReadOnlySuggestions';
import ThematicModal from '../../components/ui/ThematicModal';
import { RefreshCw } from 'lucide-react';
import { ReadOnlyAttributes } from './readonly/ReadOnlyAttributes';
import { ReadOnlySkills } from './readonly/ReadOnlySkills';
import { ReadOnlyBackgrounds } from './readonly/ReadOnlyBackgrounds';
import { ReadOnlyTraits } from './readonly/ReadOnlyTraits';
import { ReadOnlyExperience } from './readonly/ReadOnlyExperience';
import { ReadOnlyInventory } from './readonly/ReadOnlyInventory';
import { ReadOnlyPortrait } from './readonly/ReadOnlyPortrait';

interface CharacterReadOnlyViewProps {
    character: SyncedCharacter;
    onClose: () => void;
    onRefreshRules?: () => void;
    allowForceUpdate?: boolean;
}

const CharacterReadOnlyView: React.FC<CharacterReadOnlyViewProps> = ({
    character,
    onClose,
    onRefreshRules,
    allowForceUpdate = false
}) => {
    const addLog = useNotification();
    const { getCategoryLabel } = useCampaignLabels(character.setting_id || undefined);

    const [isWizardOpen, setIsWizardOpen] = useState(false);
    const [candidateRules, setCandidateRules] = useState<RulesData | null>(null);
    const [currentRules, setCurrentRules] = useState<RulesData | null>(null);
    const [processedData, setProcessedData] = useState<CharacterSheetData | null>(null);
    const [isUpdateModalOpen, setIsUpdateModalOpen] = useState(false);
    const [updateMessage, setUpdateMessage] = useState('');
    const [isUpdating, setIsUpdating] = useState(false);

    // Initial load with image injection
    useEffect(() => {
        const load = async () => {
            try {
                const parsed = typeof character.data === 'string'
                    ? JSON.parse(character.data)
                    : character.data;

                // Important: for Admin view, we need to inject images from compressed strings to local IDs
                const injected = await ImageSyncResolver.injectImagesAfterSync(parsed);
                setProcessedData(injected as CharacterSheetData);
            } catch (e) {
                logger.error("Failed to parse and inject character data", e);
                if (typeof character.data !== 'string') {
                    setProcessedData(character.data);
                }
            }
        };
        load();
    }, [character]);

    const handleImport = async () => {
        if (!processedData || !character.setting_id) return;

        try {
            const rules = await CampaignService.loadSetting(character.setting_id);
            if (!rules) {
                addLog("Impossible de récupérer les règles de la campagne.", "danger");
                return;
            }

            const { extractRulesFromCharacter } = await import('../utils/templateImporter');
            const { rules: extracted } = extractRulesFromCharacter(processedData, rules);

            setCandidateRules(extracted);
            setCurrentRules(rules);
            setIsWizardOpen(true);
        } catch (err) {
            addLog("Erreur lors de l'import : " + (err as Error).message, "danger");
        }
    };

    const handleForceMJUpdate = async () => {
        setIsUpdateModalOpen(true);
        setUpdateMessage('');
    };

    const confirmForceMJUpdate = async () => {
        if (!character.id) return;
        setIsUpdating(true);
        try {
            const success = await CharacterSyncService.requestForceUpdate(character.id, updateMessage);
            if (success) {
                addLog("Signal de mise à jour envoyé au joueur.", "success");
                setIsUpdateModalOpen(false);
            } else {
                addLog("Échec de l'envoi du signal.", "danger");
            }
        } catch (err) {
            addLog("Erreur technique : " + (err as Error).message, "danger");
        } finally {
            setIsUpdating(false);
        }
    };

    if (!processedData) {
        return (
            <div className="flex flex-col items-center justify-center p-20 text-stone-500 italic bg-stone-900 h-screen">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-amber-500 mb-4"></div>
                Exhumation des manuscrits...
            </div>
        );
    }

    return (
        <div className="fixed inset-0 z-50 flex flex-col bg-stone-900 overflow-hidden shadow-2xl">
            <ReadOnlyHeader
                character={character}
                onClose={onClose}
                onImport={handleImport}
                onForceUpdate={allowForceUpdate ? handleForceMJUpdate : undefined}
            />

            <div className="flex-grow overflow-y-auto custom-scrollbar p-8">
                <div className="max-w-7xl mx-auto space-y-12 pb-20">
                    {/* Top Section: Portrait + Identity */}
                    <div className="flex flex-col md:flex-row gap-8 items-start">
                        <ReadOnlyPortrait
                            imageId={processedData.page2?.characterImageId}
                            legacyImage={processedData.page2?.characterImage}
                        />
                        <div className="flex-grow space-y-8 w-full">
                            <ReadOnlyIdentity header={processedData.header} />
                            <ReadOnlySuggestions suggestions={processedData.suggestions} getCategoryLabel={getCategoryLabel} />
                        </div>
                    </div>

                    <ReadOnlyAttributes
                        attributeSettings={processedData.attributeSettings}
                        attributes={processedData.attributes}
                    />

                    <ReadOnlySkills
                        skills={processedData.skills}
                        specializations={processedData.specializations}
                        imposedSpecializations={processedData.imposedSpecializations}
                        getCategoryLabel={getCategoryLabel}
                    />

                    <ReadOnlyBackgrounds
                        skills={processedData.skills}
                        specializations={processedData.specializations}
                        imposedSpecializations={processedData.imposedSpecializations}
                    />

                    <ReadOnlyTraits
                        avantages={processedData.page2?.avantages}
                        desavantages={processedData.page2?.desavantages}
                    />

                    <ReadOnlyExperience
                        experience={processedData.experience}
                    />

                    <ReadOnlyInventory
                        inventory={processedData.page2?.equipement}
                    />

                    <div className="text-center pt-8 border-t border-stone-800 opacity-20">
                        <p className="text-[9px] font-bold text-stone-500 uppercase tracking-[0.5em]">
                            Archives Scellées — Fin de la Chronique
                        </p>
                    </div>
                </div>
            </div>

            {isWizardOpen && candidateRules && currentRules && character.setting_id && (
                <ImportWizardModal
                    isOpen={isWizardOpen}
                    onClose={() => setIsWizardOpen(false)}
                    currentRules={currentRules}
                    candidateRules={candidateRules}
                    onConfirm={async (merged: RulesData) => {
                        try {
                            await CampaignService.saveSetting(character.setting_id!, merged);
                            addLog("Bibliothèque de campagne mise à jour avec succès !", "success");
                            setIsWizardOpen(false);
                            onRefreshRules?.();
                        } catch (err) {
                            addLog("Échec de la mise à jour : " + (err as Error).message, "danger");
                        }
                    }}
                />
            )}

            <ThematicModal
                isOpen={isUpdateModalOpen}
                onClose={() => setIsUpdateModalOpen(false)}
                title="Pousser Mise à Jour MJ"
                scheme="mystic"
                icon={<RefreshCw size={24} />}
                footer={
                    <div className="flex gap-3 w-full justify-end">
                        <button
                            onClick={() => setIsUpdateModalOpen(false)}
                            className="px-4 py-2 text-stone-500 hover:text-stone-300 hover:bg-stone-800 rounded-sm font-bold transition-all uppercase text-xs tracking-wider"
                        >
                            Abjurer
                        </button>
                        <button
                            onClick={confirmForceMJUpdate}
                            disabled={isUpdating}
                            className="px-6 py-2 bg-amber-600 hover:bg-amber-500 text-stone-950 rounded-sm font-bold transition-all shadow-lg active:scale-95 uppercase tracking-wider text-xs disabled:opacity-50"
                        >
                            {isUpdating ? "Incantation..." : "Envoyer le Signal"}
                        </button>
                    </div>
                }
            >
                <div className="space-y-4">
                    <p className="text-stone-400 text-xs italic leading-relaxed">
                        Le voyageur <strong>{character.character_name}</strong> recevra votre message et une invitation à synchroniser ses archives lors de sa prochaine connexion.
                    </p>

                    <div>
                        <label className="block text-[10px] font-black uppercase tracking-[0.2em] text-amber-900/80 mb-2">
                            Message du Gardien (Optionnel)
                        </label>
                        <textarea
                            value={updateMessage}
                            onChange={(e) => setUpdateMessage(e.target.value)}
                            placeholder="Ex: J'ai rectifié tes points de santé..."
                            className="w-full h-32 bg-stone-900/50 border border-stone-800 rounded-sm p-3 text-sm text-stone-200 focus:border-amber-900/50 outline-none resize-none transition-all placeholder:text-stone-700"
                        />
                    </div>
                </div>
            </ThematicModal>
        </div>
    );
};

export default CharacterReadOnlyView;

import React, { useState } from 'react';
import { CalendarConfigFictional, CalendarEvent, CalendarMonthDef, CalendarSeason } from '../../../types/rules';

import CalendarEventsList from './CalendarEventsList';
import { PlusCircle, Trash2, ChevronDown, ChevronUp } from 'lucide-react';

interface Props {
    config: CalendarConfigFictional;
    onUpdate: (config: CalendarConfigFictional) => void;
}

const DEFAULT_DAY_NAMES = ['Lundi', 'Mardi', 'Mercredi', 'Jeudi', 'Vendredi', 'Samedi', 'Dimanche'];
const SEASON_COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#a855f7', '#f97316'];

const FictionalCalendarConfig: React.FC<Props> = ({ config, onUpdate }) => {
    const [seasonsOpen, setSeasonsOpen] = useState(false);

    // --- Mois ---
    const updateMonth = (i: number, patch: Partial<CalendarMonthDef>) => {
        const months = config.months.map((m: CalendarMonthDef, idx: number) => idx === i ? { ...m, ...patch } : m);
        onUpdate({ ...config, months });
    };
    const addMonth = () => {
        onUpdate({ ...config, months: [...config.months, { name: `Mois ${config.months.length + 1}`, days: 30 }] });
    };
    const removeMonth = (i: number) => {
        const months = config.months.filter((_: CalendarMonthDef, idx: number) => idx !== i);
        const seasons = config.seasons.map((s: CalendarSeason) => ({
            ...s,
            monthIndices: s.monthIndices.filter((mi: number) => mi !== i).map((mi: number) => mi > i ? mi - 1 : mi)
        }));
        onUpdate({
            ...config,
            months,
            seasons,
            currentMonthIndex: Math.min(config.currentMonthIndex, months.length - 1)
        });
    };

    // --- Jours de la semaine ---
    const updateDayName = (i: number, name: string) => {
        const dayNames = config.dayNames.map((d: string, idx: number) => idx === i ? name : d);
        onUpdate({ ...config, dayNames });
    };
    const addDay = () => {
        onUpdate({ ...config, dayNames: [...config.dayNames, `Jour ${config.dayNames.length + 1}`] });
    };
    const removeDay = (i: number) => {
        onUpdate({ ...config, dayNames: config.dayNames.filter((_: string, idx: number) => idx !== i) });
    };

    // --- Saisons ---
    const addSeason = () => {
        const s: CalendarSeason = {
            id: crypto.randomUUID(),
            name: `Saison ${config.seasons.length + 1}`,
            monthIndices: [],
            color: SEASON_COLORS[config.seasons.length % SEASON_COLORS.length]
        };
        onUpdate({ ...config, seasons: [...config.seasons, s] });
    };
    const updateSeason = (id: string, patch: Partial<CalendarSeason>) => {
        onUpdate({ ...config, seasons: config.seasons.map((s: CalendarSeason) => s.id === id ? { ...s, ...patch } : s) });
    };
    const removeSeason = (id: string) => {
        onUpdate({ ...config, seasons: config.seasons.filter((s: CalendarSeason) => s.id !== id) });
    };
    const toggleSeasonMonth = (seasonId: string, monthIdx: number) => {
        const season = config.seasons.find((s: CalendarSeason) => s.id === seasonId)!;
        const monthIndices = season.monthIndices.includes(monthIdx)
            ? season.monthIndices.filter((i: number) => i !== monthIdx)
            : [...season.monthIndices, monthIdx].sort((a, b) => a - b);
        updateSeason(seasonId, { monthIndices });
    };

    // --- Navigation Temporelle ---
    const advanceOneDay = () => {
        let { currentDay, currentMonthIndex, currentYear } = config;
        const currentMonthDays = config.months[currentMonthIndex]?.days ?? 30;

        currentDay++;
        if (currentDay > currentMonthDays) {
            currentDay = 1;
            currentMonthIndex++;
            if (currentMonthIndex >= config.months.length) {
                currentMonthIndex = 0;
                currentYear++;
            }
        }

        onUpdate({
            ...config,
            currentDay,
            currentMonthIndex,
            currentYear
        });
    };

    const inputCls = 'bg-stone-800 border border-stone-600 rounded-sm px-2 py-1 text-sm text-stone-200 focus:outline-none focus:border-amber-gold/60 transition-colors w-full';
    const labelCls = 'block text-xs font-bold text-stone-400 uppercase tracking-wider mb-2';

    return (
        <div className="space-y-8">
            {/* Dates courantes */}
            <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 bg-mystic-deep/30 p-4 rounded-sm border border-stone-700/30">
                <div>
                    <label htmlFor="cal-start-year" className={labelCls}>Année de départ</label>
                    <input id="cal-start-year" type="number" value={config.startYear} onChange={e => onUpdate({ ...config, startYear: Number(e.target.value) })} className={inputCls} />
                </div>
                <div>
                    <label htmlFor="cal-current-year" className={labelCls}>Année courante</label>
                    <input id="cal-current-year" type="number" value={config.currentYear} onChange={e => onUpdate({ ...config, currentYear: Number(e.target.value) })} className={inputCls} />
                </div>
                <div>
                    <label htmlFor="cal-current-month" className={labelCls}>Mois courant</label>
                    <select id="cal-current-month" value={config.currentMonthIndex} onChange={e => onUpdate({ ...config, currentMonthIndex: Number(e.target.value) })} className={inputCls}>
                        {config.months.map((m: CalendarMonthDef, i: number) => <option key={i} value={i}>{m.name}</option>)}
                    </select>
                </div>
                <div>
                    <label htmlFor="cal-current-day" className={labelCls}>Jour courant</label>
                    <div className="flex gap-2">
                        <input
                            id="cal-current-day"
                            type="number"
                            min={1}
                            max={config.months[config.currentMonthIndex]?.days ?? 30}
                            value={config.currentDay}
                            onChange={e => onUpdate({ ...config, currentDay: Number(e.target.value) })}
                            className={inputCls}
                        />
                        <button
                            onClick={advanceOneDay}
                            className="flex-shrink-0 px-3 flex items-center justify-center bg-amber-gold text-stone-900 rounded-sm hover:bg-amber-400 transition-colors shadow-glow-gold/20"
                            title="Passer au jour suivant"
                        >
                            <span className="font-bold text-xs uppercase tracking-tighter transition-all">+1J</span>
                        </button>
                    </div>
                </div>
            </div>

            {/* Mois */}
            <div>
                <span className={labelCls}>Mois de l'année ({config.months.length})</span>
                <div className="space-y-2 max-h-56 overflow-y-auto pr-1">
                    {config.months.map((m: CalendarMonthDef, i: number) => (
                        <div key={i} className="flex items-center gap-2">
                            <span className="text-stone-600 text-xs w-5 text-right flex-shrink-0">{i + 1}.</span>
                            <input
                                value={m.name}
                                onChange={e => updateMonth(i, { name: e.target.value })}
                                placeholder={`Mois ${i + 1}`}
                                className="bg-stone-800 border border-stone-600 rounded-sm px-2 py-1 text-xs text-stone-200 flex-1 focus:outline-none focus:border-amber-gold/60"
                            />
                            <input
                                type="number"
                                min={1}
                                max={999}
                                value={m.days}
                                onChange={e => updateMonth(i, { days: Number(e.target.value) })}
                                className="bg-stone-800 border border-stone-600 rounded-sm px-2 py-1 text-xs text-stone-200 w-20 focus:outline-none focus:border-amber-gold/60 text-center"
                                title="Nombre de jours"
                            />
                            <span className="text-stone-600 text-xs">j.</span>
                            <button onClick={() => removeMonth(i)} className="text-stone-600 hover:text-rose-500 transition-colors flex-shrink-0">
                                <Trash2 size={13} />
                            </button>
                        </div>
                    ))}
                </div>
                <button onClick={addMonth} className="flex items-center gap-1.5 text-xs text-stone-500 hover:text-amber-400 mt-2 transition-colors">
                    <PlusCircle size={13} /> Ajouter un mois
                </button>
            </div>

            {/* Jours de la semaine */}
            <div>
                <span className={labelCls}>Jours de la semaine ({config.dayNames.length})</span>
                <div className="flex flex-wrap gap-2">
                    {config.dayNames.map((d: string, i: number) => (
                        <div key={i} className="flex items-center gap-1 bg-stone-800 border border-stone-700 rounded-sm px-2 py-1">
                            <input
                                value={d}
                                onChange={e => updateDayName(i, e.target.value)}
                                className="bg-transparent text-xs text-stone-200 w-20 focus:outline-none"
                            />
                            <button onClick={() => removeDay(i)} className="text-stone-600 hover:text-rose-500 transition-colors">
                                <Trash2 size={11} />
                            </button>
                        </div>
                    ))}
                    <button onClick={addDay} className="flex items-center gap-1 text-xs text-stone-500 hover:text-amber-400 transition-colors px-2 py-1 border border-dashed border-stone-700 rounded-sm hover:border-amber-gold/40">
                        <PlusCircle size={12} /> Ajouter
                    </button>
                </div>
            </div>

            {/* Saisons */}
            <div className="border border-stone-700/50 rounded-sm overflow-hidden">
                <button
                    onClick={() => setSeasonsOpen(o => !o)}
                    className="w-full flex items-center justify-between px-4 py-3 bg-stone-800/50 hover:bg-stone-800 transition-colors"
                >
                    <span className="text-xs font-bold text-stone-300 uppercase tracking-wider">
                        Saisons ({config.seasons.length})
                    </span>
                    {seasonsOpen ? <ChevronUp size={15} className="text-stone-500" /> : <ChevronDown size={15} className="text-stone-500" />}
                </button>
                {seasonsOpen && (
                    <div className="p-4 space-y-4">
                        {config.seasons.map((season: CalendarSeason) => (
                            <div key={season.id} className="bg-mystic-deep/60 border border-stone-700/50 rounded-sm p-3 space-y-3">
                                <div className="flex items-center gap-2">
                                    <div
                                        className="w-4 h-4 rounded-full border-2 border-stone-600 flex-shrink-0 cursor-pointer"
                                        style={{ backgroundColor: season.color }}
                                        onClick={() => {
                                            const idx = SEASON_COLORS.indexOf(season.color ?? SEASON_COLORS[0]);
                                            updateSeason(season.id, { color: SEASON_COLORS[(idx + 1) % SEASON_COLORS.length] });
                                        }}
                                        title="Cliquer pour changer la couleur"
                                    />
                                    <input
                                        value={season.name}
                                        onChange={e => updateSeason(season.id, { name: e.target.value })}
                                        className="flex-1 bg-stone-800 border border-stone-600 rounded-sm px-2 py-1 text-xs text-stone-200 focus:outline-none focus:border-amber-gold/60"
                                        placeholder="Nom de la saison"
                                    />
                                    <button onClick={() => removeSeason(season.id)} className="text-stone-600 hover:text-rose-500 transition-colors">
                                        <Trash2 size={13} />
                                    </button>
                                </div>
                                <div className="flex flex-wrap gap-1.5">
                                    {config.months.map((m: CalendarMonthDef, i: number) => (
                                        <button
                                            key={i}
                                            onClick={() => toggleSeasonMonth(season.id, i)}
                                            className={`px-2 py-0.5 text-xs rounded-sm border transition-all ${season.monthIndices.includes(i)
                                                ? 'border-transparent text-stone-900 font-bold'
                                                : 'border-stone-700 text-stone-500 hover:border-stone-500'}`}
                                            style={season.monthIndices.includes(i) ? { backgroundColor: season.color } : {}}
                                        >
                                            {m.name}
                                        </button>
                                    ))}
                                </div>
                            </div>
                        ))}
                        <button onClick={addSeason} className="flex items-center gap-1.5 text-xs text-stone-500 hover:text-amber-400 transition-colors">
                            <PlusCircle size={13} /> Ajouter une saison
                        </button>
                    </div>
                )}
            </div>

            {/* Événements */}
            <div className="border-t border-stone-700/50 pt-6">
                <CalendarEventsList
                    events={config.events}
                    mode="fictional"
                    onUpdate={(events: CalendarEvent[]) => onUpdate({ ...config, events })}
                />
            </div>
        </div>
    );
};

export { DEFAULT_DAY_NAMES };
export default FictionalCalendarConfig;

import React from 'react';
import { CalendarConfigReal } from '../../../types/rules';

import CalendarEventsList from './CalendarEventsList';
import { CalendarDays } from 'lucide-react';

interface Props {
    config: CalendarConfigReal;
    onUpdate: (config: CalendarConfigReal) => void;
}

const RealCalendarConfig: React.FC<Props> = ({ config, onUpdate }) => {
    const advance = (unit: 'day' | 'week' | 'month') => {
        const d = new Date(config.currentDate || new Date().toISOString());
        if (unit === 'day') d.setDate(d.getDate() + 1);
        else if (unit === 'week') d.setDate(d.getDate() + 7);
        else d.setMonth(d.getMonth() + 1);

        onUpdate({
            ...config,
            currentDate: d.toISOString().split('T')[0]
        });
    };

    const currentDateObj = config.currentDate ? new Date(config.currentDate) : null;
    const startDateObj = config.startDate ? new Date(config.startDate) : null;
    const diffDays = (currentDateObj && startDateObj)
        ? Math.floor((currentDateObj.getTime() - startDateObj.getTime()) / 86400000)
        : null;

    const DAY_FR = ['Dimanche', 'Lundi', 'Mardi', 'Mercredi', 'Jeudi', 'Vendredi', 'Samedi'];

    return (
        <div className="space-y-6">
            {/* Dates */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                <div>
                    <label className="block text-xs font-bold text-stone-400 uppercase tracking-wider mb-2">
                        Date de début de campagne
                    </label>
                    <input
                        type="date"
                        value={config.startDate ?? ''}
                        onChange={e => onUpdate({ ...config, startDate: e.target.value })}
                        className="w-full bg-stone-800 border border-stone-600 rounded-sm px-3 py-2 text-sm text-stone-200 focus:outline-none focus:border-amber-gold/60 transition-colors"
                    />
                    {startDateObj && (
                        <p className="text-stone-500 text-xs mt-1">
                            {DAY_FR[startDateObj.getDay()]} {startDateObj.toLocaleDateString('fr-FR', { day: 'numeric', month: 'long', year: 'numeric' })}
                        </p>
                    )}
                </div>

                <div>
                    <label className="block text-xs font-bold text-stone-400 uppercase tracking-wider mb-2">
                        Date courante (dans la fiction)
                    </label>
                    <input
                        type="date"
                        value={config.currentDate ?? ''}
                        onChange={e => onUpdate({ ...config, currentDate: e.target.value })}
                        className="w-full bg-stone-800 border border-stone-600 rounded-sm px-3 py-2 text-sm text-stone-200 focus:outline-none focus:border-amber-gold/60 transition-colors"
                    />
                    {currentDateObj && (
                        <p className="text-stone-500 text-xs mt-1 flex items-center gap-2">
                            <CalendarDays size={11} />
                            {DAY_FR[currentDateObj.getDay()]} {currentDateObj.toLocaleDateString('fr-FR', { day: 'numeric', month: 'long', year: 'numeric' })}
                            {diffDays !== null && diffDays >= 0 && (
                                <span className="text-amber-gold/70">— J+{diffDays}</span>
                            )}
                        </p>
                    )}
                </div>
            </div>

            {/* Boutons avance rapide */}
            <div>
                <span className="text-xs font-bold text-stone-400 uppercase tracking-wider">Avance rapide</span>
                <div className="flex gap-2 mt-2">
                    {(['day', 'week', 'month'] as const).map(unit => (
                        <button
                            key={unit}
                            onClick={() => advance(unit)}
                            className="px-4 py-1.5 text-xs font-bold uppercase tracking-wider bg-stone-800 hover:bg-stone-700 border border-stone-600 hover:border-amber-gold/30 text-stone-300 hover:text-amber-gold rounded-sm transition-all"
                        >
                            +1 {unit === 'day' ? 'Jour' : unit === 'week' ? 'Semaine' : 'Mois'}
                        </button>
                    ))}
                </div>
            </div>

            {/* Événements */}
            <div className="border-t border-stone-700/50 pt-6">
                <CalendarEventsList
                    events={config.events}
                    mode="real"
                    onUpdate={events => onUpdate({ ...config, events })}
                />
            </div>
        </div>
    );
};

