    previewValue,
    currentPreviewData,
    allVariables,
    realCharData,
    onEdit,
    onRemove
}) => {
    const preview = previewValue !== null ? previewValue : evaluateFormula(counter.formula || '', currentPreviewData, { entry: counter });

