                        <div>
                            <label htmlFor="mystic_other_cat" className="block text-xs font-semibold uppercase tracking-wider text-stone-500 mb-2">
                                Colonne "Habilités Mystiques"
                            </label>
                            <select
                                id="mystic_other_cat"
                                value={config?.defaultMysticOtherCategory || 'Col_Comp_5'}
                                onChange={(e) => onUpdate('defaultMysticOtherCategory', e.target.value)}
                                className="w-full bg-stone-900 border border-stone-700 rounded px-3 py-2 text-sm text-stone-200 focus:border-purple-500 outline-none font-bold"
                            >
                                {skillCategories.map(cat => (
                                    <option key={cat.id} value={cat.id}>{cat.label} ({cat.id})</option>
                                ))}
                            </select>
                            <p className="text-[10px] text-stone-500 mt-1">Où placer les autres habilités du wizard</p>
                        </div>
                    </div>

                    {/* Sync Button */}
                    <div className="pt-4 border-t border-stone-700/50">
                        <button
                            onClick={() => {
                                if (onSync) {
                                    const changed = onSync();
                                    if (changed) {
                                        alert("Synchronisation réussie ! Les Avantages correspondants ont été créés ou mis à jour.");
                                    } else {
                                        alert("Tous les Avantages sont déjà synchronisés.");
                                    }
                                }
                            }}
                            className="flex items-center gap-2 px-4 py-2 bg-purple-600/20 hover:bg-purple-600/40 text-purple-300 border border-purple-500/30 rounded text-sm font-bold transition-colors"
                        >
                            <Sparkles size={14} /> Synchroniser les Avantages manquants
                        </button>
                        <p className="text-[10px] text-stone-500 mt-2">
                            Parcourt la bibliothèque des habilités mystiques pour créer automatiquement les Avantages (Traits) liés s'ils n'existent pas encore.
                        </p>
                    </div>

                </div>
            )}
        </div>
    );
};

