    return (
        <div className="flex-grow flex flex-col p-6 overflow-hidden">
            <div className="mb-4">
                <h3 className="text-lg font-bold text-slate-800">Choisir une campagne cible</h3>
                <p className="text-sm text-slate-500">Ce personnage est un "orphelin" (sans campagne). Veuillez sélectionner la campagne où importer ses caractéristiques.</p>
            </div>

            <div className="flex-grow overflow-y-auto space-y-2 pr-2">
                {settings.length === 0 ? (
                    <div className="text-center py-10 text-slate-400">
                        <Loader2 className="animate-spin mx-auto mb-2" />
                        Chargement des campagnes...
                    </div>
                ) : (
                    settings.map((s: any) => (
                        <button
                            key={s.id}
                            onClick={() => onSelect(s.id)}
                            className="w-full p-4 rounded-xl border border-slate-200 hover:border-indigo-500 hover:bg-indigo-50 transition-all text-left flex items-center justify-between group"
                        >
                            <div>
                                <div className="font-bold text-slate-800 group-hover:text-indigo-700">{s.name}</div>
                                <div className="text-xs text-slate-400">ID: {s.id.substring(0, 8)}...</div>
                            </div>
                            <div className="opacity-0 group-hover:opacity-100 text-indigo-500 font-bold text-sm">Choisir →</div>
                        </button>
                    ))
                )}
            </div>
        </div>
    );
};

import React, { useState, useMemo } from 'react';
import { RulesData } from '../../../types/rules';
import { calculateDiff, mergeRules, ImportOptions } from '../../utils/importDiffUtils';
import { Check, X, AlertTriangle, Settings, BookOpen, Database, Layers, CheckCircle2, ChevronRight, ChevronDown, PlusCircle } from 'lucide-react';

interface ImportWizardModalProps {
    isOpen: boolean;
    onClose: () => void;
    onConfirm: (mergedRules: RulesData) => void;
    currentRules: RulesData;
    candidateRules: RulesData;
}

const ImportWizardModal: React.FC<ImportWizardModalProps> = ({ isOpen, onClose, onConfirm, currentRules, candidateRules }) => {
    if (!isOpen) return null;



    // Default Options
    const [options, setOptions] = useState<ImportOptions>({
        sections: {
            general: true,
            attributes: true,
            skills: true,
            backgrounds: true,
            counters: true,
            libraries: true
        },
        libraryStrategy: 'ignore', // Safer default
        excludedIds: []
    });

    const diff = useMemo(() => calculateDiff(currentRules, candidateRules), [currentRules, candidateRules]);

    const handleToggleSection = (key: keyof ImportOptions['sections']) => {
        setOptions(prev => ({
            ...prev,
            sections: { ...prev.sections, [key]: !prev.sections[key] }
        }));
    };

    const handleConfirm = () => {
        const merged = mergeRules(currentRules, candidateRules, options);
        onConfirm(merged);
    };

    const toggleExclusion = (id: string) => {
        setOptions(prev => {
            const excluded = prev.excludedIds || [];
            if (excluded.includes(id)) {
                return { ...prev, excludedIds: excluded.filter(x => x !== id) };
            } else {
                return { ...prev, excludedIds: [...excluded, id] };
            }
        });
    };

    const [showDetails, setShowDetails] = useState(false);

    const SectionCard = ({ id, label, icon: Icon, details }: { id: keyof ImportOptions['sections'], label: string, icon: any, details: string[] }) => {
        const hasChanges = details.length > 0;

        return (
            <div className={`border rounded-lg p-4 transition-all ${options.sections[id] ? 'bg-white border-blue-300 ring-1 ring-blue-100' : 'bg-gray-50 border-gray-200 opacity-70'}`}>
                <div className="flex items-start gap-3">
                    <input
                        type="checkbox"
                        checked={options.sections[id]}
                        onChange={() => handleToggleSection(id)}
                        className="mt-1 w-4 h-4 rounded text-blue-600 focus:ring-blue-500"
                    />
                    <div className="flex-grow">
                        <div className="flex items-center gap-2 mb-1">
                            <Icon size={18} className={options.sections[id] ? 'text-blue-600' : 'text-gray-400'} />
                            <h4 className="font-bold text-gray-900">{label}</h4>
                            {hasChanges && <span className="bg-amber-100 text-amber-800 text-[10px] px-2 py-0.5 rounded-full font-bold">Modifié</span>}
                            {!hasChanges && <span className="bg-green-50 text-green-700 text-[10px] px-2 py-0.5 rounded-full">Identique</span>}
                        </div>
                        {hasChanges && (
                            <ul className="text-xs text-gray-600 list-disc list-inside mt-2 space-y-0.5">
                                {details.slice(0, 3).map((d, i) => <li key={i}>{d}</li>)}
                                {details.length > 3 && <li className="italic">... et {details.length - 3} autres</li>}
                            </ul>
                        )}
                        {!hasChanges && <p className="text-xs text-gray-400 italic mt-1">Aucune différence détectée.</p>}
                    </div>
                </div>
            </div>
        );
    };

    return (
        <div className="fixed inset-0 bg-black/70 z-[100] flex items-center justify-center p-4 backdrop-blur-sm animate-in fade-in duration-200">
            <div className="bg-white rounded-xl shadow-2xl w-full max-w-4xl max-h-[90vh] flex flex-col overflow-hidden">

                {/* Header */}
                <div className="p-5 bg-slate-900 text-white flex justify-between items-center shrink-0">
                    <div>
                        <h2 className="text-xl font-bold flex items-center gap-2">
                            <Database className="text-blue-400" /> Assistant d'Importation
                        </h2>
                        <p className="text-slate-400 text-xs mt-1">Analysez et fusionnez les données importées avec précautions.</p>
                    </div>
                    <button onClick={onClose} className="hover:bg-white/10 p-2 rounded-full transition-colors"><X size={24} /></button>
                </div>

                {/* Body */}
                <div className="flex-grow overflow-y-auto p-6 bg-slate-50">

                    {/* Step Alerts */}
                    {!diff.hasChanges && (
                        <div className="bg-green-50 border border-green-200 rounded-lg p-4 mb-6 flex gap-3 text-green-800">
                            <CheckCircle2 className="shrink-0" />
                            <div>
                                <h4 className="font-bold">Aucune différence majeure détectée</h4>
                                <p className="text-sm">Le fichier importé semble identique à la configuration actuelle sur les points clés analysés.</p>
                            </div>
                        </div>
                    )}

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
                        <SectionCard
                            id="general"
                            label="Configuration Générale"
                            icon={Settings}
                            details={diff.details.general}
                        />
                        <SectionCard
                            id="attributes"
                            label="Attributs"
                            icon={Layers}
                            details={diff.details.attributes}
                        />
                        <SectionCard
                            id="skills"
                            label="Compétences"
                            icon={BookOpen}
                            details={diff.details.skills}
                        />
                        <SectionCard
                            id="counters"
                            label="Compteurs & Jauges"
                            icon={Settings}
                            details={diff.details.counters}
                        />
                    </div>

                    {/* Libraries Special Section */}
                    <div className="bg-white border border-slate-200 rounded-lg p-5 shadow-sm">
                        <div className="flex items-center justify-between mb-4 border-b border-slate-100 pb-3">
                            <div className="flex items-center gap-2">
                                <input
                                    type="checkbox"
                                    checked={options.sections.libraries}
                                    onChange={() => handleToggleSection('libraries')}
                                    className="w-5 h-5 rounded text-blue-600"
                                />
                                <div>
                                    <h4 className="font-bold text-lg text-slate-800 flex items-center gap-2">
                                        <BookOpen size={20} className="text-amber-600" /> Bibliothèques de Contenu
                                    </h4>
                                    <p className="text-xs text-slate-500">Traits, Compétences (Réserve), Spécialisations</p>
                                </div>
                            </div>
                        </div>

                        {options.sections.libraries && (
                            <div className="pl-8 space-y-4">
                                <div className="grid grid-cols-3 gap-4 text-center">
                                    <div className="bg-slate-50 p-3 rounded border">
                                        <div className="text-xs uppercase font-bold text-slate-500">Traits</div>
                                        <div className="font-mono text-lg font-bold text-blue-600">+{diff.details.libraries.traits.new}</div>
                                        <div className="text-[10px] text-amber-600">{diff.details.libraries.traits.conflict} conflits</div>
                                    </div>
                                    <div className="bg-slate-50 p-3 rounded border">
                                        <div className="text-xs uppercase font-bold text-slate-500">Compétences</div>
                                        <div className="font-mono text-lg font-bold text-blue-600">+{diff.details.libraries.skills.new}</div>
                                        <div className="text-[10px] text-amber-600">{diff.details.libraries.skills.conflict} conflits</div>
                                    </div>
                                    <div className="bg-slate-50 p-3 rounded border">
                                        <div className="text-xs uppercase font-bold text-slate-500">Spécialisations</div>
                                        <div className="font-mono text-lg font-bold text-blue-600">+{diff.details.libraries.specializations.new}</div>
                                        <div className="text-[10px] text-amber-600">{diff.details.libraries.specializations.conflict} conflits</div>
                                    </div>
                                </div>

                                <div className="bg-amber-50 border border-amber-200 p-4 rounded-lg">
                                    <h5 className="font-bold text-amber-900 text-sm mb-2 flex items-center gap-2">
                                        <AlertTriangle size={16} /> Stratégie en cas de conflit (Item existant)
                                    </h5>
                                    <div className="flex gap-4">
                                        <label className="flex items-center gap-2 cursor-pointer">
                                            <input
                                                type="radio"
                                                name="strategy"
                                                value="ignore"
                                                checked={options.libraryStrategy === 'ignore'}
                                                onChange={() => setOptions(o => ({ ...o, libraryStrategy: 'ignore' }))}
                                                className="text-amber-600 focus:ring-amber-500"
                                            />
                                            <span className="text-sm font-medium">Ignorer (Garder actuel)</span>
                                        </label>
                                        <label className="flex items-center gap-2 cursor-pointer">
                                            <input
                                                type="radio"
                                                name="strategy"
                                                value="overwrite"
                                                checked={options.libraryStrategy === 'overwrite'}
                                                onChange={() => setOptions(o => ({ ...o, libraryStrategy: 'overwrite' }))}
                                                className="text-amber-600 focus:ring-amber-500"
                                            />
                                            <span className="text-sm font-medium">Écraser (Mettre à jour)</span>
                                        </label>
                                        <label className="flex items-center gap-2 cursor-pointer">
                                            <input
                                                type="radio"
                                                name="strategy"
                                                value="copy"
                                                checked={options.libraryStrategy === 'copy'}
                                                onChange={() => setOptions(o => ({ ...o, libraryStrategy: 'copy' }))}
                                                className="text-amber-600 focus:ring-amber-500"
                                            />
                                            <span className="text-sm font-medium">Copier (Doublon)</span>
                                        </label>
                                    </div>
                                </div>
                            </div>
                        )}
                    </div>

                    {/* Details View */}
                    <div className="mt-4">
                        <button
                            onClick={() => setShowDetails(!showDetails)}
                            className="flex items-center gap-2 text-sm font-bold text-slate-600 hover:text-blue-600 transition-colors bg-white px-4 py-2 rounded-lg border border-slate-200"
                        >
                            {showDetails ? <ChevronDown size={18} /> : <ChevronRight size={18} />}
                            Voir le détail des changements dans les bibliothèques
                        </button>

                        {showDetails && (
                            <div className="mt-3 space-y-4 animate-in slide-in-from-top-2 duration-200">
                                {Object.entries(diff.details.libraries).map(([key, stats]) => {
                                    if (stats.newItems.length === 0 && stats.conflicts.length === 0) return null;

                                    return (
                                        <div key={key} className="bg-white border border-slate-200 rounded-lg overflow-hidden shadow-sm">
                                            <div className="bg-slate-50 px-4 py-2 border-b border-slate-200 flex justify-between items-center text-xs font-bold text-slate-700 uppercase">
                                                <span>{key} ({stats.newItems.length + stats.conflicts.length})</span>
                                            </div>
                                            <div className="p-3 space-y-4">
                                                {/* New Items */}
                                                {stats.newItems.length > 0 && (
                                                    <div className="space-y-2">
                                                        <div className="text-[10px] font-bold text-green-600 uppercase flex items-center gap-1">
                                                            <PlusCircle size={12} /> Nouveaux éléments ({stats.newItems.length})
                                                        </div>
                                                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                                                            {stats.newItems.map((item, i) => {
                                                                const isExcluded = options.excludedIds?.includes(item.id);
                                                                return (
                                                                    <label key={i} className={`flex items-center gap-2 p-2 rounded border transition-colors cursor-pointer ${isExcluded ? 'bg-gray-50 border-gray-200 opacity-60' : 'bg-green-50/30 border-green-100 hover:bg-green-50'}`}>
                                                                        <input
                                                                            type="checkbox"
                                                                            checked={!isExcluded}
                                                                            onChange={() => toggleExclusion(item.id)}
                                                                            className="w-3.5 h-3.5 rounded text-green-600 focus:ring-green-500"
                                                                        />
                                                                        <span className="text-xs font-medium text-slate-700 truncate">{item.name}</span>
                                                                        {!isExcluded && <span className="ml-auto text-[9px] font-bold bg-green-100 text-green-700 px-1.5 py-0.5 rounded uppercase font-mono">Ajouté</span>}
                                                                        {isExcluded && <span className="ml-auto text-[9px] font-bold bg-gray-200 text-gray-500 px-1.5 py-0.5 rounded uppercase text-nowrap font-mono">Exclu</span>}
                                                                    </label>
                                                                );
                                                            })}
                                                        </div>
                                                    </div>
                                                )}

                                                {/* Conflicts */}
                                                {stats.conflicts.length > 0 && (
                                                    <div className="space-y-2 pt-2 border-t border-slate-100">
                                                        <div className="text-[10px] font-bold text-amber-600 uppercase flex items-center gap-1">
                                                            <AlertTriangle size={12} /> Conflits détectés ({stats.conflicts.length})
                                                        </div>
                                                        <div className="space-y-2">
                                                            {stats.conflicts.map((conflict, i) => {
                                                                const isExcluded = options.excludedIds?.includes(conflict.candidate.id);

                                                                const toggleFieldExclusion = (itemId: string, field: string) => {
                                                                    setOptions(prev => {
                                                                        const fieldExclusions = prev.fieldExclusions || {};
                                                                        const itemExclusions = fieldExclusions[itemId] || [];

                                                                        const newExclusions = itemExclusions.includes(field)
                                                                            ? itemExclusions.filter(f => f !== field)
                                                                            : [...itemExclusions, field];

                                                                        return {
                                                                            ...prev,
                                                                            fieldExclusions: {
                                                                                ...fieldExclusions,
                                                                                [itemId]: newExclusions
                                                                            }
                                                                        };
                                                                    });
                                                                };

                                                                const itemFieldExclusions = options.fieldExclusions?.[conflict.id] || [];
                                                                const isPartiallyExcluded = !isExcluded && itemFieldExclusions.length > 0 && itemFieldExclusions.length < conflict.differences.length;
                                                                const isFullyFieldExcluded = !isExcluded && itemFieldExclusions.length === conflict.differences.length;

                                                                // Dynamic Badge Text
                                                                let actionLabel = "Ignoré";
                                                                let actionClass = "bg-gray-100 text-gray-500 border-gray-200";

                                                                if (!isExcluded) {
                                                                    if (options.libraryStrategy === 'overwrite') {
                                                                        if (isPartiallyExcluded) {
                                                                            actionLabel = "Partiel";
                                                                            actionClass = "bg-blue-50 text-blue-600 border-blue-200";
                                                                        } else if (isFullyFieldExcluded) {
                                                                            actionLabel = "Ignoré";
                                                                            actionClass = "bg-gray-100 text-gray-500 border-gray-200";
                                                                        } else {
                                                                            actionLabel = "Remplacé";
                                                                            actionClass = "bg-amber-100 text-amber-700 border-amber-200";
                                                                        }
                                                                    } else if (options.libraryStrategy === 'copy') {
                                                                        actionLabel = "Doublon";
                                                                        actionClass = "bg-blue-100 text-blue-700 border-blue-200";
                                                                    }
                                                                } else {
                                                                    actionLabel = "Exclu";
                                                                    actionClass = "bg-red-50 text-red-500 border-red-100";
                                                                }

                                                                return (
                                                                    <div key={i} className={`border rounded-lg p-3 transition-colors ${isExcluded ? 'bg-gray-50 border-gray-200 opacity-60' : 'bg-white border-slate-200 hover:border-amber-300 shadow-sm'}`}>
                                                                        <div className="flex items-center gap-3 mb-2">
                                                                            <input
                                                                                type="checkbox"
                                                                                checked={!isExcluded}
                                                                                onChange={() => toggleExclusion(conflict.candidate.id)}
                                                                                className="w-4 h-4 rounded text-amber-600 focus:ring-amber-500"
                                                                            />
                                                                            <div className="font-bold text-sm text-slate-800">{conflict.name}</div>
                                                                            <span className={`ml-auto text-[10px] font-bold border px-2 py-0.5 rounded-full uppercase font-mono ${actionClass}`}>
                                                                                {actionLabel}
                                                                            </span>
                                                                        </div>
                                                                        {!isExcluded && options.libraryStrategy === 'overwrite' && (
                                                                            <div className="pl-7 space-y-1.5 mt-2 pt-2 border-t border-slate-50">
                                                                                {conflict.differences.map((d, di) => {
                                                                                    const isFieldExcluded = itemFieldExclusions.includes(d.field);
                                                                                    return (
                                                                                        <label key={di} className={`flex items-start gap-2 text-xs group cursor-pointer ${isFieldExcluded ? 'opacity-50' : ''}`}>
                                                                                            <input
                                                                                                type="checkbox"
                                                                                                checked={!isFieldExcluded}
                                                                                                onChange={() => toggleFieldExclusion(conflict.id, d.field)}
                                                                                                className="mt-0.5 w-3 h-3 rounded text-blue-500 focus:ring-blue-400"
                                                                                            />
                                                                                            <div className="flex-grow">
                                                                                                <span className="font-semibold text-slate-700">{d.label} : </span>
                                                                                                <span className="text-slate-400 line-through mr-1">{typeof d.prev === 'string' ? d.prev : JSON.stringify(d.prev)}</span>
                                                                                                <span className="text-blue-600 font-medium">→ {typeof d.next === 'string' ? d.next : JSON.stringify(d.next)}</span>
                                                                                            </div>
                                                                                        </label>
                                                                                    );
                                                                                })}
                                                                            </div>
                                                                        )}
                                                                        {!isExcluded && options.libraryStrategy !== 'overwrite' && (
                                                                            <ul className="list-disc list-inside space-y-1 text-xs text-slate-400 pl-7 italic">
                                                                                {conflict.differences.map((d, di) => (
                                                                                    <li key={di}>{d.label} sera {options.libraryStrategy === 'copy' ? 'copié' : 'ignoré'}</li>
                                                                                ))}
                                                                            </ul>
                                                                        )}
                                                                    </div>
                                                                );
                                                            })}
                                                        </div>
                                                    </div>
                                                )}
                                            </div>
                                        </div>
                                    );
                                })}
                            </div>
                        )}
                    </div>

                </div>

                {/* Footer */}
                <div className="p-4 bg-white border-t border-slate-200 flex justify-end gap-3 shrink-0">
                    <button onClick={onClose} className="px-5 py-2 text-slate-600 font-bold hover:bg-slate-100 rounded-lg transition-colors">
                        Annuler
                    </button>
                    <button
                        onClick={handleConfirm}
                        className="px-6 py-2 bg-blue-600 text-white font-bold rounded-lg shadow-lg hover:bg-blue-700 transition-colors flex items-center gap-2"
                    >
                        <Check size={20} /> Confirmer la Fusion
                    </button>
                </div>
            </div>
        </div>
    );
};

export default ImportWizardModal;

import React from 'react';
import { ImportCandidate, TabType } from '../../hooks/useLibraryImport';
import CandidateLine from '../import/CandidateLine';
import { Loader2 } from 'lucide-react';
import { DestinationSelector } from './DestinationSelector';

interface WizardContentProps {
    isLoading: boolean;
    activeTab: TabType;
    importDestination: 'campaign' | 'global';
    updateImportDestination: (dest: 'campaign' | 'global') => void;
    traitCandidates: ImportCandidate<any>[];
    skillCandidates: ImportCandidate<any>[];
    specCandidates: ImportCandidate<any>[];
    backgroundCandidates: ImportCandidate<any>[];
    counterCandidates: ImportCandidate<any>[];
    toggleCandidateSelection: (type: TabType, index: number) => void;
}

export const WizardContent: React.FC<WizardContentProps> = ({
    isLoading,
    activeTab,
    importDestination,
    updateImportDestination,
    traitCandidates,
    skillCandidates,
    specCandidates,
    backgroundCandidates,
    counterCandidates,
    toggleCandidateSelection
}) => {
    if (isLoading) {
        return (
            <div className="h-full flex flex-col items-center justify-center text-slate-400 animate-pulse">
                <Loader2 className="animate-spin mb-4" size={40} />
                <p>Analyse de la fiche et de la bibliothèque...</p>
            </div>
        );
    }

    return (
        <div className="space-y-6">
            <DestinationSelector
                importDestination={importDestination}
                onUpdateDestination={updateImportDestination}
            />

            <div className="space-y-4">
                {activeTab === 'traits' && (
                    <div className="space-y-3">
                        <h3 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-1">Avantages & Désavantages</h3>
                        {traitCandidates.length === 0 ? (
                            <div className="text-center py-10 text-slate-400 italic">Aucun trait détecté.</div>
                        ) : (
                            traitCandidates.map((c, idx) => (
                                <CandidateLine
                                    key={idx}
                                    candidate={c}
                                    onToggle={() => toggleCandidateSelection('traits', idx)}
                                    importDestination={importDestination}
                                    showType={true}
                                    typeLabel={c.data.type === 'avantage' ? 'Avantage' : 'Désavantage'}
                                />
                            ))
                        )}
                    </div>
                )}

                {activeTab === 'skills' && (
                    <div className="space-y-3">
                        <h3 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-1">Compétences Détectées</h3>
                        {skillCandidates.length === 0 ? (
                            <div className="text-center py-10 text-slate-400 italic">Aucune compétence détectée.</div>
                        ) : (
                            skillCandidates.map((c, idx) => (
                                <CandidateLine
                                    key={idx}
                                    candidate={c}
                                    onToggle={() => toggleCandidateSelection('skills', idx)}
                                    importDestination={importDestination}
                                    extraInfo={c.data.defaultCategory ? <div className="text-[10px] text-indigo-500 font-bold uppercase mt-0.5">{c.data.defaultCategory.replace('Col_Comp_', 'Série ')}</div> : null}
                                />
                            ))
                        )}
                    </div>
                )}

                {activeTab === 'specializations' && (
                    <div className="space-y-3">
                        <h3 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-1">Spécialisations Détectées</h3>
                        {specCandidates.length === 0 ? (
                            <div className="text-center py-10 text-slate-400 italic">Aucune spécialisation détectée.</div>
                        ) : (
                            specCandidates.map((c, idx) => (
                                <CandidateLine
                                    key={idx}
                                    candidate={c}
                                    onToggle={() => toggleCandidateSelection('specializations', idx)}
                                    importDestination={importDestination}
                                />
                            ))
                        )}
                    </div>
                )}

                {activeTab === 'backgrounds' && (
                    <div className="space-y-3">
                        <h3 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-1">Historiques Détectés</h3>
                        {backgroundCandidates.length === 0 ? (
                            <div className="text-center py-10 text-slate-400 italic">Aucun historique détecté.</div>
                        ) : (
                            backgroundCandidates.map((c, idx) => (
                                <CandidateLine
                                    key={idx}
                                    candidate={c}
                                    onToggle={() => toggleCandidateSelection('backgrounds', idx)}
                                    importDestination={importDestination}
                                />
                            ))
                        )}
                    </div>
                )}

                {activeTab === 'counters' && (
                    <div className="space-y-3">
                        <h3 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-1">Compteurs Détectés</h3>
                        {counterCandidates.length === 0 ? (
                            <div className="text-center py-10 text-slate-400 italic">Aucun compteur détecté.</div>
                        ) : (
                            counterCandidates.map((c, idx) => (
                                <CandidateLine
                                    key={idx}
                                    candidate={c}
                                    onToggle={() => toggleCandidateSelection('counters', idx)}
                                    importDestination={importDestination}
                                    extraInfo={
                                        <div className="flex items-center gap-3 text-[10px] text-slate-500">
                                            <span>Max: {c.data.maxValue}</span>
                                            <span>Départ: {c.data.defaultValue}</span>
                                        </div>
                                    }
                                />
                            ))
                        )}
                    </div>
                )}
            </div>
        </div>
    );
};

import React from 'react';
import { Zap, CheckCircle2 } from 'lucide-react';
import { ImportCandidate } from '../../hooks/useLibraryImport';

interface CandidateLineProps {
    candidate: ImportCandidate<any>;
    onToggle: () => void;
    importDestination: 'campaign' | 'global';
    typeLabel?: string;
    showType?: boolean;
    extraInfo?: React.ReactNode;
}

const CandidateLine: React.FC<CandidateLineProps> = ({
    candidate,
    onToggle,
    importDestination,
    typeLabel,
    showType,
    extraInfo
}) => {
    const isVariableDisabled = importDestination === 'global' && candidate.isVariable;
    const isDisabled = candidate.isDuplicate || isVariableDisabled;

    return (
        <div className={`p-3 rounded-xl border flex items-center gap-3 transition-all ${candidate.isDuplicate ? 'bg-slate-50 opacity-60 border-slate-100' : 'bg-white border-slate-200 hover:border-indigo-200'}`}>
            <input
                type="checkbox"
                checked={candidate.isSelected}
                disabled={isDisabled}
                onChange={onToggle}
                className="w-5 h-5 rounded border-slate-300 text-indigo-600 focus:ring-indigo-500 cursor-pointer disabled:opacity-30"
            />
            <div className="flex-grow">
                <div className="flex items-center gap-2">
                    {showType && typeLabel && (
                        <span className={`text-[10px] px-1.5 py-0.5 rounded font-bold uppercase ${candidate.data.type === 'avantage' ? 'bg-emerald-100 text-emerald-700' : 'bg-rose-100 text-rose-700'}`}>
                            {typeLabel}
                        </span>
                    )}
                    <span className="font-bold text-slate-800 text-sm">{candidate.data.name}</span>
                    {candidate.isVariable && (
                        <span className="bg-amber-100 text-amber-700 text-[10px] px-1.5 py-0.5 rounded font-bold uppercase flex items-center gap-1">
                            <Zap size={10} /> Variable
                        </span>
                    )}
                    {candidate.data.cost && (
                        <span className="text-xs text-slate-400 font-mono">({candidate.data.cost} pts)</span>
                    )}
                </div>
                {candidate.data.description && (
                    <p className={`text-xs text-slate-500 italic mt-0.5 ${candidate.isVariable ? 'text-amber-600/70' : ''}`}>
                        {candidate.data.description}
                    </p>
                )}
                {extraInfo}
            </div>
            {candidate.isDuplicate && (
                <div className="flex items-center gap-1 text-[10px] font-bold text-amber-600 bg-amber-50 px-2 py-1 rounded">
                    <CheckCircle2 size={12} /> Doublon
                </div>
            )}
        </div>
    );
};

export default CandidateLine;

import React, { useState, useMemo } from 'react';
import { RulesData } from '../../../types/rules';
import { LibraryCounterEntry } from '../../../types/system';
import { Search, Plus, Save, AlertOctagon, Gauge, CheckCircle2, Circle, X, Calculator } from 'lucide-react';
import ThematicModal from '../../../components/ui/ThematicModal';
import { useItemUsageDetails } from '../../../hooks/admin/useItemUsageDetails';
import { smartIncludes } from '../../../utils/stringUtils';
import ConfirmationModal from '../../../components/ui/ConfirmationModal';
import { CounterLibraryItem } from './counter/CounterLibraryItem';

interface AdminCounterLibraryProps {
    rules: RulesData;
    onUpdate: (newRules: RulesData) => void;
    globalUsage?: Record<string, number>;
}

const AdminCounterLibrary: React.FC<AdminCounterLibraryProps> = ({ rules, onUpdate, globalUsage = {} }) => {
    const list = rules.libraries.counters;
    const { usageDetailsCache, loadDetails } = useItemUsageDetails('global', 'counter');

    const [searchTerm, setSearchTerm] = useState('');
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingItem, setEditingItem] = useState<LibraryCounterEntry | null>(null);
    const [error, setError] = useState<string | null>(null);

    const filteredList = useMemo(() => {
        return list
            .filter(c => smartIncludes(c.name, searchTerm) || (c.description && smartIncludes(c.description, searchTerm)))
            .sort((a, b) => a.name.localeCompare(b.name));
    }, [list, searchTerm]);

    const placedNames = useMemo(() => {
        const names = new Set<string>();
        const counterCat = rules.definitions.skillCategories?.find(c => c.behavior === 'Compteur')?.id || 'Col_Comp_9';
        const placed = rules.definitions.skills?.[counterCat] || [];
        placed.forEach(name => {
            if (name.trim()) names.add(name.trim().toLowerCase());
        });
        return names;
    }, [rules.definitions]);

    const [showDeleteConfirm, setShowDeleteConfirm] = useState<string | null>(null);

    const handleOpenNew = () => {
        setError(null);
        setEditingItem({
            id: crypto.randomUUID(),
            name: '',
            description: '',
            maxValue: 10,
            defaultValue: 0,
            xpCost: 0,
            isGlobal: false
        });
        setIsModalOpen(true);
    };

    const handleOpenEdit = (item: LibraryCounterEntry) => {
        setError(null);
        setEditingItem({ ...item });
        setIsModalOpen(true);
    };

    const handleDelete = (id: string) => {
        setShowDeleteConfirm(id);
    };

    const confirmDelete = () => {
        if (!showDeleteConfirm) return;

        const counterToDelete = list.find(c => c.id === showDeleteConfirm);
        const newDefinitionsCounters = { ...(rules.definitions.counters || {}) };

        if (counterToDelete) {
            const key = counterToDelete.id || counterToDelete.name.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]/g, '_').replace(/_+/g, '_').replace(/^_|_$/g, '');
            delete newDefinitionsCounters[key];
        }

        onUpdate({
            ...rules,
            definitions: {
                ...rules.definitions,
                counters: newDefinitionsCounters
            },
            libraries: { ...rules.libraries, counters: list.filter(c => c.id !== showDeleteConfirm) }
        });
        setShowDeleteConfirm(null);
    };

    const handleSave = () => {
        if (!editingItem) return;
        if (!editingItem.name.trim()) { setError("Le nom est requis."); return; }

        const duplicate = list.find(c => c.id !== editingItem.id && c.name.trim().toLowerCase() === editingItem.name.trim().toLowerCase());
        if (duplicate) { setError("Un compteur portant ce nom existe déjà."); return; }

        const safeItem = {
            ...editingItem,
            maxValue: Number(editingItem.maxValue) || 10,
            defaultValue: Number(editingItem.defaultValue) || 0,
            xpCost: Number(editingItem.xpCost) || 0,
            appearance: (editingItem.appearance === 'squares_only' ? 'squares_only' : null) as 'squares_only' | null
        };

        const newList = list.some(c => c.id === editingItem.id)
            ? list.map(c => c.id === editingItem.id ? safeItem : c)
            : [...list, safeItem];

        // Sort
        newList.sort((a, b) => a.name.localeCompare(b.name));

        // Update definitions as well so it's ready to be saved correctly to the DB
        const newDefinitionsCounters = { ...(rules.definitions.counters || {}) };

        // key format as in campaignReconciler.ts
        const key = safeItem.id || safeItem.name.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]/g, '_').replace(/[^a-z0-9]/g, '_').replace(/_+/g, '_').replace(/^_|_$/g, '');

        newDefinitionsCounters[key] = {
            id: safeItem.id,
            name: safeItem.name,
            description: safeItem.description || newDefinitionsCounters[key]?.description || '',
            max: safeItem.formulaId ? 0 : (safeItem.maxValue ?? 10), // Will be calculated if formulaId is present
            value: safeItem.defaultValue ?? newDefinitionsCounters[key]?.value,
            defaultValue: safeItem.defaultValue ?? newDefinitionsCounters[key]?.defaultValue,
            xpCost: safeItem.xpCost ?? newDefinitionsCounters[key]?.xpCost ?? 0,
            appearance: safeItem.appearance === 'squares_only' ? 'squares_only' : undefined,
            formulaId: safeItem.formulaId
        };

        onUpdate({
            ...rules,
            definitions: {
                ...rules.definitions,
                counters: newDefinitionsCounters
            },
            libraries: { ...rules.libraries, counters: newList }
        });
        setIsModalOpen(false);
        setEditingItem(null);
    };

    const handleBulkSelect = (active: boolean) => {
        const visibleIds = new Set(filteredList.map(item => item.id));
        const newList = list.map(item => {
            if (!visibleIds.has(item.id)) return item;

            if (!active) {
                const isPlaced = placedNames.has(item.name.trim().toLowerCase());
                const isGloballyUsed = !!globalUsage[item.id];
                const isUsedByTrait = false; // Obsolète : Les compteurs de traits sont instanciés à la volée sur la fiche.

                if (isPlaced || isGloballyUsed || isUsedByTrait) return item; // Cannot deactivate
            }

            return { ...item, isActive: active };
        });

        // No need to update definitions.counters here since it's just isActive flag, 
        // the list remains the same, but wait! Are deactivated counters removed from the definitions map? No, definitions map just stores metadata, active list comes from libraries in the end.

        onUpdate({
            ...rules,
            libraries: { ...rules.libraries, counters: newList }
        });
    };

    return (
        <div className="bg-white p-6 rounded-lg shadow-sm border border-slate-200 h-[calc(100vh-120px)] flex flex-col">
            <div className="flex justify-between items-center mb-6">
                <div>
                    <h2 className="text-2xl font-bold text-slate-900 flex items-center gap-2">
                        <Gauge className="text-red-600" /> Bibliothèque de Compteurs
                    </h2>
                    <p className="text-slate-500 text-sm">Définissez les jauges (Santé, Volonté, Sang...).</p>
                </div>
                <div>
                    <button
                        onClick={handleOpenNew}
                        className="bg-slate-900 text-white px-4 py-2 rounded font-bold hover:bg-slate-800 transition-colors flex items-center gap-2"
                    >
                        <Plus size={18} /> Nouveau Compteur
                    </button>
                </div>
            </div>

            <div className="relative mb-4">
                <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                <input
                    className="w-full pl-9 pr-9 py-2 text-sm border border-slate-300 rounded focus:border-red-500 outline-none"
                    placeholder="Rechercher..."
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                />
                {searchTerm && (
                    <button
                        onClick={() => setSearchTerm('')}
                        className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-red-600 transition-colors"
                    >
                        <X size={14} />
                    </button>
                )}
            </div>

            {/* Bulk Actions */}
            {list.length > 0 && (
                <div className="flex gap-4 mb-4 px-1">
                    <button
                        onClick={() => handleBulkSelect(true)}
                        className="text-xs font-bold text-red-600 hover:text-red-800 flex items-center gap-1.5 transition-colors"
                    >
                        <CheckCircle2 size={14} />
                        Tout activer {searchTerm ? `(${filteredList.length})` : ''}
                    </button>
                    <button
                        onClick={() => handleBulkSelect(false)}
                        className="text-xs font-bold text-slate-500 hover:text-slate-700 flex items-center gap-1.5 transition-colors"
                    >
                        <Circle size={14} />
                        Tout désactiver {searchTerm ? `(${filteredList.length})` : ''}
                    </button>
                </div>
            )}

            <div className="flex-grow overflow-y-auto bg-slate-50 border border-slate-200 rounded p-4 custom-scrollbar">
                {list.length === 0 ? (
                    <div className="text-center text-slate-400 py-20 italic">Bibliothèque vide.</div>
                ) : filteredList.length === 0 ? (
                    <div className="text-center text-slate-400 py-10 italic">Aucun résultat.</div>
                ) : (
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-3">
                        {filteredList.map(item => {
                            const isPlaced = placedNames.has(item.name.trim().toLowerCase());
                            const isGloballyUsed = !!globalUsage[item.id];

                            // Check if any active trait uses this counter
                            const isUsedByTrait = false; // Obsolète : Les compteurs de traits sont instanciés à la volée sur la fiche et n'utilisent plus la bibliothèque Admin.

                            const isLocked = isPlaced || isGloballyUsed || isUsedByTrait;

                            return (
                                <CounterLibraryItem
                                    key={item.id}
                                    item={item}
                                    isPlaced={isPlaced}
                                    isLocked={isLocked}
                                    onToggleActive={(id: string, current: boolean) => {
                                        // Prevents disabling globally locking trait or local locking trait effect from here, maybe show a toast instead
                                        if (current && isLocked) return;
                                        const newList = list.map(c => c.id === id ? { ...c, isActive: !current } : c);
                                        onUpdate({ ...rules, libraries: { ...rules.libraries, counters: newList } });
                                    }}
                                    handleOpenEdit={handleOpenEdit}
                                    handleDelete={handleDelete}
                                    rules={rules}
                                    usageDetails={usageDetailsCache.get(item.id)}
                                    onLoadUsageDetails={loadDetails}
                                />
                            );
                        })}
                    </div>
                )}
            </div>

            {isModalOpen && editingItem && (
                <ThematicModal
                    isOpen={isModalOpen}
                    onClose={() => setIsModalOpen(false)}
                    title={editingItem.id ? 'Modifier Compteur' : 'Nouveau Compteur'}
                    icon={<Gauge size={20} />}
                    size="md"
                    footer={
                        <>
                            <button onClick={() => setIsModalOpen(false)} className="px-4 py-2 text-slate-600 font-bold hover:bg-slate-100 rounded">Annuler</button>
                            <button onClick={handleSave} className="px-6 py-2 bg-red-600 text-white rounded font-bold shadow hover:bg-red-700 flex items-center gap-2">
                                <Save size={16} /> Enregistrer
                            </button>
                        </>
                    }
                >
                    <div className="flex flex-col gap-4 py-2">
                        <div>
                            <label htmlFor="counter-name" className="block text-xs font-bold text-slate-500 uppercase mb-1">Nom</label>
                            <input
                                id="counter-name"
                                className="w-full border border-slate-300 rounded px-3 py-2 font-bold focus:border-red-500 outline-none"
                                value={editingItem.name}
                                onChange={(e) => setEditingItem({ ...editingItem, name: e.target.value })}
                            />
                        </div>

                        <div>
                            <label htmlFor="counter-description" className="block text-xs font-bold text-slate-500 uppercase mb-1">Description (Notes)</label>
                            <textarea
                                id="counter-description"
                                className="w-full border border-slate-300 rounded px-3 py-2 text-sm min-h-[60px] focus:border-red-500 outline-none resize-none"
                                value={editingItem.description || ''}
                                onChange={(e) => setEditingItem({ ...editingItem, description: e.target.value })}
                                placeholder="Expliquez à quoi sert ce compteur..."
                            />
                        </div>
                        <div>
                            <label htmlFor="counter-category" className="block text-xs font-bold text-slate-500 uppercase mb-1">Catégorie de Placement</label>
                            <select
                                id="counter-category"
                                className="w-full border border-slate-300 rounded px-3 py-2 text-sm focus:border-red-500 outline-none bg-white font-bold"
                                value={editingItem.defaultCategory || ''}
                                onChange={(e) => setEditingItem({ ...editingItem, defaultCategory: e.target.value })}
                            >
                                <option value="">-- Par Défaut (Col 9) --</option>
                                {rules.definitions.skillCategories
                                    ?.filter(cat => cat.behavior === 'Compteur')
                                    .map(cat => (
                                        <option key={cat.id} value={cat.id}>{cat.label} ({cat.id})</option>
                                    ))
                                }
                            </select>
                        </div>
                        <div className="bg-amber-500/5 p-3 rounded border border-amber-500/20 mb-2">
                            <label className="block text-xs font-bold text-amber-700 uppercase mb-2 flex items-center gap-2">
                                <Calculator size={14} /> Valeur Max (Calculée)
                            </label>
                            <select
                                className="w-full border border-stone-200 rounded px-3 py-2 text-sm focus:border-amber-500 outline-none bg-white font-medium mb-3"
                                value={editingItem.formulaId || ''}
                                onChange={(e) => setEditingItem({ ...editingItem, formulaId: e.target.value || undefined })}
                            >
                                <option value="">-- Valeur Fixe (Manuel) --</option>
                                {rules.libraries.formulas
                                    ?.filter(f => f.type === 'variable')
                                    .map(f => (
                                        <option key={f.id} value={f.id}>{f.name} ({f.formula || 'Agrégat'})</option>
                                    ))
                                }
                            </select>

                            <div className="grid grid-cols-3 gap-4">
                                <div>
                                    <label htmlFor="counter-max" className="block text-xs font-bold text-slate-500 uppercase mb-1">
                                        {editingItem.formulaId ? 'Max de Secours' : 'Max (Fixe)'}
                                    </label>
                                    <input
                                        id="counter-max"
                                        type="number"
                                        disabled={!!editingItem.formulaId}
                                        className={`w-full border border-slate-300 rounded px-3 py-2 text-sm focus:border-red-500 outline-none ${editingItem.formulaId ? 'bg-slate-100 text-slate-400 cursor-not-allowed' : ''}`}
                                        value={editingItem.maxValue ?? 10}
                                        onChange={(e) => setEditingItem({ ...editingItem, maxValue: Number(e.target.value) })}
                                    />
                                </div>
                                <div className={editingItem.formulaId ? 'opacity-40 grayscale pointer-events-none' : ''}>
                                    <label htmlFor="counter-default" className="block text-xs font-bold text-slate-500 uppercase mb-1">Défaut (Rempli)</label>
                                    <input
                                        id="counter-default"
                                        type="number"
                                        disabled={!!editingItem.formulaId}
                                        className="w-full border border-slate-300 rounded px-3 py-2 text-sm focus:border-red-500 outline-none"
                                        value={editingItem.defaultValue ?? 0}
                                        onChange={(e) => setEditingItem({ ...editingItem, defaultValue: Number(e.target.value) })}
                                    />
                                </div>
                                <div className={editingItem.formulaId ? 'opacity-40 grayscale pointer-events-none' : ''}>
                                    <label htmlFor="counter-cost" className="block text-xs font-bold text-slate-500 uppercase mb-1">Coût XP</label>
                                    <input
                                        id="counter-cost"
                                        type="number"
                                        disabled={!!editingItem.formulaId}
                                        className="w-full border border-slate-300 rounded px-3 py-2 text-sm focus:border-red-500 outline-none"
                                        value={editingItem.xpCost ?? 0}
                                        onChange={(e) => setEditingItem({ ...editingItem, xpCost: Number(e.target.value) })}
                                    />
                                </div>
                            </div>
                        </div>

                        <div className="bg-slate-50 p-3 rounded border border-slate-200 flex items-start gap-2">
                            <input
                                type="checkbox"
                                id="counter-appearance"
                                className="mt-1 accent-red-600 cursor-pointer"
                                checked={editingItem.appearance === 'squares_only'}
                                onChange={(e) => setEditingItem({ ...editingItem, appearance: e.target.checked ? 'squares_only' : null })}
                            />
                            <label htmlFor="counter-appearance" className="text-xs text-slate-600 cursor-pointer">
                                <strong className="text-slate-800 block">Affichage : Carrés uniquement</strong>
                                <span className="text-[10px] block mt-0.5">Masque la rangée de bulles rondes (Points d'origine). Utile pour les jauges dynamiques type compteurs de traits.</span>
                            </label>
                        </div>

                        {error && (
                            <div className="bg-red-50 text-red-800 text-xs p-3 rounded border border-red-200 font-bold flex items-center gap-2">
                                <AlertOctagon size={16} /> {error}
                            </div>
                        )}
                    </div>
                </ThematicModal>
            )}

            <ConfirmationModal
                isOpen={!!showDeleteConfirm}
                onClose={() => setShowDeleteConfirm(null)}
                onConfirm={confirmDelete}
                title="Supprimer le compteur ?"
                message="Cette action est irréversible pour la base de données."
                confirmLabel="Supprimer"
                type="danger"
            />
        </div>
    );
};

export default AdminCounterLibrary;

import React from 'react';
import { RulesData } from '../../../types/rules';
import { Search, Plus, GraduationCap, Save, AlertOctagon, X, Layers, UploadCloud, CheckCircle2, Circle, Globe, Filter, Sparkles } from 'lucide-react';
import ThematicModal from '../../../components/ui/ThematicModal';
import TriStateChip from '../../../components/ui/TriStateChip';
import { useAdminSkillLibrary } from '../../../hooks/admin/useAdminSkillLibrary';
import { useItemUsageDetails } from '../../../hooks/admin/useItemUsageDetails';
import ConfirmationModal from '../../../components/ui/ConfirmationModal';
import { SkillLibraryItem } from './skill/SkillLibraryItem';

interface AdminSkillLibraryProps {
    rules: RulesData;
    onUpdate: (newRules: RulesData) => void;
    globalUsage?: Record<string, number>;
}

const AdminSkillLibrary: React.FC<AdminSkillLibraryProps> = ({ rules, onUpdate, globalUsage = {} }) => {
    const {
        list,
        searchTerm, setSearchTerm,
        isModalOpen, setIsModalOpen,
        editingSkill, setEditingSkill,
        variantDraft, setVariantDraft,
        error,
        showCategoryHelp, setShowCategoryHelp,
        activeFilter, setActiveFilter,
        sourceFilter, setSourceFilter,
        typeFilter, setTypeFilter,
        usageFilter, setUsageFilter,
        mysticFilter, setMysticFilter,
        showPublishConfirm, setShowPublishConfirm,
        showDeleteConfirm, setShowDeleteConfirm,
        publishResult, setPublishResult,
        showConfigAlert, setShowConfigAlert,
        placedSkillNames,
        filteredList,
        availableCategories,
        handleOpenNew,
        handleOpenEdit,
        handleDelete,
        toggleSkillActive,
        confirmDelete,
        handleSave,
        handleBulkSelect,
        handlePublishClick,
        executePublish
    } = useAdminSkillLibrary(rules, onUpdate, globalUsage, 'global');
    const { usageDetailsCache, loadDetails } = useItemUsageDetails('global', 'skill');

    return (
        <div className="bg-white p-6 rounded-lg shadow-sm border border-slate-200 h-[calc(100vh-120px)] flex flex-col">
            <div className="flex justify-between items-center mb-6">
                <div>
                    <h2 className="text-2xl font-bold text-slate-900 flex items-center gap-2">
                        <GraduationCap className="text-amber-600" /> Réserve de Compétences
                    </h2>
                    <p className="text-slate-500 text-sm">Définissez les compétences standards que les joueurs pourront importer.</p>
                </div>
                <div className="flex gap-2">
