                    <button
                        onClick={handleOpenNew}
                        className="bg-slate-900 text-white px-4 py-2 rounded font-bold hover:bg-slate-800 transition-colors flex items-center gap-2"
                    >
                        <Plus size={18} /> Nouvelle Compétence
                    </button>
                </div>
            </div>

            <div className="relative mb-4">
                <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                <input
                    className="w-full pl-9 pr-9 py-2 text-sm border border-slate-300 rounded focus:border-amber-500 outline-none"
                    placeholder="Rechercher une compétence..."
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                />
                {searchTerm && (
                    <button
                        onClick={() => setSearchTerm('')}
                        className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-amber-600 transition-colors"
                    >
                        <X size={14} />
                    </button>
                )}
            </div>

            <div className="flex flex-wrap gap-2 items-center mb-4 p-2 bg-slate-50 border border-slate-200 rounded">
                <div className="flex items-center gap-1.5 px-2 text-slate-400 border-r border-slate-200 mr-1 py-1">
                    <Filter size={14} />
                    <span className="text-[10px] font-bold uppercase tracking-wider">Filtres</span>
                </div>

                <TriStateChip
                    label="Actifs"
                    value={activeFilter}
                    onChange={setActiveFilter}
                    icon={CheckCircle2}
                    activeColor="green"
                />

                <TriStateChip
                    label="Officiels"
                    value={sourceFilter}
                    onChange={setSourceFilter}
                    icon={Globe}
                    activeColor="indigo"
                />

                <TriStateChip
                    label="Variantes"
                    value={typeFilter}
                    onChange={setTypeFilter}
                    icon={Layers}
                    activeColor="blue"
                />

                <TriStateChip
                    label="Placés"
                    value={usageFilter}
                    onChange={setUsageFilter}
                    icon={GraduationCap}
                    activeColor="amber"
                />

                <TriStateChip
                    label="Mystiques"
                    value={mysticFilter}
                    onChange={setMysticFilter}
                    icon={Sparkles}
                    activeColor="amber"
                />

                {(activeFilter !== null || sourceFilter !== null || typeFilter !== null || usageFilter !== null || mysticFilter !== null) && (
                    <button
                        onClick={() => { setActiveFilter(null); setSourceFilter(null); setTypeFilter(null); setUsageFilter(null); setMysticFilter(null); }}
                        className="text-[10px] font-bold text-red-500 hover:text-red-700 ml-auto px-2"
                    >
                        RÉINITIALISER
                    </button>
                )}
            </div>

            {/* Bulk Actions */}
            {list.length > 0 && (
                <div className="flex gap-4 mb-4 px-1">
                    <button
                        onClick={() => handleBulkSelect(true)}
                        className="text-xs font-bold text-blue-600 hover:text-blue-800 flex items-center gap-1.5 transition-colors"
                    >
                        <CheckCircle2 size={14} />
                        Tout activer {searchTerm ? `(${filteredList.length})` : ''}
                    </button>
                    <button
                        onClick={() => handleBulkSelect(false)}
                        className="text-xs font-bold text-slate-500 hover:text-slate-700 flex items-center gap-1.5 transition-colors"
                    >
                        <Circle size={14} />
                        Tout désactiver {searchTerm ? `(${filteredList.length})` : ''}
                    </button>
                </div>
            )}

            <div className="flex-grow overflow-y-auto bg-slate-50 border border-slate-200 rounded p-4 custom-scrollbar">
                {list.length === 0 ? (
                    <div className="text-center text-slate-400 py-20 italic">La réserve est vide.</div>
                ) : filteredList.length === 0 ? (
                    <div className="text-center text-slate-400 py-10 italic">Aucun résultat.</div>
                ) : (
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-3">
                        {filteredList.map(skill => {
                            const isPlaced = placedSkillNames.has(skill.name.trim().toLowerCase());
                            const isGloballyUsed = !!globalUsage[skill.id];
                            const isLocked = isPlaced || isGloballyUsed || !!skill.isCustomized;

                            return (
                                <SkillLibraryItem
                                    key={skill.id}
                                    skill={skill}
                                    isPlaced={isPlaced}
                                    isLocked={isLocked}
                                    toggleSkillActive={toggleSkillActive}
                                    handleOpenEdit={handleOpenEdit}
                                    handleDelete={handleDelete}
                                    availableCategories={availableCategories}
                                    usageDetails={usageDetailsCache.get(skill.id)}
                                    onLoadUsageDetails={loadDetails}
                                />
                            );
                        })}
                    </div>
                )}
            </div>

            {isModalOpen && editingSkill && (
                <ThematicModal
                    isOpen={isModalOpen}
                    onClose={() => setIsModalOpen(false)}
                    title="Modification de la Base Globale"
                    icon={<GraduationCap size={20} />}
                    size={showCategoryHelp ? 'lg' : 'md'}
                    footer={
                        <>
                            <button onClick={() => setIsModalOpen(false)} className="px-4 py-2 text-slate-600 font-bold hover:bg-slate-100 rounded">Annuler</button>
                            <button onClick={handleSave} className="px-6 py-2 bg-blue-600 text-white rounded font-bold shadow hover:bg-blue-700 flex items-center gap-2">
                                <Save size={16} /> Enregistrer
                            </button>
                        </>
                    }
                >
                    <div className="flex flex-col gap-5 py-2">
                        {/* Editor Form */}
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div className="flex flex-col gap-4">
                                <div>
                                    <label htmlFor="skill-name" className="block text-xs font-bold text-slate-500 uppercase mb-1">Nom</label>
                                    <input
                                        id="skill-name"
                                        className="w-full border border-slate-300 rounded px-3 py-2 font-bold focus:border-blue-500 outline-none"
                                        value={editingSkill.name}
                                        onChange={(e) => setEditingSkill({ ...editingSkill, name: e.target.value })}
                                    />
                                </div>
                                <div>
                                    <div className="flex justify-between items-center mb-1">
                                        <label htmlFor="skill-category" className="block text-xs font-bold text-slate-500 uppercase">Catégorie de Placement</label>
                                        <button
                                            type="button"
                                            onClick={() => setShowCategoryHelp(!showCategoryHelp)}
                                            className="text-[10px] text-blue-600 hover:underline font-bold"
                                        >
                                            {showCategoryHelp ? 'Masquer aide' : 'Aide codes'}
                                        </button>
                                    </div>
                                    <select
                                        id="skill-category"
                                        className="w-full border border-slate-300 rounded px-3 py-2 text-sm focus:border-blue-500 outline-none bg-white font-bold"
                                        value={editingSkill.defaultCategory || ''}
                                        onChange={(e) => setEditingSkill({ ...editingSkill, defaultCategory: e.target.value })}
                                    >
                                        <option value="">-- Automatique (Base) --</option>
                                        {availableCategories.map(cat => (
                                            <option key={cat.code} value={cat.code}>{cat.label} ({cat.code})</option>
                                        ))}
                                    </select>
                                </div>
                                <div className="bg-blue-50 border border-blue-200 rounded p-3 flex items-center gap-3">
                                    <input
                                        type="checkbox"
                                        id="isVariableSkill"
                                        className="w-4 h-4 text-blue-600 rounded cursor-pointer"
                                        checked={editingSkill.isVariable || false}
                                        onChange={(e) => setEditingSkill({ ...editingSkill, isVariable: e.target.checked })}
                                    />
                                    <label htmlFor="isVariableSkill" className="cursor-pointer select-none">
                                        <span className="block text-sm font-bold text-blue-900 leading-tight">Variantes requises</span>
                                        <span className="block text-[10px] text-blue-700 leading-tight">Ex: "Artisanat : Forge"</span>
                                    </label>
                                </div>

                                {/* Mystic Link SECTION */}
                                <div className={`bg-amber-50 border border-amber-200 rounded p-3 flex flex-col gap-2 transition-all ${editingSkill.mysticAbilityId ? 'ring-1 ring-amber-400' : ''}`}>
                                    <div className="flex items-center gap-3">
                                        <input
                                            type="checkbox"
                                            id="isMysticAbility"
                                            className="w-4 h-4 text-amber-600 rounded cursor-pointer disabled:opacity-50 disabled:cursor-not-allowed"
                                            checked={!!editingSkill.mysticAbilityId}
                                            disabled={!rules.libraries.mysticAbilities?.length}
                                            onChange={(e) => {
                                                if (e.target.checked) {
                                                    const firstId = rules.libraries.mysticAbilities?.[0]?.id || '';
                                                    if (firstId) {
                                                        setEditingSkill({ ...editingSkill, mysticAbilityId: firstId });
                                                    }
                                                } else {
                                                    const { mysticAbilityId: _maId, ...rest } = editingSkill;
                                                    setEditingSkill(rest);
                                                }
                                            }}
                                        />
                                        <label htmlFor="isMysticAbility" className="cursor-pointer select-none">
                                            <span className="block text-sm font-bold text-amber-900 leading-tight">Habilité Mystique</span>
                                            <span className="block text-[10px] text-amber-700 leading-tight">Lier à une catégorie magique/martiale</span>
                                            {!rules.libraries.mysticAbilities?.length && (
                                                <span className="block text-[10px] text-red-600 italic mt-1">Aucune habilité mystique définie dans les règles.</span>
                                            )}
                                        </label>
                                    </div>
                                    {editingSkill.mysticAbilityId !== undefined && rules.libraries.mysticAbilities && rules.libraries.mysticAbilities.length > 0 && (
                                        <select
                                            className="w-full border border-amber-300 rounded px-2 py-1 text-xs focus:border-amber-500 outline-none bg-white font-bold"
                                            value={editingSkill.mysticAbilityId || ""}
                                            onChange={(e) => setEditingSkill({ ...editingSkill, mysticAbilityId: e.target.value })}
                                        >
                                            <option value="">-- Choisir une habilité --</option>
                                            {rules.libraries.mysticAbilities?.map(ma => (
                                                <option key={ma.id} value={ma.id}>{ma.name}</option>
                                            ))}
                                        </select>
                                    )}
                                </div>
                                {editingSkill.isVariable && (
                                    <div className="animate-in fade-in slide-in-from-top-2 duration-200">
                                        <label htmlFor="skill-variants" className="block text-xs font-bold text-slate-500 uppercase mb-1">Exemples de variantes (séparés par des virgules)</label>
                                        <input
                                            id="skill-variants"
                                            className="w-full border border-slate-300 rounded px-3 py-2 text-sm focus:border-blue-500 outline-none"
                                            placeholder="Ex: Forge, Menuiserie, Peinture..."
                                            value={variantDraft}
                                            onChange={(e) => setVariantDraft(e.target.value)}
                                        />
                                    </div>
                                )}
                            </div>
                            <div className="flex flex-col">
                                <label htmlFor="skill-description" className="block text-xs font-bold text-slate-500 uppercase mb-1">Description</label>
                                <textarea
                                    id="skill-description"
                                    className="w-full flex-grow border border-slate-300 rounded px-3 py-2 text-sm focus:border-blue-500 outline-none resize-none min-h-[120px]"
                                    value={editingSkill.description || ''}
                                    onChange={(e) => setEditingSkill({ ...editingSkill, description: e.target.value })}
                                />
                            </div>
                        </div>
                        {error && (
                            <div className="bg-red-50 text-red-800 text-xs p-3 rounded border border-red-200 font-bold flex items-center gap-2">
                                <AlertOctagon size={16} /> {error}
                            </div>
                        )}
                    </div>

                    {/* Help Panel */}
                    {showCategoryHelp && (
                        <div className="w-full lg:w-72 shrink-0 animate-in slide-in-from-right-4 duration-300 bg-slate-50 p-4 rounded border border-slate-200">
                            <div className="flex justify-between items-center mb-2 pb-2 border-b border-slate-200">
                                <h4 className="font-bold text-slate-700 text-sm">Codes Catégories</h4>
                                <button onClick={() => setShowCategoryHelp(false)}><X size={14} /></button>
                            </div>
                            <div className="space-y-2 text-xs">
                                {availableCategories.map(cat => (
                                    <div key={cat.code} className="grid grid-cols-[1fr_2fr] gap-2">
                                        <code className="bg-slate-200 px-1 rounded font-mono text-slate-700">{cat.code}</code>
                                        <span className="text-slate-500">{cat.label}</span>
                                    </div>
                                ))}
                            </div>
                        </div>
                    )}
                </ThematicModal>
            )}

            <ConfirmationModal
                isOpen={showPublishConfirm}
                onClose={() => setShowPublishConfirm(false)}
                onConfirm={executePublish}
                title="Publier la bibliothèque ?"
                message="Vous êtes sur le point de mettre à jour le fichier skills.json public. Cela rendra les nouvelles compétences accessibles à tous les joueurs."
                confirmLabel="Publier maintenant"
                type="warning"
            />

            <ConfirmationModal
                isOpen={!!showDeleteConfirm}
                onClose={() => setShowDeleteConfirm(null)}
                onConfirm={confirmDelete}
                title="Supprimer la compétence ?"
                message="Cette action est irréversible pour la base de données (mais nécessitera une publication pour être effective en ligne)."
                confirmLabel="Supprimer"
                type="danger"
            />

            <ConfirmationModal
                isOpen={!!publishResult}
                onClose={() => setPublishResult(null)}
                onConfirm={() => setPublishResult(null)}
                title={publishResult?.success ? "Publication Réussie" : "Échec de la Publication"}
                message={publishResult?.message || ""}
                confirmLabel="Fermer"
                type={publishResult?.success ? "success" : "danger"}
                cancelLabel=""
            />

            <ConfirmationModal
                isOpen={showConfigAlert}
                onClose={() => setShowConfigAlert(false)}
                onConfirm={() => setShowConfigAlert(false)}
                title="Configuration Manquante"
                message="Veuillez d'abord configurer vos identifiants GitHub via le bouton 'Publier' du menu principal."
                confirmLabel="Compris"
                type="info"
                cancelLabel=""
            />
        </div>
    );
};

export default AdminSkillLibrary;

// COMPLEX COMPONENT: VERIFY RETURNS CAREFULLY
import React from 'react';
import { RulesData } from '../../../types/rules';
import { LibrarySkillEntry } from '../../../types';
import { BookOpen, Archive, GripVertical, ArrowRight, Layers, Tag, Sparkles, Edit2, RotateCcw, PencilLine } from 'lucide-react';
import { disambiguateCategories } from '../../../utils/categoryUtils';
import { DragItem } from '../AdminSkillsEditor';
import { useAdminSkillLibrary } from '../../../hooks/admin/useAdminSkillLibrary';

// Nouveaux composants extraits
import { SkillLibraryTabs } from './SkillLibraryTabs';
import { SkillCustomizationModal } from './SkillCustomizationModal';

interface AdminSkillLibrarySidebarProps {
    rules: RulesData;
    onUpdate: (newRules: RulesData) => void;
    draggedItem: DragItem | null;
    setDraggedItem: (item: DragItem | null) => void;
}

const AdminSkillLibrarySidebar: React.FC<AdminSkillLibrarySidebarProps> = ({ rules, onUpdate, draggedItem, setDraggedItem }) => {
    const {
        isModalOpen, setIsModalOpen,
        editingSkill,
        variantDraft, setVariantDraft,
        error,
        handleOpenEdit,
        handleSave,
        handleReset,
        showCategoryHelp, setShowCategoryHelp,
        availableCategories: modalCategories,
        setEditingSkill
    } = useAdminSkillLibrary(rules, onUpdate, {}, 'override');

    const [activeTab, setActiveTab] = React.useState<'skills' | 'backgrounds' | 'counters'>('skills');
    const [editingCategory, setEditingCategory] = React.useState<string | null>(null);

    const availableCategories = React.useMemo(() => {
        return disambiguateCategories(rules.definitions.skillCategories || []);
    }, [rules.definitions.skillCategories]);

    const handleDragStart = (e: React.DragEvent, type: 'admin_lib_skill', dataPayload: Partial<DragItem>) => {
        const item: DragItem = { type, ...dataPayload };
        setDraggedItem(item);
        e.dataTransfer.effectAllowed = "move";
        e.dataTransfer.setData("application/json", JSON.stringify(item));
    };

    const handleDragOver = (e: React.DragEvent) => {
        e.preventDefault();
        e.dataTransfer.dropEffect = "move";
    };

    const handleDropOnLibrary = (e: React.DragEvent) => {
        e.preventDefault();
        if (!draggedItem) return;

        if (draggedItem.type === 'admin_sheet_skill' && activeTab === 'skills') {
            const category = draggedItem.category!;
            const index = draggedItem.index!;
            const skillName = draggedItem.name!;

            // 1. Remove from Definition
            const currentList = rules.definitions.skills[category] || [];
            const newList = [...currentList];
            newList.splice(index, 1);

            const newDefinitions = {
                ...rules.definitions,
                skills: {
                    ...rules.definitions.skills,
                    [category]: newList
                }
            };

            // 2. Add to Library (if not exists)
            const existingInLib = (rules.libraries.skills || []).find(l => l.name === skillName);
            const newLib = [...(rules.libraries.skills || [])];

            if (!existingInLib && skillName.trim() !== '') {
                const newLibEntry: LibrarySkillEntry = {
                    id: crypto.randomUUID(),
                    name: skillName,
                    description: '',
                    defaultCategory: category
                };
                newLib.push(newLibEntry);
            }

            // Sort Library
            newLib.sort((a, b) => a.name.localeCompare(b.name));

            onUpdate({
                ...rules,
                definitions: newDefinitions,
                libraries: {
                    ...rules.libraries,
                    skills: newLib
                }
            });
        }
        setDraggedItem(null);
    };

    // --- Filter Logic ---
    const getVisibleItems = () => {
        const currentNames = new Set<string>();
        Object.keys(rules.definitions.skills).forEach(cat => {
            rules.definitions.skills[cat].forEach(s => {
                if (s) currentNames.add(s.trim().toLowerCase());
            });
        });

        if (activeTab === 'skills') {
            return (rules.libraries.skills || []).filter(libItem =>
                libItem.isActive !== false && (libItem.isVariable || !currentNames.has(libItem.name.trim().toLowerCase()))
            );
        }
        if (activeTab === 'backgrounds') {
            return (rules.libraries.backgrounds || []).filter(b =>
                b.isActive !== false && !currentNames.has(b.name.trim().toLowerCase())
            );
        }
        if (activeTab === 'counters') {
            return (rules.libraries.counters || []).filter(c =>
                c.isActive !== false && !currentNames.has(c.name.trim().toLowerCase())
            );
        }
        return [];
    };

    const visibleLibrary = getVisibleItems();

    return (
        <div
            className={`w-80 shrink-0 sticky top-32 h-[calc(100vh-9rem)] bg-stone-950/80 border-l border-y border-stone-800 flex flex-col transition-colors rounded-l-md shadow-glass ${draggedItem?.type === 'admin_sheet_skill' ? 'bg-amber-950/20 border-amber-500/30' : ''}`}
            onDragOver={handleDragOver}
            onDrop={handleDropOnLibrary}
        >
            <div className="bg-stone-900 border-b border-stone-800 shadow-sm">
                <div className="p-3 font-bold text-stone-300 flex items-center gap-2 uppercase tracking-wider text-xs">
                    <BookOpen size={16} className="text-amber-500" />
                    Réserve
                </div>
                <SkillLibraryTabs activeTab={activeTab} setActiveTab={setActiveTab} />
            </div>

            {draggedItem?.type === 'admin_sheet_skill' && activeTab === 'skills' && (
                <div className="absolute inset-0 bg-stone-950/90 z-50 flex flex-col items-center justify-center border-4 border-dashed border-amber-500/50 m-2 rounded-sm pointer-events-none backdrop-blur-sm">
                    <Archive size={48} className="text-amber-500 mb-2 drop-shadow-glow" />
                    <span className="font-bold text-amber-500 text-lg font-serif tracking-widest uppercase">Archiver ici</span>
                </div>
            )}

            <div className="p-3 text-[10px] text-stone-500 border-b border-stone-800 bg-stone-950 italic font-medium">
                {activeTab === 'skills' && "Glissez vers une catégorie."}
                {activeTab === 'backgrounds' && "Glissez un Historique vers la fiche."}
                {activeTab === 'counters' && "Glissez un Compteur vers la fiche."}
            </div>

            <div className="flex-grow overflow-y-auto p-3 space-y-2 custom-scrollbar">
                {visibleLibrary.length === 0 ? (
                    <div className="text-center text-stone-600 italic mt-10 px-4 text-xs">
                        La réserve est vide.
                    </div>
                ) : (
                    visibleLibrary.map((item: any) => (
                        <div
                            key={item.id}
                            className="bg-stone-900 border border-stone-700/60 rounded-sm shadow-sm overflow-hidden hover:border-amber-500/30 transition-colors group/card"
                        >
                            <div
                                draggable
                                onDragStart={(e) => handleDragStart(e, 'admin_lib_skill', { name: item.name, data: item })}
                                className="p-2 cursor-grab active:cursor-grabbing transition-all flex justify-between items-center group/item hover:bg-stone-800"
                            >
                                <div className="flex items-center gap-2 overflow-hidden">
                                    <GripVertical size={14} className="text-stone-600 shrink-0 group-hover:text-stone-400 transition-colors" />
                                    <div className="flex flex-col min-w-0">
                                        <div className="flex items-center gap-1.5">
                                            <span className="font-bold text-xs truncate text-stone-300 group-hover:text-amber-500 transition-colors font-serif tracking-wide">
                                                {item.name}
                                            </span>
                                        </div>
                                        <div className="flex items-center gap-1">
                                            {item.isCustomized && (
                                                <div title="Cette compétence possède une surcharge pour cette campagne">
                                                    <PencilLine size={10} className="text-cyan-500 shrink-0" />
                                                </div>
                                            )}
                                            {item.isVariable && (
                                                <div className="flex items-center gap-0.5 text-[9px] text-amber-500 bg-amber-950/30 px-1 rounded-sm border border-amber-500/20" title="Compétence à variantes">
                                                    <Layers size={10} />
                                                </div>
                                            )}
                                            {item.mysticAbilityId && (
                                                <div className="flex items-center gap-0.5 text-[9px] text-amber-500 bg-amber-950/30 px-1 rounded-sm border border-amber-500/20" title="Compétence Mystique">
                                                    <Sparkles size={10} />
                                                </div>
                                            )}
                                            {item.isActive === false && (
                                                <div className="text-[9px] text-crimson-blood font-bold px-1 rounded-sm border border-crimson-blood/20 bg-crimson-blood/10">Inactif</div>
                                            )}
                                        </div>
                                    </div>
                                </div>
                                <div className="flex items-center gap-1">
                                    {activeTab === 'skills' && (
                                        <>
                                            {item.isCustomized && (
                                                <button
                                                    onClick={(e) => { e.stopPropagation(); handleReset(item.id); }}
                                                    className="p-1 text-stone-500 hover:text-amber-500 hover:bg-stone-700/50 rounded transition-all opacity-0 group-hover/card:opacity-100"
                                                    title="Réinitialiser aux valeurs d'origine"
                                                >
                                                    <RotateCcw size={12} />
                                                </button>
                                            )}
                                            <button
                                                onClick={(e) => { e.stopPropagation(); handleOpenEdit(item); }}
                                                className="p-1 text-stone-500 hover:text-amber-500 hover:bg-stone-700/50 rounded transition-all opacity-0 group-hover/card:opacity-100"
                                                title="Personnaliser pour cette campagne"
                                            >
                                                <Edit2 size={12} />
                                            </button>
                                        </>
                                    )}
                                    <ArrowRight size={14} className="text-stone-600 opacity-0 group-hover:opacity-100 shrink-0 mx-1 transition-all group-hover:translate-x-1 group-hover:text-amber-500" />
                                </div>
                            </div>

                            {/* Local Category Picker */}
                            <div className="px-2 pb-2 bg-stone-950/30 flex items-center justify-between border-t border-stone-800 pt-1">
                                {editingCategory === item.id ? (
                                    <select
                                        className="text-[10px] bg-stone-950 border border-stone-700 rounded-sm px-1 py-0.5 w-full outline-none focus:border-amber-500 text-stone-300"
                                        value={item.defaultCategory || ''}
                                        onChange={(e) => {
                                            const cat = e.target.value;
                                            const key = activeTab === 'skills' ? 'skills' : activeTab === 'backgrounds' ? 'backgrounds' : 'counters';
                                            const newList = rules.libraries[key].map((libItem: any) =>
                                                libItem.id === item.id ? { ...libItem, defaultCategory: cat } : libItem
                                            );
                                            onUpdate({
                                                ...rules,
                                                libraries: {
                                                    ...rules.libraries,
                                                    [key]: newList
                                                }
                                            });
                                            setEditingCategory(null);
                                        }}
                                        onBlur={() => setEditingCategory(null)}
                                    >
                                        <option value="">(Aucune catégorie)</option>
                                        {availableCategories.map(c => (
                                            <option key={c.id} value={c.id}>{c.label}</option>
                                        ))}
                                    </select>
                                ) : (
                                    <button
                                        onClick={() => setEditingCategory(item.id)}
                                        className="flex items-center gap-1 text-[10px] text-stone-500 hover:text-amber-500 font-medium truncate group/tag transition-colors w-full text-left"
                                    >
                                        <Tag size={10} className="shrink-0 text-stone-600 group-hover/tag:text-amber-500 transition-colors" />
                                        <span className="truncate">
                                            {item.defaultCategory ? (availableCategories.find(c => c.id === item.defaultCategory)?.label || item.defaultCategory) : "Définir catégorie..."}
                                        </span>
                                    </button>
                                )}
                            </div>
                        </div>
                    ))
                )}
            </div>

            <SkillCustomizationModal
                isOpen={isModalOpen}
                onClose={() => setIsModalOpen(false)}
                editingSkill={editingSkill}
                setEditingSkill={setEditingSkill}
                variantDraft={variantDraft}
                setVariantDraft={setVariantDraft}
                handleSave={handleSave}
                error={error}
                showCategoryHelp={showCategoryHelp}
                setShowCategoryHelp={setShowCategoryHelp}
                availableCategories={modalCategories}
                rules={rules}
            />
        </div>
    );
};

export default AdminSkillLibrarySidebar;

import React, { useState, useMemo } from 'react';
import { Search, Plus, Award, Save, UploadCloud, CheckCircle2, Circle, X } from 'lucide-react';
import { RulesData } from '../../../types/rules';
import { LibrarySpecializationEntry } from '../../../types';
import { smartIncludes } from '../../../utils/stringUtils';
import ThematicModal from '../../../components/ui/ThematicModal';
import { useNotification } from '../../../context/NotificationContext';
import { publishFileToGitHub } from '../../../services/githubService';
import { useItemUsageDetails } from '../../../hooks/admin/useItemUsageDetails';
import ConfirmationModal from '../../../components/ui/ConfirmationModal';

// Sub components
import { SpecListItem } from './specialization/SpecListItem';
import { SpecModalContent } from './specialization/SpecModalContent';

interface AdminSpecializationLibraryProps {
    rules: RulesData;
    onUpdate: (newRules: RulesData) => void;
    globalUsage?: Record<string, number>;
}

const AdminSpecializationLibrary: React.FC<AdminSpecializationLibraryProps> = ({ rules, onUpdate, globalUsage = {} }) => {
    const addLog = useNotification();
    const { usageDetailsCache, loadDetails } = useItemUsageDetails('global', 'specialization');

    const [searchTerm, setSearchTerm] = useState('');
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingEntry, setEditingEntry] = useState<LibrarySpecializationEntry | null>(null);
    const [error, setError] = useState<string | null>(null);
    const [skillSearch, setSkillSearch] = useState('');
    const [showPublishConfirm, setShowPublishConfirm] = useState(false);
    const [showDeleteConfirm, setShowDeleteConfirm] = useState<string | null>(null);

    const library = rules.libraries.specializations || [];

    const allSkills = useMemo(() => {
        const skills: { id: string, name: string }[] = [];

        // 1. From Categories (Base Skills Definitions - Legacy)
        if (rules.definitions && rules.definitions.skills) {
            Object.values(rules.definitions.skills).forEach(categorySkills => {
                categorySkills.forEach(skillName => {
                    if (skillName && skillName.trim() !== '') {
                        skills.push({ id: skillName, name: skillName });
                    }
                });
            });
        }

        // 2. From Official Library (Reserve)
        if (rules.libraries) {
            // Regular Skills
            if (rules.libraries.skills) {
                rules.libraries.skills.forEach(skill => {
                    if (!skills.some(s => s.id === skill.id)) {
                        skills.push({ id: skill.id, name: skill.name });
                    }
                });
            }

            // Mystic Abilities (Often used as parents for styles/specializations)
            if (rules.libraries.mysticAbilities) {
                rules.libraries.mysticAbilities.forEach(ma => {
                    if (!skills.some(s => s.id === ma.id)) {
                        skills.push({ id: ma.id, name: ma.name });
                    }
                });
            }

            // Backgrounds & Counters (Just in case)
            if (rules.libraries.backgrounds) {
                rules.libraries.backgrounds.forEach(bg => {
                    if (!skills.some(s => s.id === bg.id)) {
                        skills.push({ id: bg.id, name: bg.name });
                    }
                });
            }
        }

        return skills.sort((a, b) => a.name.localeCompare(b.name));
    }, [rules.definitions, rules.libraries.skills, rules.libraries.mysticAbilities, rules.libraries.backgrounds]);

    const filteredSkillsForModal = useMemo(() => {
        return allSkills.filter(s =>
            smartIncludes(s.name, skillSearch) || (editingEntry?.skillIds.includes(s.id))
        );
    }, [allSkills, skillSearch, editingEntry?.skillIds]);

    const filteredLibrary = useMemo(() => {
        return (rules.libraries.specializations || []).filter(s =>
            smartIncludes(s.name, searchTerm) ||
            (s.description && smartIncludes(s.description, searchTerm))
        ).sort((a, b) => a.name.localeCompare(b.name));
    }, [rules.libraries.specializations, searchTerm]);


    // Handlers
    const handleOpenNew = () => {
        setError(null);
        setEditingEntry({
            id: crypto.randomUUID(),
            name: '',
            skillIds: [],
            defaultMinLevel: 1,
            description: ''
        });
        setSkillSearch('');
        setIsModalOpen(true);
    };

    const handleOpenEdit = (entry: LibrarySpecializationEntry) => {
        setError(null);
        setSkillSearch('');
        setEditingEntry({ ...entry });
        setIsModalOpen(true);
    };

    const handleDelete = (id: string, name: string) => {
        setShowDeleteConfirm(id);
    };

    const confirmDelete = () => {
        if (!showDeleteConfirm) return;
        const currentList = rules.libraries.specializations || [];
        const deletedEntry = currentList.find(s => s.id === showDeleteConfirm);
        onUpdate({
            ...rules,
            libraries: {
                ...rules.libraries,
                specializations: currentList.filter(s => s.id !== showDeleteConfirm)
            }
        });
        addLog(`Spécialisation officielle "${deletedEntry?.name}" supprimée.`, 'info', 'settings');
        setShowDeleteConfirm(null);
    };

    const handleSave = () => {
        if (!editingEntry) return;

        if (!editingEntry.name.trim()) {
            setError("Le nom est requis.");
            return;
        }

        const currentList = rules.libraries.specializations || [];
        const duplicate = currentList.find(s =>
            s.id !== editingEntry.id &&
            s.name.trim().toLowerCase() === editingEntry.name.trim().toLowerCase()
        );

        if (duplicate) {
            setError("Une spécialisation portant ce nom existe déjà.");
            return;
        }

        let newList;
        const exists = currentList.some(s => s.id === editingEntry.id);
        if (exists) {
            newList = currentList.map(s => s.id === editingEntry.id ? editingEntry : s);
        } else {
            newList = [...currentList, editingEntry];
        }

        onUpdate({
            ...rules,
            libraries: {
                ...rules.libraries,
                specializations: newList
            }
        });

        addLog(`Spécialisation officielle "${editingEntry.name}" enregistrée.`, 'success', 'settings');
        setIsModalOpen(false);
        setEditingEntry(null);
    };

    const handleToggle = (id: string, currentlyActive: boolean) => {
        const currentList = rules.libraries.specializations || [];
        const newList = currentList.map(s => s.id === id ? { ...s, isActive: !currentlyActive } : s);
        onUpdate({ ...rules, libraries: { ...rules.libraries, specializations: newList } });
    };

    const handleBulkSelect = (active: boolean) => {
        const visibleIds = new Set(filteredLibrary.map(s => s.id));
        const currentList = rules.libraries.specializations || [];
        const newList = currentList.map(item =>
            visibleIds.has(item.id) ? { ...item, isActive: active } : item
        );
        onUpdate({
            ...rules,
            libraries: {
                ...rules.libraries,
                specializations: newList
            }
        });
    };

    const handlePublishClick = () => {
        const token = localStorage.getItem('GITHUB_TOKEN');
        const owner = localStorage.getItem('GITHUB_OWNER');
        const repo = localStorage.getItem('GITHUB_REPO');

        if (!token || !owner || !repo) {
            addLog("Veuillez d'abord configurer vos identifiants GitHub via le bouton 'Publier' du menu principal.", 'danger', 'settings');
            return;
        }
        setShowPublishConfirm(true);
    };

    const executePublish = async () => {
        const token = localStorage.getItem('GITHUB_TOKEN') || '';
        const owner = localStorage.getItem('GITHUB_OWNER') || '';
        const repo = localStorage.getItem('GITHUB_REPO') || '';

        try {
            const content = JSON.stringify({
                meta: {
                    version: rules.version,
                    date: new Date().toISOString(),
                    type: 'specializations'
                },
                data: rules.libraries.specializations || []
            }, null, 2);

            const result = await publishFileToGitHub(
                'public/data/specializations.json',
                content,
                `update(specs): Mise à jour bibliothèque spécialisations v${rules.version}`,
                { token, owner, repo, branch: 'main' }
            );

            if (result.success) {
                addLog('Bibliothèque de spécialisations publiée avec succès !', 'success', 'settings');
            } else {
                addLog("Erreur lors de la publication : " + result.message, 'danger', 'settings');
            }
        } catch (e) {
            addLog("Erreur inattendue lors de la publication : " + (e as Error).message, 'danger', 'settings');
        } finally {
            setShowPublishConfirm(false);
        }
    };

    return (
        <div className="flex flex-col h-full bg-[#fdfbf7] rounded-sm shadow-sm border border-[#bfae85]/50 overflow-hidden relative min-h-[500px]">
            {/* Toolbar */}
            <div className="p-4 bg-stone-100/30 border-b border-[#bfae85]/30 flex flex-col sm:flex-row justify-between items-center gap-4 shrink-0">
                <div className="relative flex-grow max-w-md w-full">
                    <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-[#4a3b32]/50" />
                    <input
                        className="w-full pl-9 pr-9 py-1.5 text-sm border border-[#bfae85]/50 rounded-sm focus:border-amber-500 outline-none text-[#1c1917] placeholder-[#4a3b32]/40 bg-white/80"
                        placeholder="Rechercher une spécialisation..."
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                    />
                    {searchTerm && (
                        <button
                            onClick={() => setSearchTerm('')}
                            className="absolute right-3 top-1/2 -translate-y-1/2 text-[#4a3b32]/40 hover:text-amber-600 transition-colors"
                        >
                            <X size={14} />
                        </button>
                    )}
                </div>

                {/* Bulk Actions */}
                {library.length > 0 && (
                    <div className="flex gap-4 px-4 py-2 bg-stone-50/50 border-b border-[#bfae85]/20">
                        <button
                            onClick={() => handleBulkSelect(true)}
                            className="text-[10px] font-bold text-amber-700 hover:text-amber-900 flex items-center gap-1.5 transition-colors uppercase tracking-wider"
                        >
                            <CheckCircle2 size={12} />
                            Tout activer {searchTerm ? `(${filteredLibrary.length})` : ''}
                        </button>
                        <button
                            onClick={() => handleBulkSelect(false)}
                            className="text-[10px] font-bold text-stone-500 hover:text-stone-700 flex items-center gap-1.5 transition-colors uppercase tracking-wider"
                        >
                            <Circle size={12} />
                            Tout désactiver {searchTerm ? `(${filteredLibrary.length})` : ''}
                        </button>
                    </div>
                )}
                <div className="flex gap-2 w-full sm:w-auto">
                    <button
                        onClick={handlePublishClick}
                        className="bg-purple-700 hover:bg-purple-800 text-white px-3 py-1.5 rounded-sm text-xs font-bold flex items-center gap-1 transition-colors shadow-sm whitespace-nowrap flex-1 sm:flex-initial justify-center"
                        title="Publier specializations.json"
                    >
                        <UploadCloud size={14} /> Publier JSON
                    </button>
                    <button
                        onClick={handleOpenNew}
                        className="bg-[#5c4d41] hover:bg-[#4a3b32] text-white px-3 py-1.5 rounded-sm text-xs font-bold flex items-center gap-1 transition-colors shadow-sm whitespace-nowrap flex-1 sm:flex-initial justify-center"
                    >
                        <Plus size={14} /> Créer
                    </button>
                </div>
            </div>

            {/* List */}
            <div className="flex-grow overflow-y-auto p-4 custom-scrollbar">
                {library.length === 0 ? (
                    <div className="text-center text-[#5c4d41]/60 py-10 italic px-4 text-sm flex flex-col items-center">
                        <Award size={48} className="opacity-20 mb-2" />
                        <p>La bibliothèque de spécialisations officielles est vide.</p>
                        <p className="text-xs mt-2 text-[#5c4d41]/80 italic">Ajoutez des spécialisations standards proposées à tous les joueurs.</p>
                    </div>
                ) : filteredLibrary.length === 0 ? (
                    <div className="text-center text-[#5c4d41]/60 py-10 italic">Aucun résultat.</div>
                ) : (
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
                        {filteredLibrary.map(entry => (
                            <SpecListItem
                                key={entry.id}
                                entry={entry}
                                isLocked={globalUsage[entry.id] > 0}
                                allSkills={allSkills}
                                onEdit={handleOpenEdit}
                                onDelete={handleDelete}
                                onToggle={handleToggle}
                                usageDetails={usageDetailsCache.get(entry.id)}
                                onLoadUsageDetails={loadDetails}
                            />
                        ))}
                    </div>
                )}
            </div>

            {/* Edit Modal */}
            <ThematicModal
                isOpen={isModalOpen && !!editingEntry}
                onClose={() => setIsModalOpen(false)}
                title={library.some(e => e.id === editingEntry?.id) ? 'Éditer Spécialisation' : 'Nouvelle Spécialisation'}
                icon={<Award size={20} />}
                size="md"
                footer={
                    <>
                        <button onClick={() => setIsModalOpen(false)} className="px-4 py-2 text-[#5c4d41] hover:bg-stone-200/50 rounded-sm font-bold">Annuler</button>
                        <button onClick={handleSave} className="px-6 py-2 bg-[#5c4d41] text-white rounded-sm font-bold shadow-md hover:bg-[#4a3b32] flex items-center gap-2">
                            <Save size={16} /> Enregistrer
                        </button>
                    </>
                }
            >
                {editingEntry && (
                    <SpecModalContent
                        editingEntry={editingEntry}
                        setEditingEntry={setEditingEntry}
                        skillSearch={skillSearch}
                        setSkillSearch={setSkillSearch}
                        filteredSkillsForModal={filteredSkillsForModal}
                        error={error}
                    />
                )}
            </ThematicModal>

            <ConfirmationModal
                isOpen={showPublishConfirm}
                onClose={() => setShowPublishConfirm(false)}
                onConfirm={executePublish}
                title="Publier les spécialisations ?"
                message="Vous allez mettre à jour le fichier specializations.json public."
                confirmLabel="Publier"
                type="warning"
            />

            <ConfirmationModal
                isOpen={!!showDeleteConfirm}
                onClose={() => setShowDeleteConfirm(null)}
                onConfirm={confirmDelete}
                title="Supprimer la spécialisation ?"
                message="Cette action supprimera définitivement l'entrée de la base admin."
                confirmLabel="Supprimer"
                type="danger"
            />
        </div>
    );
};

export default AdminSpecializationLibrary;

import React from 'react';
import { RulesData } from '../../../types/rules';
import { Search, Plus, BookOpen, Filter, Coins, Layers, ArrowDownAZ, ArrowUpAZ, UploadCloud, CheckCircle2, Circle, Globe, X, Zap, Activity, TrendingUp, ClipboardList } from 'lucide-react';
import TraitCard from '../../../components/trait-library/TraitCard';
import TraitForm from '../../../components/trait-library/TraitForm';
import TriStateChip from '../../../components/ui/TriStateChip';
import ConfirmationModal from '../../../components/ui/ConfirmationModal';
import { useAdminTraitLibrary } from '../../../hooks/admin/useAdminTraitLibrary';
import { useItemUsageDetails } from '../../../hooks/admin/useItemUsageDetails';

interface AdminTraitLibraryProps {
    rules: RulesData;
    onUpdate: (newRules: RulesData) => void;
    globalUsage?: Record<string, number>;
}

const AdminTraitLibrary: React.FC<AdminTraitLibraryProps> = ({ rules, onUpdate, globalUsage = {} }) => {
    const {
        // States
        searchTerm, setSearchTerm,
        selectedTags, setSelectedTags,
        activeFilter, setActiveFilter,
        sourceFilter, setSourceFilter,
        typeFilter, setTypeFilter,
        sortBy, setSortBy,
        sortOrder, setSortOrder,
        isModalOpen, setIsModalOpen,
        editForm, setEditForm,
        tagInput, setTagInput,
        error,
        showPublishConfirm, setShowPublishConfirm,
        showDeleteConfirm, setShowDeleteConfirm,
        publishResult, setPublishResult,
        showConfigAlert, setShowConfigAlert,

        // Derived Data
        library,
        processedList,
        allAvailableTags,
        allSkills,
        allAttributes,
        allCounters,
        allFormulas,

        // Property filters
        filterEffects, setFilterEffects,
        filterCounter, setFilterCounter,
        filterXP, setFilterXP,
        filterVariants, setFilterVariants,

        // Audit mode
        auditMode, setAuditMode,

        // Handlers
        handleOpenNew,
        handleOpenEdit,
        handleDelete,
        confirmDelete,
        handleSave,
        handleBulkSelect,
        handleToggleActive,
        handlePublishClick,
        executePublish,
        addTag,
        removeTag,
        addEffect,
        updateEffect,
        updateEffectFields,
        removeEffect
    } = useAdminTraitLibrary({ rules, onUpdate, globalUsage });
    const { usageDetailsCache, loadDetails } = useItemUsageDetails('global', 'trait');

    const hasActiveFilters = activeFilter !== null || sourceFilter !== null || typeFilter !== null
        || filterEffects || filterCounter || filterXP || filterVariants || auditMode !== null;


    return (
        <div className="bg-white p-6 rounded-lg shadow-sm border border-slate-200 h-[calc(100vh-120px)] flex flex-col">
            <div className="flex justify-between items-center mb-6">
                <div>
                    <h2 className="text-2xl font-bold text-slate-900 flex items-center gap-2">
                        <BookOpen className="text-blue-600" /> Bibliothèque de Traits Officiels
                    </h2>
                    <p className="text-slate-500 text-sm">Gérez ici les Avantages et Désavantages qui seront proposés aux joueurs.</p>
                </div>
                <div className="flex gap-2">
                    <button
                        onClick={handlePublishClick}
                        className="bg-purple-700 text-white px-3 py-2 rounded font-bold hover:bg-purple-800 transition-colors flex items-center gap-2 text-sm"
                        title="Publier traits.json"
                    >
                        <UploadCloud size={16} /> Publier JSON
                    </button>
                    <button
                        onClick={handleOpenNew}
                        className="bg-slate-900 text-white px-4 py-2 rounded font-bold hover:bg-slate-800 transition-colors flex items-center gap-2"
                    >
                        <Plus size={18} /> Nouveau Trait
                    </button>
                </div>

            </div>

            {/* Toolbar & Filters */}
            <div className="flex flex-wrap gap-3 items-center mb-4 p-3 bg-slate-50 rounded border border-slate-200">
                {/* Row 1: Search + Audit */}
                <div className="flex items-center gap-3 w-full">
                    <div className="relative flex-grow max-w-sm">
                        <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                        <input
                            className="w-full pl-9 pr-9 py-2 text-sm border border-slate-300 rounded focus:border-blue-500 outline-none"
                            placeholder="Rechercher..."
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                        />
                        {searchTerm && (
                            <button
                                onClick={() => setSearchTerm('')}
                                className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-blue-600 transition-colors"
                            >
                                <X size={14} />
                            </button>
                        )}
                    </div>

                    {/* Audit Dropdown */}
                    <div className="flex items-center gap-1.5">
                        <ClipboardList size={15} className={auditMode ? 'text-violet-600' : 'text-slate-400'} />
                        <select
                            value={auditMode ?? ''}
                            onChange={(e) => setAuditMode((e.target.value || null) as typeof auditMode)}
                            className={`text-xs border rounded py-1.5 px-2 outline-none cursor-pointer ${auditMode
                                    ? 'border-violet-400 bg-violet-50 text-violet-700 font-semibold'
                                    : 'border-slate-300 bg-white text-slate-600'
                                }`}
                        >
                            <option value="">Audit…</option>
                            <option value="incomplete">📋 À compléter</option>
                            <option value="complex">⚡ Mécaniques formules</option>
                            <option value="popular">📊 Favoris des joueurs</option>
                            <option value="unused">👻 Jamais utilisés</option>
                            <option value="duplicates">🔁 Doublons potentiels</option>
                        </select>
                    </div>

                    {/* Sort buttons */}
                    <div className="ml-auto flex gap-2 border-l border-slate-300 pl-3">
                        <button onClick={() => { setSortBy('name'); setSortOrder(o => o === 'asc' ? 'desc' : 'asc'); }} className={`p-2 rounded border ${sortBy === 'name' ? 'bg-blue-50 border-blue-200 text-blue-700' : 'bg-white border-slate-300 text-slate-600'}`}>
                            {sortBy === 'name' && sortOrder === 'asc' ? <ArrowDownAZ size={16} /> : <ArrowUpAZ size={16} />}
                        </button>
                        <button onClick={() => { setSortBy('cost'); setSortOrder(o => o === 'asc' ? 'desc' : 'asc'); }} className={`p-2 rounded border ${sortBy === 'cost' ? 'bg-blue-50 border-blue-200 text-blue-700' : 'bg-white border-slate-300 text-slate-600'}`}>
                            <Coins size={16} />
                        </button>
                    </div>
                </div>

                {/* Row 2: Boolean chips + Icon pills */}
                <div className="flex flex-wrap items-center gap-2 w-full">
                    <TriStateChip label="Actifs" value={activeFilter} onChange={setActiveFilter} icon={CheckCircle2} activeColor="green" />
                    <TriStateChip label="Officiels" value={sourceFilter} onChange={setSourceFilter} icon={Globe} activeColor="indigo" />
                    <TriStateChip label="Avantages" value={typeFilter} onChange={setTypeFilter} icon={Layers} activeColor="blue" />

                    <span className="w-px h-5 bg-slate-300 mx-1" />

                    {/* Property icon pills */}
                    {([
                        { icon: Zap, label: 'Effets', active: filterEffects, toggle: () => setFilterEffects(v => !v), color: 'text-amber-600', activeBg: 'bg-amber-50 border-amber-400 text-amber-700' },
                        { icon: Activity, label: 'Compteur', active: filterCounter, toggle: () => setFilterCounter(v => !v), color: 'text-blue-500', activeBg: 'bg-blue-50 border-blue-400 text-blue-700' },
                        { icon: TrendingUp, label: 'XP', active: filterXP, toggle: () => setFilterXP(v => !v), color: 'text-emerald-500', activeBg: 'bg-emerald-50 border-emerald-400 text-emerald-700' },
                        { icon: Layers, label: 'Variantes', active: filterVariants, toggle: () => setFilterVariants(v => !v), color: 'text-purple-500', activeBg: 'bg-purple-50 border-purple-400 text-purple-700' },
                    ] as const).map(({ icon: Icon, label, active, toggle, color, activeBg }) => (
                        <button
                            key={label}
                            onClick={toggle}
                            title={label}
                            className={`flex items-center gap-1 px-2.5 py-1 rounded-full text-[11px] font-bold border transition-all select-none ${active ? activeBg : `bg-white border-slate-300 ${color} hover:border-slate-400 hover:bg-slate-50`
                                }`}
                        >
                            <Icon size={12} />
                            {label}
                        </button>
                    ))}

                    {hasActiveFilters && (
                        <button
                            onClick={() => {
                                setActiveFilter(null); setSourceFilter(null); setTypeFilter(null);
                                setFilterEffects(false); setFilterCounter(false); setFilterXP(false); setFilterVariants(false);
                                setAuditMode(null);
                            }}
                            className="text-[10px] font-bold text-red-500 hover:text-red-700 ml-auto"
                        >
                            RESET
                        </button>
                    )}
                </div>
            </div>

            {/* Tag Filter */}
            {
                allAvailableTags.length > 0 && (
                    <div className="flex flex-wrap gap-2 mb-4 items-center pl-1">
                        <Filter size={14} className="text-slate-400" />
                        {allAvailableTags.map(tag => (
                            <button
                                key={tag}
                                onClick={() => setSelectedTags(prev => prev.includes(tag) ? prev.filter(t => t !== tag) : [...prev, tag])}
                                className={`text-xs px-2 py-0.5 rounded-full border transition-colors ${selectedTags.includes(tag) ? 'bg-blue-600 text-white border-blue-600' : 'bg-white text-slate-600 border-slate-300 hover:border-slate-400'}`}
                            >
                                {tag}
                            </button>
                        ))}
                        {selectedTags.length > 0 && <button onClick={() => setSelectedTags([])} className="text-xs text-red-500 hover:underline">Effacer</button>}
                    </div>
                )
            }

            {/* Bulk Actions */}
            {library.length > 0 && (
                <div className="flex gap-4 mb-4 px-1">
                    <button
                        onClick={() => handleBulkSelect(true)}
                        className="text-xs font-bold text-blue-600 hover:text-blue-800 flex items-center gap-1.5 transition-colors"
                    >
                        <CheckCircle2 size={14} />
                        Tout activer {searchTerm ? `(${processedList.length})` : ''}
                    </button>
                    <button
                        onClick={() => handleBulkSelect(false)}
                        className="text-xs font-bold text-slate-500 hover:text-slate-700 flex items-center gap-1.5 transition-colors"
                    >
                        <Circle size={14} />
                        Tout désactiver {searchTerm ? `(${processedList.length})` : ''}
                    </button>
                </div>
            )}

            {/* List */}
            <div className="flex-grow overflow-y-auto bg-slate-50 border border-slate-200 rounded p-2">
                {library.length === 0 && <div className="text-center text-slate-400 py-20 italic">La bibliothèque est vide.</div>}

                <div className="space-y-1">
                    {processedList.map(entry => (
                        <div key={entry.id} className="relative group">
                            <div className="flex items-center gap-1 group">
                                {/* 1. Toggle (Fixed width) */}
                                <div className="w-8 flex justify-center shrink-0">
                                    <input
                                        type="checkbox"
                                        checked={entry.isActive !== false}
                                        onChange={() => handleToggleActive(entry.id)}
                                        className="w-4 h-4 text-blue-600 rounded cursor-pointer"
                                        title={entry.isActive !== false ? "Désactiver (Retirer de la campagne)" : "Activer (Ajouter à la campagne)"}
                                    />
                                </div>

                                <div className="flex-grow">
                                    <TraitCard
                                        entry={entry}
                                        isEditable={true}
                                        isSelected={false}
                                        isActive={entry.isActive !== false}
                                        onEdit={handleOpenEdit}
                                        onDelete={handleDelete}
                                        showMultiSelect={false}
                                        source={entry.isGlobal ? 'official' : 'local'}
                                        isLocked={!!globalUsage[entry.id]}
                                        usageDetails={usageDetailsCache.get(entry.id)}
                                        onLoadUsageDetails={loadDetails}
                                    />
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>

            {/* Modal - Reusing the Player Component */}
            {
                isModalOpen && editForm && (
                    <TraitForm
                        editForm={editForm}
                        library={library}
                        allSkills={allSkills}
                        allAttributes={allAttributes}
                        allCounters={allCounters}
                        allFormulas={allFormulas}
                        tagInput={tagInput}
                        error={error}
                        setEditForm={setEditForm}
                        setTagInput={setTagInput}
                        onClose={() => setIsModalOpen(false)}
                        onSave={handleSave}
                        addTag={addTag}
                        removeTag={removeTag}
                        addEffect={addEffect}
                        updateEffect={updateEffect}
                        removeEffect={removeEffect}
                    />
                )
            }

            <ConfirmationModal
                isOpen={showPublishConfirm}
                onClose={() => setShowPublishConfirm(false)}
                onConfirm={executePublish}
                title="Publier les traits ?"
                message="Vous allez mettre à jour le fichier traits.json public. Cela affectera tous les joueurs lors de leur prochaine mise à jour."
                confirmLabel="Publier"
                type="warning"
            />

            <ConfirmationModal
                isOpen={!!showDeleteConfirm}
                onClose={() => setShowDeleteConfirm(null)}
                onConfirm={confirmDelete}
                title="Supprimer le trait ?"
                message="Cette action supprimera définitivement le trait de la base admin."
                confirmLabel="Supprimer"
                type="danger"
            />

            <ConfirmationModal
                isOpen={!!publishResult}
                onClose={() => setPublishResult(null)}
                onConfirm={() => setPublishResult(null)}
                title={publishResult?.success ? "Publication Réussie" : "Échec de la Publication"}
                message={publishResult?.message || ""}
                confirmLabel="Fermer"
                type={publishResult?.success ? "success" : "danger"}
                cancelLabel=""
            />

            <ConfirmationModal
                isOpen={showConfigAlert}
                onClose={() => setShowConfigAlert(false)}
                onConfirm={() => setShowConfigAlert(false)}
                title="Configuration Manquante"
                message="Veuillez d'abord configurer vos identifiants GitHub via le bouton 'Publier' du menu principal."
                confirmLabel="Compris"
                type="info"
                cancelLabel=""
            />
        </div>
    );
};

export default AdminTraitLibrary;

import React from 'react';
import { GraduationCap, Save, AlertOctagon, X, Sparkles } from 'lucide-react';
import ThematicModal from '../../../components/ui/ThematicModal';
import { RulesData } from '../../../types/rules';

interface SkillCustomizationModalProps {
    isOpen: boolean;
    onClose: () => void;
    editingSkill: any;
    setEditingSkill: (skill: any) => void;
    variantDraft: string;
    setVariantDraft: (draft: string) => void;
    handleSave: () => void;
    error: string | null;
    showCategoryHelp: boolean;
    setShowCategoryHelp: (show: boolean) => void;
    availableCategories: { code: string; label: string }[];
    rules: RulesData;
}

export const SkillCustomizationModal: React.FC<SkillCustomizationModalProps> = ({
    isOpen,
    onClose,
    editingSkill,
    setEditingSkill,
    variantDraft,
    setVariantDraft,
    handleSave,
    error,
    showCategoryHelp,
    setShowCategoryHelp,
    availableCategories,
    rules
}) => {
    if (!isOpen || !editingSkill) return null;

    return (
        <ThematicModal
            isOpen={isOpen}
            onClose={onClose}
            title="Personnalisation Campagne"
            icon={<GraduationCap size={20} />}
            size={showCategoryHelp ? 'lg' : 'md'}
            footer={
                <>
                    <button onClick={onClose} className="px-4 py-2 text-stone-400 hover:text-stone-200 font-bold hover:bg-stone-800 rounded">Annuler</button>
                    <button onClick={handleSave} className="px-6 py-2 bg-amber-600 text-stone-900 rounded font-bold shadow hover:bg-amber-500 flex items-center gap-2">
                        <Save size={16} /> Enregistrer
                    </button>
                </>
            }
        >
            <div className="flex flex-col gap-5 py-2">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="flex flex-col gap-4 text-stone-300">
                        <div>
                            <label htmlFor="skill-name" className="block text-xs font-bold text-stone-500 uppercase mb-1">Nom</label>
                            <input
                                id="skill-name"
                                className="w-full bg-stone-900 border border-stone-700 rounded px-3 py-2 font-bold focus:border-amber-500 outline-none text-stone-100"
                                value={editingSkill.name}
                                onChange={(e) => setEditingSkill({ ...editingSkill, name: e.target.value })}
                            />
                        </div>
                        <div className="bg-amber-950/20 border border-amber-500/20 rounded p-3 flex items-center gap-3">
                            <input
                                type="checkbox"
                                id="isVariableSkill"
                                className="w-4 h-4 text-amber-600 rounded bg-stone-900 border-stone-700 cursor-pointer"
                                checked={editingSkill.isVariable || false}
                                onChange={(e) => setEditingSkill({ ...editingSkill, isVariable: e.target.checked })}
                            />
                            <label htmlFor="isVariableSkill" className="cursor-pointer select-none">
                                <span className="block text-sm font-bold text-amber-500 leading-tight">Variantes requises</span>
                                <span className="block text-[10px] text-amber-700/70 leading-tight italic">Ex: "Artisanat : Forge"</span>
                            </label>
                        </div>

                        <div className={`bg-stone-900/50 border border-stone-700 rounded p-3 flex flex-col gap-2 transition-all ${editingSkill.mysticAbilityId ? 'ring-1 ring-amber-500/30 border-amber-500/30' : ''}`}>
                            <div className="flex items-center gap-3">
                                <input
                                    type="checkbox"
                                    id="isMysticAbility"
                                    className="w-4 h-4 text-amber-600 rounded bg-stone-900 border-stone-700 cursor-pointer disabled:opacity-50 disabled:cursor-not-allowed"
                                    checked={!!editingSkill.mysticAbilityId}
                                    disabled={!rules.libraries.mysticAbilities?.length}
                                    onChange={(e) => {
                                        if (e.target.checked) {
                                            const firstId = rules.libraries.mysticAbilities?.[0]?.id || '';
                                            if (firstId) {
                                                setEditingSkill({ ...editingSkill, mysticAbilityId: firstId });
                                            }
                                        } else {
                                            const { mysticAbilityId: maId, ...rest } = editingSkill;
                                            setEditingSkill(rest);
                                        }
                                    }}
                                />
                                <label htmlFor="isMysticAbility" className="cursor-pointer select-none">
                                    <span className="block text-sm font-bold text-stone-200 leading-tight flex items-center gap-1.5">
                                        Lien Mystique <Sparkles size={12} className="text-amber-500" />
                                    </span>
                                    <span className="block text-[10px] text-stone-500 leading-tight">Lier à une habilité magique/martiale</span>
                                </label>
                            </div>
                            {editingSkill.mysticAbilityId !== undefined && rules.libraries.mysticAbilities && rules.libraries.mysticAbilities.length > 0 && (
                                <select
                                    className="w-full bg-stone-950 border border-stone-700 rounded px-2 py-1 text-xs focus:border-amber-500 outline-none text-amber-500 font-bold"
                                    value={editingSkill.mysticAbilityId || ""}
                                    onChange={(e) => setEditingSkill({ ...editingSkill, mysticAbilityId: e.target.value })}
                                >
                                    <option value="">-- Choisir une habilité --</option>
                                    {rules.libraries.mysticAbilities?.map(ma => (
                                        <option key={ma.id} value={ma.id}>{ma.name}</option>
                                    ))}
                                </select>
                            )}
                        </div>

                        {editingSkill.isVariable && (
                            <div className="animate-in fade-in slide-in-from-top-2 duration-200">
                                <label htmlFor="skill-variants" className="block text-xs font-bold text-stone-500 uppercase mb-1">Suggestions de variantes</label>
                                <input
                                    id="skill-variants"
                                    className="w-full bg-stone-900 border border-stone-700 rounded px-3 py-2 text-sm focus:border-amber-500 outline-none text-stone-200"
                                    placeholder="Forge, Menuiserie, Peinture..."
                                    value={variantDraft}
                                    onChange={(e) => setVariantDraft(e.target.value)}
                                />
                            </div>
                        )}
                    </div>
                    <div className="flex flex-col">
                        <label htmlFor="skill-description" className="block text-xs font-bold text-stone-500 uppercase mb-1">Description</label>
                        <textarea
                            id="skill-description"
                            className="w-full flex-grow bg-stone-900 border border-stone-700 rounded px-3 py-2 text-sm focus:border-amber-500 outline-none resize-none min-h-[120px] text-stone-300"
                            value={editingSkill.description || ''}
                            onChange={(e) => setEditingSkill({ ...editingSkill, description: e.target.value })}
                            placeholder="Description de la compétence..."
                        />
                    </div>
                </div>

                {error && (
                    <div className="bg-red-950/30 text-red-400 text-xs p-3 rounded border border-red-900/50 font-bold flex items-center gap-2">
                        <AlertOctagon size={16} /> {error}
                    </div>
                )}
            </div>

            {showCategoryHelp && (
                <div className="w-full lg:w-72 shrink-0 animate-in slide-in-from-right-4 duration-300 bg-stone-900 p-4 rounded border border-stone-800 shadow-xl">
                    <div className="flex justify-between items-center mb-2 pb-2 border-b border-stone-800">
                        <h4 className="font-bold text-amber-500 text-xs uppercase tracking-wider">Codes Catégories</h4>
                        <button onClick={() => setShowCategoryHelp(false)} className="text-stone-500 hover:text-stone-300"><X size={14} /></button>
                    </div>
                    <div className="space-y-2 text-[10px] custom-scrollbar max-h-60 overflow-y-auto">
                        {availableCategories.map(cat => (
                            <div key={cat.code} className="grid grid-cols-[60px_1fr] gap-2 items-start border-b border-stone-800/50 pb-1">
                                <code className="bg-stone-950 px-1 rounded font-mono text-amber-500/70 border border-amber-500/10 text-[9px] truncate">{cat.code}</code>
                                <span className="text-stone-400 font-medium">{cat.label}</span>
                            </div>
                        ))}
                    </div>
                </div>
            )}
        </ThematicModal>
    );
};

import React, { useState, useRef } from 'react';
import { RulesData } from '../../../../types/rules';
import { LibraryBackgroundEntry } from '../../../../types/system';
import { Layers, Lock, Edit2, Trash2 } from 'lucide-react';
import { PortalTooltip } from '../../../../components/ui/PortalTooltip';
import { ItemUsageDetail } from '../../../../types/usageTypes';
import { UsageLockedTooltip } from '../UsageLockedTooltip';

interface BackgroundLibraryItemProps {
    item: LibraryBackgroundEntry;
    isPlaced: boolean;
    isLocked: boolean;
    onToggleActive: (id: string, current: boolean) => void;
    handleOpenEdit: (item: LibraryBackgroundEntry) => void;
    handleDelete: (id: string) => void;
    rules: RulesData;
    usageDetails?: ItemUsageDetail;
    onLoadUsageDetails?: (id: string) => void;
}

export const BackgroundLibraryItem: React.FC<BackgroundLibraryItemProps> = ({
    item,
    isPlaced,
    isLocked,
    onToggleActive,
    handleOpenEdit,
    handleDelete,
    rules,
    usageDetails,
    onLoadUsageDetails
}) => {
    const hasVariants = item.variants && item.variants.length > 0;
    const [showVariantsTooltip, setShowVariantsTooltip] = useState(false);
    const [showLockTooltip, setShowLockTooltip] = useState(false);
    const anchorRef = useRef<HTMLDivElement>(null);
    const lockIconRef = useRef<HTMLDivElement>(null);

    return (
        <div className={`bg-white border rounded p-2 transition-shadow group flex items-center gap-2 ${item.isActive === false ? 'opacity-60 grayscale border-slate-200' : 'hover:shadow-md border-slate-300'}`}>
            {/* 1. Toggle */}
            <div className="w-8 flex justify-center shrink-0">
                <input
                    type="checkbox"
                    checked={item.isActive !== false}
                    onChange={() => onToggleActive(item.id, item.isActive !== false)}
                    className="w-4 h-4 text-purple-600 rounded cursor-pointer"
                    title={item.isActive !== false ? "Désactiver" : "Activer"}
                />
            </div>

            {/* 2. Content */}
            <div className="flex-grow overflow-hidden pr-2">
                <div className="flex items-center gap-2 overflow-hidden">
                    <div className={`font-bold truncate text-sm ${item.isActive === false ? 'text-slate-500 line-through' : 'text-slate-800'}`} title={item.name}>
                        {item.name}
                    </div>
                </div>
                <div className="flex items-center gap-1.5 mt-0.5">
                    {item.isVariable && (
                        <div
                            ref={anchorRef}
                            className="relative"
                            onMouseEnter={() => setShowVariantsTooltip(true)}
                            onMouseLeave={() => setShowVariantsTooltip(false)}
                            title={!hasVariants ? "Variable" : undefined}
                        >
                            <Layers
                                size={11}
                                className="text-purple-400 shrink-0"
                            />

                            {hasVariants && (
                                <PortalTooltip
                                    anchorRef={anchorRef}
                                    isOpen={showVariantsTooltip}
                                    title="Variantes (Réserve)"
                                >
                                    <div className="flex flex-wrap gap-1">
                                        {item.variants?.map((v, i) => (
                                            <span key={i} className="bg-slate-700 px-1 rounded-sm border border-slate-600">{v}</span>
                                        ))}
                                    </div>
                                </PortalTooltip>
                            )}
                        </div>
                    )}
                    {isLocked && (
                        <div
                            ref={lockIconRef}
                            onMouseEnter={() => {
                                if (isLocked && !isPlaced && onLoadUsageDetails) {
                                    onLoadUsageDetails(item.id);
                                }
                                setShowLockTooltip(true);
                            }}
                            onMouseLeave={() => setShowLockTooltip(false)}
                            className="relative flex items-center shrink-0"
                            title={isPlaced ? "Utilisé dans cette campagne" : undefined}
                        >
                            <Lock size={11} className="text-amber-500" />
                            <UsageLockedTooltip
                                anchorRef={lockIconRef}
                                isOpen={showLockTooltip}
                                isLocked={isLocked}
                                isPlaced={isPlaced}
                                usageDetails={usageDetails}
                            />
                        </div>
                    )}

                    {item.defaultCategory && (
                        <span
                            className="text-[9px] font-black bg-slate-100 text-slate-500 border border-slate-200 px-1 rounded-sm uppercase tracking-tighter shrink-0"
                            title={`Placement : ${rules.definitions.skillCategories?.find(c => c.id === item.defaultCategory)?.label || item.defaultCategory}`}
                        >
                            {rules.definitions.skillCategories?.find(c => c.id === item.defaultCategory)?.label || item.defaultCategory}
                        </span>
                    )}

                    {item.description && (
                        <div className="text-[10px] text-slate-500 italic truncate" title={item.description}>
                            {item.description}
                        </div>
                    )}
                </div>
            </div>

            {/* 4. Actions */}
            <div className="w-16 flex justify-end gap-1 opacity-0 group-hover:opacity-100 transition-opacity shrink-0">
                <button onClick={() => handleOpenEdit(item)} className="text-blue-600 hover:bg-blue-50 p-1 rounded" title="Modifier"><Edit2 size={14} /></button>
                <button
                    onClick={() => handleDelete(item.id)}
                    disabled={isLocked}
                    className={`p-1 rounded ${isLocked ? 'text-slate-300' : 'text-red-500 hover:bg-red-50'}`}
                    title={!isLocked ? "Supprimer" : undefined}
                >
                    <Trash2 size={14} />
                </button>
            </div>
        </div>
    );
};

