import React from 'react';
import { CharacterSheetData, TraitEntry, LibraryEntry } from '../types';
import { BookOpen, X } from 'lucide-react';
import TraitLibrary from './TraitLibrary';
import { useCharacter } from '../context/CharacterContext';

import { useRules } from '../context/RulesContext';

// Imports Refactorisés
import { LEGACY_SKILL_MAP } from '../utils/migrations/migrateSkills';
import NotebookInput from './shared/NotebookInput';
import CharacterImageWidget from './shared/CharacterImageWidget';
import { Page2SectionHeader } from './sheet/page2/Page2Components';
import { useTraitEditor } from '../hooks/sheet/useTraitEditor';
import { useReputationManager } from '../hooks/sheet/useReputationManager';
import MysticSkillWizard from './sheet/ui/MysticSkillWizard';
import MasterSkillWizard from './sheet/ui/MasterSkillWizard';
import TraitEditModal from './sheet/page2/TraitEditModal';

// Nouveaux composants extraits
import { IdentityBoxes, NotesBoxes, MoneyBoxes } from './sheet/page2/Page2SidebarBoxes';
import { TraitsColumn } from './sheet/page2/TraitsColumn';

interface Props {
    isLandscape?: boolean;
}

const CharacterSheetPage2: React.FC<Props> = ({ isLandscape = false }) => {
    const { data, updateData: onChange, addLog: onAddLog, recordXPTransaction } = useCharacter();
    const { rules } = useRules();

    // State déclaré avant useTraitEditor car le callback en a besoin
    const [masterSkillWizard, setMasterSkillWizard] = React.useState<{ isOpen: boolean, traitName: string, traitType: 'avantages' | 'desavantages' } | null>(null);
    // Ref pour capturer le type de cible avant que multiSelectTarget soit remis à null
    const multiSelectTargetRef = React.useRef<'avantages' | 'desavantages' | null>(null);

    const {
        multiSelectTarget, setMultiSelectTarget,
        removeTrait,
        handleMultiAdd,
        applyMasterSkill
    } = useTraitEditor(data, rules, onChange, onAddLog, recordXPTransaction, (traitName, _pendingAdd) => {
        // Ouvrir le wizard master_skill après ajout du trait
        setMasterSkillWizard({ isOpen: true, traitName, traitType: multiSelectTargetRef.current || 'avantages' });
    });

    // Synchroniser la ref avec l'état
    React.useEffect(() => {
        if (multiSelectTarget !== null) {
            multiSelectTargetRef.current = multiSelectTarget;
        }
    }, [multiSelectTarget]);

    const {
        updateReputationEntry,
        handleReputationKeyDown
    } = useReputationManager(data, onChange, onAddLog);

    // Mystic Wizard State
    const [wizardState, setWizardState] = React.useState<{ isOpen: boolean, mysticAbilityId: string | null, mysticAbilityName: string }>({
        isOpen: false,
        mysticAbilityId: null,
        mysticAbilityName: ''
    });

    const [editingTrait, setEditingTrait] = React.useState<{ type: 'avantages' | 'desavantages', index: number, trait: TraitEntry } | null>(null);

    // Wrapped handleMultiAdd to detect Mystic Ability link
    const handleMultiAddWrapper = (instances: { entry: LibraryEntry; variant?: string; cost?: string }[]) => {
        let mysticId: string | undefined;
        let mysticName: string | undefined;

        // Pre-process instances to inject missing mysticAbilityId
        const processedInstances = instances.map(instance => {
            // 1. Existing ID
            if (instance.entry.mysticAbilityId) {
                mysticId = instance.entry.mysticAbilityId;
                mysticName = instance.entry.name;
                return instance;
            }

            // 2. Fallback: Search by Name
            if (rules?.libraries?.mysticAbilities && rules.configurations?.creation?.mysticAbilities?.active) {
                const match = rules.libraries.mysticAbilities.find(
                    ma => ma.name.toLowerCase().trim() === instance.entry.name.toLowerCase().trim()
                );
                if (match) {
                    mysticId = match.id;
                    mysticName = match.name;
                    // Return patched instance
                    return {
                        ...instance,
                        entry: {
                            ...instance.entry,
                            mysticAbilityId: match.id
                        }
                    };
                }
            }
            return instance;
        });

        // Add the processed instances (with patched IDs)
        handleMultiAdd(processedInstances);

        if (mysticId && mysticName && rules?.configurations?.creation?.mysticAbilities?.active) {
            // Open Wizard
            setTimeout(() => {
                setWizardState({
                    isOpen: true,
                    mysticAbilityId: mysticId!,
                    mysticAbilityName: mysticName!
                });
            }, 100);
        }
    };

    const handleWizardConfirm = (skillIds: string[]) => {
        if (!wizardState.mysticAbilityId) return;

        // Add skills to sheet
        const newSkills = { ...data.skills };
        const newLibrary = [...(data.skillLibrary || [])];
        const libSkills = rules?.libraries?.skills || [];

        let addedCount = 0;

        skillIds.forEach(id => {
            const skillDef = libSkills.find(s => s.id === id);
            if (!skillDef) return;

            // Fallback placement logic
            let category = '';

            // 1. Check direct skill default category
            if (skillDef.defaultCategory) {
                category = LEGACY_SKILL_MAP[skillDef.defaultCategory] || skillDef.defaultCategory;
            }
            // 2. Check parent mystic ability default category
            else {
                const parentAbility = rules?.libraries?.mysticAbilities?.find(ma => ma.id === (skillDef.mysticAbilityId || wizardState.mysticAbilityId));
                if (parentAbility?.defaultCategory) {
                    category = LEGACY_SKILL_MAP[parentAbility.defaultCategory] || parentAbility.defaultCategory;
                }
            }

            // 3. Last resort: Hardcoded naming logic
            if (!category) {
                const nameLower = skillDef.name.toLowerCase();
                const isMartialArt = nameLower.includes('art martia');
                const isMystic = isMartialArt || wizardState.mysticAbilityName;

                if (isMystic) {
                    const mysticConfig = rules?.configurations?.creation?.mysticAbilities;
                    if (isMartialArt) {
                        category = mysticConfig?.defaultMartialArtsCategory || 'Col_Comp_7';
                    } else {
                        category = mysticConfig?.defaultMysticOtherCategory || 'Col_Comp_5';
                    }
                } else {
                    category = 'competences'; // Default fallback for everything else
                }
            }

            if (!newSkills[category]) newSkills[category] = [];

            // Check if already exists
            const existing = newSkills[category].find(s => s.name === skillDef.name);
            if (!existing) {
                // Add to skills
                newSkills[category].push({
                    id: crypto.randomUUID(),
                    name: skillDef.name,
                    value: 0,
                    creationValue: 0, // Initially learned at level 0
                    max: 5,
                    variant: skillDef.isVariable ? '' : undefined,
                    description: skillDef.description || undefined,
                    definitionId: skillDef.id, // Lien vers la bibliothèque pour l'enrichissement des couleurs
                    mysticAbilityId: skillDef.mysticAbilityId || wizardState.mysticAbilityId || undefined
                } as any);

                // Add to local library if not present
                if (!newLibrary.find(l => l.id === skillDef.id)) {
                    newLibrary.push(skillDef);
                }
                addedCount++;
            }
        });

        if (addedCount > 0) {
            onChange({
                ...data,
                skills: newSkills,
                skillLibrary: newLibrary
            });
            onAddLog(`Ajout de ${addedCount} compétence(s) mystique(s) liée(s) à ${wizardState.mysticAbilityName}`, 'info', 'sheet', 'Compétences');
        }

        // Close wizard (even if 0 added, user confirmed)
        setWizardState(prev => ({ ...prev, isOpen: false }));
    };

    const updateStringField = (field: keyof CharacterSheetData['page2'], value: string) => {
        onChange({ ...data, page2: { ...data.page2, [field]: value } });
        onAddLog(`Modification ${String(field)}`, 'info', 'sheet', `${String(field)}`);
    };

    const handleSaveTrait = (updatedTrait: TraitEntry) => {
        if (!editingTrait) return;

        const { type, index } = editingTrait;
        const oldTrait = data.page2[type][index];
        const newList = [...data.page2[type]];
        newList[index] = updatedTrait;

        // Log XP if changed and post-creation
        if (updatedTrait.isPostCreation && updatedTrait.value !== oldTrait.value) {
            const oldVal = parseInt(oldTrait.value) || 0;
            const newVal = parseInt(updatedTrait.value) || 0;
            const traitCostFactor = rules?.configurations?.xpCosts?.traitCost ?? (data.xpCosts?.traitCost ?? 5);
            const diff = Math.abs(newVal - oldVal);

            if (diff !== 0) {
                recordXPTransaction({
                    type: newVal > oldVal ? 'spend' : 'refund',
                    description: `Modification Trait : ${updatedTrait.name} (${oldVal} → ${newVal})`,
                    amount: diff * traitCostFactor,
                    source: 'XP Libre'
                });
            }
        } else if (type === 'desavantages' && oldTrait.creationValue !== undefined && updatedTrait.value !== oldTrait.value) {
            // Special case: rachat de désavantage
            const oldVal = parseInt(oldTrait.value) || 0;
            const newVal = parseInt(updatedTrait.value) || 0;
            const traitCostFactor = rules?.configurations?.xpCosts?.traitCost ?? (data.xpCosts?.traitCost ?? 5);
            const diff = Math.abs(newVal - oldVal);

            if (diff !== 0) {
                recordXPTransaction({
                    type: newVal < oldVal ? 'spend' : 'refund', // Réduire un désavantage coûte de l'XP
                    description: `Réduction Désavantage : ${updatedTrait.name} (${oldVal} → ${newVal})`,
                    amount: diff * traitCostFactor,
                    source: 'XP Libre'
                });
            }
        }

        // Mettre à jour le compteur auto si le variant a changé
        let newCounters = data.counters;
        if (
            updatedTrait.associatedCounterId &&
            updatedTrait.variant !== oldTrait.variant
        ) {
            const traitDef = rules?.libraries?.traits?.find(t => t.id === updatedTrait.definitionId);
            const counterEffect = traitDef?.effects?.find(e => e.type === 'auto_counter');

            const baseCounterName = counterEffect?.target?.trim();
            const variantName = updatedTrait.variant?.trim();
            let newCounterName = '';
            if (baseCounterName) {
                newCounterName = variantName ? `${baseCounterName} (${variantName})` : baseCounterName;
            } else {
                newCounterName = variantName || updatedTrait.name;
            }

            const customCounters = data.counters.custom.map(c =>
                c.id === updatedTrait.associatedCounterId ? { ...c, name: newCounterName } : c
            );
            newCounters = { ...data.counters, custom: customCounters };
            onAddLog(`Compteur mis à jour : ${newCounterName}`, 'info', 'sheet');
        }

        onChange({ ...data, page2: { ...data.page2, [type]: newList }, counters: newCounters });
        onAddLog(`Modification ${type === 'avantages' ? 'Avantage' : 'Désavantage'} : ${updatedTrait.name}`, 'info', 'sheet');
        setEditingTrait(null);
    };

    const handleImageLog = React.useCallback((msg: string, type: 'success' | 'danger') => {
        onAddLog(msg, type, 'sheet');
    }, [onAddLog]);

    const handleMasterSkillConfirm = React.useCallback((categoryId: string, skillName: string) => {
        if (!masterSkillWizard) return;

        // 1. Appliquer la maîtrise (mise à jour du rang et du variant du trait)
        const updated = applyMasterSkill(data, masterSkillWizard.traitType, masterSkillWizard.traitName, categoryId, skillName);

        // 2. Si la compétence n'existe pas encore sur la fiche, on doit l'ajouter
        let finalSheet = updated;
        let skillFound = false;

        // On cherche dans toutes les catégories si la compétence existe
        for (const catId of Object.keys(updated.skills)) {
            if (updated.skills[catId]?.some(s => s.name === skillName)) {
                skillFound = true;
                break;
            }
        }

        if (!skillFound) {
            const skillDef = rules?.libraries?.skills?.find(s => s.name === skillName);
            if (skillDef) {
                const newSkills = { ...updated.skills };
                if (!newSkills[categoryId]) newSkills[categoryId] = [];

                newSkills[categoryId].push({
                    id: crypto.randomUUID(),
                    name: skillDef.name,
                    value: 5,
                    creationValue: 5,
                    max: 5,
                    definitionId: skillDef.id
                } as any);

                finalSheet = { ...updated, skills: newSkills };
            }
        }

        onChange(finalSheet);
        onAddLog(`Maîtrise accordée : ${skillName} portée au rang 5 (via ${masterSkillWizard.traitName})`, 'success', 'sheet');
        setMasterSkillWizard(null);
    }, [masterSkillWizard, applyMasterSkill, data, rules, onChange, onAddLog]);

    const updateCharacterImageId = React.useCallback((id: string) => {
        onChange((prev: CharacterSheetData) => ({
            ...prev,
            page2: { ...prev.page2, characterImageId: id, characterImage: '' }
        }));
    }, [onChange]);

    const calculateTotal = (list: TraitEntry[]) => list.reduce((acc, item) => acc + (parseInt(item.value) || 0), 0);

    const commonTraitsProps = {
        onTraitClick: (index: number, item: TraitEntry, type: 'avantages' | 'desavantages') => {
            if (!item.name.trim()) setMultiSelectTarget(type);
            else setEditingTrait({ type, index, trait: item });
        },
        onRemove: (type: 'avantages' | 'desavantages', index: number) => removeTrait(type, index)
    };

    return (
        <>
            {isLandscape ? (
                <div className="sheet-container landscape flex flex-col overflow-hidden">
                    <div className="grid grid-cols-4 border-b-2 border-stone-800 h-[35%] overflow-hidden">
                        <div className="border-r border-stone-400 p-0 flex flex-col h-full overflow-hidden bg-stone-50">
                            <CharacterImageWidget imageId={data.page2.characterImageId} legacyImage={data.page2.characterImage} onImageUpdate={updateCharacterImageId} onAddLog={handleImageLog} />
                        </div>
                        <div className="border-r border-stone-400 p-1.5 flex flex-col gap-2 h-full overflow-hidden">
                            <IdentityBoxes data={data} updateStringField={updateStringField} />
                        </div>
                        <div className="border-r border-stone-400 p-1.5 flex flex-col gap-2 h-full overflow-hidden">
                            <NotesBoxes data={data} updateStringField={updateStringField} updateReputationEntry={updateReputationEntry} handleReputationKeyDown={handleReputationKeyDown} />
                        </div>
                        <div className="p-1.5 flex flex-col gap-2 h-full overflow-hidden">
                            <MoneyBoxes data={data} updateStringField={updateStringField} />
                        </div>
                    </div>
                    <div className="grid grid-cols-4 h-[65%] overflow-hidden">
                        <TraitsColumn
                            title="Avantages"
                            traits={data.page2.avantages}
                            type="avantages"
                            total={calculateTotal(data.page2.avantages)}
                            totalColor="text-green-700 bg-green-50 border-green-200"
                            onOpenLibrary={() => setMultiSelectTarget('avantages')}
                            onTraitClick={(i, trait) => commonTraitsProps.onTraitClick(i, trait, 'avantages')}
                            onRemove={(i) => commonTraitsProps.onRemove('avantages', i)}
                            onManageMystic={(i, trait) => {
                                if (trait.mysticAbilityId) setWizardState({ isOpen: true, mysticAbilityId: trait.mysticAbilityId, mysticAbilityName: trait.name });
                            }}
                            className="col-span-1 border-r border-stone-400 p-1.5"
                        />
                        <TraitsColumn
                            title="Désavantages"
                            traits={data.page2.desavantages}
                            type="desavantages"
                            total={calculateTotal(data.page2.desavantages)}
                            totalColor="text-red-700 bg-red-50 border-red-200"
                            onOpenLibrary={() => setMultiSelectTarget('desavantages')}
                            onTraitClick={(i, trait) => commonTraitsProps.onTraitClick(i, trait, 'desavantages')}
                            onRemove={(i) => commonTraitsProps.onRemove('desavantages', i)}
                            className="col-span-1 border-l border-stone-400 -ml-[1px] p-1.5"
                        />
                        <div className="col-span-1 border-r border-l border-stone-400 p-1.5 flex flex-col h-full overflow-hidden"><Page2SectionHeader title="Equipement" /><div className="flex-grow min-h-0"><NotebookInput value={data.page2.equipement} onChange={(v) => updateStringField('equipement', v)} /></div></div>
                        <div className="col-span-1 p-1.5 flex flex-col h-full overflow-hidden"><Page2SectionHeader title="Notes" /><div className="flex-grow min-h-0"><NotebookInput value={data.page2.notes} onChange={(v) => updateStringField('notes', v)} /></div></div>
                    </div>
                </div>
            ) : (
                <div className="sheet-container flex flex-col">
                    <div className="flex border-b border-stone-400 h-[400px] shrink-0 overflow-hidden">
                        <div className="w-[35%] border-r border-stone-400 bg-stone-50 p-0 flex flex-col overflow-hidden"><CharacterImageWidget imageId={data.page2.characterImageId} legacyImage={data.page2.characterImage} onImageUpdate={updateCharacterImageId} onAddLog={handleImageLog} /></div>
                        <div className="w-[65%] flex flex-col overflow-hidden">
                            <div className="h-1/3 flex border-b border-stone-400">
                                <IdentityBoxes data={data} updateStringField={updateStringField} />
                            </div>
                            <div className="h-1/3 flex border-b border-stone-400">
                                <NotesBoxes data={data} updateStringField={updateStringField} updateReputationEntry={updateReputationEntry} handleReputationKeyDown={handleReputationKeyDown} />
                            </div>
                            <div className="h-1/3 flex">
                                <MoneyBoxes data={data} updateStringField={updateStringField} />
                            </div>
                        </div>
                    </div>
                    <div className="flex h-[720px] overflow-hidden shrink-0 border-b border-stone-400">
                        <div className="w-[67.5%] border-r border-stone-400 flex flex-col">
                            <Page2SectionHeader title="Traits - Signes Particuliers" />
                            <div className="grid grid-cols-2 flex-grow overflow-hidden min-h-0">
                                <TraitsColumn
                                    title="Avantages"
                                    traits={data.page2.avantages}
                                    type="avantages"
                                    total={calculateTotal(data.page2.avantages)}
                                    totalColor="text-green-700 bg-green-50 border-green-200"
                                    onOpenLibrary={() => setMultiSelectTarget('avantages')}
                                    onTraitClick={(i, trait) => commonTraitsProps.onTraitClick(i, trait, 'avantages')}
                                    onRemove={(i) => commonTraitsProps.onRemove('avantages', i)}
                                    onManageMystic={(i, trait) => {
                                        if (trait.mysticAbilityId) setWizardState({ isOpen: true, mysticAbilityId: trait.mysticAbilityId, mysticAbilityName: trait.name });
                                    }}
                                    className="border-r border-stone-400 p-1.5"
                                />
                                <TraitsColumn
                                    title="Désavantages"
                                    traits={data.page2.desavantages}
                                    type="desavantages"
                                    total={calculateTotal(data.page2.desavantages)}
                                    totalColor="text-red-700 bg-red-50 border-red-200"
                                    onOpenLibrary={() => setMultiSelectTarget('desavantages')}
                                    onTraitClick={(i, trait) => commonTraitsProps.onTraitClick(i, trait, 'desavantages')}
                                    onRemove={(i) => commonTraitsProps.onRemove('desavantages', i)}
                                    className="border-l border-stone-400 -ml-[1px] p-1.5"
                                />
                            </div>
                        </div>
                        <div className="w-[32.5%] flex flex-col h-full overflow-hidden"><Page2SectionHeader title="Equipement" /><div className="p-1.5 flex-grow min-h-0"><NotebookInput value={data.page2.equipement} onChange={(v) => updateStringField('equipement', v)} /></div></div>
                    </div>
                    <div className="flex-grow border-t border-stone-400 p-1.5 flex flex-col shrink-0 min-h-[440px]"><Page2SectionHeader title="Notes" /><div className="flex-grow min-h-0 mt-1 flex flex-col"><NotebookInput className="flex-grow" value={data.page2.notes} onChange={(v) => updateStringField('notes', v)} /></div></div>
                </div>
            )}


            {multiSelectTarget && (
                <div className="fixed inset-0 bg-black/60 z-[100] flex items-center justify-center p-4 backdrop-blur-sm animate-in fade-in duration-200">
                    <div className="bg-white rounded-xl shadow-2xl w-full max-w-2xl h-[85vh] flex flex-col overflow-hidden">
                        <div className={`p-4 border-b flex justify-between items-center text-white ${multiSelectTarget === 'avantages' ? 'bg-green-700' : 'bg-red-700'}`}>
                            <h3 className="font-bold text-lg flex items-center gap-2"><BookOpen size={20} />Ajouter des {multiSelectTarget === 'avantages' ? 'Avantages' : 'Désavantages'}</h3>
                            <button onClick={() => setMultiSelectTarget(null)} className="hover:bg-white/20 p-1 rounded transition-colors"><X size={24} /></button>
                        </div>
                        <div className="flex-grow overflow-hidden relative"><TraitLibrary data={data} onUpdate={onChange} isEditable={false} defaultFilter={multiSelectTarget === 'avantages' ? 'avantage' : 'desavantage'} onMultiSelect={handleMultiAddWrapper} hidePossessed={true} lockFilter={true} /></div>
                    </div>
                </div>
            )}

            {wizardState.isOpen && wizardState.mysticAbilityId && rules && (
                <MysticSkillWizard
                    isOpen={wizardState.isOpen}
                    onClose={() => setWizardState(prev => ({ ...prev, isOpen: false }))}
                    onConfirm={handleWizardConfirm}
                    mysticAbilityId={wizardState.mysticAbilityId}
                    mysticAbilityName={wizardState.mysticAbilityName}
                    sheet={data}
                    rules={rules}
                />
            )}

            {masterSkillWizard?.isOpen && (
                <MasterSkillWizard
                    isOpen={true}
                    traitName={masterSkillWizard.traitName}
                    onClose={() => setMasterSkillWizard(null)}
                    onConfirm={handleMasterSkillConfirm}
                    sheet={data}
                    rules={rules}
                />
            )}

            {editingTrait && (
                <TraitEditModal
                    isOpen={!!editingTrait}
                    onClose={() => setEditingTrait(null)}
                    trait={editingTrait.trait}
                    onSave={handleSaveTrait}
                    type={editingTrait.type}
                />
            )}
        </>
    );
};

export default CharacterSheetPage2;

import { useCharacter } from '../context/CharacterContext';
import { CharacterSheetData, DotEntry, SkillCategoryKey } from '../types';
import SpecializationOmnibar from './specialization-library/SpecializationOmnibar';
import SpecializationLibraryDrawer from './specialization-library/SpecializationLibraryDrawer';
import ConfirmationModal from './ui/ConfirmationModal';
import { Award, ArrowUpCircle, Plus, Zap } from 'lucide-react';
import { useState } from 'react';
import { useRules } from '../context/RulesContext';
import { logger } from '../utils/logger';
import { ErrorService } from '../services/ErrorService';
import { createDotEntry } from '../utils/factories';

interface Props {
    isLandscape?: boolean;
}

const SectionHeader: React.FC<{ title: string }> = ({ title }) => (
    <div className="bg-slate-200 text-slate-800 text-center font-bold text-xs border-y border-stone-500 uppercase py-0.5 mt-3 mb-2 tracking-wide shadow-sm rounded-sm">
        {title}
    </div>
);

const CharacterSheetSpecializations: React.FC<Props> = ({ isLandscape = false }) => {
    const { data, updateData: onChange, addLog: onAddLog } = useCharacter();
    const { rules } = useRules();
    const [isDrawerOpen, setIsDrawerOpen] = useState(false);
    const [duplicateErrorModal, setDuplicateErrorModal] = useState<string | null>(null);
    const [promoteImposedModal, setPromoteImposedModal] = useState<{ skillId: string; specName: string } | null>(null);

    const getSkillName = (skillId: string): string => {
        for (const cat of Object.keys(data.skills)) {
            const skill = data.skills[cat].find((s: DotEntry) => s.id === skillId);
            if (skill) return skill.name;
        }
        return 'Compétence';
    };

    const updateSpecialization = (skillId: string, index: number, value: string) => {
        const currentSpecs = data.specializations[skillId] || [];
        const newSpecs = [...currentSpecs];
        // Pad array if needed
        if (newSpecs.length <= index) {
            // Fill gaps with empty strings
            for (let i = newSpecs.length; i <= index; i++) {
                newSpecs[i] = "";
            }
        }
        newSpecs[index] = value;

        onChange({
            ...data,
            specializations: {
                ...data.specializations,
                [skillId]: newSpecs
            }
        });

        const skillName = getSkillName(skillId);
        onAddLog(`Spécialisation modifiée (${skillName}) : ${value}`, 'info', 'sheet', `spec_${skillId}_${index}`);
    };

    const handlePromote = (skillId: string, index: number, specName: string) => {
        try {
            if (!specName || specName.trim() === '') return;

            // 1. Identifier la catégorie cible "Secondaire"
            const secondaryCat = rules?.definitions?.skillCategories?.find((cat: any) => cat.behavior === 'Secondaire' || cat.label.toLowerCase().includes('secondaire'))?.id || 'competences_secondaires';

            // 2. Vérifier si la compétence n'existe pas déjà
            const existingSkills = data.skills[secondaryCat] || [];
            const isDuplicate = existingSkills.some((s: DotEntry) => s.name.trim().toLowerCase() === specName.trim().toLowerCase());

            if (isDuplicate) {
                onAddLog(`La compétence secondaire "${specName}" existe déjà.`, 'danger', 'sheet');
                setDuplicateErrorModal(specName);
                return;
            }

            logger.info(`[Promotion] Promouvoir "${specName}" vers ${secondaryCat} (Skill ID: ${skillId}, Index: ${index})`);

            // 3. Créer la nouvelle compétence (valeur 0 comme demandé)
            const newSkill = createDotEntry(specName, 0);

            // 4. Mettre à jour les données de manière fonctionnelle pour éviter tout souci de synchronisation
            onChange((prev: CharacterSheetData) => {
                const currentSpecs = prev.specializations[skillId] || [];
                const newSpecs = [...currentSpecs];
                newSpecs[index] = ""; // Libère l'emplacement

                const currentCatSkills = prev.skills[secondaryCat] || [];

                return {
                    ...prev,
                    skills: {
                        ...prev.skills,
                        [secondaryCat]: [...currentCatSkills, newSkill]
                    },
                    specializations: {
                        ...prev.specializations,
                        [skillId]: newSpecs
                    }
                };
            });

            onAddLog(`Spécialisation "${specName}" promue en compétence secondaire.`, 'success', 'sheet');
        } catch (err) {
            logger.error(`[Promotion] Error:`, err);
            ErrorService.handleError(err, { context: 'CharacterSheetSpecializations.handlePromote' });
        }
    };

    const handlePromoteImposed = (skillId: string, specName: string) => {
        try {
            if (!specName || specName.trim() === '') return;

            // 1. Identifier la catégorie cible "Secondaire"
            const secondaryCat = rules?.definitions?.skillCategories?.find((cat: any) => cat.behavior === 'Secondaire' || cat.label.toLowerCase().includes('secondaire'))?.id || 'competences_secondaires';

            // 2. Vérifier si la compétence n'existe pas déjà
            const existingSkills = data.skills[secondaryCat] || [];
            const isDuplicate = existingSkills.some((s: DotEntry) => s.name.trim().toLowerCase() === specName.trim().toLowerCase());

            if (isDuplicate) {
                onAddLog(`La compétence secondaire "${specName}" existe déjà.`, 'danger', 'sheet');
                setDuplicateErrorModal(specName);
                return;
            }

            logger.info(`[PromotionImposée] Promouvoir "${specName}" vers ${secondaryCat} (Skill ID: ${skillId})`);

            // 3. Créer la nouvelle compétence (valeur 0)
            const newSkill = createDotEntry(specName, 0);

            // 4. Ajouter la compétence sans toucher aux specs imposées (le MJ reste maître)
            onChange((prev: CharacterSheetData) => ({
                ...prev,
                skills: {
                    ...prev.skills,
                    [secondaryCat]: [...(prev.skills[secondaryCat] || []), newSkill]
                }
            }));

            onAddLog(`Spécialisation imposée "${specName}" convertie en compétence secondaire.`, 'success', 'sheet');
        } catch (err) {
            logger.error(`[PromotionImposée] Error:`, err);
            ErrorService.handleError(err, { context: 'CharacterSheetSpecializations.handlePromoteImposed' });
        }
    };

    const handleDrop = (e: React.DragEvent, skillId: string) => {
        e.preventDefault();
        try {
            const dragData = e.dataTransfer.getData('application/json');
            if (dragData) {
                const { name } = JSON.parse(dragData);
                if (name) {
                    // Find first empty slot
                    const skill = findSkill(skillId);
                    if (!skill) return;

                    const userSpecs = data.specializations[skillId] || [];
                    const firstEmptyIndex = Array.from({ length: skill.value }).findIndex((_, i) => !userSpecs[i]);

                    if (firstEmptyIndex !== -1) {
                        updateSpecialization(skillId, firstEmptyIndex, name);
                    } else {
                        // All slots full? Maybe add to the last one or do nothing
                        onAddLog(`Plus d'emplacement disponible pour ${skill.name}`, 'danger', 'sheet');
                    }
                }
            }
        } catch (err) {
            ErrorService.handleError(err, { context: 'CharacterSheetSpecializations.Drop', silent: true });
        }
    };

    const findSkill = (skillId: string): DotEntry | null => {
        for (const cat of Object.keys(data.skills)) {
            const skill = data.skills[cat].find((s: DotEntry) => s.id === skillId);
            if (skill) return skill;
        }
        return null;
    };

    const renderSkillBox = (skill: DotEntry) => {
        const count = skill.value;
        const imposedSpecs = (data.imposedSpecializations[skill.id] || [])
            .filter((spec: any) => skill.value >= (spec.minLevel || 0));

        if (count <= 0 && imposedSpecs.length === 0) return null;

        const userSpecs = data.specializations[skill.id] || [];

        return (
            <div
                key={skill.id}
                className="border border-stone-300 p-1.5 bg-white/50 backdrop-blur-sm shadow-sm flex flex-col gap-1.5 rounded-md group/skill hover:border-amber-400 hover:bg-white transition-all duration-200"
                onDragOver={(e) => {
                    e.preventDefault();
                    e.currentTarget.classList.add('bg-amber-50', 'border-amber-400');
                }}
                onDragLeave={(e) => {
                    e.currentTarget.classList.remove('bg-amber-50', 'border-amber-400');
                }}
                onDrop={(e) => {
                    e.currentTarget.classList.remove('bg-amber-50', 'border-amber-400');
                    handleDrop(e, skill.id);
                }}
            >
                <div className="font-black text-[9px] uppercase tracking-tighter flex justify-between items-center text-stone-500 group-hover/skill:text-amber-700 transition-colors px-0.5">
                    <span className="truncate" title={skill.name}>{skill.name}</span>
                    <span className="opacity-40 text-[8px]">({count})</span>
                </div>

                <div className="grid grid-cols-2 gap-x-2 gap-y-1.5">
                    {/* Render Imposed Specializations first (avec bouton de promotion) */}
                    {imposedSpecs.map((spec: any, i: number) => (
                        <div key={`imp-${i}`} className="group/imposed bg-slate-100 border border-slate-200 rounded-full py-0.5 px-2 flex items-center shadow-inner h-5 hover:border-indigo-300 hover:bg-indigo-50 transition-colors">
                            <Zap size={10} className="text-blue-500 fill-blue-500 mr-1 shrink-0" />
                            <span className="text-[10px] font-bold text-slate-600 truncate leading-none flex-1" title={spec.name}>
                                {spec.name}
                            </span>
                            <button
                                onClick={() => setPromoteImposedModal({ skillId: skill.id, specName: spec.name })}
                                className="opacity-0 group-hover/imposed:opacity-100 transition-opacity ml-0.5 text-indigo-500 hover:text-indigo-700"
                                title="Transformer en compétence secondaire"
                            >
                                <ArrowUpCircle size={10} />
                            </button>
                        </div>
                    ))}

                    {/* Render User Specializations */}
                    {Array.from({ length: count }).map((_, i) => {
                        const hasValue = !!userSpecs[i];
                        return (
                            <div
                                key={`user-${i}`}
                                className={`relative flex items-center h-5 transition-all duration-200 ${hasValue
                                    ? 'bg-amber-50 border border-amber-200 rounded-full shadow-sm'
                                    : 'border-b border-dashed border-stone-300 hover:border-amber-400'
                                    }`}
                            >
                                <SpecializationOmnibar
                                    value={userSpecs[i] || ''}
                                    onChange={(val: string) => updateSpecialization(skill.id, i, val)}
                                    onPromote={(val: string) => handlePromote(skill.id, i, val)}
                                    skillId={skill.id}
                                    className="w-full"
                                    variant="sheet"
                                    showPlaceholder={false}
                                />
                                {!hasValue && (
                                    <div className="absolute inset-0 pointer-events-none flex items-center justify-center opacity-0 group-hover/skill:opacity-20">
                                        <Plus size={8} className="text-stone-400" />
                                    </div>
                                )}
                            </div>
                        );
                    })}
                </div>
            </div>
        );
    };

    const renderCategory = (title: string, categoryKey: SkillCategoryKey) => {
        const categoryData = data.skills[categoryKey];
        if (!categoryData || !Array.isArray(categoryData)) return null;

        // Show skill if it has dots OR imposed specializations
        const skills = categoryData.filter((s: any) => {
            if (!s || !s.name || s.name.trim() === '') return false; // Skip spacers
            const hasPoints = s.value > 0;
            const hasImposed = data.imposedSpecializations[s.id] && data.imposedSpecializations[s.id].length > 0;
            // Always show if it has points or if MJ imposed something
            return hasPoints || hasImposed;
        });

        if (skills.length === 0) return null;

        // Adapt columns based on landscape mode (6 for portrait, 8 for landscape)
        const gridClass = isLandscape
            ? "grid grid-cols-8 gap-1"
            : "grid grid-cols-6 gap-1";

        return (
            <div className="mb-1 break-inside-avoid">
                <SectionHeader title={title} />
                <div className="grid grid-cols-6 gap-2">
                    {skills.map(renderSkillBox)}
                </div>
            </div>
        );
    };

    // Check if there are any skills with values to display default message
    const hasAnySkill = Object.keys(data.skills).some(key => {
        if (key === 'arrieres_plans') return false;
        if (key === 'competences2') return false; // Exclude secondary skills from empty check
        // Check for dots OR imposed specs
        return data.skills[key].some((s: DotEntry) => {
            const hasDots = s.value > 0;
            const hasVisibleImposed = (data.imposedSpecializations[s.id] || [])
                .some(spec => s.value >= (spec.minLevel || 0));
            return hasDots || hasVisibleImposed;
        });
    });

    return (
        <div className={`flex justify-center transition-all duration-300 ${isDrawerOpen ? 'pr-80' : ''}`}>
            <div className={`sheet-container p-6 ${isLandscape ? 'landscape' : ''}`}>

                <h1 className="text-3xl font-black text-center uppercase py-2 tracking-widest border-b-2 border-stone-800 mb-4 text-indigo-950 font-serif relative">
                    Spécialisations
                    <button
                        onClick={() => setIsDrawerOpen(true)}
                        className="absolute right-0 top-1/2 -translate-y-1/2 bg-amber-600 hover:bg-amber-700 text-white text-[10px] font-bold py-1 px-3 rounded shadow-sm transition-colors flex items-center gap-1 uppercase cursor-pointer"
                    >
                        <Award size={14} /> Catalogue
                    </button>
                </h1>

                <div className="flex-grow flex flex-col overflow-hidden">
                    {!hasAnySkill && (
                        <div className="text-center text-stone-400 italic mt-20 flex-grow flex items-center justify-center">
                            <div>
                                <p className="mb-2 text-lg">Aucune compétence (principale) ne possède de point ou de spécialisation imposée.</p>
                                <p className="text-sm">Ajoutez des points dans l'onglet "Personnage" pour voir apparaître les champs de spécialisation ici.</p>
                            </div>
                        </div>
                    )}

                    <div className="space-y-0.5 overflow-auto">
                        {/* Dynamic Rendering from Rules */}
                        {rules?.definitions?.skillCategories
                            ?.filter((cat: any) => cat.behavior === 'Compétence')
                            ?.map((cat: any) => (
                                <div key={cat.id}>
                                    {renderCategory(cat.label, cat.id as any)}
                                </div>
                            ))}

                        {/* Fallback Rendering if no rules / legacy keys */}
                        {(!rules || !rules.definitions?.skillCategories) && (
                            <>
                                {renderCategory("Talents", "talents" as any)}
                                {renderCategory("Compétences", "competences" as any)}
                                {renderCategory("Compétences (Suite)", "competences_col_2" as any)}
                                {renderCategory("Connaissances", "connaissances" as any)}
                                {renderCategory("Autres Compétences", "autres_competences" as any)}
                                {renderCategory("Autres", "autres" as any)}
                            </>
                        )}
                    </div>
                </div>

                <SpecializationLibraryDrawer
                    isOpen={isDrawerOpen}
                    onClose={() => setIsDrawerOpen(false)}
                />

                {duplicateErrorModal && (
                    <ConfirmationModal
                        isOpen={!!duplicateErrorModal}
                        onClose={() => setDuplicateErrorModal(null)}
                        onConfirm={() => setDuplicateErrorModal(null)}
                        title="Promotion Impossible"
                        message={
                            <span>
                                La compétence secondaire <strong>"{duplicateErrorModal}"</strong> existe déjà.
                                <br /><br />
                                <span className="text-[11px] opacity-80">
                                    Veuillez supprimer la compétence existante ou choisir une autre spécialisation à promouvoir.
                                </span>
                            </span>
                        }
                        confirmLabel="Compris"
                        cancelLabel=""
                        type="danger"
                        scheme="paper"
                    />
                )}

                {promoteImposedModal && (
                    <ConfirmationModal
                        isOpen={!!promoteImposedModal}
                        onClose={() => setPromoteImposedModal(null)}
                        onConfirm={() => {
                            handlePromoteImposed(promoteImposedModal.skillId, promoteImposedModal.specName);
                            setPromoteImposedModal(null);
                        }}
                        title="Transformer en Compétence Secondaire"
                        message={
                            <span>
                                Souhaitez-vous transformer <strong>"{promoteImposedModal.specName}"</strong> en compétence secondaire ?
                                <br /><br />
                                <span className="text-[11px] opacity-80">
                                    Une nouvelle compétence sera créée avec une valeur de 0. La spécialisation imposée restera visible (elle est définie par les règles).
                                </span>
                            </span>
                        }
                        confirmLabel="Transformer"
                        cancelLabel="Annuler"
                        type="warning"
                        scheme="paper"
                    />
                )}
            </div>
        </div>
    );
};

export default CharacterSheetSpecializations;

import React, { useState } from 'react';
import { useNotification } from '../context/NotificationContext';
import { useCharacter } from '../context/CharacterContext';
import { Calculator, AlertTriangle, Sliders, Feather, AlertOctagon } from 'lucide-react';
import { useCreationBudget } from '../hooks/useCreationBudget';
import { BudgetGauge } from './creation/BudgetGauge';
import { CreationValidationModal } from './creation/CreationValidationModal';
import { CreationGuidance } from './creation/CreationGuidance';

const CreationHUD: React.FC = () => {
    const { data, updateData: setData, addLog } = useCharacter();
    const [showConfirm, setShowConfirm] = useState(false);

    const onValidate = () => {
        setData(prev => ({
            ...prev,
            creationConfig: {
                ...prev.creationConfig,
                active: false
            }
        }));
        addLog("Création de personnage validée. Mode création désactivé.", 'success', 'sheet');
    };

    const {
        xpSpentTotal,
        xpSpentAttributes,
        xpSpentSkills,
        xpSpentBackgrounds,
        xpEquivalence,
        ranksUsed,
        attributesUsed,
        backgroundsUsed,
        messages,
        overspent,
        hasErrors,
        formatNumber,
        isGlobalPoints,
        xpRemainingGlobal
    } = useCreationBudget();

    const { mode, rankSlots, startingXP, pointsBuckets, attributePoints, backgroundPoints, attributeMin, attributeMax } = data.creationConfig;

    const minAttr = attributeMin ?? -2;
    const maxAttr = attributeMax ?? 3;

    const handleValidateClick = () => {
        setShowConfirm(true);
    };

    const handleConfirmValidation = () => {
        setShowConfirm(false);
        onValidate();
    };

    return (
        <>
            <CreationGuidance />

            <div className={`fixed bottom-0 left-0 right-0 z-[90] bg-stone-900 text-stone-100 shadow-[0_-5px_20px_rgba(0,0,0,0.5)] border-t-4 transition-colors duration-300 animate-in slide-in-from-bottom no-print ${hasErrors ? 'border-red-700' : 'border-amber-600'}`}>
                <div className="max-w-[1600px] mx-auto px-6 py-6 flex flex-col xl:flex-row items-center justify-between gap-6">

                    {/* Left: Identity Block */}
                    <div className="flex items-center gap-4 min-w-[280px]">
                        <div className={`w-14 h-14 rounded-full flex items-center justify-center border-2 shadow-inner shrink-0 ${hasErrors ? 'bg-red-950 border-red-600 text-red-500' : 'bg-stone-800 border-amber-600 text-amber-500'}`}>
                            {hasErrors ? <AlertTriangle size={32} /> : <Feather size={32} />}
                        </div>
                        <div>
                            <h3 className="font-bold text-xl uppercase tracking-widest font-serif text-amber-500 leading-tight">
                                Création
                            </h3>
                            <span className="text-sm font-medium text-stone-400">
                                {mode === 'rangs' ? 'Système par Rangs' : (isGlobalPoints ? 'Système par XP (Global)' : 'Système par XP (Budgets)')}
                            </span>
                        </div>
                    </div>

                    {/* Center: Budget Dashboard */}
                    <div className="flex-grow flex justify-center flex-wrap gap-4 items-center w-full xl:w-auto">

                        {/* Stats & Info Cards */}
                        <div className="flex gap-4 mr-4 border-r border-stone-700 pr-4">
                            <div className="flex flex-col items-center justify-center">
                                <div className="flex items-center gap-2 mb-1">
                                    <Calculator size={14} className="text-stone-500" />
                                    <span className="text-[10px] text-stone-500 font-bold uppercase tracking-wide">Valeur Totale</span>
                                </div>
                                <span className="font-mono font-bold text-amber-100 text-xl">{formatNumber(xpEquivalence)} XP</span>
                            </div>
                            <div className="flex flex-col items-center justify-center">
                                <div className="flex items-center gap-2 mb-1">
                                    <Sliders size={14} className="text-stone-500" />
                                    <span className="text-[10px] text-stone-500 font-bold uppercase tracking-wide">Limites Attr.</span>
                                </div>
                                <span className="font-mono font-bold text-stone-300 text-base">
                                    {minAttr > 0 ? `+${minAttr}` : minAttr} / {maxAttr > 0 ? `+${maxAttr}` : maxAttr}
                                </span>
                            </div>
                        </div>

                        {mode === 'points' ? (
                            isGlobalPoints ? (
                                // MODE GLOBAL
                                <div className={`relative px-8 py-3 rounded-lg border-2 bg-stone-800 shadow-inner min-w-[200px] text-center overflow-hidden ${xpRemainingGlobal < 0 ? 'border-red-600' : (xpRemainingGlobal === 0 ? 'border-green-600' : 'border-blue-600')}`}>
                                    <div className="text-xs uppercase text-stone-400 font-bold mb-1 tracking-widest relative z-10">XP Restants</div>
                                    <div className={`text-3xl font-mono font-black relative z-10 ${xpRemainingGlobal < 0 ? 'text-red-400' : (xpRemainingGlobal === 0 ? 'text-green-400' : 'text-blue-200')}`}>
                                        {formatNumber(xpRemainingGlobal)} {mode === 'points' && <span className="text-lg text-stone-500">/ {startingXP}</span>}
                                    </div>
                                    {/* Background Progress Effect */}
                                    <div
                                        className={`absolute bottom-0 left-0 top-0 opacity-10 transition-all duration-500 ${xpRemainingGlobal < 0 ? 'bg-red-500' : 'bg-blue-500'}`}
                                        style={{ width: `${Math.min(100, (xpSpentTotal / startingXP) * 100)}%` }}
                                    />
                                </div>
                            ) : (
                                // MODE BUCKETS
                                <div className="flex gap-4 overflow-x-auto pb-1 items-center no-scrollbar">
                                    <BudgetGauge label="Attributs" current={xpSpentAttributes} max={pointsBuckets?.attributes || 0} formatNumber={formatNumber} />
                                    <BudgetGauge label="Compétences" current={xpSpentSkills} max={pointsBuckets?.skills || 0} formatNumber={formatNumber} />
                                    <BudgetGauge label="Arrière-plans" current={xpSpentBackgrounds} max={pointsBuckets?.backgrounds || 0} formatNumber={formatNumber} />
                                </div>
                            )
                        ) : (
                            // MODE RANGS
                            <div className="flex gap-3 overflow-x-auto pb-1 items-center no-scrollbar">
                                <BudgetGauge label="Attributs" current={attributesUsed} max={attributePoints || 15} formatNumber={formatNumber} />

                                {/* Ranks (Compact Vertical) */}
                                <div className="flex bg-stone-800 rounded-lg border border-stone-700 p-2 gap-2 shadow-lg">
                                    {[1, 2, 3, 4, 5].map(rank => {
                                        const used = ranksUsed[rank] || 0;
                                        const max = (rankSlots as Record<number, number>)[rank] || 0;
                                        if (max === 0 && used === 0) return null;

                                        const isOver = used > max;
                                        const isFull = used === max;

                                        const statusColor = isOver ? 'text-red-400' : (isFull ? 'text-green-400' : 'text-stone-300');
                                        const ringColor = isOver ? 'border-red-500' : (isFull ? 'border-green-600' : 'border-stone-600');

                                        return (
                                            <div key={rank} className="flex flex-col items-center min-w-[36px]">
                                                <div className={`w-8 h-8 rounded-full border-2 ${ringColor} flex items-center justify-center font-mono font-bold text-sm bg-stone-900 ${statusColor}`}>
                                                    {formatNumber(used)}
                                                </div>
                                                <span className="text-[9px] text-stone-500 mt-1 uppercase font-bold">R{rank}</span>
                                                <span className="text-[9px] text-stone-600 font-mono">/{max}</span>
                                            </div>
                                        );
                                    })}
                                </div>

                                <BudgetGauge label="Arrière-plans" current={backgroundsUsed} max={backgroundPoints || 5} formatNumber={formatNumber} />
                            </div>
                        )}
                    </div>

                    {/* Right: Validation Button */}
                    <div className="min-w-[180px] flex justify-end">
                        <button
                            onClick={handleValidateClick}
                            className={`group relative flex items-center gap-3 px-8 py-4 rounded font-bold shadow-xl transform transition-all hover:scale-105 active:scale-95 overflow-hidden ${hasErrors
                                ? 'bg-red-800 text-red-100 hover:bg-red-700 ring-2 ring-red-500 ring-offset-2 ring-offset-stone-900'
                                : 'bg-green-700 text-green-100 hover:bg-green-600 ring-2 ring-green-500 ring-offset-2 ring-offset-stone-900'
                                }`}
                        >
                            <div className="relative z-10 flex items-center gap-2 text-lg font-serif tracking-wide">
                                {hasErrors ? <AlertOctagon size={24} /> : <Feather size={24} />}
                                {hasErrors ? 'Incomplet' : 'Valider'}
                            </div>
                            {/* Shine Effect */}
                            <div className="absolute top-0 -inset-full h-full w-1/2 z-5 block transform -skew-x-12 bg-gradient-to-r from-transparent to-white opacity-20 group-hover:animate-shine" />
                        </button>
                    </div>
                </div>
            </div>

            {/* Validation Modal */}
            <CreationValidationModal
                isOpen={showConfirm}
                hasErrors={hasErrors}
                messages={messages}
                overspent={overspent}
                onClose={() => setShowConfirm(false)}
                onConfirm={handleConfirmValidation}
            />
        </>
    );
};

export default CreationHUD;

import React, { useState, useMemo } from 'react';
import { CharacterSheetData, LibrarySkillEntry } from '../types';
import { BookOpen, GraduationCap, Award } from 'lucide-react';
import TraitLibrary from './TraitLibrary';
import SpecializationLibraryView from './specialization-library/SpecializationLibraryView';
import { useCharacter } from '../context/CharacterContext';
import { useNotification } from '../context/NotificationContext';
import { useRules } from '../context/RulesContext';
import { MergedEntry } from '../utils/libraryMerger';
import LibrarySkillForm from './library/LibrarySkillForm';
import LibraryDeleteModal from './library/LibraryDeleteModal';
import LibraryImportModal from './library/LibraryImportModal';
import LibraryRenameModal from './library/LibraryRenameModal';
import { disambiguateCategories } from '../utils/categoryUtils';
import SkillLibraryTab from './library/SkillLibraryTab';
import { useSkillLibrary } from '../hooks/library/useSkillLibrary';

interface LibraryViewProps {
    data?: CharacterSheetData; // Optional to support standalone use if needed, but we will pass it
    onUpdate?: (newData: CharacterSheetData) => void;
}

const LibraryView: React.FC<LibraryViewProps> = ({ data: propData, onUpdate: propUpdate }) => {
    // Fallback to context if not provided (for backward compatibility if used elsewhere)
    const { data: contextData, updateData: contextUpdate } = useCharacter();

    const data = propData || contextData;
    const onUpdate = propUpdate || contextUpdate;

    if (!data) return <div className="p-4 text-gray-500 italic">Chargement des données...</div>;

    const [activeTab, setActiveTab] = useState<'traits' | 'skills' | 'specializations'>('traits');
    const addLog = useNotification();

    // OFFICIAL: Get Rules Context
    const { rules, updateRules } = useRules();

    // MERGE: Compute Hybrid Skill Library
    const {
        skillSearch, setSkillSearch,
        hideKnownSkills, setHideKnownSkills,
        isSkillModalOpen, setIsSkillModalOpen,
        editingSkill, setEditingSkill,
        skillError, setSkillError,
        showRenameConfirm, setShowRenameConfirm,
        showImportConfirm, setShowImportConfirm,
        skillToDelete, setSkillToDelete,
        hybridSkills,
        usedSkillNames,
        filteredSkills,
        handleOpenNewSkill,
        handleOpenEditSkill,
        handleSaveSkill,
        finalizeSaveSkill,
        handleDeleteRequest,
        executeDeleteSkill,
        executeImportFromSheet
    } = useSkillLibrary(data, rules, onUpdate, addLog);

    // OFFICIAL: Use local state for visibility for now (could be moved to hook too if shared)
    const [showOfficialUpdateConfirm, setShowOfficialUpdateConfirm] = useState(false);

    // Dynamic Categories Source of Truth
    const availableCategories = useMemo(() => {
        let rawCategories: { code: string, label: string, loc: string }[] = [];

        if (rules?.definitions.skillCategories && rules.definitions.skillCategories.length > 0) {
            rawCategories = rules.definitions.skillCategories.map(cat => ({
                code: cat.id,
                label: cat.label,
                loc: cat.description || ""
            }));
        }

        return disambiguateCategories(rawCategories);
    }, [rules]);

    const getCategoryLabel = (code: string) => {
        return availableCategories.find(c => c.code === code)?.label || code;
    };

    const handleOfficialUpdateClick = () => {
        setShowOfficialUpdateConfirm(true);
    };

    const executeOfficialUpdate = async () => {
        try {
            const res = await fetch('./data/skills.json?t=' + Date.now());
            if (!res.ok) throw new Error("Fichier introuvable");

            const json = await res.json();
            const newSkills = json.data as LibrarySkillEntry[];

            if (json.meta && json.meta.type !== 'skills') throw new Error("Format invalide");

            // Update Rules Context
            const updatedRules = {
                ...rules!,
                libraries: {
                    ...rules!.libraries,
                    skills: newSkills
                }
            };
            updateRules(updatedRules);
            addLog(`Bibliothèque officielle mise à jour (${newSkills.length} compétences).`, 'success', 'settings');
        } catch (e) {
            addLog("Échec de la mise à jour officielle : " + (e as Error).message, 'danger', 'settings');
        }
    };

    return (
        <div className="flex flex-col h-full bg-[#fdfbf7] rounded-sm shadow-sm border border-[#bfae85]/50 overflow-hidden relative">

            {/* Tabs Header */}
            <div className="flex border-b border-[#bfae85]/30 bg-stone-100/30 shrink-0">
                <button
                    onClick={() => setActiveTab('traits')}
                    className={`flex-1 py-4 font-bold text-sm flex items-center justify-center gap-2 transition-colors border-b-2 ${activeTab === 'traits'
                        ? 'border-[#8b2e2e] text-[#8b2e2e] bg-white/50'
                        : 'border-transparent text-[#5c4d41]/60 hover:bg-stone-200/50 hover:text-[#5c4d41]'
                        }`}
                >
                    <BookOpen size={18} />
                    Bibliothèque de Traits
                </button>
                <button
                    onClick={() => setActiveTab('skills')}
                    className={`flex-1 py-4 font-bold text-sm flex items-center justify-center gap-2 transition-colors border-b-2 ${activeTab === 'skills'
                        ? 'border-[#5c4d41] text-[#5c4d41] bg-white/50'
                        : 'border-transparent text-[#5c4d41]/60 hover:bg-stone-200/50 hover:text-[#5c4d41]'
                        }`}
                >
                    <GraduationCap size={18} />
                    Réserve de Compétences
                </button>
                <button
                    onClick={() => setActiveTab('specializations')}
                    className={`flex-1 py-4 font-bold text-sm flex items-center justify-center gap-2 transition-colors border-b-2 ${activeTab === 'specializations'
                        ? 'border-amber-600 text-amber-700 bg-white/50'
                        : 'border-transparent text-[#5c4d41]/60 hover:bg-stone-200/50 hover:text-[#5c4d41]'
                        }`}
                >
                    <Award size={18} />
                    Bibliothèque de Spécialisations
                </button>
            </div>

            {/* Content */}
            <div className="flex-grow min-h-0 relative">
                {activeTab === 'traits' && (
                    // Use existing component logic, wrapped to fit height
                    <div className="absolute inset-0">
                        <TraitLibrary data={data} onUpdate={onUpdate} isEditable={true} />
                    </div>
                )}

                {activeTab === 'skills' && (
                    <SkillLibraryTab
                        skillsList={hybridSkills}
                        filteredSkills={filteredSkills}
                        usedSkillNames={usedSkillNames}
                        skillSearch={skillSearch}
                        setSkillSearch={setSkillSearch}
                        hideKnownSkills={hideKnownSkills}
                        setHideKnownSkills={setHideKnownSkills}
                        handleOfficialUpdateClick={handleOfficialUpdateClick}
                        setShowImportConfirm={setShowImportConfirm}
                        handleOpenNewSkill={handleOpenNewSkill}
                        handleOpenEditSkill={handleOpenEditSkill}
                        handleDeleteRequest={handleDeleteRequest}
                        getCategoryLabel={getCategoryLabel}
                    />
                )}

                {activeTab === 'specializations' && (
                    <div className="absolute inset-0">
                        <SpecializationLibraryView data={data} onUpdate={onUpdate} />
                    </div>
                )}
            </div>

            {/* Sub-Components (Modals) */}
            {skillToDelete && (
                <LibraryDeleteModal
                    skillName={skillToDelete.name}
                    onClose={() => setSkillToDelete(null)}
                    onConfirm={executeDeleteSkill}
                />
            )}

            {showImportConfirm && (
                <LibraryImportModal
                    onClose={() => setShowImportConfirm(false)}
                    onConfirm={executeImportFromSheet}
                />
            )}

            {isSkillModalOpen && editingSkill && (
                <LibrarySkillForm
                    isOpen={isSkillModalOpen}
                    onClose={() => setIsSkillModalOpen(false)}
                    title={data.skillLibrary?.some(s => s.id === editingSkill.id) ? 'Éditer Compétence' : 'Nouvelle Compétence (Copie)'}
                    skill={editingSkill}
                    onSkillChange={setEditingSkill}
                    onSave={() => handleSaveSkill(editingSkill)} // Passing editingSkill here
                    error={skillError}
                    categories={availableCategories.length > 0 ? availableCategories : undefined}
                />
            )}

            {showRenameConfirm && (
                <LibraryRenameModal
                    oldName={showRenameConfirm.oldName}
                    newName={showRenameConfirm.newSkill.name}
                    onClose={() => setShowRenameConfirm(null)}
                    onConfirm={() => finalizeSaveSkill(showRenameConfirm.newSkill, true)}
                />
            )}

        </div >
    );
};

export default LibraryView;

import React, { useEffect, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { GameSettingSummary, CampaignService } from '../services/CampaignService';
import { Cloud, Wifi, WifiOff, Loader2, ArrowRight, RotateCcw, BookOpen, Scroll, Sparkles, Clock } from 'lucide-react';
import { RulesData } from '../types/rules';
import { ErrorService } from '../services/ErrorService';
import { MotionFade } from './ui/motion/MotionFade';
import { MotionCard } from './ui/motion/MotionCard';
import ThematicButton from './ui/ThematicButton';

interface RulesSourceSelectorProps {
    isOpen: boolean;
    onSelectSource: (sourceType: 'online' | 'offline', rules?: RulesData, settingId?: string, settingName?: string) => void;
}

const RulesSourceSelector: React.FC<RulesSourceSelectorProps> = ({ isOpen, onSelectSource }) => {
    const [publicSettings, setPublicSettings] = useState<GameSettingSummary[]>([]);
    const [isLoading, setIsLoading] = useState(false);
    const [mode, setMode] = useState<'initial' | 'online_list'>('initial');

    // Check for existing session in localStorage
    const saved = localStorage.getItem('rpg-sheet-data');
    let resumeInfo: { name: string; campaign: string; settingId: string } | null = null;
    if (saved) {
        try {
            const parsed = JSON.parse(saved);
            if (parsed.header?.name || (parsed.syncInfo?.settingId)) {
                resumeInfo = {
                    name: parsed.header?.name || 'Sans Nom',
                    campaign: parsed.syncInfo?.settingName || 'Inconnue',
                    settingId: parsed.syncInfo?.settingId || 'orphan'
                };
            }
        } catch (e) {
            ErrorService.handleError(e, {
                context: 'RulesSourceSelector.parseLocalStorage',
                userMessage: 'Impossible de restaurer la session précédente',
                silent: true
            });
        }
    }

    const handleOnlineClick = async () => {
        setIsLoading(true);
        try {
            const settings = await CampaignService.listPublicSettings();
            setPublicSettings(settings);
            setMode('online_list');
        } catch (e) {
            ErrorService.handleError(e, { context: 'RulesSourceSelector.OnlineClick', userMessage: "Erreur de connexion : Impossible de récupérer la liste des campagnes." });
        } finally {
            setIsLoading(false);
        }
    };

    const handleResumeClick = async () => {
        if (!resumeInfo || resumeInfo.settingId === 'orphan') {
            onSelectSource('offline');
            return;
        }
        setIsLoading(true);
        try {
            const rules = await CampaignService.loadSetting(resumeInfo.settingId);
            if (rules) {
                onSelectSource('online', rules, resumeInfo.settingId, resumeInfo.campaign);
            } else {
                onSelectSource('offline');
            }
        } catch (e) {
            ErrorService.handleError(e, { context: 'RulesSourceSelector.Resume' });
            onSelectSource('offline');
        } finally {
            setIsLoading(false);
        }
    };

    const handleSettingClick = async (setting: GameSettingSummary) => {
        setIsLoading(true);
        try {
            const rules = await CampaignService.loadSetting(setting.id);
            if (rules) {
                onSelectSource('online', rules, setting.id, setting.name);
            }
        } catch (e) {
            ErrorService.handleError(e, { context: 'RulesSourceSelector.SettingClick', userMessage: "Une erreur critique est survenue lors du chargement." });
        } finally {
            setIsLoading(false);
        }
    };

    const handleOfflineClick = () => {
        onSelectSource('offline');
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-stone-950 flex flex-col items-center justify-center z-[100] p-4 font-sans overflow-hidden">
            {/* Background Texture & Effects */}
            <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/dark-leather.png')] opacity-30 pointer-events-none" />

            {/* Mystic Glows */}
            <motion.div
                animate={{
                    scale: [1, 1.2, 1],
                    opacity: [0.1, 0.2, 0.1],
                }}
                transition={{ duration: 8, repeat: Infinity, ease: "easeInOut" }}
                className="absolute top-1/4 left-1/4 w-[500px] h-[500px] bg-amber-900/30 rounded-full blur-[120px] pointer-events-none"
            />
            <motion.div
                animate={{
                    scale: [1.2, 1, 1.2],
                    opacity: [0.1, 0.2, 0.1],
                }}
                transition={{ duration: 10, repeat: Infinity, ease: "easeInOut" }}
                className="absolute bottom-1/4 right-1/4 w-[500px] h-[500px] bg-crimson-blood/20 rounded-full blur-[120px] pointer-events-none"
            />

            <div className="max-w-4xl w-full relative z-10 flex flex-col items-center">
                {/* Hero Header */}
                <MotionFade delay={0.2} className="text-center mb-16">
                    <div className="relative inline-block mb-6">
                        <Scroll size={80} className="text-amber-600/40 rotate-12 blur-sm" />
                        <Sparkles className="absolute -top-2 -right-2 text-amber-400 animate-pulse" size={24} />
                        <BookOpen size={64} className="absolute inset-0 m-auto text-amber-500 drop-shadow-[0_0_15px_rgba(245,158,11,0.5)]" />
                    </div>

                    <h1 className="text-4xl md:text-6xl font-serif font-black tracking-tighter mb-4 text-transparent bg-clip-text bg-gradient-to-b from-amber-200 via-amber-500 to-amber-800 drop-shadow-2xl">
                        ADRIRA LYELL
                    </h1>
                    <p className="text-amber-700/80 font-serif italic text-lg md:text-xl tracking-widest uppercase">
                        Les Chroniques de l'Investigateur
                    </p>
                    <div className="w-48 h-px bg-gradient-to-r from-transparent via-amber-900 to-transparent mx-auto mt-6" />
                </MotionFade>

                <AnimatePresence mode="wait">
                    {mode === 'initial' ? (
                        <motion.div
                            key="initial"
                            initial={{ opacity: 0, y: 20 }}
                            animate={{ opacity: 1, y: 0 }}
                            exit={{ opacity: 0, y: -20 }}
                            className="grid grid-cols-1 md:grid-cols-3 gap-6 w-full"
                        >
                            {/* Resume Card (Full width if single column, or part of grid) */}
                            {resumeInfo && (
                                <MotionCard
                                    hoverEffect="glow"
                                    onClick={handleResumeClick}
                                    className="p-8 border-indigo-900/30 bg-indigo-950/10 flex flex-col items-center text-center group"
                                >
                                    <div className="w-16 h-16 rounded-full bg-indigo-900/20 flex items-center justify-center mb-6 border border-indigo-500/30 group-hover:bg-indigo-600/40 transition-all shadow-[0_0_20px_rgba(79,70,229,0.2)]">
                                        <RotateCcw className="text-indigo-400" size={32} />
                                    </div>
                                    <h3 className="text-2xl font-serif font-bold text-indigo-300 mb-2">Reprendre</h3>
                                    <p className="text-indigo-500/70 text-sm mb-6 font-medium">
                                        {resumeInfo.name}<br />{resumeInfo.campaign}
                                    </p>
                                    <div className="mt-auto text-indigo-400 flex items-center gap-2 font-bold text-xs uppercase tracking-widest opacity-0 group-hover:opacity-100 transition-opacity">
                                        Continuer <ArrowRight size={14} />
                                    </div>
                                </MotionCard>
                            )}

                            {/* Online Card */}
                            <MotionCard
                                hoverEffect="glow"
                                onClick={handleOnlineClick}
                                className={`p-8 border-amber-900/30 bg-amber-950/10 flex flex-col items-center text-center group ${!resumeInfo ? 'md:col-span-1 md:col-start-1' : ''}`}
                            >
                                <div className="w-16 h-16 rounded-full bg-amber-900/20 flex items-center justify-center mb-6 border border-amber-500/30 group-hover:bg-amber-600/40 transition-all shadow-[0_0_20px_rgba(245,158,11,0.2)]">
                                    <Wifi className="text-amber-400" size={32} />
                                </div>
                                <h3 className="text-2xl font-serif font-bold text-amber-300 mb-2">Chroniques</h3>
                                <p className="text-amber-700/60 text-sm mb-6">
                                    Rejoindre une campagne<br />en ligne
                                </p>
                                <div className="mt-auto text-amber-400 flex items-center gap-2 font-bold text-xs uppercase tracking-widest opacity-0 group-hover:opacity-100 transition-opacity">
                                    Explorer <ArrowRight size={14} />
                                </div>
                            </MotionCard>

                            {/* Offline Card */}
                            <MotionCard
                                hoverEffect="glow"
                                onClick={handleOfflineClick}
                                className={`p-8 border-stone-800 bg-stone-900/20 flex flex-col items-center text-center group ${!resumeInfo ? 'md:col-span-1' : ''}`}
                            >
                                <div className="w-16 h-16 rounded-full bg-stone-800/40 flex items-center justify-center mb-6 border border-stone-700 group-hover:bg-stone-700 transition-all">
                                    <WifiOff className="text-stone-400" size={32} />
                                </div>
                                <h3 className="text-2xl font-serif font-bold text-stone-300 mb-2">Hors Ligne</h3>
                                <p className="text-stone-500/70 text-sm mb-6">
                                    Fiche indépendante<br />ou fichier local
                                </p>
                                <div className="mt-auto text-stone-400 flex items-center gap-2 font-bold text-xs uppercase tracking-widest opacity-0 group-hover:opacity-100 transition-opacity">
                                    Inscrire <ArrowRight size={14} />
                                </div>
                            </MotionCard>
                        </motion.div>
                    ) : (
                        <motion.div
                            key="online_list"
                            initial={{ opacity: 0, x: 50 }}
                            animate={{ opacity: 1, x: 0 }}
                            exit={{ opacity: 0, x: -50 }}
                            className="w-full max-w-2xl bg-stone-900/60 backdrop-blur-md border border-amber-900/30 rounded-sm p-8 shadow-glass relative"
                        >
                            <div className="flex items-center justify-between mb-8 pb-4 border-b border-amber-900/20">
                                <button
                                    onClick={() => setMode('initial')}
                                    className="text-amber-700 hover:text-amber-500 text-sm flex items-center gap-2 uppercase font-bold tracking-widest transition-colors"
                                >
                                    <ArrowRight size={16} className="rotate-180" /> Retour
                                </button>
                                <h2 className="text-xl font-serif font-bold text-amber-200 flex items-center gap-2">
                                    <Cloud size={20} className="text-amber-500" /> Campanages Publiques
                                </h2>
                            </div>

                            {isLoading ? (
                                <div className="flex flex-col items-center justify-center py-20 gap-4">
                                    <Loader2 className="animate-spin text-amber-600" size={48} />
                                    <span className="text-amber-700 font-serif italic">Consultation des archives...</span>
                                </div>
                            ) : (
                                <div className="max-h-[400px] overflow-y-auto space-y-3 pr-2 scrollbar-thin scrollbar-thumb-amber-900/50">
                                    {publicSettings.length === 0 ? (
                                        <div className="text-center py-10 text-stone-500 italic font-serif">
                                            Aucune chronique publique n'a été trouvée dans les registres.
                                        </div>
                                    ) : (
                                        publicSettings.map((setting, idx) => (
                                            <motion.button
                                                key={setting.id}
                                                initial={{ opacity: 0, y: 10 }}
                                                animate={{ opacity: 1, y: 0 }}
                                                transition={{ delay: idx * 0.05 }}
                                                onClick={() => handleSettingClick(setting)}
                                                className="w-full group flex items-center justify-between p-4 rounded-sm border border-stone-800 bg-stone-950/40 hover:border-amber-500/50 hover:bg-amber-950/20 transition-all text-left"
                                            >
                                                <div>
                                                    <div className="font-serif font-bold text-stone-200 group-hover:text-amber-400 transition-colors text-lg">
                                                        {setting.name}
                                                    </div>
                                                    <div className="text-[10px] font-bold text-amber-900 uppercase tracking-widest flex gap-3 mt-1">
                                                        <span className="bg-stone-900 px-1.5 py-0.5 rounded border border-stone-800">v{setting.version}</span>
                                                        <span className="flex items-center gap-1"><Clock size={10} /> {new Date(setting.last_updated).toLocaleDateString()}</span>
                                                    </div>
                                                </div>
                                                <ArrowRight size={20} className="text-stone-700 group-hover:text-amber-500 group-hover:translate-x-1 transition-all" />
                                            </motion.button>
                                        ))
                                    )}
                                </div>
                            )}

                            {/* Footer hint */}
                            <p className="mt-8 text-center text-stone-600 text-xs italic font-serif">
                                "Nul secret ne reste enfoui à jamais."
                            </p>
                        </motion.div>
                    )}
                </AnimatePresence>

                {/* Bottom decorative elements */}
                <MotionFade delay={1} className="mt-20 flex gap-12 text-amber-900/20 pointer-events-none">
                    <Scroll size={40} className="-rotate-12" />
                    <Sparkles size={30} />
                    <Scroll size={40} className="rotate-12" />
                </MotionFade>
            </div>
        </div>
    );
};

