    const [isSearching, setIsSearching] = useState(false);
    const [loadStatus, setLoadStatus] = useState<LoadStatus>('idle');
    const [errorMessage, setErrorMessage] = useState('');
    const [selectedCharId, setSelectedCharId] = useState<string | null>(null);
    const [showConfirm, setShowConfirm] = useState(false);
    const [pendingLoad, setPendingLoad] = useState<SyncedCharacterSummary | null>(null);
    const [pendingData, setPendingData] = useState<CharacterSheetData | null>(null);

    // Conflict Resolution State
    const [conflicts, setConflicts] = useState<DataConflict[]>([]);
    const [resolutionMap, setResolutionMap] = useState<Record<string, 'keep_current' | 'replace'>>({});
    const [isResolvingConflicts, setIsResolvingConflicts] = useState(false);

    const addLog = useNotification();

    const handleSearch = async () => {
        if (!playerName.trim()) {
            setErrorMessage('Veuillez saisir un nom de joueur');
            return;
        }

        setIsSearching(true);
        setErrorMessage('');
        setCharacters([]);

        const results = await CharacterSyncService.getCharactersByPlayerName(playerName);
        setCharacters(results);
        setIsSearching(false);

        if (results.length === 0) {
            setErrorMessage('Aucun personnage trouvé pour ce joueur');
        }
    };

    const handleLoadCharacter = async (char: SyncedCharacterSummary) => {
        // Check if local character exists
        if (data.header?.name && data.header.name.trim() !== '') {
            // Show confirmation modal
            setPendingLoad(char);
            setShowConfirm(true);
            return;
        }

        // No local character, load directly
        await performLoad(char);
    };

    const performLoad = async (char: SyncedCharacterSummary) => {
        setLoadStatus('loading');
        setSelectedCharId(char.id);
        setErrorMessage('');
        setShowConfirm(false);

        try {
            const fullCharacter = await CharacterSyncService.getCharacterById(char.id);

            if (!fullCharacter) {
                setLoadStatus('error');
                setErrorMessage('Échec du chargement du personnage');
                setSelectedCharId(null);
                return;
            }

            // Step 1: Restore images from cloud format to local IndexedDB
            fullCharacter.data = await ImageSyncResolver.injectImagesAfterSync(fullCharacter.data) as CharacterSheetData;

            const incomingData = fullCharacter.data;

            // Step 2: 3-Way Check (Dirty Check)
            const isLocalLinked = data.syncInfo?.syncId === char.id;
            const currentHash = CharacterSyncService.generateDataHash(data);
            const lastSyncedHash = data.syncInfo?.lastSyncedHash;
            const isLocalDirty = isLocalLinked && lastSyncedHash && currentHash !== lastSyncedHash;

            if (isLocalDirty && !isResolvingConflicts) {
                logger.info("Local character is dirty, forcing conflict resolver", { currentHash, lastSyncedHash });
                setConflicts([{
                    type: 'skill', // Fake conflict to trigger resolver
                    key: 'force_conflict_root',
                    name: 'Données Personnelles',
                    current: { name: 'Version Locale (Modifiée)', description: 'Vos changements non synchronisés' } as any,
                    incoming: { name: 'Version Cloud', description: 'Version du Gardien / Dernier backup' } as any
                }]);
                setPendingData(incomingData);
                setIsResolvingConflicts(true);
                setLoadStatus('idle');
                return;
            }

            // Step 3: Standard Library Conflict Detection
            if (data.header?.name && data.header.name.trim() !== '' && !isResolvingConflicts) {
                const detected = detectConflicts(
                    data.skillLibrary || [], incomingData.skillLibrary || [],
                    data.library || [], incomingData.library || [],
                    data.specializationLibrary || [], incomingData.specializationLibrary || []
                );

                if (detected.length > 0) {
                    setConflicts(detected);
                    const initialMap: Record<string, 'keep_current' | 'replace'> = {};
                    detected.forEach(c => initialMap[c.key] = 'keep_current');
                    setResolutionMap(initialMap);
                    setPendingData(incomingData);
                    setIsResolvingConflicts(true);
                    setLoadStatus('idle');
                    return;
                }
            }

            // Get campaign name for syncInfo
            const campaigns = await CampaignService.listPublicSettings();
            const campaign = campaigns.find(c => c.id === char.setting_id);

            // Update syncInfo
            const loadedData: CharacterSheetData = {
                ...incomingData,
                syncInfo: {
                    syncId: fullCharacter.id,
                    settingId: fullCharacter.setting_id || 'orphan',
                    settingName: campaign?.name || (fullCharacter.setting_id ? 'Campagne Inconnue' : 'Indépendant (Archives)'),
                    lastSynced: new Date(fullCharacter.last_synced).getTime(),
                    lastSyncedHash: CharacterSyncService.generateDataHash(incomingData),
                    mjMessage: incomingData.syncInfo?.mjMessage // Carry over any MJ message
                }
            };

            setLoadStatus('success');
            if (onLoadSuccess) onLoadSuccess(loadedData);
            setTimeout(() => onClose(), 1500);

        } catch (error) {
            ErrorService.handleError(error, { context: 'CloudPanel.performLoad', userMessage: "Erreur lors du chargement." });
            setLoadStatus('error');
            setErrorMessage('Erreur technique lors du chargement');
        }
    };

    const handleConfirmMerge = () => {
        if (!pendingData || !pendingLoad) return;

        try {
            const mergedSkills = smartMerge(data.skillLibrary || [], pendingData.skillLibrary || [], resolutionMap, 'skill');
            const mergedTraits = smartMerge(data.library || [], pendingData.library || [], resolutionMap, 'trait');
            const mergedSpecs = smartMerge(data.specializationLibrary || [], pendingData.specializationLibrary || [], resolutionMap, 'specialization');

            const finalData: CharacterSheetData = {
                ...pendingData,
                skillLibrary: mergedSkills,
                library: mergedTraits,
                specializationLibrary: mergedSpecs,
                syncInfo: {
                    syncId: pendingLoad.id,
                    settingId: pendingLoad.setting_id || 'orphan',
                    settingName: 'Fusion Cloud', // Simplification or fetch campaign name
                    lastSynced: Date.now()
                }
            };

            setLoadStatus('success');
            if (onLoadSuccess) onLoadSuccess(finalData);
            addLog("Synchronisation et fusion réussies.", 'success', 'both');
            onClose();
        } catch (error) {
            ErrorService.handleError(error, { context: 'CloudPanel.handleConfirmMerge' });
            addLog("Erreur lors de la fusion.", 'danger', 'both');
        }
    };

    return (
        <div className="flex flex-col gap-4">
            {/* Info Banner */}
            <div className="bg-blue-50 border border-blue-200 rounded-md p-3 text-sm text-blue-800">
                <p>
                    Chargez un personnage précédemment synchronisé depuis le cloud.
                    Saisissez votre nom de joueur pour voir vos personnages.
                </p>
            </div>

            {/* Search Section */}
            <div className="flex gap-3">
                <div className="flex-grow">
                    <label className="block text-sm font-bold text-[#4a3b32] mb-1.5">
                        Nom du Joueur
                    </label>
                    <input
                        type="text"
                        value={playerName}
                        onChange={(e) => setPlayerName(e.target.value)}
                        onKeyPress={(e) => e.key === 'Enter' && handleSearch()}
                        placeholder="Votre nom"
                        className="w-full px-3 py-2 border border-[#bfae85] rounded-md bg-white text-[#2c241b] focus:outline-none focus:ring-2 focus:ring-[#8b2e2e]"
                    />
                </div>
                <div className="flex items-end">
                    <button
                        onClick={handleSearch}
                        disabled={isSearching || !playerName.trim()}
                        className={`px-6 py-2 rounded-md font-bold flex items-center gap-2 transition-all ${isSearching || !playerName.trim()
                            ? 'bg-gray-300 text-gray-500 cursor-not-allowed'
                            : 'bg-[#2d5a27] hover:bg-[#3d7a37] text-white'
                            }`}
                    >
                        {isSearching ? (
                            <>
                                <Loader2 size={18} className="animate-spin" />
                                Recherche...
                            </>
                        ) : (
                            <>
                                <Cloud size={18} />
                                Rechercher
                            </>
                        )}
                    </button>
                </div>
            </div>

            {/* Error Message */}
            {errorMessage && (
                <div className="bg-red-50 border border-red-300 rounded-md p-3 text-sm text-red-700 flex items-center gap-2">
                    <AlertTriangle size={16} />
                    {errorMessage}
                </div>
            )}

            {/* Characters List */}
            {characters.length > 0 && (
                <div className="border border-[#bfae85] rounded-md overflow-hidden">
                    <div className="bg-[#8b2e2e] text-white px-4 py-2 font-bold flex items-center gap-2">
                        <Cloud size={18} />
                        Personnages trouvés ({characters.length})
                    </div>
                    <div className="max-h-96 overflow-y-auto">
                        {characters.map((char) => (
                            <div
                                key={char.id}
                                className="border-b border-[#bfae85]/30 last:border-b-0 p-4 hover:bg-[#bfae85]/10 transition-colors"
                            >
                                <div className="flex justify-between items-center">
                                    <div className="flex-grow">
                                        <div className="font-bold text-[#2c241b]">
                                            {char.character_name}
                                        </div>
                                        <div className="text-sm text-stone-600">
                                            Dernière sync : {new Date(char.last_synced).toLocaleString('fr-FR')}
                                        </div>
                                    </div>
                                    <button
                                        onClick={() => handleLoadCharacter(char)}
                                        disabled={loadStatus === 'loading'}
                                        className={`px-4 py-2 rounded-md font-bold flex items-center gap-2 transition-all ${selectedCharId === char.id && loadStatus === 'loading'
                                            ? 'bg-gray-300 text-gray-500'
                                            : selectedCharId === char.id && loadStatus === 'success'
                                                ? 'bg-green-600 text-white'
                                                : 'bg-[#2d5a27] hover:bg-[#3d7a37] text-white'
                                            }`}
                                    >
                                        {selectedCharId === char.id && loadStatus === 'loading' ? (
                                            <>
                                                <Loader2 size={16} className="animate-spin" />
                                                Chargement...
                                            </>
                                        ) : selectedCharId === char.id && loadStatus === 'success' ? (
                                            <>
                                                <CheckCircle size={16} />
                                                Chargé !
                                            </>
                                        ) : (
                                            <>
                                                <Download size={16} />
                                                Charger
                                            </>
                                        )}
                                    </button>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            )}

            {/* Confirmation Modal */}
            {showConfirm && pendingLoad && (
                <ThematicModal
                    isOpen={showConfirm}
                    onClose={() => { setShowConfirm(false); setPendingLoad(null); }}
                    title="Confirmer le chargement"
                    scheme="mystic"
                >
                    <div className="p-4">
                        <p className="text-stone-300 mb-6">
                            Vous avez déjà un personnage local (<strong>{data.header?.name}</strong>).
                            Voulez-vous fusionner les données ou tout écraser ?
                        </p>
                        <div className="flex flex-col gap-3">
                            <ThematicButton
                                variant="primary"
                                onClick={() => performLoad(pendingLoad)}
                            >
                                Charger (Vérifier les conflits de bibliothèque)
                            </ThematicButton>
                            <ThematicButton
                                variant="secondary"
                                onClick={() => {
                                    // Hack: simulate no conflicts to force overwrite or add separate logic
                                    // For now, performLoad will naturally detect conflicts if name exists.
                                    performLoad(pendingLoad);
                                }}
                            >
                                Écraser tout
                            </ThematicButton>
                        </div>
                    </div>
                </ThematicModal>
            )}

            {/* Conflict Resolver Overlay */}
            {isResolvingConflicts && (
                <div className="fixed inset-0 z-[70] bg-black/80 flex items-center justify-center p-4">
                    <div className="bg-stone-950 w-full max-w-4xl h-[80vh] rounded-2xl overflow-hidden shadow-2xl border border-amber-900/30">
                        <CloudConflictResolver
                            conflicts={conflicts}
                            resolutionMap={resolutionMap}
                            onResolutionChoice={(key, choice) => setResolutionMap(prev => ({ ...prev, [key]: choice }))}
                            onResolveAll={(choice) => {
                                const newMap: Record<string, 'keep_current' | 'replace'> = {};
                                conflicts.forEach(c => newMap[c.key] = choice);
                                setResolutionMap(newMap);
                            }}
                            onCancel={() => setIsResolvingConflicts(false)}
                            onConfirm={handleConfirmMerge}
                        />
                    </div>
                </div>
            )}
        </div>
    );
};

export default CloudPanel;

import React, { useState, useEffect } from 'react';
import { CharacterSheetData } from '../../types';
import { Download, User, Shield, LayoutTemplate, Layers, BookOpen, GraduationCap, Award } from 'lucide-react';
import { APP_VERSION } from '../../constants/app';
import { createTemplateFromData } from '../../utils/importExportUtils';
import { getImage, blobToBase64 } from '../../services/imageDB';
import { useNotification } from '../../context/NotificationContext';
import { ImageCompressionService } from '../../services/ImageCompressionService';
import { ImageSyncResolver } from '../../services/ImageSyncResolver';
import { ErrorService } from '../../services/ErrorService';

interface ExportPanelProps {
    data: CharacterSheetData;
    variant: 'player' | 'gm';
    onExportSuccess?: () => void;
}

type ExportType = 'full' | 'system' | 'template' | 'library_traits' | 'library_skills' | 'library_specs' | 'library_all';

const ExportPanel: React.FC<ExportPanelProps> = ({ data, variant, onExportSuccess }) => {
    const [exportType, setExportType] = useState<ExportType>('full');
    const addLog = useNotification();

    // Force default export type when opening in player mode
    useEffect(() => {
        if (variant === 'player') {
            setExportType('full');
        }
    }, [variant]);

    const handleExport = async () => {
        let exportData: any = {};
        let filename = "Sauvegarde";

        const dataToProcess = JSON.parse(JSON.stringify(data));

        // Resolve Character Image from DB if present
        if (dataToProcess.page2?.characterImageId) {
            try {
                const blob = await getImage(dataToProcess.page2.characterImageId);
                if (blob) {
                    const base64 = await blobToBase64(blob);
                    dataToProcess.page2.characterImage = base64;
                }
            } catch (e) {
                ErrorService.handleError(e, { context: 'ExportPanel.exportCharImage', silent: true });
            }
            delete dataToProcess.page2.characterImageId;
        }

        // Resolve Campaign Notes Images
        if (dataToProcess.campaignNotes) {
            for (const note of dataToProcess.campaignNotes) {
                // Main Image
                if (note.imageId && note.imageId.startsWith('img_')) {
                    try {
                        const blob = await getImage(note.imageId);
                        if (blob) {
                            (note as any).base64Cover = await blobToBase64(blob);
                        }
                    } catch (e) {
                        ErrorService.handleError(e, { context: 'ExportPanel.exportNoteCover', silent: true });
                    }
                    delete note.imageId;
                }

                // Gallery Images
                if (note.images && Array.isArray(note.images)) {
                    for (const img of note.images) {
                        if (img.imageId) {
                            try {
                                const blob = await getImage(img.imageId);
                                if (blob) {
                                    (img as any).base64Data = await blobToBase64(blob);
                                }
                            } catch (e) {
                                ErrorService.handleError(e, { context: 'ExportPanel.exportNoteImage', silent: true });
                            }
                            delete img.imageId;
                        }
                    }
                }
            }
        }

        // --- PERSIST LOCAL SETTINGS ---
        const expertMode = localStorage.getItem('rpg-sheet-expert-mode') === 'true';
        const activeRulesId = localStorage.getItem('rules-source-id') || undefined;

        dataToProcess.syncInfo = {
            ...dataToProcess.syncInfo,
            localSettings: {
                expertMode,
                activeRulesId
            }
        };

        if (!dataToProcess.appVersion) {
            dataToProcess.appVersion = APP_VERSION;
        }

        const template = createTemplateFromData(dataToProcess);
        if (!(template as any).appVersion) {
            (template as any).appVersion = APP_VERSION;
        }

        const now = new Date();
        const day = String(now.getDate()).padStart(2, '0');
        const month = String(now.getMonth() + 1).padStart(2, '0');
        const year = now.getFullYear();
        const hours = String(now.getHours()).padStart(2, '0');
        const minutes = String(now.getMinutes()).padStart(2, '0');
        const timestamp = `${day}-${month}-${year}_${hours}h${minutes}`;

        switch (exportType) {
            case 'full':
                exportData = dataToProcess;
                filename = `${timestamp}_Personnage_${data.header.name || 'SansNom'}`;
                break;
            case 'system':
                // Template + ALL Libraries
                exportData = template;
                exportData.library = data.library;
                exportData.skillLibrary = data.skillLibrary;
                exportData.specializationLibrary = data.specializationLibrary;
                filename = `${timestamp}_Systeme_Jeu`;
                break;
            case 'template':
                exportData = template;
                delete exportData.library;
                delete exportData.skillLibrary;
                delete exportData.specializationLibrary;
                filename = `${timestamp}_Template_Structure`;
                break;
            case 'library_traits':
                exportData = { library: data.library, appVersion: APP_VERSION };
                filename = `${timestamp}_Biblio_Traits`;
                break;
            case 'library_skills':
                exportData = { skillLibrary: data.skillLibrary, appVersion: APP_VERSION };
                filename = `${timestamp}_Biblio_Competences`;
                break;
            case 'library_specs':
                exportData = { specializationLibrary: data.specializationLibrary, appVersion: APP_VERSION };
                filename = `${timestamp}_Biblio_Specialisations`;
                break;
        }

        // --- COMPRESS IMAGES IN EXPORT DATA ---
        addLog("Compression des images en cours...", 'info', 'sheet', 'img-compress');
        try {
            // resolveImagesForSync is more comprehensive than simple processImages
            // because it handles bookImage nodes too.
            const portableData = await ImageSyncResolver.resolveImagesForSync(exportData);
            exportData = portableData;
            addLog("Images compressées avec succès.", 'success', 'sheet', 'img-compress');
        } catch (e) {
            ErrorService.handleError(e, { context: 'ExportPanel.compression', silent: true });
            addLog("Avertissement : La compression des images a échoué, export brut utilisé.", 'danger', 'sheet', 'img-compress');
        }

        const blob = new Blob([JSON.stringify(exportData, null, 2)], { type: "application/json" });
        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = `${filename}.json`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        URL.revokeObjectURL(url);

        if (onExportSuccess) onExportSuccess();
        addLog(`Sauvegarde réussie (${exportType}) : ${filename}.json`, 'info', 'both');
    };

    const isGM = variant === 'gm';

    return (
        <div className="flex-1 bg-slate-50 p-6 flex flex-col animate-in fade-in duration-300">
            <div className="space-y-3 flex-grow overflow-y-auto custom-scrollbar">
                {!isGM && (
                    <div className="flex flex-col items-center justify-center h-full gap-4 text-center">
                        <div className="bg-blue-100 p-6 rounded-full text-blue-600 mb-2">
                            <User size={48} />
                        </div>
                        <h4 className="text-lg font-bold text-slate-700">Sauvegarder ma fiche</h4>
                        <p className="text-sm text-slate-500 max-w-sm">
                            Télécharge un fichier <code>.json</code> complet contenant toutes vos statistiques, votre journal et vos images.
                        </p>
                    </div>
                )}

                {isGM && (
                    <>
                        {/* Character & System */}
                        <div className="space-y-3 mb-6">
                            <h4 className="text-xs font-bold text-gray-400 uppercase">Données Principales</h4>
                            <label className={`flex items-start gap-3 p-4 rounded-lg border cursor-pointer transition-all ${exportType === 'full' ? 'bg-white border-blue-500 shadow-md ring-1 ring-blue-500' : 'border-slate-200 hover:bg-white'}`}>
                                <input type="radio" name="exportType" checked={exportType === 'full'} onChange={() => setExportType('full')} className="mt-1 accent-blue-600" />
                                <div>
                                    <span className="font-bold text-slate-800 flex items-center gap-2"><User size={16} /> Personnage Complet</span>
                                    <span className="text-xs text-slate-500 block mt-1">Tout ce que contient la fiche actuelle (Valeurs, Notes, Images, Bibliothèques).</span>
                                </div>
                            </label>

                            <label className={`flex items-start gap-3 p-4 rounded-lg border cursor-pointer transition-all ${exportType === 'system' ? 'bg-white border-blue-500 shadow-md ring-1 ring-blue-500' : 'border-slate-200 hover:bg-white'}`}>
                                <input type="radio" name="exportType" checked={exportType === 'system'} onChange={() => setExportType('system')} className="mt-1 accent-blue-600" />
                                <div>
                                    <span className="font-bold text-slate-800 flex items-center gap-2"><Shield size={16} /> Système de Jeu (MJ)</span>
                                    <span className="text-xs text-slate-500 block mt-1">Structure + Bibliothèques. <span className="text-red-500 font-bold">Sans les valeurs du joueur.</span> Idéal pour partager un template.</span>
                                </div>
                            </label>

                            <label className={`flex items-start gap-3 p-4 rounded-lg border cursor-pointer transition-all ${exportType === 'template' ? 'bg-white border-blue-500 shadow-md ring-1 ring-blue-500' : 'border-slate-200 hover:bg-white'}`}>
                                <input type="radio" name="exportType" checked={exportType === 'template'} onChange={() => setExportType('template')} className="mt-1 accent-blue-600" />
                                <div>
                                    <span className="font-bold text-slate-800 flex items-center gap-2"><LayoutTemplate size={16} /> Structure Seule</span>
                                    <span className="text-xs text-slate-500 block mt-1">Uniquement la configuration des compétences et attributs. Pas de bibliothèque.</span>
                                </div>
                            </label>
                        </div>

                        {/* Libraries */}
                        <div className="space-y-3">
                            <h4 className="text-xs font-bold text-gray-400 uppercase">Bibliothèques</h4>
                            <label className={`flex items-start gap-3 p-4 rounded-lg border cursor-pointer transition-all ${exportType === 'library_all' ? 'bg-white border-blue-500 shadow-md ring-1 ring-blue-500' : 'border-slate-200 hover:bg-white'}`}>
                                <input type="radio" name="exportType" checked={exportType === 'library_all'} onChange={() => setExportType('library_all')} className="mt-1 accent-blue-600" />
                                <div>
                                    <span className="font-bold text-slate-800 flex items-center gap-2"><Layers size={16} /> Bibliothèques Complètes</span>
                                    <span className="text-xs text-slate-500 block mt-1">Traits + Compétences + Catalogue de Spés.</span>
                                </div>
                            </label>

                            <div className="grid grid-cols-2 gap-3">
                                <label className={`flex items-start gap-2 p-3 rounded-lg border cursor-pointer transition-all ${exportType === 'library_traits' ? 'bg-white border-blue-500 shadow-md ring-1 ring-blue-500' : 'border-slate-200 hover:bg-white'}`}>
                                    <input type="radio" name="exportType" checked={exportType === 'library_traits'} onChange={() => setExportType('library_traits')} className="mt-1 accent-blue-600" />
                                    <div>
                                        <span className="font-bold text-slate-800 flex items-center gap-1 text-sm"><BookOpen size={14} /> Traits</span>
                                        <span className="text-[10px] text-slate-500 block">Avantages / Désavantages seuls.</span>
                                    </div>
                                </label>

                                <label className={`flex items-start gap-2 p-3 rounded-lg border cursor-pointer transition-all ${exportType === 'library_skills' ? 'bg-white border-blue-500 shadow-md ring-1 ring-blue-500' : 'border-slate-200 hover:bg-white'}`}>
                                    <input type="radio" name="exportType" checked={exportType === 'library_skills'} onChange={() => setExportType('library_skills')} className="mt-1 accent-blue-600" />
                                    <div>
                                        <span className="font-bold text-slate-800 flex items-center gap-1 text-sm"><GraduationCap size={14} /> Skills</span>
                                        <span className="text-[10px] text-slate-500 block">Réserve seule.</span>
                                    </div>
                                </label>

                                <label className={`flex items-start gap-2 p-3 rounded-lg border cursor-pointer transition-all ${exportType === 'library_specs' ? 'bg-white border-blue-500 shadow-md ring-1 ring-blue-500' : 'border-slate-200 hover:bg-white'}`}>
                                    <input type="radio" name="exportType" checked={exportType === 'library_specs'} onChange={() => setExportType('library_specs')} className="mt-1 accent-blue-600" />
                                    <div>
                                        <span className="font-bold text-slate-800 flex items-center gap-1 text-sm"><Award size={14} /> Spés</span>
                                        <span className="text-[10px] text-slate-500 block">Catalogue seul.</span>
                                    </div>
                                </label>
                            </div>
                        </div>
                    </>
                )}
            </div>

            <div className="mt-4 pt-4 border-t border-slate-200">
                <button
                    onClick={handleExport}
                    className="w-full bg-blue-600 text-white px-4 py-3 rounded-lg hover:bg-blue-700 transition-all font-bold flex items-center justify-center gap-2 shadow-lg hover:-translate-y-0.5"
                >
                    <Download size={20} />
                    Sauvegarder
                </button>
            </div>
        </div>
    );
};

export default ExportPanel;

import React, { useRef } from 'react';
import { Upload } from 'lucide-react';
import { logger } from '../../utils/logger';

interface FileDropZoneProps {
    onFileSelect: (json: any) => void;
}

export const FileDropZone: React.FC<FileDropZoneProps> = ({ onFileSelect }) => {
    const fileInputRef = useRef<HTMLInputElement>(null);

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        const reader = new FileReader();
        reader.onload = (event) => {
            try {
                const json = JSON.parse(event.target?.result as string);
                onFileSelect(json);
                if (fileInputRef.current) fileInputRef.current.value = "";
            } catch (error) {
                logger.error("Error parsing JSON", error);
                // Parent handles error mostly via context, but we should probably bubble up error?
                // The hook `handleFileLoad` catches errors.
                // But here we are just parsing.
                // Let's pass the raw string? No, parent expects JSON.
                // We will rely on parent passing a handler that catches errors if possible?
                // Or better, let's keep parsing here and pass object.
            }
        };
        reader.readAsText(file);
    };

    return (
        <div className="flex-grow flex flex-col justify-center items-center text-center space-y-6 border-2 border-dashed border-slate-300 rounded-xl bg-slate-50 p-8 hover:bg-orange-50 hover:border-orange-300 transition-colors cursor-pointer group" onClick={() => fileInputRef.current?.click()}>
            <div className="p-5 bg-white rounded-full shadow-sm text-slate-400 group-hover:text-orange-500 transition-colors">
                <Upload size={48} />
            </div>
            <div>
                <p className="text-lg text-slate-700 font-bold mb-2">
                    Cliquez pour sélectionner un fichier
                </p>
                <p className="text-sm text-slate-500">
                    Accepte les fichiers <code>.json</code>
                </p>
            </div>
            <input
                type="file"
                accept=".json"
                ref={fileInputRef}
                className="hidden"
                onChange={handleFileChange}
            />
            <button
                className="bg-white border border-slate-300 text-slate-700 px-6 py-2 rounded-full font-bold hover:bg-white hover:text-orange-600 hover:border-orange-400 transition-colors shadow-sm pointer-events-none"
            >
                Parcourir...
            </button>
        </div>
    );
};

import React from 'react';
import {
    AlertTriangle, User, FileBox, LayoutTemplate, Merge, RefreshCw, GraduationCap, BookOpen, Award
} from 'lucide-react';
import { APP_VERSION } from '../../constants/app';

interface ImportOptionsSectionProps {
    analysis: {
        hasHeader: boolean;
        hasStructure: boolean;
        hasLibrary: boolean;
        hasSkillLibrary: boolean;
        hasSpecLibrary: boolean;
        isFilled: boolean;
        fileVersion?: string;
        versionMismatch: boolean;
    };
    variant: 'player' | 'gm';
    importAction: string;
    onActionChange: (action: string) => void;
}

const ImportOptionsSection: React.FC<ImportOptionsSectionProps> = ({
    analysis,
    variant,
    importAction,
    onActionChange
}) => {
    const versionWarning = analysis.versionMismatch && (
        <div className="mb-4 p-3 bg-amber-50 border border-amber-200 rounded-lg flex items-start gap-3 text-amber-800">
            <AlertTriangle size={18} className="mt-0.5 shrink-0" />
            <div className="text-xs">
                <p className="font-bold mb-1">Décalage de version détecté</p>
                <p>Ce fichier (v{analysis.fileVersion || '???'}) est différent de votre version actuelle (v{APP_VERSION}).</p>
                <p className="mt-1 opacity-80 italic">Une conversion automatique sera tentée lors de l'importation.</p>
            </div>
        </div>
    );

    if (variant === 'player') {
        return (
            <div className="space-y-4 h-full">
                {versionWarning}
                <div className="bg-orange-50 border border-orange-200 rounded p-4 text-center">
                    <User size={32} className="mx-auto text-orange-600 mb-2" />
                    <p className="font-bold text-orange-900 text-sm mb-1">Prêt à charger</p>
                    <p className="text-xs text-orange-800">
                        Ce fichier va remplacer votre personnage actuel.
                    </p>
                </div>
            </div>
        );
    }

    const options = [];

    // 1. STRUCTURE IMPORTS
    if (analysis.hasStructure) {
        options.push(
            <div key="group_struct" className="mb-4">
                <div className="text-xs font-bold text-gray-400 uppercase mb-2">Structure & Personnage</div>
                <div className="space-y-2">
                    <label className={`flex items-start gap-3 p-3 rounded-lg border cursor-pointer transition-all ${importAction === 'replace_all' ? 'bg-red-50 border-red-500 ring-1 ring-red-500' : 'border-gray-200 hover:bg-gray-50'}`}>
                        <input type="radio" name="importAction" checked={importAction === 'replace_all'} onChange={() => onActionChange('replace_all')} className="mt-1" />
                        <div>
                            <span className="font-bold text-gray-800 flex items-center gap-2"><User size={16} /> Tout remplacer (Clone)</span>
                            <span className="text-xs text-red-600 block mt-1"><AlertTriangle size={12} className="inline mr-1" />Toutes vos données actuelles seront perdues.</span>
                        </div>
                    </label>
                    <label className={`flex items-start gap-3 p-3 rounded-lg border cursor-pointer transition-all ${importAction === 'system' ? 'bg-orange-50 border-orange-500 ring-1 ring-orange-500' : 'border-gray-200 hover:bg-gray-50'}`}>
                        <input type="radio" name="importAction" checked={importAction === 'system'} onChange={() => onActionChange('system')} className="mt-1" />
                        <div>
                            <span className="font-bold text-gray-800 flex items-center gap-2"><FileBox size={16} /> Système de Jeu (MJ)</span>
                            <span className="text-xs text-orange-600 block mt-1">Écrase structure et bibliothèques. Réinitialise les valeurs.</span>
                        </div>
                    </label>
                    {!analysis.hasLibrary && !analysis.hasSkillLibrary && (
                        <label className={`flex items-start gap-3 p-3 rounded-lg border cursor-pointer transition-all ${importAction === 'template' ? 'bg-orange-50 border-orange-500 ring-1 ring-orange-500' : 'border-gray-200 hover:bg-gray-50'}`}>
                            <input type="radio" name="importAction" checked={importAction === 'template'} onChange={() => onActionChange('template')} className="mt-1" />
                            <div>
                                <span className="font-bold text-gray-800 flex items-center gap-2"><LayoutTemplate size={16} /> Structure Seule</span>
                                <span className="text-xs text-orange-600 block mt-1">Structure uniquement. Vos bibliothèques sont conservées.</span>
                            </div>
                        </label>
                    )}
                </div>
            </div>
        );
    }

    // 2. COMBINED LIBRARY IMPORTS
    if (analysis.hasLibrary && analysis.hasSkillLibrary) {
        options.push(
            <div key="group_all_libs" className="mb-4">
                <div className="text-xs font-bold text-gray-400 uppercase mb-2">Toutes les Bibliothèques</div>
                <div className="space-y-2">
                    <label className={`flex items-start gap-3 p-3 rounded-lg border cursor-pointer transition-all ${importAction === 'all_libs_merge' ? 'bg-green-50 border-green-500 ring-1 ring-green-500' : 'border-gray-200 hover:bg-gray-50'}`}>
                        <input type="radio" name="importAction" checked={importAction === 'all_libs_merge'} onChange={() => onActionChange('all_libs_merge')} className="mt-1" />
                        <div>
                            <span className="font-bold text-gray-800 flex items-center gap-2"><Merge size={16} /> Tout Fusionner (Bibliothèques)</span>
                            <span className="text-xs text-gray-600 block mt-1">Ajoute le contenu sans toucher à votre fiche.</span>
