    }

    return (
        <div className="space-y-3 max-h-[350px] overflow-y-auto pr-2 custom-scrollbar">
            {versionWarning}
            {options}
        </div>
    );
};

export default ImportOptionsSection;

import { useState, useRef } from 'react';
import { CharacterSheetData } from '../../../types';
import { useNotification } from '../../../context/NotificationContext';
import { useCharacter } from '../../../context/CharacterContext';
import { APP_VERSION } from '../../../constants/app';
import { createTemplateFromData, detectConflicts, smartMerge, DataConflict } from '../../../utils/importExportUtils';
import { base64ToBlob, saveImage } from '../../../services/imageDB';
import { ImageSyncResolver } from '../../../services/ImageSyncResolver';
import { ErrorService } from '../../../services/ErrorService';

export interface FileAnalysis {
    hasHeader: boolean;
    hasStructure: boolean;
    hasLibrary: boolean;
    hasSkillLibrary: boolean;
    hasSpecLibrary: boolean;
    isFilled: boolean;
    fileVersion?: string;
    versionMismatch: boolean;
}

interface UseImportLogicProps {
    data: CharacterSheetData;
    variant: 'player' | 'gm';
    onImportSuccess?: (newData: CharacterSheetData) => void;
    onClose: () => void;
}

export function useImportLogic({ data, variant, onImportSuccess, onClose }: UseImportLogicProps) {
    const { importData } = useCharacter();
    const addLog = useNotification();

    const [pendingFile, setPendingFile] = useState<Partial<CharacterSheetData> | null>(null);
    const [analysis, setAnalysis] = useState<FileAnalysis | null>(null);
    const [importAction, setImportAction] = useState<string>('');

    // Conflict Resolution State
    const [conflicts, setConflicts] = useState<DataConflict[]>([]);
    const [resolutionMap, setResolutionMap] = useState<Record<string, 'keep_current' | 'replace'>>({});
    const [isResolvingConflicts, setIsResolvingConflicts] = useState(false);

    // Migration Status
    const [migrationReport, setMigrationReport] = useState<{ oldVersion: string; newVersion: string } | null>(null);

    const checkFileCompatibility = (json: any) => {
        const hasHeader = !!json.header;
        const hasStructure = !!(json.skills && json.attributes);
        const hasLibrary = !!(json.library && Array.isArray(json.library) && json.library.length > 0);
        const hasSkillLibrary = !!(json.skillLibrary && Array.isArray(json.skillLibrary) && json.skillLibrary.length > 0);
        const hasSpecLibrary = !!(json.specializationLibrary && Array.isArray(json.specializationLibrary) && json.specializationLibrary.length > 0);

        const fileVersion = json.appVersion;
        const versionMismatch = fileVersion !== APP_VERSION;
        const isFilled = (json.header && json.header.name) || (json.experience && parseInt(json.experience.spent) > 0);
        const hasAnyLib = hasLibrary || hasSkillLibrary || hasSpecLibrary;

        if (!hasStructure && !hasAnyLib) {
            addLog("Ce fichier ne semble pas être compatible (aucune donnée reconnue).", 'danger', 'both');
            return null;
        }

        return { hasHeader, hasStructure, hasLibrary, hasSkillLibrary, hasSpecLibrary, isFilled, fileVersion, versionMismatch };
    };

    const handleFileLoad = (json: any) => {
        try {
            const analysisResult = checkFileCompatibility(json);
            if (!analysisResult) return;

            setPendingFile(json);
            setAnalysis(analysisResult);

            if (variant === 'player') {
                setImportAction('replace_all');
            } else {
                setImportAction('');
            }
        } catch (error) {
            ErrorService.handleError(error, { context: 'useImportLogic.handleFileLoad', userMessage: "Erreur lors de l'analyse du fichier." });
            addLog("Erreur lors de l'analyse du fichier.", 'danger', 'both');
        }
    };

    const processImportedData = async (dataObj: Partial<CharacterSheetData>) => {
        try {
            // ImageSyncResolver.injectImagesAfterSync is the source of truth for restoring 
            // portable data (compressed base64) to local data (IndexedDB IDs).
            const localData = await ImageSyncResolver.injectImagesAfterSync(dataObj);
            return localData;
        } catch (e) {
            ErrorService.handleError(e, { context: 'useImportLogic.processImportedData', silent: true });
            return dataObj;
        }
    };

    const executeImport = async () => {
        if (!pendingFile || !importAction) return;

        const importedFile: any = pendingFile;
        // --- CONFLICT CHECK FOR MERGES ---
        if ((['skill_lib_merge', 'lib_merge', 'all_libs_merge'].includes(importAction)) && !isResolvingConflicts) {
            const checkSkills = importAction.includes('skill') || importAction.includes('all');
            const checkTraits = importAction.includes('lib_merge') || importAction.includes('all');

            const currentSkills = checkSkills ? (data.skillLibrary || []) : [];
            const incomingSkills = checkSkills ? (importedFile.skillLibrary || []) : [];

            const currentTraits = checkTraits ? (data.library || []) : [];
            const incomingTraits = checkTraits ? (importedFile.library || []) : [];

            const currentSpecs = checkTraits ? (data.specializationLibrary || []) : [];
            const incomingSpecs = checkTraits ? (importedFile.specializationLibrary || []) : [];

            const detected = detectConflicts(currentSkills, incomingSkills, currentTraits, incomingTraits, currentSpecs, incomingSpecs);

            if (detected.length > 0) {
                setConflicts(detected);

                // Pre-fill resolution map with 'keep_current'
                const initialMap: Record<string, 'keep_current' | 'replace'> = {};
                detected.forEach(c => initialMap[c.key] = 'keep_current');
                setResolutionMap(initialMap);

                setIsResolvingConflicts(true);
                return;
            }
        }

        // --- PROCEED WITH IMPORT ---

        let finalData = { ...data };
        let logMsg = "";

        if (importAction === 'replace_all') {
            finalData = (await processImportedData(pendingFile!)) as CharacterSheetData;
            if (!finalData.library) finalData.library = [];
            if (!finalData.skillLibrary) finalData.skillLibrary = [];
            if (!finalData.specializationLibrary) finalData.specializationLibrary = [];
            logMsg = "Remplacement complet du personnage.";
        }
        else if (importAction === 'system') {
            const template = createTemplateFromData(importedFile);
            finalData = template;
            if (importedFile.library) finalData.library = importedFile.library as any;
            else finalData.library = [];
            if (importedFile.skillLibrary) finalData.skillLibrary = importedFile.skillLibrary as any;
            else finalData.skillLibrary = [];
            if (importedFile.specializationLibrary) finalData.specializationLibrary = importedFile.specializationLibrary as any;
            else finalData.specializationLibrary = [];

            logMsg = "Chargement du Système (Template + Bibliothèques).";
        }
        else if (importAction === 'template') {
            const template = createTemplateFromData(importedFile);
            finalData = template;
            finalData.library = data.library || [];
            finalData.skillLibrary = data.skillLibrary || [];
            finalData.specializationLibrary = data.specializationLibrary || [];
            logMsg = "Chargement du Template. Bibliothèques conservées.";
        }

        // TRAITS ACTIONS
        else if (importAction === 'lib_replace') {
            finalData.library = importedFile.library as any || [];
            logMsg = "Remplacement de la Bibliothèque de Traits.";
        }
        else if (importAction === 'lib_merge') {
            finalData.library = smartMerge(data.library || [], (importedFile.library || []) as any[], resolutionMap, 'trait');
            logMsg = "Fusion de la Bibliothèque de Traits.";
        }

        // SKILLS ACTIONS
        else if (importAction === 'skill_lib_replace') {
            finalData.skillLibrary = importedFile.skillLibrary as any || [];
            logMsg = "Remplacement de la Réserve de Compétences.";
        }
        else if (importAction === 'skill_lib_merge') {
            finalData.skillLibrary = smartMerge(data.skillLibrary || [], (importedFile.skillLibrary || []) as any[], resolutionMap, 'skill');
            logMsg = "Fusion de la Réserve de Compétences.";
        }

        // SPECIALIZATION ACTIONS
        else if (importAction === 'spec_lib_replace') {
            finalData.specializationLibrary = importedFile.specializationLibrary as any || [];
            logMsg = "Remplacement du Catalogue de Spécialisations.";
        }
        else if (importAction === 'spec_lib_merge') {
            finalData.specializationLibrary = smartMerge(data.specializationLibrary || [], (importedFile.specializationLibrary || []) as any[], resolutionMap, 'specialization');
            logMsg = "Fusion du Catalogue de Spécialisations.";
        }

        // COMBINED ACTIONS
        else if (importAction === 'all_libs_replace') {
            if (importedFile.library) finalData.library = importedFile.library as any;
            if (importedFile.skillLibrary) finalData.skillLibrary = importedFile.skillLibrary as any;
            if (importedFile.specializationLibrary) finalData.specializationLibrary = importedFile.specializationLibrary as any;
            logMsg = "Remplacement de toutes les bibliothèques.";
        }
        else if (importAction === 'all_libs_merge') {
            if (importedFile.library) {
                finalData.library = smartMerge(data.library || [], (importedFile.library || []) as any[], resolutionMap, 'trait');
            }
            if (importedFile.skillLibrary) {
                finalData.skillLibrary = smartMerge(data.skillLibrary || [], (importedFile.skillLibrary || []) as any[], resolutionMap, 'skill');
            }
            if (importedFile.specializationLibrary) {
                finalData.specializationLibrary = smartMerge(data.specializationLibrary || [], (importedFile.specializationLibrary || []) as any[], resolutionMap, 'specialization');
            }
            logMsg = "Fusion de toutes les bibliothèques.";
        }

        if (Object.keys(resolutionMap).length > 0) {
            logMsg += ` (${Object.keys(resolutionMap).length} conflits résolus)`;
        }

        importData(finalData);
        if (onImportSuccess) onImportSuccess(finalData);

        if (analysis?.versionMismatch) {
            addLog(`${logMsg} (Migration effectuée). Nous vous conseillons de sauvegarder votre personnage immédiatement.`, 'success', 'both');
            setMigrationReport({
                oldVersion: analysis.fileVersion || 'Inconnue',
                newVersion: APP_VERSION
            });
        } else {
            addLog(logMsg, 'success', 'both');
            onClose();
        }
    };

    const handleSuccessClose = () => {
        setMigrationReport(null);
        onClose();
    };

    const handleResolutionChoice = (key: string, choice: 'keep_current' | 'replace') => {
        setResolutionMap(prev => ({ ...prev, [key]: choice }));
    };

    const resolveAll = (choice: 'keep_current' | 'replace') => {
        const newMap: Record<string, 'keep_current' | 'replace'> = {};
        conflicts.forEach(c => newMap[c.key] = choice);
        setResolutionMap(newMap);
    };

    return {
        pendingFile,
        setPendingFile,
        analysis,
        setAnalysis,
        importAction,
        setImportAction,
        conflicts,
        resolutionMap,
        isResolvingConflicts,
        setIsResolvingConflicts,
        migrationReport,
        handleFileLoad,
        executeImport,
        handleSuccessClose,
        handleResolutionChoice,
        resolveAll
    };
}

import React, { useState } from 'react';
import { Book, Settings, FileText, Layout, Save, Upload, Feather, LogOut, Printer, Monitor, Smartphone, History, HelpCircle, ScrollText, ArrowRightLeft, BookOpen, Download, RectangleVertical, RectangleHorizontal, Palette, UploadCloud, Info, Menu, X, AlertTriangle } from 'lucide-react';
import { useCharacter } from '../../context/CharacterContext';
import { useRules } from '../../context/RulesContext';
import { useStorageUsage } from '../../hooks/useStorageUsage';
import { CharacterSheetData } from '../../types';
import RulesStatus from '../ui/RulesStatus';
import { motion, AnimatePresence } from 'framer-motion';

interface DiegeticNavigationProps {
    currentMode: 'sheet' | 'settings';
    onModeChange: (mode: 'sheet' | 'settings') => void;
    onOpenImportExport: () => void;
    onPrintRequest: () => void;
    onToggleLandscape: () => void;
    isLandscape: boolean;
    onShowLogs: () => void;
    showLogs: boolean;
    onShowUserGuide: () => void;
    onShowChangelog: () => void;
    onOpenAppearance: () => void;
    onOpenSync: () => void;
    syncStatus?: 'none' | 'synced' | 'pending' | 'update-available';
    appVersion: string;
    onShowCampaignInfo: () => void;
    autoSaveCountdown?: number;
}

const DiegeticNavigation: React.FC<DiegeticNavigationProps> = ({
    currentMode, onModeChange, onOpenImportExport,
    onPrintRequest, onToggleLandscape, isLandscape,
    onShowLogs, showLogs, onShowUserGuide, onShowChangelog, onOpenAppearance, onOpenSync, syncStatus, appVersion,
    onShowCampaignInfo, autoSaveCountdown
}) => {
    const { data, isSyncing } = useCharacter();
    const { rules } = useRules();
    const { stats } = useStorageUsage();
    const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

    const toggleMobileMenu = () => setIsMobileMenuOpen(!isMobileMenuOpen);

    const menuItems = [
        { label: 'Thème', icon: <Palette size={18} />, onClick: onOpenAppearance },
        {
            label: 'Réglages',
            icon: (
                <div className="relative">
                    <Settings size={18} />
                    {(stats?.isCritical || stats?.isWarning) && (
                        <div className={`absolute -top-1 -right-1 w-2.5 h-2.5 rounded-full border border-gray-900 ${stats.isCritical ? 'bg-red-500 animate-pulse' : 'bg-amber-500'}`} />
                    )}
                </div>
            ),
            onClick: () => { onModeChange('settings'); setIsMobileMenuOpen(false); },
            active: currentMode === 'settings',
            isWarning: stats?.isCritical || stats?.isWarning
        },
        { label: 'Import/Export', icon: <Download size={18} />, onClick: onOpenImportExport },
        {
            label: 'Synchro',
            icon: (
                <div className="relative">
                    <UploadCloud size={18} />
                    {syncStatus === 'update-available' && (
                        <div className="absolute -top-1 -right-1 w-2.5 h-2.5 rounded-full bg-amber-500 border border-gray-900 animate-pulse" />
                    )}
                </div>
            ),
            onClick: onOpenSync,
            highlight: data.syncInfo?.isAutoSyncEnabled || syncStatus === 'update-available'
        },
        { label: 'Imprimer', icon: <Printer size={18} />, onClick: onPrintRequest },
        { label: 'Historique', icon: <History size={18} />, onClick: onShowLogs, active: showLogs },
        { label: 'Guide', icon: <HelpCircle size={18} />, onClick: onShowUserGuide },
        { label: 'Changelog', icon: <ScrollText size={18} />, onClick: onShowChangelog },
    ];

    return (
        <nav className="bg-gray-800 text-white px-4 shadow-md no-print sticky top-0 z-50 h-14 flex items-center border-b border-gray-700 relative">
            <div className="max-w-[1920px] mx-auto flex justify-between items-center w-full">

                {/* Left: Toggles + Sheet Button */}
                <div className="flex items-center gap-2 md:gap-4 mr-4 z-10">
                    <button
                        onClick={onToggleLandscape}
                        className={`px-3 py-1.5 rounded-lg flex items-center gap-2 transition-all ${isLandscape
                            ? 'bg-indigo-600 text-white border border-indigo-400'
                            : 'bg-gray-700 text-gray-300 border border-gray-600 hover:bg-gray-600'
                            }`}
                        title={isLandscape ? "Passer en Portrait" : "Passer en Paysage"}
                        aria-label={isLandscape ? "Passer en Portrait" : "Passer en Paysage"}
                    >
                        {isLandscape ? <RectangleHorizontal size={18} /> : <RectangleVertical size={18} />}
                    </button>

                    <button
                        onClick={onOpenAppearance}
                        className="px-3 py-1.5 rounded-lg flex items-center gap-2 transition-all bg-gray-700 text-gray-300 border border-gray-600 hover:bg-gray-600 hover:text-white"
                        title="Changer l'apparence"
                        aria-label="Changer l'apparence"
                    >
                        <Palette size={18} />
                    </button>

                    <div className="w-px h-6 bg-gray-600 hidden md:block"></div>

                    {/* Sheet Button & Setting Badge */}
                    <div className="flex flex-col md:flex-row md:items-center gap-1 md:gap-3">
                        <button
                            onClick={() => onModeChange('sheet')}
                            className={`px-3 md:px-4 py-1.5 rounded-md text-xs md:text-sm font-bold transition-colors flex items-center gap-2 ${currentMode === 'sheet'
                                ? 'bg-blue-600 text-white shadow-sm'
                                : 'text-gray-300 hover:text-white hover:bg-gray-700'}`}
                        >
                            <FileText size={16} /> <span className="hidden sm:inline">Fiche</span>
                        </button>

                        {(rules as any)?.settingName && (
                            <div className="flex items-center gap-1.5 pl-2.5 pr-1 py-1 bg-slate-700/50 border border-slate-600 rounded-full text-[10px] md:text-xs font-medium text-slate-300 animate-in fade-in slide-in-from-left-2 duration-300">
                                <div className="w-1.5 h-1.5 rounded-full bg-blue-500 shadow-[0_0_8px_rgba(59,130,246,0.5)]"></div>
                                <span className="font-bold text-white truncate max-w-[80px] md:max-w-[150px]">
                                    {(rules as any).settingName}
                                </span>
                                {rules?.showMetadataToPlayers && (
                                    <button
                                        onClick={onShowCampaignInfo}
                                        className="ml-2 p-1 bg-blue-600 hover:bg-blue-500 text-white rounded-full transition-all active:scale-90"
                                        title="Voir les infos de campagne"
                                        aria-label="Voir les infos de campagne"
                                    >
                                        <Info size={10} />
                                    </button>
                                )}
                            </div>
                        )}
                    </div>

                </div>

                {/* Center: Character Name (Hidden on very small) */}
                <div className="absolute left-1/2 top-1/2 transform -translate-x-1/2 -translate-y-1/2 hidden sm:flex flex-col items-center pointer-events-none z-0">
                    <span className="text-[9px] text-gray-400 uppercase font-bold leading-none text-center">Personnage</span>
                    <span className="text-xs font-bold text-gray-200 max-w-[200px] truncate leading-tight text-center">
                        {data.header?.name || 'Sans Nom'}
                    </span>
                </div>

                {/* Right: Main Navigation + Tools */}
                <div className="flex items-center gap-1 md:gap-2 z-10">

                    {/* Desktop Tools */}
                    <div className="hidden md:flex items-center gap-2">
                        <div className="flex items-center gap-2 mr-4 border-r border-gray-600 pr-4">
                            <button
                                onClick={() => onModeChange('settings')}
                                className={`px-4 py-1.5 rounded-md text-sm font-bold transition-all flex items-center gap-2 relative ${currentMode === 'settings'
                                    ? 'bg-blue-600 text-white shadow-sm'
                                    : 'text-gray-300 hover:text-white hover:bg-gray-700'}`}
                                title="Réglages"
                            >
                                <div className="relative">
                                    <Settings size={16} />
                                    {(stats?.isCritical || stats?.isWarning) && (
                                        <div className="absolute -top-1.5 -right-1.5 flex items-center justify-center">
                                            {stats.isCritical && <span className="animate-ping absolute inline-flex h-2.5 w-2.5 rounded-full bg-red-400 opacity-75"></span>}
                                            <span className={`relative inline-flex rounded-full h-2 w-2 border border-gray-900 ${stats.isCritical ? 'bg-red-500' : 'bg-amber-500'}`}></span>
                                        </div>
                                    )}
                                </div>
                                {stats?.isCritical && (
                                    <AlertTriangle size={14} className="text-red-400 animate-pulse ml-0.5" />
                                )}
                                {stats?.isWarning && !stats?.isCritical && (
                                    <AlertTriangle size={14} className="text-amber-400 ml-0.5" />
                                )}
                            </button>
                        </div>

                        <button
                            onClick={onOpenImportExport}
                            className="bg-amber-700/20 hover:bg-amber-700/40 text-amber-500 hover:text-amber-400 border border-amber-700/50 px-3 py-1.5 rounded-lg flex items-center gap-2 transition-all text-sm font-bold"
                            title="Sauvegarder / Charger"
                        >
                            <Save size={18} />
                        </button>

                        <button
                            onClick={onOpenSync}
                            className={`px-3 py-1.5 rounded-lg flex items-center gap-2 transition-all text-sm font-bold border relative ${syncStatus === 'synced'
                                ? 'bg-green-700/20 text-green-500 border-green-700/50'
                                : syncStatus === 'update-available'
                                    ? 'bg-amber-700/30 text-amber-400 border-amber-500 shadow-[0_0_10px_rgba(245,158,11,0.2)] animate-pulse'
                                    : 'bg-purple-700/20 text-purple-400 border-purple-700/50'
                                }`}
                        >
                            <UploadCloud size={18} className={isSyncing ? "animate-spin-slow" : ""} />
                            <span className="hidden lg:inline">Sync</span>
                            {syncStatus === 'update-available' && (
                                <span className="absolute -top-1 -right-1 flex h-3 w-3">
                                    <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-amber-400 opacity-75"></span>
                                    <span className="relative inline-flex rounded-full h-3 w-3 bg-amber-500 border border-gray-900"></span>
                                </span>
                            )}
                            {/* Auto-Save Countdown Badge */}
                            {typeof autoSaveCountdown === 'number' && (
                                <span className="absolute -bottom-2 -right-2 bg-blue-600 text-white text-[10px] font-mono font-bold w-5 h-5 flex items-center justify-center rounded-full shadow border-2 border-gray-800 z-10">
                                    {autoSaveCountdown}
                                </span>
                            )}
                        </button>

                        <button onClick={onPrintRequest} className="p-2 bg-gray-700 hover:bg-gray-600 text-gray-300 rounded-lg"><Printer size={18} /></button>
                        <button onClick={onShowLogs} className={`p-2 rounded-lg ${showLogs ? 'bg-gray-200 text-gray-900' : 'bg-gray-700 text-gray-300'}`}><History size={18} /></button>
                    </div>

                    <div className="h-8 flex items-center border-l md:border-r border-gray-600 px-2">
                        <RulesStatus />
                    </div>

                    <button
                        onClick={onShowChangelog}
                        className="hidden md:flex items-center gap-1 bg-indigo-900/30 text-indigo-300 border border-indigo-800/50 px-2 py-1.5 rounded-lg text-xs font-mono"
                    >
                        v{appVersion}
                    </button>

                    {/* Mobile Menu Button */}
                    <button
                        onClick={toggleMobileMenu}
                        className="md:hidden p-2 bg-gray-700 hover:bg-gray-600 text-white rounded-lg transition-colors border border-gray-600"
                        aria-label="Menu"
                    >
                        {isMobileMenuOpen ? <X size={20} /> : <Menu size={20} />}
                    </button>
                </div>
            </div>

            {/* Mobile Menu Overlay */}
            <AnimatePresence>
                {isMobileMenuOpen && (
                    <motion.div
                        initial={{ opacity: 0, x: '100%' }}
                        animate={{ opacity: 1, x: 0 }}
                        exit={{ opacity: 0, x: '100%' }}
                        className="fixed inset-0 top-14 bg-gray-900/95 backdrop-blur-md z-[100] md:hidden overflow-y-auto"
                    >
                        <div className="p-6 grid grid-cols-2 gap-4">
                            {menuItems.map((item, idx) => (
                                <button
                                    key={idx}
                                    onClick={() => { item.onClick(); setIsMobileMenuOpen(false); }}
                                    className={`flex flex-col items-center justify-center p-6 rounded-xl border transition-all gap-3 ${item.active
                                        ? 'bg-blue-600 border-blue-400 text-white'
                                        : 'bg-gray-800 border-gray-700 text-gray-300 active:bg-gray-700'
                                        } ${item.highlight ? 'ring-2 ring-purple-500' : ''}`}
                                >
                                    <div className={`${item.active ? 'text-white' : 'text-amber-500'}`}>
                                        {item.icon}
                                    </div>
                                    <span className="text-xs font-bold uppercase tracking-widest">{item.label}</span>
                                </button>
                            ))}

                            <div className="col-span-2 pt-6 border-t border-gray-800 flex justify-between items-center text-[10px] text-gray-500 font-mono uppercase">
                                <span>Version {appVersion}</span>
                                <span className="text-gray-600 italic">"Les ombres attendent"</span>
                            </div>
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>
        </nav>
    );
};

export default DiegeticNavigation;

import React, { useState, useEffect, lazy, Suspense } from 'react';
import { useNotification } from '../../context/NotificationContext';
import { useCharacter } from '../../context/CharacterContext';
import { NotificationProvider } from '../../context/NotificationContext';
import { CharacterSheetData } from '../../types';
import { APP_VERSION } from '../../constants/app';
import { migrateData } from '../../utils/migrations';
import { useRules } from '../../context/RulesContext';
import { loadRules } from '../../services/RulesLoader';
import { RulesData } from '../../types/rules';
import { CampaignService } from '../../services/CampaignService';
import { ErrorService } from '../../services/ErrorService';
import { INITIAL_DATA } from '../../data/initialState';
import { logger } from '../../utils/logger';
import { useCloudSyncCheck } from '../../hooks/useCloudSyncCheck';
import { useAutoSave } from '../../hooks/useAutoSave';
import { useRealtimeSync } from '../../hooks/useRealtimeSync';

// Static Components
import DiegeticNavigation from './DiegeticNavigation';
import CharacterSheet from '../CharacterSheet';
import CharacterSheetPage2 from '../CharacterSheetPage2';
import CharacterSheetSpecializations from '../CharacterSheetSpecializations';
import CharacterSheetXP from '../CharacterSheetXP';

// Lazy Loaded Components
const SettingsView = lazy(() => import('../SettingsView'));
const CampaignNotes = lazy(() => import('../CampaignNotes'));
const ImportExportModal = lazy(() => import('../ImportExportModal'));
const PrintSelectionModal = lazy(() => import('../PrintSelectionModal'));
const ChangelogModal = lazy(() => import('../ChangelogModal'));
const UserGuideModal = lazy(() => import('../UserGuideModal'));
const CreationHUD = lazy(() => import('../CreationHUD'));
const UpdateNotifier = lazy(() => import('../UpdateNotifier'));
const AppearanceModal = lazy(() => import('../AppearanceModal'));
const RulesSourceSelector = lazy(() => import('../RulesSourceSelector'));
const SyncModal = lazy(() => import('../SyncModal'));
const CampaignConflictModal = lazy(() => import('../ui/CampaignConflictModal'));
const CampaignInfoModal = lazy(() => import('../ui/CampaignInfoModal'));
import ConfirmationModal from '../ui/ConfirmationModal';

import { exportCharacterAsJSON } from '../../utils/importExportUtils';
import { useNavigationState } from '../../hooks/layout/useNavigationState';
import { usePrintManager } from '../../hooks/layout/usePrintManager';
import { useRulesSync } from '../../hooks/layout/useRulesSync';
import PostItBoard from '../ui/PostItBoard';

// Icons
import { Settings, Printer, FileText, Layers, FileType, AlertTriangle, List, TrendingUp, History, Clock, X, Trash2, Save, Book, LogOut, Menu, Upload } from 'lucide-react';

const MainLayout: React.FC = () => {
    const { data, updateData: setData, addLog, importData, isSyncing, sync } = useCharacter();
    const { rules, updateRules, isOnlineMode, reloadRules } = useRules();

    // Custom Hooks
    const [isLandscape, setIsLandscape] = useState(() => {
        if (typeof window !== 'undefined') {
            const saved = localStorage.getItem('rpg-landscape-mode');
            return saved === 'true';
        }
        return false;
    });

    useEffect(() => {
        localStorage.setItem('rpg-landscape-mode', String(isLandscape));
    }, [isLandscape]);
    const {
        mode, setMode,
        sheetTab, setSheetTab,
        showDiscardConfirm, setShowDiscardConfirm,
        isSettingsDirty, setIsSettingsDirty,
        handleSwitchMode,
        confirmDiscard
    } = useNavigationState();

    const {
        showPrintModal, setShowPrintModal,
        pagesToPrint,
        handlePrintConfirm
    } = usePrintManager(isLandscape);

    const {
        isSourceSelected, setIsSourceSelected,
        showConflict, setShowConflict,
        pendingRules,
        handleSourceSelect,
        handleConfirmReset
    } = useRulesSync(data, rules, setData, updateRules, addLog);

    const { hasUpdate, mjMessage } = useCloudSyncCheck(data);

    // Notifications temps réel : admin → joueur
    useRealtimeSync({
        settingId: rules?.settingId,
        characterId: data?.syncInfo?.syncId,
        isOnlineMode,
        reloadRules,
        addLog,
    });

    // Auto-Save Logic
    const { countdown } = useAutoSave(data, false, (mode) => sync(mode));

    // Other UI States
    const [lastSavedState, setLastSavedState] = useState<string>("");
    const [showImportExport, setShowImportExport] = useState(false);
    const [showChangelog, setShowChangelog] = useState(false);
    const [showUserGuide, setShowUserGuide] = useState(false);
    const [showLogs, setShowLogs] = useState(false);
    const [historyTab, setHistoryTab] = useState<'sheet' | 'settings'>('sheet');
    const [showAppearance, setShowAppearance] = useState(false);
    const [showSync, setShowSync] = useState(false);
    const [showCampaignInfo, setShowCampaignInfo] = useState(false);

    // Guidance Logic
    const shouldHighlightMystic = React.useMemo(() => {
        const active = rules?.configurations?.creation?.mysticAbilities?.active;
        const hasTrait = data?.page2?.avantages?.some((t: any) => t.mysticAbilityId);
        return !!(active && !hasTrait && data?.creationConfig?.active);
    }, [rules, data]);

    // Initialize Reference State & Error Service
    useEffect(() => {
        if (data) setLastSavedState(JSON.stringify(data));
        ErrorService.init(addLog);

        // Show welcome message if available and not shown in this session
        if (rules?.showMetadataToPlayers && rules?.welcomeMessage) {
            const hasShownWelcome = sessionStorage.getItem(`welcome-shown-${rules.settingId}`);
            if (!hasShownWelcome) {
                setShowCampaignInfo(true);
                sessionStorage.setItem(`welcome-shown-${rules.settingId}`, 'true');
            }
        }
    }, []);

    // Logging helpers
    const clearCurrentLogs = () => {
        setData((prev: CharacterSheetData) => ({
            ...prev,
            appLogs: prev.appLogs.filter((log: any) => log.category !== historyTab)
        }));
    };

    const filteredLogs = (data.appLogs || []).filter((log: any) => {
        if (log.category === 'both') return true;
        return log.category === historyTab;
    });

    const handlePrintRequest = () => setShowPrintModal(true);

    const handleImportSuccess = async (newData: CharacterSheetData) => {
        setIsSourceSelected(true);
        sessionStorage.setItem('rpg-source-selected', 'true');
        importData(newData);
        const migrated = migrateData(newData);

        const syncInfo = migrated.syncInfo; // Extract syncInfo for clarity

        if (syncInfo?.settingId) {
            const currentSettingId = rules?.settingId;
            try {
                const freshRules = await CampaignService.loadSetting(syncInfo.settingId);
                if (freshRules && syncInfo) {
                    updateRules({
                        ...freshRules,
                        settingId: syncInfo.settingId,
                        settingName: syncInfo.settingName
                    });

                    // Added narrowing check for TypeScript
                    if (syncInfo.settingId !== currentSettingId) {
                        addLog(`Règles de la campagne "${syncInfo.settingName}" chargées.`, 'success', 'settings');
                    }
                }
            } catch (e) {
                ErrorService.handleError(e, { context: 'MainLayout.handleImportSuccess', userMessage: "Echec de la synchro des règles." });
            }
        }

        setMode('sheet');
        setIsSettingsDirty(false);
        setLastSavedState(JSON.stringify(newData));
    };

    useEffect(() => {
        if (hasUpdate) {
            addLog("Mise à jour disponible sur le Cloud (Note du MJ possible). Cliquez sur 'Sync' pour voir.", "success");
            // Debug log to console if in dev
            if (import.meta.env.DEV) {
                logger.log("[Sync] Update detected:", { hasUpdate, mjMessage });
            }
        }
    }, [hasUpdate, mjMessage, addLog]);

    const handleConfirmBackup = async () => {
        await exportCharacterAsJSON(data, addLog);
    };



    if (!rules || !isSourceSelected) {
        return (
            <div className="fixed inset-0 bg-[#1c1c1c] text-white flex items-center justify-center z-50 bg-[url('https://www.transparenttextures.com/patterns/aged-paper.png')]">
                <Suspense fallback={<div className="text-white animate-pulse">Chargement des règles...</div>}>
                    <RulesSourceSelector
                        isOpen={true}
                        onSelectSource={handleSourceSelect}
                    />

                    {/* Render conflict modal here too because rules are still null during conflict resolution */}
                    <CampaignConflictModal
                        isOpen={showConflict}
                        onClose={() => setShowConflict(false)}
                        characterName={data.header?.name}
                        currentCampaignName={data.syncInfo?.settingName || 'Indépendante'}
                        newCampaignName={pendingRules?.name || ''}
                        onConfirmReset={handleConfirmReset}
                        onStay={() => setShowConflict(false)}
                        onBackup={handleConfirmBackup}
                    />
                </Suspense>
            </div>
        );
    }

    return (
        <NotificationProvider value={addLog}>
            <div className={`min-h-screen bg-[#1c1c1c] text-stone-200 font-sans selection:bg-red-900 selection:text-white ${isLandscape ? 'landscape-mode' : ''}`}>
                <Suspense fallback={null}>
                    <UpdateNotifier />
                </Suspense>

                {/* Background Texture (Parchemin Global) */}
                <div className="fixed inset-0 pointer-events-none z-0 opacity-20 bg-[url('https://www.transparenttextures.com/patterns/aged-paper.png')]"></div>

                {/* NEW: Diegetic Navigation (Styled as Classic) */}
                <DiegeticNavigation
                    currentMode={mode}
                    onModeChange={handleSwitchMode}
                    onOpenImportExport={() => setShowImportExport(true)}
                    onPrintRequest={handlePrintRequest}
                    onToggleLandscape={() => setIsLandscape(!isLandscape)}
                    isLandscape={isLandscape}
                    onShowLogs={() => setShowLogs(!showLogs)}
                    showLogs={showLogs}
                    onShowUserGuide={() => setShowUserGuide(true)}
                    onShowChangelog={() => setShowChangelog(true)}
                    onOpenAppearance={() => setShowAppearance(true)}
                    onOpenSync={() => setShowSync(true)}
                    syncStatus={
                        isSyncing ? 'pending' :
                            hasUpdate ? 'update-available' :
                                data.syncInfo ? 'synced' : 'none'
                    }
                    appVersion={APP_VERSION}
                    onShowCampaignInfo={() => setShowCampaignInfo(true)}
                    autoSaveCountdown={countdown}
                />

                <div className="relative z-10 flex flex-col min-h-screen">

                    {/* Logs Panel */}
                    <aside
                        className={`fixed right-0 top-14 bottom-0 w-80 bg-white shadow-2xl border-l border-gray-200 transform transition-transform duration-300 z-[60] flex flex-col no-print ${showLogs ? 'translate-x-0' : 'translate-x-full'}`}
                        aria-label="Historique des actions"
                    >
                        <div className="bg-gray-100 border-b border-gray-200">
                            <div className="p-3 flex justify-between items-center">
                                <h4 className="font-bold text-sm text-gray-700 flex items-center gap-2"><Clock size={16} /> Historique</h4>
                                <div className="flex items-center gap-1">
                                    {filteredLogs.length > 0 && (<button onClick={clearCurrentLogs} className="text-gray-500 hover:text-red-600 hover:bg-red-50 rounded p-1 transition-colors" title="Vider la liste actuelle"><Trash2 size={16} /></button>)}
                                    <button onClick={() => setShowLogs(false)} className="text-gray-500 hover:bg-gray-200 rounded p-1"><X size={16} /></button>
                                </div>
                            </div>
                            <div className="flex text-sm font-medium border-t border-gray-200">
                                <button onClick={() => setHistoryTab('sheet')} className={`flex-1 py-2 text-center transition-colors border-b-2 ${historyTab === 'sheet' ? 'border-blue-500 text-blue-700 bg-white' : 'border-transparent text-gray-500 hover:bg-gray-50 hover:text-gray-700'}`}>Fiche</button>
                                <button onClick={() => setHistoryTab('settings')} className={`flex-1 py-2 text-center transition-colors border-b-2 ${historyTab === 'settings' ? 'border-blue-500 text-blue-700 bg-white' : 'border-transparent text-gray-500 hover:bg-gray-50 hover:text-gray-700'}`}>Configuration</button>
                            </div>
                        </div>
                        <div className="flex-grow overflow-y-auto p-4 space-y-3 bg-gray-50">
                            {filteredLogs.length === 0 && (<div className="text-center text-gray-400 text-xs italic mt-4 flex flex-col items-center gap-2"><Clock size={24} className="opacity-20" /><p>Aucune action enregistrée pour {historyTab === 'sheet' ? 'la fiche' : 'la configuration'}</p></div>)}
                            {filteredLogs.map((log) => (
                                <div key={log.id} className={`p-2 rounded border text-xs shadow-sm flex flex-col gap-1 animate-in slide-in-from-right-2 fade-in duration-300 ${log.type === 'success' ? 'bg-green-50 border-green-200 text-green-800' : log.type === 'danger' ? 'bg-red-50 border-red-200 text-red-800' : 'bg-white border-gray-200 text-gray-700'}`}>
                                    <div className="flex justify-between items-center opacity-70 border-b border-black/5 pb-1 mb-1"><span className="font-mono text-[10px]">{log.timestamp}</span></div>
                                    <p>{log.message}</p>
                                </div>
                            ))}
                        </div>
                    </aside>

                    {/* Main Content */}
                    <main className={`mt-4 flex flex-col items-center gap-4 w-full main-content-area ${data.creationConfig?.active ? 'pb-40' : ''}`}>
                        <Suspense fallback={<div className="p-8 text-center text-stone-400">Chargement...</div>}>
                            {mode === 'sheet' ? (
                                <>
                                    {/* Sub Navigation for Sheets */}
                                    <nav
                                        className="sticky top-14 z-40 mb-2 no-print w-full flex justify-center pointer-events-none"
                                        aria-label="Navigation des onglets de personnage"
                                    >
                                        <div className="pointer-events-auto flex gap-4 bg-white/90 backdrop-blur p-1.5 rounded-full shadow-lg border border-gray-200 flex-wrap justify-center">
                                            <button onClick={() => setSheetTab('p1')} className={`px-4 py-2 rounded-full font-bold text-sm flex items-center gap-2 transition-all ${sheetTab === 'p1' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-100'}`}><Layers size={16} /> Personnage</button>
                                            <button onClick={() => setSheetTab('specs')} className={`px-4 py-2 rounded-full font-bold text-sm flex items-center gap-2 transition-all ${sheetTab === 'specs' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-100'}`}><List size={16} /> Spécialisations</button>
                                            <button
                                                onClick={() => setSheetTab('p2')}
                                                className={`px-4 py-2 rounded-full font-bold text-sm flex items-center gap-2 transition-all 
                                                    ${sheetTab === 'p2'
                                                        ? 'bg-blue-600 text-white shadow-md'
                                                        : shouldHighlightMystic
                                                            ? 'bg-amber-100/30 text-amber-600 border border-amber-400/50 shadow-[0_0_12px_rgba(245,158,11,0.2)] animate-pulse'
                                                            : 'text-gray-600 hover:bg-gray-100'
                                                    }`}
                                            >
                                                <FileType size={16} />
                                                Détails & Equipement
                                                {shouldHighlightMystic && sheetTab !== 'p2' && (
                                                    <span className="ml-1 w-2 h-2 rounded-full bg-amber-500 animate-ping"></span>
                                                )}
                                            </button>
                                            <button onClick={() => setSheetTab('xp')} className={`px-4 py-2 rounded-full font-bold text-sm flex items-center gap-2 transition-all ${sheetTab === 'xp' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-100'}`}><TrendingUp size={16} /> Gestion XP</button>
                                            <button onClick={() => setSheetTab('notes')} className={`px-4 py-2 rounded-full font-bold text-sm flex items-center gap-2 transition-all ${sheetTab === 'notes' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-100'}`}><Book size={16} /> Notes de Campagne</button>
                                        </div>
                                    </nav>



                                    <div className={`w-full flex px-2 md:px-0 pb-8 ${sheetTab === 'notes' ? 'overflow-visible' : sheetTab === 'prototype' ? 'overflow-hidden' : 'overflow-x-auto'}`}>
                                        <div className={`${sheetTab === 'p1' ? 'block' : 'hidden'} mx-auto`}><CharacterSheet isLandscape={isLandscape} /></div>
                                        <div className={`${sheetTab === 'specs' ? 'block' : 'hidden'} mx-auto`}><CharacterSheetSpecializations isLandscape={isLandscape} /></div>
                                        <div className={`${sheetTab === 'p2' ? 'block' : 'hidden'} mx-auto`}><CharacterSheetPage2 isLandscape={isLandscape} /></div>
                                        <div className={`${sheetTab === 'xp' ? 'block' : 'hidden'} mx-auto`}><CharacterSheetXP isLandscape={isLandscape} /></div>
                                        <div className={`${sheetTab === 'notes' ? 'block' : 'hidden'} mx-auto`}><CampaignNotes /></div>
                                    </div>

                                    {data.creationConfig?.active && (<CreationHUD />)}
                                    <PostItBoard currentTab={sheetTab} />
                                </>
                            ) : (
                                <SettingsView
                                    onClose={() => handleSwitchMode('sheet')}
                                    onDirtyChange={setIsSettingsDirty}
                                />
                            )}
                        </Suspense>
                    </main>

                    <div id="printable-area" className="hidden">
                        {pagesToPrint.p1 && (<div className="print-sheet-wrapper"><CharacterSheet isLandscape={isLandscape} /></div>)}
                        {pagesToPrint.specs && (<div className="print-sheet-wrapper"><CharacterSheetSpecializations isLandscape={isLandscape} /></div>)}
                        {pagesToPrint.p2 && (<div className="print-sheet-wrapper"><CharacterSheetPage2 isLandscape={isLandscape} /></div>)}
                        {pagesToPrint.xp && (<div className="print-sheet-wrapper"><CharacterSheetXP isLandscape={isLandscape} /></div>)}
                        {pagesToPrint.notes && (<div className="print-sheet-wrapper"><CampaignNotes /></div>)}
                    </div>

                    <Suspense fallback={null}>
                        <ImportExportModal
                            isOpen={showImportExport}
                            onClose={() => setShowImportExport(false)}
                            onImportSuccess={handleImportSuccess}
                            onExportSuccess={() => { setLastSavedState(JSON.stringify(data)); }}
                            variant={mode === 'settings' ? 'gm' : 'player'}
                        />
                        <PrintSelectionModal isOpen={showPrintModal} onClose={() => setShowPrintModal(false)} onConfirm={(s: Record<string, boolean>) => handlePrintConfirm(s as any)} />

                        <ChangelogModal isOpen={showChangelog} onClose={() => setShowChangelog(false)} />
                        <UserGuideModal isOpen={showUserGuide} onClose={() => setShowUserGuide(false)} />
                        <AppearanceModal
                            isOpen={showAppearance}
                            onClose={() => setShowAppearance(false)}
                            data={data}
                            rules={rules}
                            onUpdate={(newData) => setData(newData)}
                        />
                        <SyncModal
                            isOpen={showSync}
                            onClose={() => setShowSync(false)}
                            characterData={data}
                            onSyncComplete={(syncInfo: any) => {
                                setData((prev: CharacterSheetData) => ({ ...prev, syncInfo }));
                                addLog(`Fiche synchronisée avec ${syncInfo?.settingName}`, 'success', 'sheet');
                            }}
                            onRestore={(restoredData) => {
                                setData(restoredData);
                                addLog("Version historique restaurée avec succès", 'success', 'sheet');
                            }}
                        />

                        <CampaignConflictModal
                            isOpen={showConflict}
                            onClose={() => setShowConflict(false)}
                            characterName={data.header?.name}
                            currentCampaignName={data.syncInfo?.settingName || 'Indépendante'}
                            newCampaignName={pendingRules?.name || ''}
                            onConfirmReset={handleConfirmReset}
                            onStay={() => setShowConflict(false)}
                            onBackup={handleConfirmBackup}
                        />

                        <CampaignInfoModal
                            isOpen={showCampaignInfo}
                            onClose={() => setShowCampaignInfo(false)}
                            campaignName={rules?.settingName || 'Ma Campagne'}
                            description={rules?.description}
                            welcomeMessage={rules?.welcomeMessage}
                        />

                        <ConfirmationModal
                            isOpen={showDiscardConfirm}
                            onClose={() => setShowDiscardConfirm(false)}
                            onConfirm={confirmDiscard}
                            title="Abandonner les modifications ?"
                            message="Vous avez des modifications non enregistrées. Voulez-vous vraiment quitter sans sauvegarder ?"
                            confirmLabel="Quitter sans sauvegarder"
                            cancelLabel="Rester ici"
                            type="warning"
                        />
                    </Suspense>
                </div>
            </div>
        </NotificationProvider>
    );
};

export default MainLayout;

import React, { useState } from 'react';
import { GraduationCap, Save, HelpCircle, X, AlertOctagon } from 'lucide-react';
import ThematicModal from '../ui/ThematicModal';
import { CATEGORY_HELP } from '../../constants/app';
import { LibrarySkillEntry } from '../../types';

interface LibrarySkillFormProps {
    isOpen: boolean;
    onClose: () => void;
    title: string;
    skill: LibrarySkillEntry;
    onSkillChange: (skill: LibrarySkillEntry) => void;
    onSave: () => void;
    error: string | null;
    categories?: { code: string, label: string, loc?: string }[];
}

const LibrarySkillForm: React.FC<LibrarySkillFormProps> = ({
    isOpen,
    onClose,
    title,
    skill,
    onSkillChange,
    onSave,
    error,
    categories = CATEGORY_HELP
}) => {
    const [showCategoryHelp, setShowCategoryHelp] = useState(false);
    const [variantDraft, setVariantDraft] = useState(skill.variants?.join(', ') || '');

    React.useEffect(() => {
        setVariantDraft(skill.variants?.join(', ') || '');
    }, [skill.variants?.join(',')]);

    const handleSave = () => {
        const cleaned = variantDraft.split(',').map(v => v.trim()).filter(Boolean);
        onSkillChange({ ...skill, variants: cleaned });
        // Since setState is async, we can't rely on skill prop being updated yet if onSave uses it.
        // But most of our onSave functions in this project use the latest 'skill' object passed to onSkillChange.
        // Actually, let's look at how LibrarySkillLibrary.tsx handleSave works.
        onSave();
    };

    return (
        <ThematicModal
            isOpen={isOpen}
            onClose={onClose}
            title={title}
            icon={<GraduationCap size={20} />}
            size={showCategoryHelp ? 'lg' : 'md'}
            footer={
                <>
                    <button onClick={onClose} className="px-4 py-2 text-[#5c4d41] hover:bg-stone-200/50 rounded-sm font-bold">Annuler</button>
                    <button onClick={handleSave} className="px-6 py-2 bg-[#5c4d41] text-white rounded-sm font-bold shadow-md hover:bg-[#4a3b32] flex items-center gap-2">
                        <Save size={16} /> Enregistrer
                    </button>
                </>
            }
        >
            <div className="flex flex-col lg:flex-row gap-8 py-2">
                {/* Editor Form */}
                <div className="flex-grow flex flex-col gap-5">
                    <div>
                        <label className="block text-[10px] font-bold text-[#bfae85] uppercase mb-1 tracking-widest">Nom de la compétence</label>
                        <input
                            className="w-full border border-[#bfae85]/50 rounded-sm px-3 py-2 font-serif font-black text-[#1c1917] bg-white/50 focus:border-amber-500 outline-none shadow-sm"
                            value={skill.name}
                            onChange={(e) => onSkillChange({ ...skill, name: e.target.value })}
                        />
                    </div>
                    <div>
                        <label className="block text-[10px] font-bold text-[#bfae85] uppercase mb-1 tracking-widest">Description (Narrative)</label>
                        <textarea
                            className="w-full border border-[#bfae85]/50 rounded-sm px-3 py-3 text-sm text-[#1c1917] bg-white/50 min-h-[120px] focus:border-amber-500 outline-none resize-none shadow-sm italic leading-relaxed"
                            value={skill.description || ''}
                            onChange={(e) => onSkillChange({ ...skill, description: e.target.value })}
                        />
                    </div>
                    <div>
                        <div className="flex justify-between items-center mb-1">
                            <label className="block text-[10px] font-bold text-[#bfae85] uppercase tracking-widest">Catégorie de placement par défaut</label>
                            {!showCategoryHelp && (
                                <button
                                    onClick={() => setShowCategoryHelp(true)}
                                    className="text-[#5c4d41] hover:text-[#8b2e2e] transition-colors flex items-center gap-1 text-[9px] font-bold"
                                    title="Voir l'aide sur les catégories"
                                >
                                    <HelpCircle size={14} /> Aide
                                </button>
                            )}
                        </div>
                        <select
                            className="w-full border border-[#bfae85]/50 rounded-sm px-3 py-2 text-sm text-[#1c1917] bg-white/50 focus:border-amber-500 outline-none shadow-sm font-bold"
                            value={skill.defaultCategory || ''}
                            onChange={(e) => onSkillChange({ ...skill, defaultCategory: e.target.value })}
                        >
                            <option value="">-- Placement libre --</option>
                            {categories.map(cat => (
                                <option key={cat.code} value={cat.code}>{cat.label}</option>
                            ))}
                        </select>
                        <p className="text-[10px] text-[#5c4d41] mt-1.5 italic px-1">Définit dans quelle section de la fiche cette compétence sera rangée lors de l'importation.</p>
                    </div>
                    <div className="bg-amber-50/50 border border-amber-200/50 rounded-sm p-3 flex items-center gap-3">
                        <input
                            type="checkbox"
                            id="isVariableSkill"
                            className="w-4 h-4 accent-amber-600 cursor-pointer"
                            checked={skill.isVariable || false}
                            onChange={(e) => onSkillChange({ ...skill, isVariable: e.target.checked })}
                        />
                        <label htmlFor="isVariableSkill" className="cursor-pointer select-none">
                            <span className="block text-xs font-bold text-[#5c4d41] uppercase tracking-wide">Compétence à Spécialité / Variable</span>
                            <span className="block text-[10px] text-[#5c4d41]/70 italic mt-0.5">Cochez si le joueur doit préciser quelque chose (ex: "Artisanat : Forge"). Permet d'avoir plusieurs fois cette compétence.</span>
                        </label>
                    </div>

                    {skill.isVariable && (
                        <div className="animate-in fade-in slide-in-from-top-2 duration-200 -mt-2 px-1">
                            <label className="block text-[10px] font-bold text-[#bfae85] uppercase mb-1 tracking-widest">Variantes suggérées (Réserve)</label>
                            <input
                                className="w-full border border-[#bfae85]/50 rounded-sm px-3 py-2 text-xs text-[#1c1917] bg-[#fdfbf7] focus:border-amber-500 outline-none shadow-sm font-bold placeholder:italic placeholder:font-normal"
                                value={variantDraft}
                                onChange={(e) => setVariantDraft(e.target.value)}
                                onBlur={() => {
                                    const cleaned = variantDraft.split(',').map(v => v.trim()).filter(v => v !== '');
                                    onSkillChange({ ...skill, variants: cleaned });
                                }}
                                placeholder="Forge, Histoire, Épées..."
                            />
                            <p className="text-[9px] text-[#5c4d41]/70 mt-1 italic px-1">Séparez par des virgules. Ces options seront proposées lors du drag-and-drop.</p>
                        </div>
                    )}
                    {error && (
                        <div className="bg-red-50 text-red-800 text-[11px] p-3 rounded-sm border border-red-200 font-bold flex items-center gap-2 animate-shake">
                            <AlertOctagon size={16} /> {error}
                        </div>
                    )}
                </div>

                {/* Side Help Panel */}
                {showCategoryHelp && (
                    <div className="w-full lg:w-72 shrink-0 animate-in slide-in-from-right-4 duration-300">
                        <div className="flex justify-between items-center mb-2 border-b border-[#bfae85]/30 pb-1">
                            <span className="text-[10px] font-serif font-black uppercase text-[#8b2e2e] tracking-widest flex items-center gap-1">
                                <HelpCircle size={12} /> Aide aux catégories
                            </span>
                            <button
                                onClick={() => setShowCategoryHelp(false)}
                                className="text-[#5c4d41] hover:text-[#8b2e2e] p-0.5 rounded"
                            >
                                <X size={14} />
                            </button>
                        </div>
                        <div className="p-0 overflow-hidden bg-white/30 rounded-sm border border-[#bfae85]/30 relative">
                            <table className="w-full text-[10px] text-left border-collapse">
                                <thead className="bg-[#fdfbf7] border-b border-[#bfae85]/50 transition-colors">
                                    <tr>
                                        <th className="px-3 py-2 font-black tracking-widest text-[#8b2e2e]">Code</th>
                                        <th className="px-3 py-2 font-black tracking-widest text-[#8b2e2e]">Emplacement</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-[#bfae85]/20">
                                    {categories.map((cat, i) => (
                                        <tr key={i} className="hover:bg-amber-50/30 transition-colors">
                                            <td className="px-3 py-1.5 font-mono text-[#8b2e2e] font-bold">{cat.code}</td>
                                            <td className="px-3 py-1.5 text-[#4a3b32]">
                                                <div className="font-bold leading-tight">{cat.label}</div>
                                                <div className="text-[8px] text-[#5c4d41]/70 italic leading-tight">{cat.loc}</div>
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                        <p className="mt-3 text-[9px] text-[#5c4d41]/70 leading-relaxed italic border-l-2 border-[#bfae85]/30 pl-2">
                            Conseil : Copiez-collez le code technique exact pour un tri automatique parfait.
                        </p>
                    </div>
                )}
            </div>
        </ThematicModal>
    );
};

export default LibrarySkillForm;

import React, { useState } from 'react';
import { Search, Plus, Eye, EyeOff, CheckCircle2, Globe, RefreshCw, Download, Layers, Edit2, Trash2, GraduationCap, Sparkles, X } from 'lucide-react';
import { LibrarySkillEntry } from '../../types';
import { MergedEntry } from '../../utils/libraryMerger';

interface SkillLibraryTabProps {
    skillsList: MergedEntry<LibrarySkillEntry>[];
    filteredSkills: MergedEntry<LibrarySkillEntry>[];
    usedSkillNames: Set<string>;
    skillSearch: string;
    setSkillSearch: (val: string) => void;
    hideKnownSkills: boolean;
    setHideKnownSkills: (val: boolean) => void;
    handleOfficialUpdateClick: () => void;
    setShowImportConfirm: (val: boolean) => void;
    handleOpenNewSkill: () => void;
    handleOpenEditSkill: (merged: MergedEntry<LibrarySkillEntry>) => void;
    handleDeleteRequest: (merged: MergedEntry<LibrarySkillEntry>) => void;
    getCategoryLabel: (code: string) => string;
}

const SkillLibraryTab: React.FC<SkillLibraryTabProps> = ({
    skillsList,
    filteredSkills,
    usedSkillNames,
    skillSearch,
    setSkillSearch,
    hideKnownSkills,
    setHideKnownSkills,
    handleOfficialUpdateClick,
    setShowImportConfirm,
    handleOpenNewSkill,
    handleOpenEditSkill,
    handleDeleteRequest,
    getCategoryLabel
}) => {
    return (
        <div className="absolute inset-0 flex flex-col bg-[#fdfbf7]">
            {/* Skill Toolbar */}
            <div className="p-3 bg-stone-100/30 border-b border-[#bfae85]/30 grid grid-cols-1 lg:grid-cols-3 items-center gap-4 shrink-0">
                {/* Search Bar - Left */}
                <div className="relative w-full max-w-sm flex gap-2">
                    <div className="relative flex-grow">
                        <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-[#4a3b32]/50" />
                        <input
                            className="w-full pl-9 pr-9 py-1.5 text-sm border border-[#bfae85]/50 rounded-sm focus:border-amber-500 outline-none text-[#1c1917] placeholder-[#4a3b32]/40 bg-white/80"
                            placeholder="Rechercher une compétence..."
                            value={skillSearch}
                            onChange={(e) => setSkillSearch(e.target.value)}
                        />
                        {skillSearch && (
                            <button
                                onClick={() => setSkillSearch('')}
                                className="absolute right-2 top-1/2 -translate-y-1/2 text-[#4a3b32]/40 hover:text-amber-600 transition-colors"
                            >
                                <X size={14} />
                            </button>
                        )}
                    </div>
                    <button
                        onClick={() => setHideKnownSkills(!hideKnownSkills)}
                        className={`px-2 py-1.5 rounded-sm border transition-colors flex items-center justify-center ${hideKnownSkills ? 'bg-amber-100 text-amber-800 border-amber-300' : 'bg-white text-[#5c4d41] border-[#bfae85]/50 hover:bg-stone-50'}`}
                        title={hideKnownSkills ? "Afficher les compétences acquises" : "Masquer les compétences acquises"}
                    >
                        {hideKnownSkills ? <EyeOff size={16} /> : <Eye size={16} />}
                    </button>
                </div>

                {/* Shared Legend - Center */}
                <div className="flex justify-center gap-2 flex-wrap">
                    <div className="flex items-center gap-1 px-1.5 py-0.5 bg-green-50/50 border border-green-200/50 rounded-full w-fit">
                        <CheckCircle2 size={10} className="text-green-600" />
                        <span className="text-[9px] font-bold text-green-800/70 uppercase tracking-tight whitespace-nowrap">Présent</span>
                    </div>
                    <div className="flex items-center gap-1 px-1.5 py-0.5 bg-blue-50/50 border border-blue-200/50 rounded-full w-fit">
                        <Globe size={10} className="text-indigo-600" />
                        <span className="text-[9px] font-bold text-indigo-800/70 uppercase tracking-tight whitespace-nowrap">Officiel</span>
                    </div>
                    <div className="flex items-center gap-1 px-1.5 py-0.5 bg-amber-50/50 border border-amber-200/50 rounded-full w-fit">
                        <Sparkles size={10} className="text-amber-600" />
                        <span className="text-[9px] font-bold text-amber-800/70 uppercase tracking-tight whitespace-nowrap">Mystique</span>
                    </div>
                    <div className="flex items-center gap-1 px-1.5 py-0.5 bg-blue-50/50 border border-blue-200/50 rounded-full w-fit">
                        <Layers size={10} className="text-blue-600" />
                        <span className="text-[9px] font-bold text-blue-800/70 uppercase tracking-tight whitespace-nowrap">Variant</span>
                    </div>
                </div>

                {/* Actions - Right */}
                <div className="flex gap-2 justify-end">
                    <button
                        onClick={handleOfficialUpdateClick}
                        className="bg-blue-50 border border-blue-200 text-blue-700 hover:bg-blue-100 px-3 py-1.5 rounded-sm text-xs font-bold flex items-center gap-1 transition-colors shadow-sm whitespace-nowrap"
                        title="Mettre à jour depuis le serveur officiel"
                    >
                        <RefreshCw size={14} /> Officiel
                    </button>
                    <button
                        onClick={() => setShowImportConfirm(true)}
                        className="bg-white/80 border border-[#bfae85]/50 text-[#5c4d41] hover:bg-stone-50 hover:text-[#1c1917] px-3 py-1.5 rounded-sm text-xs font-bold flex items-center gap-1 transition-colors shadow-sm whitespace-nowrap"
                        title="Ajouter toutes les compétences de la fiche à la réserve"
                    >
                        <Download size={14} /> Importer
                    </button>
                    <button
                        onClick={handleOpenNewSkill}
                        className="bg-[#5c4d41] hover:bg-[#4a3b32] text-white px-3 py-1.5 rounded-sm text-xs font-bold flex items-center gap-1 transition-colors shadow-sm whitespace-nowrap"
                    >
                        <Plus size={14} /> Créer
                    </button>
                </div>
            </div>

            {/* Skill List */}
            <div className="flex-grow overflow-y-auto p-4 custom-scrollbar">
                {skillsList.length === 0 ? (
                    <div className="text-center text-[#5c4d41]/60 py-10 italic px-4 text-sm flex flex-col items-center">
                        <GraduationCap size={48} className="opacity-20 mb-2" />
                        <p>La réserve de compétences est vide.</p>
                        <p className="text-xs mt-2 text-[#5c4d41]/80 italic">
                            Utilisez le bouton <strong>"Importer de la fiche"</strong> pour la remplir automatiquement <br />
                            avec vos compétences actuelles.
                        </p>
                    </div>
                ) : filteredSkills.length === 0 ? (
                    <div className="text-center text-[#5c4d41]/60 py-10 italic">Aucune compétence trouvée.</div>
                ) : (
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
                        {filteredSkills.map(merged => {
                            const skill = merged.entry;
                            const isUsed = usedSkillNames.has(skill.name.trim().toLowerCase());
                            const isOfficial = merged.source === 'official';

                            return (
                                <div
                                    key={skill.id}
                                    className={`border rounded-sm p-2 group flex flex-col justify-between transition-all bg-white/60 ${isUsed
                                        ? 'border-green-300/40 bg-green-50/10'
                                        : isOfficial ? 'border-blue-300/40 bg-blue-50/5' : 'border-[#bfae85]/30 hover:border-amber-400/50 hover:shadow-sm'
                                        }`}
                                >
                                    <div className="flex flex-col gap-1">
                                        <div className="flex justify-between items-center gap-2">
                                            <div className="flex items-center gap-1.5 min-w-0">
                                                {skill.isVariable && (
                                                    <span title="Compétence à variations">
                                                        <Layers size={10} className="text-blue-600 shrink-0" />
                                                    </span>
                                                )}
                                                {skill.mysticAbilityId && (
                                                    <span title="Habilité Mystique">
                                                        <Sparkles size={10} className="text-amber-500 shrink-0" />
                                                    </span>
                                                )}
                                                {isOfficial && (
                                                    <span title="Compétence Officielle">
                                                        <Globe size={11} className="text-indigo-500 shrink-0" />
                                                    </span>
                                                )}
                                                {isUsed && (
                                                    <span title="Présent dans la fiche">
                                                        <CheckCircle2 size={10} className="text-green-600 shrink-0" />
                                                    </span>
                                                )}
                                                <span className={`font-serif font-black uppercase text-[11px] tracking-wide truncate ${isUsed ? 'text-green-800' : 'text-[#4a3b32]'}`}>
                                                    {skill.name}
                                                </span>
                                            </div>

                                            <div className="flex gap-1 shrink-0 opacity-40 group-hover:opacity-100 transition-opacity">
                                                <button onClick={() => handleOpenEditSkill(merged)} className="text-blue-500 hover:bg-blue-50 p-1 rounded" title="Éditer/Voir"><Edit2 size={12} /></button>
                                                {!isUsed && !isOfficial && (
                                                    <button onClick={() => handleDeleteRequest(merged)} className="text-red-500 hover:bg-red-50 p-1 rounded" title="Supprimer"><Trash2 size={12} /></button>
                                                )}
                                            </div>
                                        </div>
                                        {skill.description && (
                                            <p className="text-[10px] text-[#5c4d41] italic line-clamp-1 leading-tight opacity-70" title={skill.description}>{skill.description}</p>
                                        )}
                                    </div>
                                    {skill.defaultCategory && (
                                        <span className="text-[8px] text-amber-800/50 font-mono bg-amber-100/20 px-1 py-0.5 rounded-sm self-start mt-1 border border-amber-200/10">
                                            {getCategoryLabel(skill.defaultCategory)}
                                        </span>
                                    )}

                                </div>
                            );
                        })}
                    </div>
                )}
            </div>
        </div>
    );
};

export default SkillLibraryTab;

import React from 'react';
import { CharacterSheetData, SuggestionEntry } from '../../types';
import { useRules } from '../../context/RulesContext';
import { Check, X, BookmarkPlus, type LucideIcon, Lightbulb } from 'lucide-react';
import ThematicButton from '../ui/ThematicButton';

interface Props {
    data: CharacterSheetData;
    onUpdate: (newData: CharacterSheetData) => void;
    onAddLog: (msg: string, type: 'success' | 'info' | 'danger', cat: 'sheet' | 'settings' | 'both') => void;
}

const AdminSuggestions: React.FC<Props> = ({ data, onUpdate, onAddLog }) => {
    const { rules, updateRules } = useRules();
    const suggestions = data.suggestions || [];

    const handleReject = (id: string) => {
        const newSuggestions = suggestions.filter(s => s.id !== id);
        onUpdate({ ...data, suggestions: newSuggestions });
        onAddLog("Suggestion rejetée et supprimée.", 'info', 'settings');
    };

    const handlePromote = (suggestion: SuggestionEntry) => {
        if (!rules) return;

        const newRules = JSON.parse(JSON.stringify(rules)); // Deep clone
        let promoted = false;

        if (suggestion.type === 'variant' && suggestion.parentId) {
            // Logic for Variants: Add to parent skill's variants list
            const skill = newRules.libraries.skills.find((s: any) => s.id === suggestion.parentId);
            if (skill) {
                if (!skill.variants) skill.variants = [];
                if (!skill.variants.includes(suggestion.name)) {
                    skill.variants.push(suggestion.name);
                    skill.variants.sort((a: string, b: string) => a.localeCompare(b)); // Keep sorted
                    promoted = true;
                    onAddLog(`Variante "${suggestion.name}" ajoutée à la compétence "${skill.name}".`, 'success', 'settings');
                } else {
                    onAddLog("Cette variante existe déjà dans la définition.", 'info', 'settings');
                    // Mark as promoted anyway to remove it
                    promoted = true;
                }
            } else {
                onAddLog("Erreur : Compétence parente introuvable.", 'danger', 'settings');
            }
        }
        /* 
        // Future logic for Traits/Skills promotion
        else if (suggestion.type === 'trait') {
             // ... create new trait entry in library ...
        }
        */

        if (promoted) {
            updateRules(newRules);
            handleReject(suggestion.id); // Remove from list after promotion
        }
    };

    if (suggestions.length === 0) {
        return (
            <div className="flex flex-col items-center justify-center p-8 text-stone-500 italic">
                <Lightbulb size={48} className="mb-4 opacity-20" />
                <p>Aucune suggestion en attente.</p>
            </div>
        );
    }

    return (
        <div className="space-y-4">
            <div className="bg-amber-50 border border-amber-200 p-4 rounded-sm flex items-start gap-3">
                <Lightbulb className="text-amber-600 shrink-0 mt-1" size={20} />
                <div>
                    <h3 className="font-bold text-amber-800 text-sm uppercase tracking-wide mb-1">Suggestions des Joueurs</h3>
                    <p className="text-xs text-amber-900/80">
                        Ces éléments ont été créés localement par les joueurs. Vous pouvez les valider pour les intégrer officiellement aux règles de la campagne (Bibliothèque).
                    </p>
                </div>
            </div>

            <div className="grid gap-3">
                {suggestions.map(s => (
                    <div key={s.id} className="bg-white border border-stone-200 p-4 rounded-sm shadow-sm flex items-center justify-between hover:border-amber-300 transition-colors">
                        <div className="flex items-center gap-3">
                            <div className={`p-2 rounded-full ${s.type === 'variant' ? 'bg-indigo-100 text-indigo-700' : 'bg-stone-100 text-stone-600'}`}>
                                {s.type === 'variant' ? <BookmarkPlus size={18} /> : <Lightbulb size={18} />}
                            </div>
                            <div>
                                <div className="font-bold text-[#2c241b]">{s.name}</div>
                                <div className="text-xs text-stone-500 uppercase tracking-widest flex items-center gap-2">
                                    <span>{s.type === 'variant' ? 'Nouvelle Variante' : 'Nouvel Élément'}</span>
                                    {s.category && <span className="px-1.5 py-0.5 bg-stone-100 rounded text-[10px]">{s.category}</span>}
                                </div>
                            </div>
                        </div>

                        <div className="flex items-center gap-2">
                            <ThematicButton onClick={() => handlePromote(s)} variant="primary" className="!px-3 !py-1.5 text-xs">
                                <Check size={14} className="mr-1" /> Intégrer
                            </ThematicButton>
                            <ThematicButton onClick={() => handleReject(s.id)} variant="secondary" className="!px-3 !py-1.5 text-xs !bg-stone-100 hover:!bg-red-50 hover:!text-red-700 hover:!border-red-200">
                                <X size={14} />
                            </ThematicButton>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
};

export default AdminSuggestions;

import React from 'react';
import { CharacterSheetData, ThemeConfig } from '../../types';
import { RulesData } from '../../types/rules';
import {
    Palette, RotateCcw, Circle, Square, Diamond, Triangle, Hexagon, Star, Heart,
    Zap, Shield, Skull, Plus, Sword, Flame, Moon, LucideIcon,
    Crown, Ghost, Axe, Hammer, Eye, Droplets, Wind, Sun, Cloud,
    Target, Crosshair, Trophy, Key, Anchor, Feather, PawPrint,
    TreeDeciduous, Mountain, Waves, Sparkles, Layers, RefreshCcw
} from 'lucide-react';
import { DEFAULT_THEME } from '../../data/initialState';

interface AppearanceEditorProps {
    data: CharacterSheetData;
    onUpdate: (newData: CharacterSheetData) => void;
    onAddLog: (message: string, type?: 'success' | 'danger' | 'info', category?: 'sheet' | 'settings') => void;
    rules: RulesData | null;
}

const AppearanceEditor: React.FC<AppearanceEditorProps> = ({ data, onUpdate, onAddLog, rules }) => {
    const theme: ThemeConfig = data.theme || DEFAULT_THEME;

    const updateTheme = (field: keyof ThemeConfig, value: any) => {
        onUpdate({
            ...data,
            theme: {
                ...theme,
                [field]: value
            }
        });
    };

    const updateSkillColor = (key: 'variable' | 'mysticDefault', value: string) => {
        onUpdate({
            ...data,
            theme: {
                ...theme,
                skillColors: {
                    ...(theme.skillColors || {}),
                    [key]: value
                }
            }
        });
    };

    const updateMysticOverride = (abilityId: string, value: string) => {
        onUpdate({
            ...data,
            theme: {
                ...theme,
                skillColors: {
                    ...(theme.skillColors || {}),
                    mysticOverrides: {
                        ...(theme.skillColors?.mysticOverrides || {}),
                        [abilityId]: value
                    }
                }
            }
        });
    };

    const removeMysticOverride = (abilityId: string) => {
        const newOverrides = { ...(theme.skillColors?.mysticOverrides || {}) };
        delete newOverrides[abilityId];

        onUpdate({
            ...data,
            theme: {
                ...theme,
                skillColors: {
                    ...(theme.skillColors || {}),
                    mysticOverrides: newOverrides
                }
            }
        });
    };

    const resetTheme = () => {
        onUpdate({
            ...data,
            theme: DEFAULT_THEME
        });
        onAddLog('Thème réinitialisé aux couleurs par défaut.', 'info', 'settings');
    };

    return (
        <div className="max-w-4xl mx-auto space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-300">
            <div className="bg-[#fdfbf7]/80 backdrop-blur-sm p-6 rounded-sm shadow-md border border-[#bfae85]/30">
                <div className="flex items-center justify-between border-b border-[#bfae85]/30 pb-2 mb-4">
                    <h4 className="font-bold text-[#5c4d41] flex items-center gap-2 uppercase tracking-widest text-sm">
                        <Palette size={18} className="text-[#8b2e2e]" /> Paramètres Visuels
                    </h4>
                    <button
                        onClick={resetTheme}
                        className="text-[10px] font-bold text-[#5c4d41]/60 hover:text-[#8b2e2e] hover:bg-[#8b2e2e]/5 px-2 py-1 rounded-sm flex items-center gap-1 transition-colors border border-transparent hover:border-[#8b2e2e]/20"
                        title="Remettre les couleurs par défaut"
                    >
                        <RotateCcw size={12} /> Réinitialiser
                    </button>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="space-y-3 bg-[#bfae85]/5 p-4 rounded-sm border border-[#bfae85]/20">
                        <label className="block text-[10px] font-bold text-[#8b2e2e] uppercase tracking-widest">Points à la Création</label>
                        <p className="text-[10px] text-[#5c4d41]/70 mb-2 italic">Couleur des points de base et en mode création.</p>
                        <div className="flex items-center gap-3">
                            <input
                                type="color"
                                value={theme.creationColor}
                                onChange={(e) => updateTheme('creationColor', e.target.value)}
                                className="w-12 h-12 border-none rounded-sm cursor-pointer bg-white shadow-sm ring-1 ring-[#bfae85]/30"
                            />
                            <div className="flex-grow flex flex-col justify-center">
                                <span className="text-xs font-mono font-bold text-[#5c4d41]">{theme.creationColor}</span>
                            </div>
                        </div>
                    </div>

                    <div className="space-y-3 bg-[#bfae85]/5 p-4 rounded-sm border border-[#bfae85]/20">
                        <label className="block text-[10px] font-bold text-[#8b2e2e] uppercase tracking-widest">Points via XP</label>
                        <p className="text-[10px] text-[#5c4d41]/70 mb-2 italic">Couleur des points achetés avec de l'expérience.</p>
                        <div className="flex items-center gap-3">
                            <input
                                type="color"
                                value={theme.xpColor}
                                onChange={(e) => updateTheme('xpColor', e.target.value)}
                                className="w-12 h-12 border-none rounded-sm cursor-pointer bg-white shadow-sm ring-1 ring-[#bfae85]/30"
                            />
                            <div className="flex-grow flex flex-col justify-center">
                                <span className="text-xs font-mono font-bold text-[#5c4d41]">{theme.xpColor}</span>
                            </div>
                        </div>
                    </div>
                </div>

                {/* Skill Text Colors Section */}
                <div className="mt-6 border-t border-[#bfae85]/30 pt-4">
                    <h5 className="font-bold text-[#5c4d41] uppercase tracking-widest text-xs mb-4 flex items-center gap-2">
                        <Palette size={14} className="text-[#8b2e2e]" /> Couleurs des Textes (Compétences)
                    </h5>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        {/* 1. Variable Skills */}
                        <div className="space-y-3 bg-[#bfae85]/5 p-4 rounded-sm border border-[#bfae85]/20">
                            <div className="flex justify-between items-start">
                                <div>
                                    <label className="block text-[10px] font-bold text-[#8b2e2e] uppercase tracking-widest flex items-center gap-1.5">
                                        <Layers size={12} /> Compétences Variables
                                    </label>
                                    <p className="text-[10px] text-[#5c4d41]/70 mb-2 italic">Ex: Artisanat, Savoir, Langue...</p>
                                </div>
                                {theme.skillColors?.variable && (
                                    <button
                                        onClick={() => updateSkillColor('variable', '')}
                                        className="text-[10px] text-[#5c4d41]/40 hover:text-red-500"
                                        title="Réinitialiser (Défaut)"
                                    >
                                        <RefreshCcw size={10} />
                                    </button>
                                )}
                            </div>
                            <div className="flex items-center gap-3">
                                <input
                                    type="color"
                                    value={theme.skillColors?.variable || '#d97706'}
                                    onChange={(e) => updateSkillColor('variable', e.target.value)}
                                    className="w-10 h-10 border-none rounded-sm cursor-pointer bg-white shadow-sm ring-1 ring-[#bfae85]/30"
                                />
                                <span className="text-xs font-bold" style={{ color: theme.skillColors?.variable || '#d97706' }}>
                                    Exemple de Nom
                                </span>
                            </div>
                        </div>

                        {/* 2. Default Mystic */}
                        <div className="space-y-3 bg-[#bfae85]/5 p-4 rounded-sm border border-[#bfae85]/20">
                            <div className="flex justify-between items-start">
                                <div>
                                    <label className="block text-[10px] font-bold text-[#8b2e2e] uppercase tracking-widest flex items-center gap-1.5">
                                        <Sparkles size={12} /> Mystique (Défaut)
                                    </label>
                                    <p className="text-[10px] text-[#5c4d41]/70 mb-2 italic">Couleur de base des habilités mystiques.</p>
                                </div>
                                {theme.skillColors?.mysticDefault && (
                                    <button
                                        onClick={() => updateSkillColor('mysticDefault', '')}
                                        className="text-[10px] text-[#5c4d41]/40 hover:text-red-500"
                                        title="Réinitialiser (Défaut)"
                                    >
                                        <RefreshCcw size={10} />
                                    </button>
                                )}
                            </div>
                            <div className="flex items-center gap-3">
                                <input
                                    type="color"
                                    value={theme.skillColors?.mysticDefault || '#8b5cf6'}
                                    onChange={(e) => updateSkillColor('mysticDefault', e.target.value)}
                                    className="w-10 h-10 border-none rounded-sm cursor-pointer bg-white shadow-sm ring-1 ring-[#bfae85]/30"
                                />
                                <span className="text-xs font-bold" style={{ color: theme.skillColors?.mysticDefault || '#8b5cf6' }}>
                                    Exemple de Pouvoir
                                </span>
                            </div>
                        </div>
                    </div>

                    {/* 3. Mystic Overrides */}
                    {rules?.libraries?.mysticAbilities && rules.libraries.mysticAbilities.length > 0 && (
                        <div className="mt-4 space-y-3 bg-[#bfae85]/5 p-4 rounded-sm border border-[#bfae85]/20">
                            <label className="block text-[10px] font-bold text-[#8b2e2e] uppercase tracking-widest">Surcharges par Habilité</label>
                            <p className="text-[10px] text-[#5c4d41]/70 italic mb-3">Définissez une couleur spécifique pour chaque voie mystique.</p>

                            <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-3">
                                {rules.libraries.mysticAbilities.map(ability => {
                                    // Logic for resolving current color: Override > Default > Fallback
                                    const hasOverride = theme.skillColors?.mysticOverrides?.[ability.id];
                                    const currentColor = hasOverride
                                        || theme.skillColors?.mysticDefault
                                        || '#8b5cf6';

                                    return (
                                        <div key={ability.id} className="flex items-center gap-2 bg-white/40 p-2 rounded border border-[#bfae85]/20">
                                            <input
                                                type="color"
                                                value={currentColor}
                                                onChange={(e) => updateMysticOverride(ability.id, e.target.value)}
                                                className="w-6 h-6 border-none rounded-sm cursor-pointer bg-white shadow-sm ring-1 ring-[#bfae85]/30 shrink-0"
                                            />
                                            <div className="flex-grow min-w-0">
                                                <span className="block text-[10px] font-bold truncate" style={{ color: currentColor }}>
                                                    {ability.name}
                                                </span>
                                            </div>
                                            {hasOverride && (
                                                <button
                                                    onClick={() => removeMysticOverride(ability.id)}
                                                    className="text-stone-400 hover:text-red-500 shrink-0"
                                                    title="Réinitialiser"
                                                >
                                                    <RotateCcw size={10} />
                                                </button>
                                            )}
                                        </div>
                                    );
                                })}
                            </div>
                        </div>
                    )}
                </div>

                {/* Symbol Selection */}
                <div className="mt-8 bg-[#bfae85]/5 p-4 rounded-sm border border-[#bfae85]/20 space-y-4">
                    <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
                        <div>
                            <label className="block text-[10px] font-bold text-[#8b2e2e] uppercase tracking-widest">Forme des points</label>
                            <p className="text-[10px] text-[#5c4d41]/70 italic leading-tight">Le symbole héraldique utilisé pour marquer vos scores.</p>
                        </div>
                        <div className="flex items-center gap-2 px-3 py-1.5 bg-[#fdfbf7] rounded-sm border border-[#bfae85]/30 shadow-inner">
                            <span className="text-[9px] font-bold text-[#5c4d41]/50 uppercase tracking-tighter">Aperçu :</span>
                            <div className="flex gap-1">
                                <SymbolPreview symbol={theme.dotSymbol || 'circle'} color={theme.creationColor} filled={true} />
                                <SymbolPreview symbol={theme.dotSymbol || 'circle'} color={theme.creationColor} filled={true} />
                                <SymbolPreview symbol={theme.dotSymbol || 'circle'} color={theme.xpColor} filled={true} />
                                <SymbolPreview symbol={theme.dotSymbol || 'circle'} color={theme.xpColor} filled={false} />
                            </div>
                        </div>
                    </div>

                    <div className="grid grid-cols-5 sm:grid-cols-7 md:grid-cols-8 lg:grid-cols-10 gap-2">
                        {Object.entries(SYMBOL_MAP).map(([name, Icon]) => (
                            <button
                                key={name}
                                onClick={() => updateTheme('dotSymbol', name)}
                                className={`p-2.5 rounded-sm border transition-all ${(theme.dotSymbol || 'circle') === name
                                    ? 'bg-[#8b2e2e] border-[#5c1e1e] text-white shadow-inner scale-105'
                                    : 'bg-white/50 border-[#bfae85]/30 text-[#5c4d41]/40 hover:border-[#8b2e2e]/40 hover:text-[#8b2e2e]/60'
                                    }`}
                                title={name.charAt(0).toUpperCase() + name.slice(1)}
                            >
                                <Icon size={18} fill={(theme.dotSymbol || 'circle') === name ? 'white' : 'transparent'} strokeWidth={2} />
                            </button>
                        ))}
                    </div>
                </div>
            </div>
        </div>
    );
};

// Internal Helper for preview
const SymbolPreview: React.FC<{ symbol: string, color: string, filled: boolean }> = ({ symbol, color, filled }) => {
    const Icon = SYMBOL_MAP[symbol] || Circle;
    const inactiveColor = '#d6d3d1'; // stone-300

    return (
        <div className="w-4 h-4 flex items-center justify-center">
            <Icon
                size={12}
                stroke={filled ? color : inactiveColor}
                fill={filled ? color : 'transparent'}
                strokeWidth={filled ? 2.5 : 1.5}
            />
        </div>
    );
};

const SYMBOL_MAP: Record<string, LucideIcon> = {
    circle: Circle,
    square: Square,
    diamond: Diamond,
    triangle: Triangle,
    hexagon: Hexagon,
    star: Star,
    heart: Heart,
    zap: Zap,
    shield: Shield,
    skull: Skull,
    plus: Plus,
    sword: Sword,
    flame: Flame,
    moon: Moon,
    crown: Crown,
    ghost: Ghost,
    axe: Axe,
    hammer: Hammer,
    eye: Eye,
    droplets: Droplets,
    wind: Wind,
    sun: Sun,
    cloud: Cloud,
    target: Target,
    crosshair: Crosshair,
    trophy: Trophy,
    key: Key,
    anchor: Anchor,
    feather: Feather,
    paw: PawPrint,
    tree: TreeDeciduous,
    mountain: Mountain,
    waves: Waves
};

export default AppearanceEditor;

import React from 'react';
import { CharacterSheetData } from '../../types';
import { Zap, Play, CheckSquare, Info, LayoutGrid } from 'lucide-react';
import ThematicModal from '../ui/ThematicModal';
import { ATTRIBUTE_PRESETS } from '../../data/defaults/attributes';
import { useAttributesEditor } from './hooks/useAttributesEditor';

interface AttributesEditorProps {
    data: CharacterSheetData;
    onUpdate: (newData: CharacterSheetData) => void;
    onAddLog: (message: string, type?: 'success' | 'danger' | 'info', category?: 'sheet' | 'settings') => void;
}

const AttributesEditor: React.FC<AttributesEditorProps> = ({ data, onUpdate, onAddLog }) => {
    const {
        pendingPreset,
        showPresetConfirm,
        setShowPresetConfirm,
        setPendingPreset,
        categories,
        count,
        globalAttrCount,
        requestPresetLoad,
        executePresetLoad,
        handleCategoryCountChange,
        handleGlobalAttributeCountChange,
        updateCategoryLabel,
        updateAttributeName,
        toggleSecondaryAttributes,
        updateSecondaryAttributeName,
        updateAttributeCost
    } = useAttributesEditor({ data, onUpdate, onAddLog });

    return (
        <div className="bg-[#fdfbf7]/80 backdrop-blur-sm p-6 rounded-sm shadow-md border border-[#bfae85]/30 animate-in fade-in slide-in-from-bottom-4 duration-300">
            <h3 className="font-serif font-black text-sm mb-6 text-[#5c4d41] border-b border-[#bfae85]/30 pb-4 flex items-center gap-2 uppercase tracking-widest">
                <LayoutGrid className="text-[#8b2e2e]" size={20} />
                Configuration des Attributs
            </h3>

            {/* Quick Slots (Presets) */}
            <div className="mb-8">
                <h4 className="font-bold text-[10px] text-[#bfae85] mb-3 flex items-center gap-2 uppercase tracking-widest">
                    <Zap size={14} className="text-amber-500" /> Emplacements Rapides (Préréglages)
                </h4>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {ATTRIBUTE_PRESETS.map((preset, idx) => (
                        <button
                            key={idx}
                            onClick={() => requestPresetLoad(preset)}
                            className="bg-[#fdfbf7] border border-[#bfae85]/30 hover:border-amber-400 hover:bg-amber-50/30 hover:shadow-md rounded-sm p-3 text-left transition-all group flex items-start gap-3"
                        >
                            <div className="bg-white p-2 rounded-full border border-[#bfae85]/20 group-hover:border-amber-400 group-hover:text-amber-700 text-[#bfae85]/50">
                                <Play size={14} className="ml-0.5" />
                            </div>
                            <div>
                                <span className="block font-bold text-[#5c4d41] text-xs group-hover:text-amber-900">{preset.name}</span>
                                <span className="block text-[10px] text-[#5c4d41]/60 italic">{preset.description}</span>
                            </div>
                        </button>
                    ))}
                </div>
            </div>

            {/* Option Secondary Attributes */}
            <div className="mb-8 p-4 bg-[#8b2e2e]/5 border border-[#8b2e2e]/20 rounded-sm flex items-center justify-between">
                <div>
                    <h4 className="font-bold text-[#8b2e2e] text-[10px] uppercase tracking-widest flex items-center gap-2">
                        <CheckSquare size={16} /> Attributs Secondaires
                    </h4>
                    <p className="text-[10px] text-[#5c4d41]/70 mt-1 italic leading-tight">
                        Active 2 attributs supplémentaires par pavé pour les calculs dérivés ou jauges spéciales.
                    </p>
                </div>
                <button
                    onClick={toggleSecondaryAttributes}
                    className={`w-12 h-6 rounded-full p-1 transition-colors duration-300 ${data.secondaryAttributesActive ? 'bg-[#8b2e2e]' : 'bg-stone-300'}`}
                >
                    <div className={`bg-white w-4 h-4 rounded-full shadow transform transition-transform duration-300 ${data.secondaryAttributesActive ? 'translate-x-6' : ''}`} />
                </button>
            </div>

            {/* Global Settings (Cats & Attrs Count) */}
            <div className="mb-8 bg-[#bfae85]/5 p-4 rounded-sm border border-[#bfae85]/20 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">

                {/* Category Count */}
                <div className="flex flex-col gap-2">
                    <span className="font-bold text-[#5c4d41]/80 uppercase text-[10px] tracking-widest">Nombre de pavés :</span>
                    <div className="flex gap-2">
                        {[1, 2, 3, 4].map(n => (
                            <button
                                key={n}
                                onClick={() => handleCategoryCountChange(n)}
                                className={`w-10 h-10 rounded-full font-black text-base transition-all ${count === n
                                    ? 'bg-[#8b2e2e] text-white shadow-lg ring-2 ring-[#8b2e2e]/20 scale-110'
                                    : 'bg-white border border-[#bfae85]/30 text-[#5c4d41]/50 hover:bg-[#8b2e2e]/5 hover:text-[#8b2e2e]'
                                    }`}
                            >
                                {n}
                            </button>
                        ))}
                    </div>
                </div>

                {/* Attributes Count (Global) */}
                <div className="flex flex-col gap-2">
                    <span className="font-bold text-[#5c4d41]/80 uppercase text-[10px] tracking-widest">Attributs par pavé :</span>
                    <div className="flex gap-2">
                        {[1, 2, 3, 4, 5].map(n => (
                            <button
                                key={n}
                                onClick={() => handleGlobalAttributeCountChange(n)}
                                className={`w-10 h-10 rounded-full font-black text-base transition-all ${globalAttrCount === n
                                    ? 'bg-[#8b2e2e] text-white shadow-lg ring-2 ring-[#8b2e2e]/20 scale-110'
                                    : 'bg-white border border-[#bfae85]/30 text-[#5c4d41]/50 hover:bg-[#8b2e2e]/5 hover:text-[#8b2e2e]'
                                    }`}
                            >
                                {n}
                            </button>
                        ))}
                    </div>
                </div>

                {/* Attribute Cost */}
                <div className="flex flex-col gap-2">
                    <label className="block text-[10px] font-bold text-[#5c4d41]/80 uppercase tracking-widest">Coût XP</label>
                    <div className="flex items-center gap-2">
                        <input
                            type="number"
                            value={data.creationConfig.attributeCost ?? 6}
                            onChange={(e) => updateAttributeCost(parseInt(e.target.value) || 0)}
                            className="w-20 border border-[#bfae85]/40 rounded-sm px-3 py-1.5 focus:border-[#8b2e2e] outline-none font-bold"
                        />
                        <div title="Coût en expérience pour augmenter un attribut de 1 point (Défaut: 6)" className="text-[10px] text-[#5c4d41]/60 italic flex items-center gap-1">
                            <Info size={14} className="text-[#bfae85]" />
                            <span>/ point</span>
                        </div>
                    </div>
                </div>
            </div>

            {/* Category Cards Grid */}
            <div className={`grid gap-4 grid-cols-1 md:grid-cols-${count}`}>
                {categories.map((cat, idx) => {
                    const attrs = data.attributes[cat.id] || [];
                    const secondaryAttrs = data.secondaryAttributesActive ? (data.secondaryAttributes[cat.id] || []) : [];

                    return (
                        <div key={cat.id} className="bg-white border border-gray-200 rounded-lg shadow-sm hover:shadow-md transition-shadow overflow-hidden flex flex-col h-full">
                            <div className="bg-slate-100 p-3 border-b border-gray-200">
                                <label className="text-xs font-bold text-gray-500 uppercase tracking-wide block mb-1">
                                    Pavé {idx + 1}
                                </label>
                                <input
                                    value={cat.label}
                                    onChange={(e) => updateCategoryLabel(cat.id, e.target.value)}
                                    onFocus={(e) => e.target.select()}
                                    className="w-full font-bold text-lg bg-white border border-gray-300 rounded px-2 py-1 shadow-inner focus:border-blue-500 focus:ring-2 focus:ring-blue-200 outline-none text-gray-900 transition-all"
                                    placeholder="Nom du pavé"
                                />
                            </div>

                            <div className="p-3 space-y-2 flex-grow bg-slate-50/50">
                                {attrs.map((attr, aIdx) => (
                                    <div key={attr.id} className="flex items-center gap-2">
                                        <span className="text-xs text-gray-400 w-4 font-mono select-none">{aIdx + 1}</span>
                                        <input
                                            value={attr.name}
                                            onChange={(e) => updateAttributeName(cat.id, attr.id, e.target.value)}
                                            onFocus={(e) => e.target.select()}
                                            className="flex-grow text-sm border border-gray-300 rounded px-2 py-1 focus:border-blue-500 outline-none bg-white shadow-sm font-medium text-gray-800"
                                            placeholder={`Attribut ${aIdx + 1}`}
                                        />
                                    </div>
                                ))}

                                {data.secondaryAttributesActive && secondaryAttrs.length > 0 && (
                                    <>
                                        <hr className="my-3 border-dashed border-gray-300" />
                                        <div className="text-[10px] text-gray-400 font-bold uppercase text-center mb-2 tracking-wide">Secondaires</div>
                                        {secondaryAttrs.map((sAttr, sIdx) => (
                                            <div key={sAttr.id} className="flex items-center gap-2">
                                                <span className="text-xs text-purple-400 w-4 font-mono select-none">+{sIdx + 1}</span>
                                                <input
                                                    value={sAttr.name}
                                                    onChange={(e) => updateSecondaryAttributeName(cat.id, sIdx, e.target.value)}
                                                    onFocus={(e) => e.target.select()}
                                                    className="flex-grow text-sm border border-purple-200 rounded px-2 py-1 focus:border-purple-500 outline-none bg-white shadow-sm font-medium text-gray-800"
                                                    placeholder={`Attr. Secondaire ${sIdx + 1}`}
                                                />
                                            </div>
                                        ))}
                                    </>
                                )}
                            </div>
                        </div>
                    );
                })}
            </div>

            {/* Preset Confirmation Modal */}
            {showPresetConfirm && pendingPreset && (
                <ThematicModal
                    isOpen={showPresetConfirm}
                    onClose={() => { setShowPresetConfirm(false); setPendingPreset(null); }}
                    title="Charger le préréglage ?"
                    icon={<Zap size={24} className="text-amber-600" />}
                    size="md"
                    footer={
                        <>
                            <button onClick={() => { setShowPresetConfirm(false); setPendingPreset(null); }} className="px-4 py-2 text-[#5c4d41] hover:bg-stone-200/50 rounded-sm font-bold">Annuler</button>
                            <button onClick={executePresetLoad} className="px-6 py-2 bg-[#8b2e2e] text-white rounded-sm font-bold shadow-md hover:bg-[#6a2424]">
                                Confirmer
                            </button>
                        </>
                    }
                >
                    <div className="flex flex-col items-center text-center space-y-4 py-4">
                        <div className="bg-amber-50/50 p-4 rounded-sm border border-[#bfae85]/30 w-full">
                            <span className="block font-black text-[#8b2e2e] uppercase tracking-widest text-sm mb-1">{pendingPreset.name}</span>
                            <span className="text-[10px] text-[#5c4d41]/70 italic">{pendingPreset.description}</span>
                        </div>
                        <p className="text-xs text-[#5c4d41] leading-relaxed">
                            Cette action remplacera <span className="font-bold underline">toute</span> votre configuration d'attributs actuelle.
                        </p>
                        <div className="bg-red-50/50 border border-red-200/50 p-2 rounded-sm w-full">
                            <p className="text-[10px] text-red-800/80 italic font-bold">Les noms et scores actuels seront perdus.</p>
                        </div>
                    </div>
                </ThematicModal>
            )}
        </div>
    );
};

export default AttributesEditor;

import React from 'react';
import { CharacterSheetData } from '../../types';
import { Sliders, List, PieChart, CreditCard, Info, AlertCircle } from 'lucide-react';

interface CreationConfigEditorProps {
    data: CharacterSheetData;
    onUpdate: (newData: CharacterSheetData) => void;
    onAddLog: (message: string, type?: 'success' | 'danger' | 'info', category?: 'sheet' | 'settings') => void;
