                    </div>
                    <div>
                        <label className="block text-xs font-bold text-gray-500 mb-1 uppercase">Seuil de Base (Valet)</label>
                        <input
                            type="number"
                            step="0.1"
                            value={config.cardConfig?.baseStart ?? 2}
                            onChange={(e) => updateCardConfig('baseStart', parseFloat(e.target.value))}
                            className="w-full border border-gray-300 rounded px-3 py-2 focus:border-blue-500 outline-none"
                        />
                    </div>
                </div>
            </div>

        </div>
    );
};

export default CreationConfigEditor;

import React from 'react';
import { CharacterSheetData, LibrarySkillEntry, SkillCategoryKey } from '../../types';
import { BookOpen, Archive, GripVertical, ArrowRight, Layers, CheckCircle2 } from 'lucide-react';

interface LibrarySidebarProps {
    data: CharacterSheetData;
    onUpdate: (newData: CharacterSheetData) => void;
    onAddLog: (message: string, type?: 'success' | 'danger' | 'info', category?: 'sheet' | 'settings') => void;
    draggedItem: { type: 'sheet_skill' | 'lib_skill', category?: string, index?: number, id?: string, data?: any } | null;
    setDraggedItem: (item: any) => void;
}

const LibrarySidebar: React.FC<LibrarySidebarProps> = ({ data, onUpdate, onAddLog, draggedItem, setDraggedItem }) => {

    const handleDragStart = (e: React.DragEvent, type: 'lib_skill', dataPayload: any) => {
        setDraggedItem({ type, ...dataPayload });
        e.dataTransfer.effectAllowed = "move";
        e.dataTransfer.setData("application/json", JSON.stringify({ type, ...dataPayload }));
    };

    const handleDragOver = (e: React.DragEvent) => {
        e.preventDefault();
        e.dataTransfer.dropEffect = "move";
    };

    const handleDropOnLibrary = (e: React.DragEvent) => {
        e.preventDefault();
        if (!draggedItem) return;

        // Only accept items from sheet (archiving)
        if (draggedItem.type === 'sheet_skill' && draggedItem.category !== 'counters') {
            const catKey = draggedItem.category as SkillCategoryKey;
            const index = draggedItem.index!;

            const newSkills = { ...data.skills };
            const list = [...(newSkills[catKey] || [])];
            const [removedItem] = list.splice(index, 1);
            newSkills[catKey] = list;

            // Add to Library
            // Check duplicate name first to be safe
            const existingInLib = (data.skillLibrary || []).find(l => l.name === removedItem.name);
            const newLib = [...(data.skillLibrary || [])];

            if (!existingInLib && removedItem.name.trim() !== '') {
                const newLibEntry: LibrarySkillEntry = {
                    id: Math.random().toString(36).substr(2, 9),
                    name: removedItem.name,
                    description: '',
                    defaultCategory: catKey
                };
                newLib.push(newLibEntry);
                onAddLog(`Archivage : "${removedItem.name}" déplacé vers la réserve`, 'info', 'settings');
            } else {
                onAddLog(`Suppression : "${removedItem.name}" retiré de la fiche`, 'info', 'settings');
            }

            // Sort Library Alphabetically
            newLib.sort((a, b) => a.name.localeCompare(b.name));

            onUpdate({
                ...data,
                skills: newSkills,
                skillLibrary: newLib
            });
        }
        setDraggedItem(null);
    };

    // Filter out skills that are already present on the sheet to avoid duplication clutter
    const currentSkillNames = new Set<string>();
    Object.keys(data.skills).forEach(cat => {
        data.skills[cat].forEach(s => {
            if (s.name) currentSkillNames.add(s.name.trim().toLowerCase());
        });
    });

    const visibleLibrary = (data.skillLibrary || []).filter(libItem =>
        libItem.isVariable || !currentSkillNames.has(libItem.name.trim().toLowerCase())
    );

    return (
        <div
            className={`w-80 bg-slate-100 border-l border-gray-300 flex flex-col fixed right-0 top-14 bottom-0 z-30 transition-colors ${draggedItem?.type === 'sheet_skill' ? 'bg-orange-50 border-orange-300' : ''}`}
            onDragOver={handleDragOver}
            onDrop={handleDropOnLibrary}
        >
            <div className="p-4 bg-slate-200 border-b border-gray-300 font-bold text-slate-700 flex items-center gap-2 shadow-sm">
                <BookOpen size={18} />
                Réserve de Compétences
            </div>

            {draggedItem?.type === 'sheet_skill' && draggedItem.category !== 'counters' && (
                <div className="absolute inset-0 bg-orange-100/90 z-50 flex flex-col items-center justify-center border-4 border-dashed border-orange-400 m-2 rounded-xl pointer-events-none">
                    <Archive size={48} className="text-orange-600 mb-2" />
                    <span className="font-bold text-orange-800 text-lg">Archiver ici</span>
                    <span className="text-sm text-orange-700">Retirer de la fiche et garder en réserve</span>
                </div>
            )}

            <div className="p-3 text-xs text-slate-500 border-b border-slate-200 bg-slate-50">
                Glissez des compétences ici vers la fiche pour les ajouter.
                Glissez une compétence de la fiche ici pour la ranger.
            </div>

            <div className="flex-grow overflow-y-auto p-3 space-y-2 custom-scrollbar">
                {visibleLibrary.length === 0 ? (
                    <div className="text-center text-slate-400 italic mt-10 px-4">
                        {(data.skillLibrary || []).length > 0
                            ? "Toutes les compétences de la réserve sont déjà sur la fiche."
                            : "La réserve est vide."}
                    </div>
                ) : (
                    visibleLibrary.map(item => {
                        const isPresent = currentSkillNames.has(item.name.trim().toLowerCase());

                        return (
                            <div
                                key={item.id}
                                draggable
                                onDragStart={(e) => handleDragStart(e, 'lib_skill', { data: item })}
                                className={`p-2 rounded border shadow-sm cursor-grab active:cursor-grabbing transition-all flex justify-between items-center group ${isPresent
                                        ? 'bg-green-50/30 border-green-200/60 hover:border-green-400'
                                        : 'bg-white border-gray-300 hover:border-purple-400 hover:shadow-md'
                                    }`}
                            >
                                <div className="flex items-center gap-2 overflow-hidden">
                                    <GripVertical size={14} className="text-gray-300 shrink-0" />
                                    <div className="flex flex-col min-w-0">
                                        <div className="flex items-center gap-1.5">
                                            <span className={`font-bold text-sm truncate ${isPresent ? 'text-green-800' : 'text-slate-700'}`}>
                                                {item.name}
                                            </span>
                                        </div>
                                        <div className="flex items-center gap-1">
                                            {item.isVariable && (
                                                <div className="flex items-center gap-0.5 text-[10px] text-blue-600 bg-blue-50 px-1 rounded-sm border border-blue-100">
                                                    <Layers size={10} />
                                                    <span className="font-semibold" title="Compétence à variations">Variable</span>
                                                </div>
                                            )}
                                            {isPresent && (
                                                <div className="flex items-center gap-0.5 text-[10px] text-green-700 bg-green-50 px-1 rounded-sm border border-green-100">
                                                    <CheckCircle2 size={10} />
                                                    <span className="font-semibold">Présent</span>
                                                </div>
                                            )}
                                        </div>
                                    </div>
                                </div>
                                <ArrowRight size={14} className="text-gray-300 opacity-0 group-hover:opacity-100 shrink-0 mx-1" />
                            </div>
                        );
                    })
                )}
            </div>
        </div>
    );
};

export default LibrarySidebar;

import React from 'react';
import { CharacterSheetData, DotEntry, SkillCategoryKey } from '../../types';
import { Save, GraduationCap } from 'lucide-react';
import ThematicModal from '../ui/ThematicModal';
import { useRules } from '../../context/RulesContext';
import { useSkillsEditorActions } from './hooks/useSkillsEditorActions';
import { SkillCategoryEditor } from './skills/SkillCategoryEditor';

interface SkillsEditorProps {
    data: CharacterSheetData;
    onUpdate: (newData: CharacterSheetData) => void;
    onAddLog: (message: string, type?: 'success' | 'danger' | 'info', category?: 'sheet' | 'settings') => void;
    draggedItem: { type: 'sheet_skill' | 'lib_skill', category?: string, index?: number, id?: string, data?: any } | null;
    setDraggedItem: (item: any) => void;
}

const SkillsEditor: React.FC<SkillsEditorProps> = ({ data, onUpdate, onAddLog, draggedItem, setDraggedItem }) => {
    const { rules } = useRules();
    const skillCategories = rules?.definitions?.skillCategories || [];

    const actions = useSkillsEditorActions({
        data,
        onUpdate,
        onAddLog,
        draggedItem,
        setDraggedItem,
        rules
    });

    const {
        variantModalOpen,
        setVariantModalOpen,
        pendingSkillDrop,
        setPendingSkillDrop,
        variantInput,
        setVariantInput,
        confirmVariableSkill
    } = actions;

    return (
        <div className="animate-in fade-in slide-in-from-bottom-2 duration-300 space-y-8">
            <div>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                    {skillCategories.map((cat) => (
                        <div key={cat.id} className="min-h-[200px]">
                            <SkillCategoryEditor
                                title={cat.label}
                                category={cat.id}
                                heightClass="h-full"
                                defaultItemName={cat.behavior === 'Arrière-plan' ? 'Nouvel Arrière Plan' : 'Nouvelle Compétence'}
                                list={(data.skills?.[cat.id as SkillCategoryKey] || []) as DotEntry[]}
                                draggedItem={draggedItem}
                                actions={actions}
                            />
                        </div>
                    ))}
                </div>
            </div>

            {/* Custom Counters section removed per user request (counters managed in Library/System only) */}

            {/* Variable Skill Modal */}
            {variantModalOpen && pendingSkillDrop && (
                <ThematicModal
                    isOpen={variantModalOpen}
                    onClose={() => { setVariantModalOpen(false); setPendingSkillDrop(null); }}
                    title="Précision requise"
                    icon={<GraduationCap size={24} />}
                    size="md"
                    footer={
                        <>
                            <button
                                onClick={() => { setVariantModalOpen(false); setPendingSkillDrop(null); }}
                                className="px-4 py-2 text-[#5c4d41] hover:bg-stone-200/50 rounded-sm font-bold"
                            >
                                Annuler
                            </button>
                            <button
                                onClick={confirmVariableSkill}
                                className="px-6 py-2 bg-[#5c4d41] text-white rounded-sm font-bold shadow-md hover:bg-[#4a3b32] flex items-center gap-2"
                            >
                                <Save size={16} /> Confirmer
                            </button>
                        </>
                    }
                >
                    <div className="flex flex-col gap-4 py-2">
                        <div className="bg-amber-50/50 border border-amber-200/50 p-3 rounded-sm text-sm text-[#5c4d41]">
                            Vous ajoutez la compétence <strong>{pendingSkillDrop.libItem.name}</strong>.
                            <br />
                            Cette compétence nécessite une précision (variante).
                        </div>

                        <div>
                            <label className="block text-[10px] font-bold text-[#bfae85] uppercase mb-1 tracking-widest">
                                Spécialité / Variante (ex: Forge, Histoire, Épées...)
                            </label>
                            <input
                                className="w-full border border-[#bfae85]/50 rounded-sm px-3 py-2 font-serif font-black text-[#1c1917] bg-white/50 focus:border-amber-500 outline-none shadow-sm text-lg"
                                value={variantInput}
                                onChange={(e) => setVariantInput(e.target.value)}
                                onKeyDown={(e) => e.key === 'Enter' && confirmVariableSkill()}
                            />

                            {/* Suggested Variants */}
                            {pendingSkillDrop.libItem.variants && pendingSkillDrop.libItem.variants.length > 0 && (
                                <div className="flex flex-wrap gap-2 mt-4 pt-3 border-t border-[#bfae85]/20">
                                    <span className="w-full text-[9px] font-bold text-[#bfae85] uppercase tracking-wider mb-1">Variantes suggérées :</span>
                                    {pendingSkillDrop.libItem.variants.map((v: string) => (
                                        <button
                                            key={v}
                                            onClick={() => setVariantInput(v)}
                                            className={`px-2 py-1 text-xs rounded-full border transition-all ${variantInput === v ? 'bg-[#8b2e2e] text-white border-[#8b2e2e]' : 'bg-white text-[#5c4d41] border-[#bfae85]/30 hover:border-[#8b2e2e] hover:shadow-sm'}`}
                                        >
                                            {v}
                                        </button>
                                    ))}
                                </div>
                            )}
                        </div>
                    </div>
                </ThematicModal>
            )}
        </div>
    );
};

export default SkillsEditor;

