export default SpecializationLibrarySidebar;

import React, { useState } from 'react';
import { CharacterSheetData, DotEntry, SkillCategoryKey } from '../../types';
import { Plus, Trash2, Award } from 'lucide-react';
import SpecializationOmnibar from '../specialization-library/SpecializationOmnibar';
import { ErrorService } from '../../services/ErrorService';

interface SpecializationsEditorProps {
  data: CharacterSheetData;
  onUpdate: (newData: CharacterSheetData) => void;
  onAddLog: (message: string, type?: 'success' | 'danger' | 'info', category?: 'sheet' | 'settings') => void;
}

const SpecializationsEditor: React.FC<SpecializationsEditorProps> = ({ data, onUpdate, onAddLog }) => {
  const [newlyAddedSpec, setNewlyAddedSpec] = useState<{ skillId: string; index: number } | null>(null);

  const getSkillContext = (skillId: string) => {
    if (!data.skills) return { name: "Inconnu" };
    for (const cat of Object.keys(data.skills)) {
      const list = data.skills[cat];
      if (Array.isArray(list)) {
        const found = list.find(s => s.id === skillId);
        if (found) return { name: found.name };
      }
    }
    return { name: "Inconnu" };
  };

  const updateSpecialization = (skillId: string, index: number, field: 'name' | 'minLevel', value: string | number) => {
    const currentSpecs = data.imposedSpecializations[skillId] || [];
    const newSpecs = [...currentSpecs];
    newSpecs[index] = { ...newSpecs[index], [field]: value };

    onUpdate({
      ...data,
      imposedSpecializations: {
        ...data.imposedSpecializations,
        [skillId]: newSpecs
      }
    });
  };

  const syncSpecializationWithLibrary = (skillId: string, name: string, minLevel: number) => {
    if (name.trim() === '') return;

    const newLibrary = [...(data.specializationLibrary || [])];
    const normName = name.trim().toLowerCase();
    const existingIdx = newLibrary.findIndex(l => l.name.trim().toLowerCase() === normName);

    if (existingIdx !== -1) {
      const entry = newLibrary[existingIdx];
      const skillIds = entry.skillIds || [];
      if (!skillIds.includes(skillId)) {
        newLibrary[existingIdx] = {
          ...entry,
          skillIds: [...skillIds, skillId]
        };
        onUpdate({ ...data, specializationLibrary: newLibrary });
      }
    } else {
      newLibrary.push({
        id: Math.random().toString(36).substr(2, 9),
        name: name.trim(),
        skillIds: [skillId],
        defaultMinLevel: minLevel || 0,
        description: ''
      });
      newLibrary.sort((a, b) => a.name.localeCompare(b.name));
      onUpdate({ ...data, specializationLibrary: newLibrary });
    }
  };

  const addSpecialization = (skillId: string) => {
    const currentSpecs = data.imposedSpecializations[skillId] || [];
    const newSpec = { name: "", minLevel: 0 };
    const newSpecs = [...currentSpecs, newSpec];

    onUpdate({
      ...data,
      imposedSpecializations: {
        ...data.imposedSpecializations,
        [skillId]: newSpecs
      }
    });
    setNewlyAddedSpec({ skillId, index: currentSpecs.length });
    const { name } = getSkillContext(skillId);
    onAddLog(`Ajout : Spécialisation automatique pour "${name}"`, 'success', 'settings');
  };

  const removeSpecialization = (skillId: string, index: number) => {
    const currentSpecs = data.imposedSpecializations[skillId] || [];
    const specName = currentSpecs[index]?.name || '(vide)';
    const newSpecs = currentSpecs.filter((_, i) => i !== index);
    onUpdate({
      ...data,
      imposedSpecializations: {
        ...data.imposedSpecializations,
        [skillId]: newSpecs
      }
    });
    const { name } = getSkillContext(skillId);
    onAddLog(`Suppression : Spécialisation "${specName || '(vide)'}" pour "${name}"`, 'danger', 'settings');
  };

  const handleDrop = (e: React.DragEvent, skillId: string) => {
    e.preventDefault();
    try {
      const dragData = e.dataTransfer.getData('application/json');
      if (dragData) {
        const { name, minLevel } = JSON.parse(dragData);
        if (name) {
          const currentSpecs = data.imposedSpecializations[skillId] || [];
          const newSpecs = [...currentSpecs, { name, minLevel: minLevel || 1 }];
          onUpdate({
            ...data,
            imposedSpecializations: {
              ...data.imposedSpecializations,
              [skillId]: newSpecs
            }
          });
          const { name: skillName } = getSkillContext(skillId);
          onAddLog(`Ajout (via catalogue) : "${name}" pour "${skillName}"`, 'success', 'settings');
        }
      }
    } catch (err) {
      ErrorService.handleError(err, { context: 'SpecializationsEditor.Drop', silent: true });
    }
  };

  const renderSpecializationEditor = (title: string, category: string) => {
    // Migration safety: support both legacy and new category keys
    const legacyToNew: Record<string, string> = {
      'talents': 'Col_Comp_1',
      'competences': 'Col_Comp_2',
      'competences_col_2': 'Col_Comp_3',
      'connaissances': 'Col_Comp_4',
      'autres_competences': 'Col_Comp_5',
      'autres': 'Col_Comp_7',
      'arrieres_plans': 'Col_Comp_8'
    };

    const list: DotEntry[] = data.skills[category] || (legacyToNew[category] ? data.skills[legacyToNew[category]] : []) || [];

    return (
      <div className="bg-white p-4 rounded shadow flex flex-col h-full animate-in fade-in duration-300">
        <h3 className="font-bold text-sm mb-4 text-gray-800 border-b pb-2 flex items-center justify-between">
          {title}
        </h3>
        <div className="flex-grow overflow-y-auto space-y-3 pr-2 max-h-[500px] custom-scrollbar">
          {list.length === 0 && (
            <div className="text-center text-gray-400 text-xs italic py-4 border-2 border-dashed border-gray-100 rounded">
              Aucune compétence.
            </div>
          )}
          {list.map((skill) => {
            const imposedSpecs = data.imposedSpecializations[skill.id] || [];

            // Skip spacers (empty names)
            if (!skill.name) return null;

            return (
              <div
                key={skill.id}
                className="border border-gray-200 rounded p-2.5 bg-gray-50/50 hover:bg-white hover:shadow-sm transition-all group/skill"
                onDragOver={(e) => {
                  e.preventDefault();
                  e.currentTarget.classList.add('bg-amber-50');
                  e.currentTarget.classList.add('border-amber-300');
                }}
                onDragLeave={(e) => {
                  e.currentTarget.classList.remove('bg-amber-50');
                  e.currentTarget.classList.remove('border-amber-300');
                }}
                onDrop={(e) => {
                  e.currentTarget.classList.remove('bg-amber-50');
                  e.currentTarget.classList.remove('border-amber-300');
                  handleDrop(e, skill.id);
                }}
              >
                <div className="flex justify-between items-center mb-2">
                  <span className="font-bold text-sm text-gray-700">{skill.name}</span>
                  <button
                    onClick={() => addSpecialization(skill.id)}
                    className="text-[10px] bg-white border border-blue-200 text-blue-600 hover:bg-blue-50 px-2 py-1 rounded flex items-center gap-1 transition-colors font-bold shadow-sm opacity-0 group-hover/skill:opacity-100"
                  >
                    <Plus size={10} /> Ajouter
                  </button>
                </div>

                {imposedSpecs.length === 0 && (
                  <div className="text-[10px] text-gray-400 italic px-1 pb-1">
                    Aucune spécialisation automatique.
                  </div>
                )}

                <div className="space-y-1.5">
                  {imposedSpecs.map((spec, idx) => (
                    <div key={idx} className="flex items-center gap-1 animate-in slide-in-from-left-2 duration-200">
                      <div className="w-1.5 h-1.5 rounded-full bg-blue-400 shrink-0 ml-1"></div>
                      <SpecializationOmnibar
                        value={spec.name}
                        onChange={(val) => updateSpecialization(skill.id, idx, 'name', val)}
                        onBlur={(val) => syncSpecializationWithLibrary(skill.id, val, spec.minLevel)}
                        onSelect={(entry) => updateSpecialization(skill.id, idx, 'minLevel', entry.defaultMinLevel)}
                        skillId={skill.id}
                        className="flex-grow"
                        placeholder="Spécialisation..."
                      />
                      <div className="flex items-center bg-white border border-gray-300 rounded px-1 h-[26px] shrink-0">
                        <span className="text-[9px] font-bold text-gray-400 mr-1 uppercase">Seuil</span>
                        <input
                          type="number"
                          min="0"
                          max="5"
                          value={spec.minLevel || 0}
                          onChange={(e) => {
                            const val = parseInt(e.target.value) || 0;
                            updateSpecialization(skill.id, idx, 'minLevel', val);
                            syncSpecializationWithLibrary(skill.id, spec.name, val);
                          }}
                          className="w-6 text-center text-xs font-bold text-blue-600 outline-none bg-transparent"
                          title="Niveau minimum requis dans la compétence"
                        />
                      </div>
                      <button
                        onClick={() => removeSpecialization(skill.id, idx)}
                        className="text-gray-400 hover:text-red-500 hover:bg-red-50 p-1 rounded transition-colors"
                        title="Supprimer"
                      >
                        <Trash2 size={12} />
                      </button>
                    </div>
                  ))}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    );
  };

  return (
    <div className="animate-in fade-in slide-in-from-bottom-2 duration-300 space-y-8">
      <div>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
          {renderSpecializationEditor("Talents (Col 1)", "talents")}
          {renderSpecializationEditor("Compétences (Col 2)", "competences")}
          {renderSpecializationEditor("Compétences (Col 3)", "competences_col_2")}
          {renderSpecializationEditor("Connaissances (Col 4)", "connaissances")}
        </div>
      </div>
      <div>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
          {renderSpecializationEditor("Autres Compétences", "autres_competences")}
          {renderSpecializationEditor("Autres", "autres")}
        </div>
      </div>
    </div>
  );
};

export default SpecializationsEditor;

import { useState } from 'react';
import { CharacterSheetData } from '../../../types';
import { DEFAULT_ATTRIBUTES, ATTRIBUTE_PRESETS } from '../../../data/defaults/attributes';

interface UseAttributesEditorProps {
    data: CharacterSheetData;
    onUpdate: (newData: CharacterSheetData) => void;
    onAddLog: (message: string, type?: 'success' | 'danger' | 'info', category?: 'sheet' | 'settings') => void;
}

export const useAttributesEditor = ({ data, onUpdate, onAddLog }: UseAttributesEditorProps) => {
    const [pendingPreset, setPendingPreset] = useState<any>(null);
    const [showPresetConfirm, setShowPresetConfirm] = useState(false);

    const categories = data.attributeSettings || [];
    const count = categories.length;

    const firstCatId = categories[0]?.id;
    const globalAttrCount = firstCatId && data.attributes[firstCatId]
        ? data.attributes[firstCatId].length
        : 4;

    const requestPresetLoad = (preset: typeof ATTRIBUTE_PRESETS[0]) => {
        setPendingPreset(preset);
        setShowPresetConfirm(true);
    };

    const executePresetLoad = () => {
        if (!pendingPreset) return;

        const newSettings: any[] = [];
        const newAttributes: any = {};

        pendingPreset.structure.forEach((cat: any) => {
            newSettings.push({ id: cat.id, label: cat.label });
            newAttributes[cat.id] = cat.attrs.map((name: string) => ({
                id: Math.random().toString(36).substr(2, 9),
                name: name,
                val1: "0", val2: "", val3: "",
                creationVal1: 0, creationVal2: 0, creationVal3: 0
            }));
        });

        onUpdate({
            ...data,
            attributeSettings: newSettings,
            attributes: newAttributes
        });

        onAddLog(`Préréglage attributs appliqué : ${pendingPreset.name}`, 'success', 'settings');
        setShowPresetConfirm(false);
        setPendingPreset(null);
    };

    const handleCategoryCountChange = (newCount: number) => {
        const defaultDefs = [
            { id: 'pave_attributs_1', label: 'Physique' },
            { id: 'pave_attributs_2', label: 'Mental' },
            { id: 'pave_attributs_3', label: 'Social' },
            { id: 'pave_attributs_4', label: 'Mystique' }
        ];

        const currentDefs = [...data.attributeSettings];
        const currentAttributes = { ...data.attributes };

        const firstCat = currentDefs[0]?.id;
        const currentAttrCount = firstCat && currentAttributes[firstCat] ? currentAttributes[firstCat].length : 4;

        if (newCount > currentDefs.length) {
            for (let i = currentDefs.length; i < newCount; i++) {
                let defToAdd = defaultDefs[i];
                if (!defToAdd) {
                    defToAdd = { id: `pave_attributs_${i + 1}`, label: `Pavé ${i + 1}` };
                }

                if (currentDefs.some(d => d.id === defToAdd.id)) {
                    defToAdd = { ...defToAdd, id: `${defToAdd.id}_${Math.random().toString(36).substr(2, 4)}` };
                }
                currentDefs.push(defToAdd);

                currentAttributes[defToAdd.id] = Array(currentAttrCount).fill(null).map((_, idx) => {
                    let attrName = `Attribut ${idx + 1}`;
                    const baseId = defToAdd.id.split('_')[0];
                    if (DEFAULT_ATTRIBUTES[baseId] && DEFAULT_ATTRIBUTES[baseId][idx]) {
                        attrName = DEFAULT_ATTRIBUTES[baseId][idx];
                    }

                    return {
                        id: Math.random().toString(36).substr(2, 9),
                        name: attrName,
                        val1: "0", val2: "", val3: ""
                    };
                });
            }
        } else if (newCount < currentDefs.length) {
            const removed = currentDefs.splice(newCount);
            removed.forEach(def => {
                delete currentAttributes[def.id];
            });
        }

        onUpdate({
            ...data,
            attributeSettings: currentDefs,
            attributes: currentAttributes
        });
    };

    const handleGlobalAttributeCountChange = (newCount: number) => {
        const newAttributes = { ...data.attributes };

        Object.keys(newAttributes).forEach(catId => {
            const attrs = [...(newAttributes[catId] || [])];
            if (newCount > attrs.length) {
                const diff = newCount - attrs.length;
                for (let i = 0; i < diff; i++) {
                    const idx = attrs.length;
                    let attrName = `Attribut ${idx + 1}`;
                    const baseId = catId.split('_')[0];
                    if (DEFAULT_ATTRIBUTES[baseId] && DEFAULT_ATTRIBUTES[baseId][idx]) {
                        attrName = DEFAULT_ATTRIBUTES[baseId][idx];
                    }

                    attrs.push({
                        id: Math.random().toString(36).substr(2, 9),
                        name: attrName,
                        val1: "0", val2: "", val3: ""
                    });
                }
            } else if (newCount < attrs.length) {
                attrs.splice(newCount);
            }
            newAttributes[catId] = attrs;
        });

        onUpdate({
            ...data,
            attributes: newAttributes
        });
    };

    const updateCategoryLabel = (id: string, label: string) => {
        const newSettings = data.attributeSettings.map(def =>
            def.id === id ? { ...def, label } : def
        );
        onUpdate({ ...data, attributeSettings: newSettings });
    };

    const updateAttributeName = (catId: string, attrId: string, name: string) => {
        const catAttrs = data.attributes[catId];
        if (!catAttrs) return;

        const newAttrs = catAttrs.map(attr =>
            attr.id === attrId ? { ...attr, name } : attr
        );
        onUpdate({
            ...data,
            attributes: {
                ...data.attributes,
                [catId]: newAttrs
            }
        });
    };

    const toggleSecondaryAttributes = () => {
        const isActive = !data.secondaryAttributesActive;
        const newSecondary = { ...data.secondaryAttributes };

        if (isActive) {
            data.attributeSettings.forEach(cat => {
                if (!newSecondary[cat.id]) {
                    newSecondary[cat.id] = [
                        { id: Math.random().toString(36).substr(2, 9), name: 'Secondaire 1', val1: "0", val2: "", val3: "" },
                        { id: Math.random().toString(36).substr(2, 9), name: 'Secondaire 2', val1: "0", val2: "", val3: "" }
                    ];
                }
            });
        }

        onUpdate({
            ...data,
            secondaryAttributesActive: isActive,
            secondaryAttributes: newSecondary
        });
    };

    const updateSecondaryAttributeName = (catId: string, index: number, name: string) => {
        const newSecAttrs = [...(data.secondaryAttributes[catId] || [])];
        if (newSecAttrs[index]) {
            newSecAttrs[index] = { ...newSecAttrs[index], name };
            onUpdate({
                ...data,
                secondaryAttributes: {
                    ...data.secondaryAttributes,
                    [catId]: newSecAttrs
                }
            });
        }
    };

    const updateAttributeCost = (cost: number) => {
        onUpdate({
            ...data,
            creationConfig: {
                ...data.creationConfig,
                attributeCost: cost
            }
        });
    };

    return {
        pendingPreset,
        showPresetConfirm,
        setShowPresetConfirm,
        setPendingPreset,
        categories,
        count,
        globalAttrCount,
        requestPresetLoad,
        executePresetLoad,
        handleCategoryCountChange,
        handleGlobalAttributeCountChange,
        updateCategoryLabel,
        updateAttributeName,
        toggleSecondaryAttributes,
        updateSecondaryAttributeName,
        updateAttributeCost
    };
};

import { useState } from 'react';
import { CharacterSheetData, DotEntry, LibrarySkillEntry, SkillCategoryKey, RulesData, SkillCategoryConfig } from '../../../types';

interface UseSkillsEditorActionsProps {
    data: CharacterSheetData;
    onUpdate: (newData: CharacterSheetData) => void;
    onAddLog: (message: string, type?: 'success' | 'danger' | 'info', category?: 'sheet' | 'settings') => void;
    draggedItem: any;
    setDraggedItem: (item: any) => void;
    rules: RulesData | null;
}

export function useSkillsEditorActions({ data, onUpdate, onAddLog, draggedItem, setDraggedItem, rules }: UseSkillsEditorActionsProps) {
    const skillCategories = rules?.definitions?.skillCategories || [];

    const [focusedValue, setFocusedValue] = useState<string | null>(null);
    const [newlyAddedId, setNewlyAddedId] = useState<string | null>(null);

    // State for Variable Skill Modal
    const [variantModalOpen, setVariantModalOpen] = useState(false);
    const [pendingSkillDrop, setPendingSkillDrop] = useState<{
        libItem: LibrarySkillEntry;
        category: string;
        index: number;
    } | null>(null);
    const [variantInput, setVariantInput] = useState("");

    const getCategoryLabel = (catId: string) => {
        const found = skillCategories.find((c: SkillCategoryConfig) => c.id === catId);
        return found ? found.label : catId;
    };

    // --- CRUD LOGIC ---

    const updateSkillName = (category: SkillCategoryKey, id: string, newName: string) => {
        const list = data.skills[category];
        if (!list) return;

        onUpdate({
            ...data,
            skills: {
                ...data.skills,
                [category]: list.map(item => item.id === id ? { ...item, name: newName } : item)
            }
        });
    };

    const updateSkillVariant = (category: SkillCategoryKey, id: string, newVariant: string) => {
        const list = data.skills[category];
        if (!list) return;

        onUpdate({
            ...data,
            skills: {
                ...data.skills,
                [category]: list.map(item => item.id === id ? { ...item, variant: newVariant } : item)
            }
        });
    };

    const syncSkillWithLibrary = (name: string, category: SkillCategoryKey) => {
        if (name.trim() === '' || name === 'Nouvelle Compétence') return;

        const normName = name.trim().toLowerCase();
        let newLibrary = [...(data.skillLibrary || [])];
        const exists = newLibrary.some(l => l.name.trim().toLowerCase() === normName);

        if (!exists) {
            const newLibEntry: LibrarySkillEntry = {
                id: Math.random().toString(36).substr(2, 9),
                name: name.trim(),
                description: '',
                defaultCategory: category
            };
            newLibrary = [...newLibrary, newLibEntry].sort((a, b) => a.name.localeCompare(b.name));
            onUpdate({ ...data, skillLibrary: newLibrary });
        }
    };

    const removeSkill = (category: SkillCategoryKey, id: string) => {
        const list = data.skills[category];
        if (!list) return;

        const skillToRemove = list.find(s => s.id === id);
        if (!skillToRemove) return;

        const skillName = skillToRemove.name;

        // Return to library check
        const libList = data.skillLibrary || [];
        const existsInLib = libList.some(l => l.name.trim().toLowerCase() === skillName.trim().toLowerCase());

        let newLibrary = libList;

        if (!existsInLib && skillName.trim() !== '') {
            const newLibEntry: LibrarySkillEntry = {
                id: Math.random().toString(36).substr(2, 9),
                name: skillName,
                description: '',
                defaultCategory: category
            };
            newLibrary = [...libList, newLibEntry];
            newLibrary.sort((a, b) => a.name.localeCompare(b.name));
            onAddLog(`"${skillName}" retiré de la fiche et ajouté à la réserve`, 'info', 'settings');
        } else {
            onAddLog(`"${skillName}" retiré de la fiche (retourne en réserve)`, 'info', 'settings');
        }

        onUpdate({
            ...data,
            skillLibrary: newLibrary,
            skills: {
                ...data.skills,
                [category]: list.filter(item => item.id !== id)
            }
        });
    };

    const addSkill = (category: SkillCategoryKey, isSpacer = false, defaultName = 'Nouvelle Compétence') => {
        const list = data.skills[category] || [];
        const newId = Math.random().toString(36).substr(2, 9);
        const newSkill: DotEntry = {
            id: newId,
            name: isSpacer ? '' : defaultName,
            value: 0,
            creationValue: 0,
            max: 5
        };

        onUpdate({
            ...data,
            skills: {
                ...data.skills,
                [category]: [...list, newSkill]
            }
        });

        if (!isSpacer) {
            setNewlyAddedId(newId);
            onAddLog(`Ajout : Nouvelle compétence dans [${getCategoryLabel(category)}]`, 'success', 'settings');
        } else {
            onAddLog(`Ajout : Espaceur dans [${getCategoryLabel(category)}]`, 'info', 'settings');
        }
    };

    // --- DRAG & DROP LOGIC ---

    const handleDragStart = (e: React.DragEvent, type: 'sheet_skill' | 'lib_skill', dataPayload: { category: string; index: number; item: DotEntry } | LibrarySkillEntry) => {
        setDraggedItem({ type, ...dataPayload });
        e.dataTransfer.effectAllowed = "move";
        e.dataTransfer.setData("application/json", JSON.stringify({ type, ...dataPayload }));
    };

    const handleDragOver = (e: React.DragEvent) => {
        e.preventDefault();
        e.dataTransfer.dropEffect = "move";
    };

    const handleDropOnSheet = (e: React.DragEvent, targetCategory: string, targetIndex: number) => {
        e.preventDefault();
        e.stopPropagation();

        if (!draggedItem) return;

        // 1. Reordering within Sheet
        if (draggedItem.type === 'sheet_skill') {
            const sourceCategory = draggedItem.category!;
            const sourceIndex = draggedItem.index!;

            // Same pos check
            if (sourceCategory === targetCategory && sourceIndex === targetIndex) return;

            const newSkills = { ...data.skills };
            const sourceList = [...(newSkills[sourceCategory as SkillCategoryKey] || [])];
            const targetList = (sourceCategory === targetCategory) ? sourceList : [...(newSkills[targetCategory as SkillCategoryKey] || [])];

            const [itemToMove] = sourceList.splice(sourceIndex, 1);

            targetList.splice(targetIndex, 0, itemToMove);

            newSkills[sourceCategory as SkillCategoryKey] = sourceList;
            if (sourceCategory !== targetCategory) {
                newSkills[targetCategory as SkillCategoryKey] = targetList;
            }

            onUpdate({ ...data, skills: newSkills });
        }

        // 2. Dropping from Library to Sheet
        else if (draggedItem.type === 'lib_skill') {
            const libItem = draggedItem.data as LibrarySkillEntry;

            // Handle Variable Skills (Option 1)
            if (libItem.isVariable) {
                setPendingSkillDrop({
                    libItem,
                    category: targetCategory,
                    index: targetIndex
                });
                setVariantInput("");
                setVariantModalOpen(true);
                setDraggedItem(null);
                return;
            }

            const newSkillEntry: DotEntry = {
                id: Math.random().toString(36).substr(2, 9),
                name: libItem.name,
                value: 0,
                creationValue: 0,
                max: 5,
                variant: undefined
            };

            const newSkills = { ...data.skills };
            const targetList = [...(newSkills[targetCategory as SkillCategoryKey] || [])];

            targetList.splice(targetIndex, 0, newSkillEntry);
            newSkills[targetCategory as SkillCategoryKey] = targetList;

            onUpdate({ ...data, skills: newSkills });
            onAddLog(`Importation : "${libItem.name}" depuis la réserve`, 'success', 'settings');
        }

        setDraggedItem(null);
    };

    const confirmVariableSkill = () => {
        if (!pendingSkillDrop) return;

        const { libItem, category, index } = pendingSkillDrop;
        const variant = variantInput.trim();

        const newSkillEntry: DotEntry = {
            id: Math.random().toString(36).substr(2, 9),
            name: libItem.name,
            value: 0,
            creationValue: 0,
            max: 5,
            variant: variant
        };

        const newSkills = { ...data.skills };
        const targetList = [...(newSkills[category as SkillCategoryKey] || [])];

        targetList.splice(index, 0, newSkillEntry);
        newSkills[category as SkillCategoryKey] = targetList;

        onUpdate({ ...data, skills: newSkills });
        const logMsg = variant
            ? `Importation : "${libItem.name} : ${variant}" depuis la réserve`
            : `Importation : "${libItem.name}" depuis la réserve`;

        onAddLog(logMsg, 'success', 'settings');

        setVariantModalOpen(false);
        setPendingSkillDrop(null);
    };

    return {
        focusedValue,
        setFocusedValue,
        newlyAddedId,
        setNewlyAddedId,
        variantModalOpen,
        setVariantModalOpen,
        pendingSkillDrop,
        setPendingSkillDrop,
        variantInput,
        setVariantInput,
        getCategoryLabel,
        updateSkillName,
        updateSkillVariant,
        syncSkillWithLibrary,
        removeSkill,
        addSkill,
        handleDragStart,
        handleDragOver,
        handleDropOnSheet,
        confirmVariableSkill,
        onAddLog
    };
}

import React from 'react';
import { DotEntry, SkillCategoryKey } from '../../../types';
import { Minus, Plus, GripVertical, Trash2 } from 'lucide-react';
import { useSkillsEditorActions } from '../hooks/useSkillsEditorActions';

interface SkillCategoryEditorProps {
    title: string;
    category: string;
    list: DotEntry[];
    draggedItem: any;
    actions: ReturnType<typeof useSkillsEditorActions>;
    heightClass?: string;
    defaultItemName?: string;
    isCounters?: boolean;
}

export const SkillCategoryEditor: React.FC<SkillCategoryEditorProps> = ({
    title,
    category,
    list,
    draggedItem,
    actions,
    heightClass = "h-full",
    defaultItemName = "Nouvelle Compétence",
    isCounters = false
}) => {
    const {
        addSkill,
        handleDragOver,
        handleDropOnSheet,
        handleDragStart,
        newlyAddedId,
        setNewlyAddedId,
        focusedValue,
        setFocusedValue,
        updateSkillName,
        updateSkillVariant,
        syncSkillWithLibrary,
        removeSkill,
        getCategoryLabel,
        onAddLog
    } = actions;

    return (
        <div
            className={`bg-[#fdfbf7]/80 backdrop-blur-sm p-4 rounded-sm shadow-md flex flex-col ${heightClass} border border-[#bfae85]/30 transition-all duration-300 ${draggedItem && !isCounters ? 'border-dashed border-amber-400 bg-amber-50/50 scale-[1.01]' : ''}`}
            onDragOver={handleDragOver}
            onDrop={(e) => handleDropOnSheet(e, category, list.length)}
        >
            <h3 className="font-bold text-[10px] mb-4 text-[#5c4d41] border-b border-[#bfae85]/30 pb-2 flex justify-between items-center select-none uppercase tracking-widest">
                {title}
                <div className="flex gap-1">
                    <button
                        onClick={() => addSkill(category as SkillCategoryKey, true)}
                        className="text-[9px] bg-stone-500 text-white px-2 py-1 rounded-sm flex items-center gap-1 hover:bg-stone-600 transition-colors font-bold shadow-sm"
                        title="Ajouter un espaceur"
                    >
                        <Minus size={12} /> Espace
                    </button>
                    <button
                        onClick={() => addSkill(category as SkillCategoryKey, false, defaultItemName)}
                        className="text-[9px] bg-[#166534] text-white px-2 py-1 rounded-sm flex items-center gap-1 hover:bg-[#114b27] transition-colors font-bold shadow-sm"
                    >
                        <Plus size={12} /> Ajouter
                    </button>
                </div>
            </h3>
            <div className="flex-grow overflow-y-auto space-y-2 pr-1 max-h-[500px] min-h-[50px] custom-scrollbar">
                {list.length === 0 && (
                    <div className="h-16 border-2 border-dashed border-[#bfae85]/30 rounded-sm flex items-center justify-center text-[#5c4d41]/40 text-[10px] pointer-events-none italic">
                        Zone de dépôt
                    </div>
                )}
                {list.map((item, index) => {
                    const isDragging = draggedItem?.type === 'sheet_skill' && draggedItem?.category === category && draggedItem?.index === index;
                    return (
                        <div
                            key={item.id}
                            className={`flex items-center gap-2 text-sm group transition-all duration-200 p-1 rounded-sm ${isDragging ? 'opacity-50 bg-[#bfae85]/10' : 'hover:bg-[#bfae85]/5'}`}
                            draggable
                            onDragStart={(e) => handleDragStart(e, 'sheet_skill', { category, index, item })}
                            onDragOver={handleDragOver}
                            onDrop={(e) => { e.stopPropagation(); handleDropOnSheet(e, category, index); }}
                        >
                            <div className="cursor-grab text-[#bfae85]/40 hover:text-[#8b2e2e] active:cursor-grabbing p-1 transition-colors">
                                <GripVertical size={16} />
                            </div>
                            <span className="text-[#5c4d41]/30 text-[9px] w-4 text-center select-none font-mono">{index + 1}</span>

                            {item.name === '' ? (
                                <div className="flex-grow h-8 bg-black/5 border border-dashed border-[#bfae85]/30 rounded-sm flex items-center justify-center text-[10px] text-[#5c4d41]/40 italic cursor-default select-none shadow-inner">
                                    Espaceur
                                </div>
                            ) : (
                                <div className="flex-grow flex items-center gap-1">
                                    <input
                                        type="text"
                                        ref={(el) => { if (el && item.id === newlyAddedId) el.focus(); }}
                                        value={item.name}
                                        readOnly={!!item.variant}
                                        title={item.variant ? "Le nom racine ne peut pas être modifié pour une compétence variable" : undefined}
                                        onFocus={(e) => {
                                            setFocusedValue(e.target.value);
                                            if (e.target.value === defaultItemName) {
                                                e.target.select();
                                            }
                                        }}
                                        onBlur={(e) => {
                                            if (item.id === newlyAddedId) {
                                                setNewlyAddedId(null);
                                            }
                                            if (focusedValue !== null && e.target.value !== focusedValue) {
                                                const label = isCounters ? "Compteurs" : getCategoryLabel(category);
                                                onAddLog(`Modification : "${focusedValue}" renommé en "${e.target.value}" dans [${label}]`, 'info', 'settings');

                                                syncSkillWithLibrary(e.target.value, category as SkillCategoryKey);
                                            }
                                            setFocusedValue(null);
                                        }}
                                        onKeyDown={(e) => {
                                            if (e.key === 'Enter') {
                                                e.currentTarget.blur();
                                            }
                                        }}
                                        onChange={(e) => updateSkillName(category as SkillCategoryKey, item.id, e.target.value)}
                                        className={`border border-[#bfae85]/30 p-1 rounded-sm w-full focus:border-[#8b2e2e] outline-none bg-white/50 text-xs font-bold text-[#2c241b] transition-all ${item.variant ? 'bg-stone-100 text-stone-500 italic' : ''}`}
                                    />
                                    {item.variant !== undefined && (
                                        <>
                                            <span className="text-[#5c4d41] font-bold">:</span>
                                            <input
                                                type="text"
                                                value={item.variant}
                                                placeholder="Spécialité..."
                                                onChange={(e) => updateSkillVariant(category as SkillCategoryKey, item.id, e.target.value)}
                                                className="border border-[#bfae85]/30 p-1 rounded-sm w-full focus:border-[#8b2e2e] outline-none bg-white/50 text-xs font-bold text-[#8b2e2e] transition-all"
                                            />
                                        </>
                                    )}
                                </div>
                            )}
                            <button
                                onClick={() => removeSkill(category as SkillCategoryKey, item.id)}
                                className="text-red-500 hover:text-red-700 p-1 opacity-0 group-hover:opacity-100 transition-opacity"
                                title="Supprimer (remettre en réserve)"
                            >
                                <Trash2 size={14} />
                            </button>
                        </div>
                    );
                })}
            </div>
        </div>
    );
};

import React, { useRef, useState, useEffect } from 'react';
import { Upload, Trash2, Image as ImageIcon } from 'lucide-react';
import { saveImage, getImage, deleteImage, base64ToBlob } from '../../services/imageDB';
import ConfirmationModal from '../ui/ConfirmationModal';
import { ImageCompressionService, GZIP_MARKER } from '../../services/ImageCompressionService';
import { ErrorService } from '../../services/ErrorService';

interface CharacterImageWidgetProps {
    imageId: string | undefined;
    legacyImage: string | undefined;
    onImageUpdate: (id: string) => void;
    onAddLog: (msg: string, type: 'success' | 'danger') => void;
}

const CharacterImageWidget: React.FC<CharacterImageWidgetProps> = ({ imageId, legacyImage, onImageUpdate, onAddLog }) => {
    const fileInputRef = useRef<HTMLInputElement>(null);
    const [imageUrl, setImageUrl] = useState<string | null>(null);
    const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
    const [loading, setLoading] = useState(false);

    // Track the current blob URL in a ref so we can safely revoke the *previous* one
    // when a new one is created, rather than revoking in cleanup (which runs before paint).
    const currentBlobRef = useRef<string | null>(null);

    useEffect(() => {
        let active = true;

        const load = async () => {
            if (active) setLoading(true);

            try {
                if (imageId) {
                    const blob = await getImage(imageId);
                    if (blob && active) {
                        const newUrl = URL.createObjectURL(blob);
                        // Revoke previous blob URL only AFTER creating the new one
                        if (currentBlobRef.current) {
                            URL.revokeObjectURL(currentBlobRef.current);
                        }
                        currentBlobRef.current = newUrl;
                        setImageUrl(newUrl);
                    } else if (!blob && active) {
                        setImageUrl(null);
                    }
                } else if (legacyImage && legacyImage.length > 100) {
                    // If legacy image is gzipped, decompress for migration
                    const toMigrate = legacyImage.startsWith(GZIP_MARKER)
                        ? ImageCompressionService.decompressFull(legacyImage)
                        : legacyImage;

                    const blob = await base64ToBlob(toMigrate);
                    const newId = await saveImage(blob);

                    if (active) {
                        onImageUpdate(newId);
                        onAddLog("Migration automatique de l'image.", 'success');
                    }
                } else {
                    if (active) setImageUrl(null);
                }
            } catch (e) {
                ErrorService.handleError(e, { context: 'CharacterImageWidget.load', silent: true });
                if (active) {
                    // Fallback to legacy if it's a direct base64
                    if (legacyImage && !legacyImage.startsWith(GZIP_MARKER)) {
                        setImageUrl(legacyImage);
                    } else {
                        setImageUrl(null);
                    }
                }
            } finally {
                if (active) setLoading(false);
            }
        };

        load();

        return () => {
            active = false;
            // Do NOT revoke here — the image is still being displayed.
            // It will be revoked on the next successful load or on unmount below.
        };
    }, [imageId, legacyImage, onImageUpdate, onAddLog]);

    // Revoke the blob URL only when the component truly unmounts
    useEffect(() => {
        return () => {
            if (currentBlobRef.current) {
                URL.revokeObjectURL(currentBlobRef.current);
                currentBlobRef.current = null;
            }
        };
    }, []);

    const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;
        setLoading(true);
        try {
            const newId = await saveImage(file);
            onImageUpdate(newId);
            onAddLog("Image enregistrée.", 'success');
        } catch (error) {
            const message = error instanceof Error ? error.message : "Erreur de sauvegarde.";
            onAddLog(message, 'danger');
        } finally {
            setLoading(false);
            e.target.value = '';
        }
    };

    const confirmRemove = async () => {
        if (imageId) await deleteImage(imageId);
        onImageUpdate('');
        onAddLog("Image supprimée.", 'danger');
        setShowDeleteConfirm(false);
    };

    return (
        <>
            <div
                className="w-full h-full flex flex-col items-center justify-center relative group cursor-pointer bg-stone-50/30 overflow-hidden"
                onClick={() => !imageUrl && !loading && fileInputRef.current?.click()}
            >
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileChange} />
                {imageUrl ? (
                    <div className="w-full h-full p-4 flex items-center justify-center">
                        <div className="w-full h-full border-4 border-white shadow-md bg-stone-200 flex items-center justify-center overflow-hidden relative ring-1 ring-stone-300 rounded-sm">
                            <img src={imageUrl} alt="Character" className="w-full h-full object-contain" />
                            <div className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-2 backdrop-blur-[1px]">
                                <button onClick={(e) => { e.stopPropagation(); fileInputRef.current?.click(); }} className="bg-white/90 p-2 rounded-full hover:bg-blue-50 text-blue-600 transition-colors shadow-lg"><Upload size={20} /></button>
                                <button onClick={(e) => { e.stopPropagation(); setShowDeleteConfirm(true); }} className="bg-white/90 p-2 rounded-full hover:bg-red-50 text-red-600 transition-colors shadow-lg"><Trash2 size={20} /></button>
                            </div>
                        </div>
                    </div>
                ) : (
                    <div className="w-full h-full p-4 flex items-center justify-center">
                        <div className={`w-full h-full border-2 border-dashed border-stone-300 flex flex-col items-center justify-center text-stone-400 bg-white/50 hover:bg-white hover:border-blue-400 hover:text-blue-500 transition-all rounded-lg ${loading ? 'opacity-50 cursor-wait' : ''}`}>
                            {loading ? <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-stone-500 mb-2"></div> : <ImageIcon size={48} className="mb-2 opacity-50" />}
                            <span className="text-xs font-bold uppercase tracking-wider text-center px-4">{loading ? "Traitement..." : "Ajouter une image"}</span>
                        </div>
                    </div>
                )}
            </div>
            <ConfirmationModal
                isOpen={showDeleteConfirm}
                onClose={() => setShowDeleteConfirm(false)}
                onConfirm={confirmRemove}
                title="Supprimer l'image ?"
                message="Cette action est irréversible."
                confirmLabel="Supprimer"
                type="danger"
            />
        </>
    );
};

export default CharacterImageWidget;

import React from 'react';
import { SheetColumn, SkillBlock as SkillBlockType } from '../../hooks/useSheetLayout';
import { CharacterSheetData } from '../../types';
import { RulesData } from '../../types/rules';
import { ThemeConfig } from '../../types/system';
import { SkillBlock } from './SkillBlock';

interface CharacterSheetGridProps {
    columns: SheetColumn[];
    backgrounds: SkillBlockType[];
    isLandscape: boolean;
    isEditMode: boolean;
    allowExtendedSkills: boolean;
    theme?: ThemeConfig;
    rules: RulesData | null;
    specializations: CharacterSheetData['specializations'];
    imposedSpecializations: CharacterSheetData['imposedSpecializations'];
    onUpdateDot: (section: 'skills', category: string, id: string, value: number) => void;
    onDefineVariant: (category: string, id: string, skillName: string, definitionId?: string) => void;
    onDropItem: (category: string, payload: any, targetIndex?: number) => void;
    onRemoveItem: (category: string, id: string) => void;
    // For Landscape extra column
    renderExtraColumn?: () => React.ReactNode;
    // For Portrait extra sections
    renderBottomSection?: () => React.ReactNode;
    validateSkillIncrease?: (id: string, newValue: number) => { allowed: boolean; reason?: string };
    blockedSkills?: Record<string, { isBlocked: boolean, sourceName: string }>;
}

const CharacterSheetGrid: React.FC<CharacterSheetGridProps> = ({
    columns,
    backgrounds,
    isLandscape,
    isEditMode,
    allowExtendedSkills,
    theme,
    rules,
    specializations,
    imposedSpecializations,
    onUpdateDot,
    onDefineVariant,
    onDropItem,
    onRemoveItem,
    renderExtraColumn,
    renderBottomSection,
    validateSkillIncrease,
    blockedSkills = {}
}) => {

    const renderSkillBlock = (block: SkillBlockType) => (
        <SkillBlock
            key={block.cat}
            title={block.title}
            items={block.items}
            cat={block.cat}
            onUpdate={onUpdateDot}
            userSpecs={specializations}
            imposedSpecs={imposedSpecializations}
            theme={theme}
            onDefineVariant={onDefineVariant}
            allowExtendedSkills={allowExtendedSkills}
            description={block.description}
            isEditing={isEditMode}
            categoryBehavior={rules?.definitions?.skillCategories?.find(c => c.id === block.cat)?.behavior}
            onDrop={onDropItem}
            onRemove={onRemoveItem}
            validateIncrease={validateSkillIncrease}
            blockedSkills={blockedSkills}
        />
    );

    if (isLandscape) {
        return (
            <div className="flex-grow grid grid-cols-6 border-b-2 border-stone-800">
                {columns.map((col, idx) => (
                    <div key={idx} className="border-r border-stone-400 flex flex-col">
                        {col.blocks.map((block) => (
                            <div key={block.cat} className="flex-grow border-b border-stone-300 last:border-b-0">
                                {renderSkillBlock(block)}
                            </div>
                        ))}
                    </div>
                ))}

                {/* 6th Column */}
                <div className="flex flex-col h-full">
                    {backgrounds.map(renderSkillBlock)}
                    {renderExtraColumn && renderExtraColumn()}
                </div>
            </div>
        );
    }

    return (
        <>
            <div className="grid grid-cols-4 border-b-2 border-stone-800 h-auto">
                {columns.map((col, idx) => (
                    <div key={idx} className={idx < 3 ? "border-r border-stone-400" : ""}>
                        {col.topBlocks.map(renderSkillBlock)}
                    </div>
                ))}
            </div>

            <div className="grid grid-cols-4 border-b-2 border-stone-800 flex-grow min-h-[200px]">
                {columns.map((col, idx) => (
                    <div key={idx} className={idx < 3 ? "border-r border-stone-400" : ""}>
                        {col.bottomBlocks.map(renderSkillBlock)}
                        {idx === 3 && backgrounds.map(renderSkillBlock)}
                    </div>
                ))}
            </div>

            {renderBottomSection && renderBottomSection()}
        </>
    );
};

export default CharacterSheetGrid;

import React, { useState, useRef, useEffect } from 'react';
import { CharacterSheetData, DotEntry } from '../../types';
import DotRating from '../ui/DotRating';
import { SectionHeader } from './Shared';
import { useRules } from '../../context/RulesContext';
import { normalizeString } from '../../utils/stringUtils';
import { evaluateFormula, getSheetVariables, getAggregateDetails } from '../../utils/formulaEvaluator';
import { Minus, Plus, RefreshCw } from 'lucide-react';
import { Parser, Tokenizer } from 'safe-expr-eval';
import { PortalTooltip } from '../ui/PortalTooltip';

const parser = new Parser();

const getExpressionVariables = (formula: string): string[] => {
    try {
        const tokenizer = new Tokenizer(formula);
        const tokens = tokenizer.tokenize();
        return Array.from(new Set(
            tokens
                .filter(t => t.type === 'IDENTIFIER')
                .map(t => String(t.value))
                .filter(v => v !== 'true' && v !== 'false')
        ));
    } catch {
        return [];
    }
};

interface NumericCounterItemProps {
    counter: DotEntry;
    entryOrFormula: any;
    isCustom: boolean;
    data: CharacterSheetData;
    rules: any;
    calculatedMaxes: Record<string, number>;
    updateCounter: (id: string, value: number, isCustom: boolean, field: 'value' | 'current') => void;
}

const translateAggregateConfig = (config: any): string => {
    if (!config) return '';
    let target = config.targetType || config.target || '';
    switch (target) {
        case 'skills': target = 'Compétences'; break;
        case 'attributes': target = 'Attributs'; break;
        case 'secondaryAttributes': target = 'Attributs Sec.'; break;
        case 'traits': target = 'Traits'; break;
        case 'mysticAbilities': target = 'Cap. Mystiques'; break;
    }

    let op = config.operation?.toLowerCase() || '';
    switch (op) {
        case 'sum': op = 'Somme'; break;
        case 'count': op = 'Nombre'; break;
        case 'max':
        case 'highest': op = 'Maximum'; break;
        case 'avg':
        case 'average': op = 'Moyenne'; break;
    }

    let filter = '';
    if (config.filterTarget && config.filterValue) {
        const typeF = config.filterTarget === 'tag' ? 'Tag' : config.filterTarget === 'category' ? 'Catégorie' : 'Nom';
        filter = ` (${typeF}: ${config.filterValue})`;
    }

    return `${op} de : ${target}${filter}`;
};

const translateVariableName = (v: string): string => {
    switch (v) {
        case 'SUM_HABILITES_MYSTIQUES': return 'Somme Cap. Mystiques';
        case 'SCENARIOS_COUNT': return 'Nombre de Scénarios';
        case 'TRAIT_LEVEL': return 'Niveau de Trait';
        default: return v;
    }
};

const NumericCounterItem: React.FC<NumericCounterItemProps> = ({
    counter,
    entryOrFormula,
    isCustom,
    data,
    rules,
    calculatedMaxes,
    updateCounter
}) => {
    const [isOpen, setIsOpen] = useState(false);
    const anchorRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (anchorRef.current && !anchorRef.current.contains(event.target as Node)) {
                setIsOpen(false);
            }
        };

        if (isOpen) {
            document.addEventListener('mousedown', handleClickOutside);
        }
        return () => {
            document.removeEventListener('mousedown', handleClickOutside);
        };
    }, [isOpen]);

    const normalizedName = normalizeString(counter.name);
    const nameKey = normalizedName.replace(/\s+/g, '');
    const calculatedMax = calculatedMaxes[counter.name] || calculatedMaxes[normalizedName] || calculatedMaxes[nameKey];

    // Metadata recovery: if entryOrFormula is a "dumb" character entry, 
    // try to find the full definition in the rules libraries.
    const globalDef = rules?.libraries?.counters?.find((l: any) => normalizeString(l.name) === normalizedName)
        || Object.values(rules?.definitions?.counters || {}).find((c: any) => normalizeString(c.name) === normalizedName);

    const effectiveEntryOrFormula = { ...globalDef, ...entryOrFormula };

    const resolvedFormula = !effectiveEntryOrFormula.formula && effectiveEntryOrFormula.formulaId
        ? rules?.libraries?.formulas?.find((f: any) => f.id === effectiveEntryOrFormula.formulaId)
        : null;

    const formula = effectiveEntryOrFormula.formula || resolvedFormula?.formula || '';
    const aggregateConfig = effectiveEntryOrFormula.aggregateConfig || resolvedFormula?.aggregateConfig;
    const effectiveEntry = resolvedFormula ? { ...effectiveEntryOrFormula, ...resolvedFormula } : effectiveEntryOrFormula;

    const computedMax = calculatedMax ?? evaluateFormula(
        formula,
        { ...data, formulaLibrary: rules?.libraries?.formulas || data.formulaLibrary },
        aggregateConfig ? { ...effectiveEntry, aggregateConfig } : undefined
    );

    const currentSpent = counter.current || 0;
    const currentRemaining = Math.max(0, computedMax - currentSpent);

    const renderDetails = () => {
        if (!isOpen) return null;

        if (aggregateConfig) {
            const details = getAggregateDetails({ ...data, formulaLibrary: rules?.libraries?.formulas || data.formulaLibrary }, aggregateConfig);
            const translatedDesc = translateAggregateConfig(aggregateConfig);

            if (!details.length) {
                return (
                    <div className="flex flex-col gap-1 w-full min-w-[140px]">
                        <div className="text-slate-400 italic text-[9px] mb-1">{translatedDesc}</div>
                        <div className="text-stone-400 italic text-xs">Aucun élément correspondant</div>
                    </div>
                );
            }

            return (
                <div className="flex flex-col gap-1 w-full min-w-[280px]">
                    <div className="text-amber-200/80 italic text-sm border-b border-slate-600/50 pb-1 mb-2 leading-tight">
                        {translatedDesc}
                    </div>
                    <div className="columns-2 gap-x-6">
                        {details.map((d, i) => (
                            <div key={i} className="flex justify-between items-center text-sm mb-0.5 break-inside-avoid px-2">
                                <span className="text-slate-300 truncate font-medium flex-1 mr-2" title={d.name}>{d.name || d.category || 'Inconnu'}</span>
                                <span className="font-mono text-white text-right shrink-0">{d.value >= 0 ? `+${d.value}` : d.value}</span>
                            </div>
                        ))}
                    </div>
                    <div className="border-t border-slate-600 mt-1 pt-2 flex justify-between items-center font-bold text-base">
                        <span className="text-slate-200">TOTAL</span>
                        <span className="font-mono text-amber-400">{computedMax}</span>
                    </div>
                </div>
            );
        } else if (formula) {
            const sheetVars = getSheetVariables({ ...data, formulaLibrary: rules?.libraries?.formulas || data.formulaLibrary });
            let parsedVars: string[] = [];
            let baseValue = 0;
            try {
                const expr = parser.parse(formula);
                parsedVars = getExpressionVariables(formula);
                const zeroContext: Record<string, number> = parsedVars.reduce((acc, v: string) => ({ ...acc, [v]: 0 }), {});
                baseValue = Number(expr.evaluate(zeroContext)) || 0;
            } catch (e) {
                // Ignore parse errors for UI
            }

            return (
                <div className="flex flex-col gap-1 w-[460px] max-w-[95vw]">
                    {baseValue !== 0 && (
                        <div className="flex justify-between items-center text-sm border-b border-slate-600/50 pb-2 mb-2 px-2">
                            <span className="text-slate-400 italic">Base</span>
                            <span className="font-mono text-slate-400 shrink-0">{baseValue >= 0 ? `+${baseValue}` : baseValue}</span>
                        </div>
                    )}
                    <div className="columns-2 gap-x-6">
                        {parsedVars.map(v => {
                            const val = sheetVars[v] || 0;
                            // Essayer de trouver le nom humain dans la bibliothèque de formules
                            const formulaEntry = rules?.libraries?.formulas?.find((f: any) =>
                                f.code === v || f.id === v || normalizeString(f.name) === normalizeString(v)
                            );
                            const displayName = formulaEntry?.name || translateVariableName(v);

                            const hasAggregateDetails = formulaEntry?.aggregateConfig && val !== 0;
                            const aggDetails = hasAggregateDetails
                                ? getAggregateDetails({ ...data, formulaLibrary: rules?.libraries?.formulas || data.formulaLibrary }, formulaEntry.aggregateConfig)
                                : [];

                            return (
                                <div key={v} className="flex flex-col mb-3">
                                    <div className="flex justify-between items-center text-sm pb-1 break-after-avoid px-2">
                                        <span className="text-slate-200 truncate font-semibold flex-1 mr-2" title={displayName}>{displayName}</span>
                                        <span className="font-mono text-white text-right shrink-0">{val >= 0 ? `+${val}` : val}</span>
                                    </div>
                                    {aggDetails.length > 0 && (
                                        <div className="pl-3 flex flex-col gap-1 border-l-2 border-slate-600/80 mb-1 ml-2 mt-1">
                                            {aggDetails.map((d, i) => (
                                                <div key={i} className="flex justify-between items-center text-xs opacity-90 break-inside-avoid pr-2">
                                                    <span className="truncate flex-1 text-slate-400 mr-2" title={d.name || d.category || 'Inconnu'}>{d.name || d.category || 'Inconnu'}</span>
                                                    <span className="font-mono text-slate-300 shrink-0">{d.value >= 0 ? `+${d.value}` : d.value}</span>
                                                </div>
                                            ))}
                                        </div>
                                    )}
                                </div>
                            );
                        })}
                    </div>
                    <div className="border-t border-slate-600 mt-2 pt-2 flex justify-between items-center font-bold text-base">
                        <span className="text-slate-200">TOTAL</span>
                        <span className="font-mono text-amber-400">{computedMax}</span>
                    </div>
                </div>
            );
        }

        return <div className="text-stone-400 italic">Valeur de base : {computedMax}</div>;
    };

    return (
        <div className="col-span-1 border border-[#bfae85]/40 bg-gradient-to-br from-[#fdfbf7] to-[#f4f2eb] rounded-sm shadow-[inset_0_1px_4px_rgba(0,0,0,0.05)] flex items-center justify-between px-1 overflow-visible h-9 group transition-all relative">
            <div
                className="flex flex-col items-start justify-center flex-grow cursor-help h-full w-full"
                ref={anchorRef}
                onClick={() => setIsOpen(!isOpen)}
            >
                <span className="font-bold text-[9px] uppercase tracking-tighter text-[#8b2e2e]/90 leading-tight truncate w-full">
                    {counter.name}
                </span>
                <span className="font-black text-sm text-[#5c4d41] leading-none mb-[1px]">
                    {currentRemaining} <span className="text-[10px] text-stone-400 font-normal">/ {computedMax}</span>
                </span>
            </div>

            <PortalTooltip isOpen={isOpen} anchorRef={anchorRef} title={`${counter.name} (Calcul)`} maxWidth={540}>
                {renderDetails()}
            </PortalTooltip>

            <div className={`flex flex-shrink-0 items-center justify-end transition-opacity z-10 bg-gradient-to-l from-[#f4f2eb] from-80% to-transparent pl-4 h-full absolute right-0 ${isOpen ? 'opacity-0 pointer-events-none' : 'opacity-100 md:opacity-0 md:group-hover:opacity-100'}`}>
                <button onClick={() => updateCounter(counter.id, 0, isCustom, 'current')} className="w-5 h-5 mr-0.5 rounded hover:bg-stone-200 flex items-center justify-center text-stone-500 transition-colors" title="Restaurer (Reset dépense)">
                    <RefreshCw size={11} />
                </button>
                <button onClick={() => updateCounter(counter.id, Math.min(computedMax, currentSpent + 1), isCustom, 'current')} className="w-5 h-5 mr-0.5 rounded hover:bg-[#8b2e2e]/10 flex items-center justify-center text-[#8b2e2e] transition-colors" title="Dépenser 1 (Baisse la jauge)">
                    <Minus size={14} />
                </button>
                <button onClick={() => updateCounter(counter.id, Math.max(0, currentSpent - 1), isCustom, 'current')} className="w-5 h-5 rounded hover:bg-amber-600/10 flex items-center justify-center text-amber-600 transition-colors" title="Récupérer 1 (Remonte la jauge)">
                    <Plus size={14} />
                </button>
            </div>
        </div>
    );
};

interface CountersSectionProps {
    data: CharacterSheetData;
    updateCounter: (id: string, value: number, isCustom: boolean, field: 'value' | 'current') => void;
    isLandscape: boolean;
    creationBonuses?: Record<string, number>;
    xpBonuses?: Record<string, number>;
    calculatedMaxes?: Record<string, number>;
    activeReserves?: string[];
}

export const CountersSection = React.memo<CountersSectionProps>(({
    data,
    updateCounter,
    isLandscape,
    creationBonuses = {},
    xpBonuses = {},
    calculatedMaxes = {},
    activeReserves = []
}) => {
    const { rules } = useRules();

    const renderCounterItem = (counter: DotEntry, isCustom: boolean) => {
        const isSquaresOnly = counter.variant === 'squares_only';
        const normalizedName = normalizeString(counter.name);
        const nameKey = normalizedName.replace(/\s+/g, '');
        const libEntry = data.counterLibrary?.find(l => normalizeString(l.name) === normalizedName)
            || rules?.libraries?.counters?.find((l: any) => normalizeString(l.name) === normalizedName);
        const sysDef = rules?.definitions?.counters?.[nameKey] || Object.values(rules?.definitions?.counters || {}).find(c => normalizeString(c.name) === normalizedName);
        const isNumeric = libEntry?.isNumeric || libEntry?.formulaId || sysDef?.formulaId || sysDef?.isNumeric;
        if (isNumeric) {
            return (
                <NumericCounterItem
                    key={counter.id}
                    counter={counter}
                    entryOrFormula={libEntry || sysDef}
                    isCustom={isCustom}
                    data={data}
                    rules={rules}
                    calculatedMaxes={calculatedMaxes}
                    updateCounter={updateCounter}
                />
            );
        }

        const creationBonus = creationBonuses[nameKey] || 0;
        const xpBonus = xpBonuses[nameKey] || 0;
        const calculatedMax = calculatedMaxes[counter.name] || calculatedMaxes[nameKey];

        const effectiveValue = counter.value + creationBonus + xpBonus;
        const effectiveCreationValue = (counter.creationValue || 0) + creationBonus;
        const effectiveMax = calculatedMax ?? (counter.max || 10);

        return (
            <div key={counter.id} className="col-span-2 border border-stone-300 bg-white rounded-sm shadow-sm flex items-center p-1 overflow-hidden h-9">
                <div
                    className="w-16 shrink-0 font-bold text-[8px] leading-tight uppercase tracking-tighter text-stone-800 border-r border-stone-200 mr-1 pr-1 h-full flex items-center justify-center text-center cursor-help"
                    title={counter.description || counter.name}
                >
                    {counter.name}
                </div>

                <div className="flex flex-col gap-0.5 flex-grow justify-center items-end pr-1 overflow-hidden">
                    {!isSquaresOnly && (
                        <div className="flex items-center h-3.5">
                            <div className="scale-[0.85] origin-right">
                                <DotRating
                                    value={effectiveValue}
                                    creationValue={effectiveCreationValue}
                                    max={effectiveMax}
                                    onChange={(v) => {
                                        const newBaseValue = Math.max(0, v - creationBonus - xpBonus);
                                        updateCounter(counter.id, newBaseValue, isCustom, 'value');
                                    }}
                                    creationColor={data.theme?.creationColor}
                                    xpColor={data.theme?.xpColor}
                                    symbol={data.theme?.dotSymbol}
                                />
                            </div>
                        </div>
                    )}

                    <div className="flex items-center h-3.5">
                        <div className="scale-[0.85] origin-right flex items-center space-x-1">
                            {Array.from({ length: effectiveMax }).map((_, i) => {
                                if (i >= effectiveMax) return null;
                                if (!isSquaresOnly && i >= effectiveValue) {
                                    return <div key={i} className="w-3 h-3" />;
                                }
                                const isChecked = i < (counter.current || 0);
                                return (
                                    <button
                                        key={i}
                                        type="button"
                                        onClick={() => {
                                            const newVal = i + 1;
                                            const currentVal = counter.current || 0;
                                            updateCounter(counter.id, newVal === currentVal ? newVal - 1 : newVal, isCustom, 'current');
                                        }}
                                        className={`w-3 h-3 border border-stone-600 transition-colors ${isChecked ? 'bg-ink' : 'bg-white hover:bg-stone-100'}`}
                                        title="Point utilisé"
                                    />
                                );
                            })}
                        </div>
                    </div>
                </div>
            </div >
        );
    };

    const counterCat = rules?.definitions?.skillCategories?.find((c: any) => c.behavior === 'Compteur');
    const sortedIds = counterCat ? (rules?.definitions?.skills?.[counterCat.id] || []) : [];
    const allKeys = Object.keys(data.counters).filter(k => k !== 'custom');
    const customCounters = data.counters.custom || [];

    const orderedKeys: string[] = [];
    const remainingKeys = new Set(allKeys);

    sortedIds.forEach((idOrName: string) => {
        const matchedKey = Array.from(remainingKeys).find(key => {
            if (key === idOrName) return true;
            const counterData = data.counters[key];
            if (counterData && !Array.isArray(counterData) && counterData.name === idOrName) return true;
            const sysDef = rules?.definitions?.counters?.[key];
            if (sysDef?.name === idOrName) return true;
            return false;
        });
        if (matchedKey) {
            orderedKeys.push(matchedKey);
            remainingKeys.delete(matchedKey);
        }
    });

    const numericItems: React.ReactNode[] = [];
    const standardItems: React.ReactNode[] = [];

    orderedKeys.forEach(key => {
        const counter = data.counters[key];
        if (Array.isArray(counter)) return;
        const normalizedName = normalizeString(counter.name);
        const nameKey = normalizedName.replace(/\s+/g, '');
        const libEntry = data.counterLibrary?.find(l => normalizeString(l.name) === normalizedName)
            || rules?.libraries?.counters?.find((l: any) => normalizeString(l.name) === normalizedName);
        const sysDef = rules?.definitions?.counters?.[nameKey] || Object.values(rules?.definitions?.counters || {}).find(c => normalizeString(c.name) === normalizedName);
        const isNumeric = libEntry?.isNumeric || libEntry?.formulaId || sysDef?.formulaId || sysDef?.isNumeric;
        if (isNumeric) {
            numericItems.push(
                <NumericCounterItem
                    key={`numeric-${counter.id}`}
                    counter={counter}
                    entryOrFormula={libEntry || sysDef}
                    isCustom={false}
                    data={data}
                    rules={rules}
                    calculatedMaxes={calculatedMaxes}
                    updateCounter={updateCounter}
                />
            );
        } else {
            standardItems.push(renderCounterItem(counter, false));
        }
    });

    customCounters
        .filter(c => c.name?.trim())
        .forEach(c => {
            const nameKey = normalizeString(c.name);
            const libEntry = data.counterLibrary?.find(l => normalizeString(l.name) === nameKey)
                || rules?.libraries?.counters?.find((l: any) => normalizeString(l.name) === nameKey);
            const sysDef = rules?.definitions?.counters?.[nameKey];
            const isNumeric = libEntry?.isNumeric || libEntry?.formulaId || sysDef?.formulaId || sysDef?.isNumeric;
            if (isNumeric) {
                numericItems.push(
                    <NumericCounterItem
                        key={`custom-numeric-${c.id}`}
                        counter={c}
                        entryOrFormula={libEntry || sysDef}
                        isCustom={true}
                        data={data}
                        rules={rules}
                        calculatedMaxes={calculatedMaxes}
                        updateCounter={updateCounter}
                    />
                );
            } else {
                standardItems.push(renderCounterItem(c, true));
            }
        });

    activeReserves.forEach(formulaId => {
        const formulaEntry = rules?.libraries?.formulas?.find(f => f.id === formulaId);
        if (!formulaEntry) return;
        const existingCustom = customCounters.find(c => normalizeString(c.name) === normalizeString(formulaEntry.name));
        const counterToRender: DotEntry = existingCustom || {
            id: formulaId,
            name: formulaEntry.name,
            value: 0,
            creationValue: 0,
            current: 0,
            max: 0,
            description: formulaEntry.description
        };
        numericItems.push(
            <NumericCounterItem
                key={`reserve-${counterToRender.id}`}
                counter={counterToRender}
                entryOrFormula={formulaEntry}
                isCustom={true}
                data={data}
                rules={rules}
                calculatedMaxes={calculatedMaxes}
                updateCounter={updateCounter}
            />
        );
    });

    return (
        <div className="flex flex-col h-full border-l border-stone-400">
            <SectionHeader title="Compteurs & Réserves" />
            <div className="p-1 flex-grow overflow-y-auto bg-stone-50/30">
                <div className="grid grid-cols-4 gap-1">
                    {standardItems}
                    {numericItems}
                </div>
            </div>
        </div>
    );
});

import React, { useState, useMemo } from 'react';
import { useCharacterData, useCharacterActions } from '../../context/CharacterContext';
import { useRules } from '../../context/RulesContext';
import {
    BookOpen,
    GripVertical,
    Plus,
    Search,
    X,
    Target,
    Sparkles,
    Layers,
    Globe
} from 'lucide-react';
import { LibrarySkillEntry, DotEntry } from '../../types';

interface EditionSidebarProps {
    onClose: () => void;
}

const EditionSidebar: React.FC<EditionSidebarProps> = ({ onClose }) => {
    const { rules } = useRules();
    const data = useCharacterData();
    const { updateData: _updateData } = useCharacterActions();

    const [activeTab, setActiveTab] = useState<'skills' | 'backgrounds'>('skills');
    const [searchTerm, setSearchTerm] = useState('');
    const [customName, setCustomName] = useState('');

    // Get all currently placed items (skills and backgrounds)
    const currentItemNames = useMemo(() => {
        const names = new Set<string>();
        Object.values(data.skills).forEach((categorySkills: DotEntry[]) => {
            categorySkills.forEach((skill: DotEntry) => {
                if (skill.name) names.add(skill.name.trim().toLowerCase());
            });
        });
        return names;
    }, [data.skills]);

    // Filter available items from libraries
    const availableItems = useMemo(() => {
        const library = activeTab === 'skills' ? (rules?.libraries?.skills || []) : (rules?.libraries?.backgrounds || []);
        return library.filter((item: LibrarySkillEntry) => {
            if (item.isActive === false) return false;

            const matchesSearch = item.name.toLowerCase().includes(searchTerm.toLowerCase());
            const isAlreadyOnSheet = !item.isVariable && currentItemNames.has(item.name.trim().toLowerCase());

            return matchesSearch && !isAlreadyOnSheet;
        });
    }, [activeTab, rules?.libraries?.skills, rules?.libraries?.backgrounds, searchTerm, currentItemNames]); // Updated dependency array

    const handleDragStart = (e: React.DragEvent, item: LibrarySkillEntry) => {
        const payload = {
            type: 'lib_skill',
            data: item,
            origin: 'sidebar'
        };
        e.dataTransfer.setData('application/json', JSON.stringify(payload));
        e.dataTransfer.effectAllowed = 'copy';
    };

    return (
        <div className="fixed right-0 top-0 bottom-0 w-80 bg-slate-900/95 backdrop-blur-md border-l border-[#bfae85]/30 shadow-2xl z-[1000] flex flex-col animate-in slide-in-from-right duration-300">
            {/* Header */}
            <div className="p-4 border-b border-[#bfae85]/20 flex items-center justify-between bg-slate-800/50">
                <div className="flex items-center gap-2 text-[#bfae85]">
                    <BookOpen size={20} />
                    <h2 className="font-bold uppercase tracking-wider text-sm">Édition Directe</h2>
                </div>
                <button
                    onClick={onClose}
                    className="p-1 hover:bg-white/10 rounded-full transition-colors text-slate-400 hover:text-white"
                >
                    <X size={20} />
                </button>
            </div>

            {/* Tabs */}
            <div className="flex border-b border-[#bfae85]/10">
                <button
                    onClick={() => setActiveTab('skills')}
                    className={`flex-1 py-3 text-xs font-bold uppercase tracking-widest transition-all ${activeTab === 'skills'
                        ? 'text-[#bfae85] border-b-2 border-[#bfae85] bg-[#bfae85]/5'
                        : 'text-slate-500 hover:text-slate-300'
                        }`}
                >
                    Compétences
                </button>
                <button
                    onClick={() => setActiveTab('backgrounds')}
                    className={`flex-1 py-3 text-xs font-bold uppercase tracking-widest transition-all ${activeTab === 'backgrounds'
                        ? 'text-[#bfae85] border-b-2 border-[#bfae85] bg-[#bfae85]/5'
                        : 'text-slate-500 hover:text-slate-300'
                        }`}
                >
                    Historiques
                </button>
            </div>

            {/* Search & Custom */}
            <div className="p-3 space-y-3 bg-slate-800/30">
                <div className="relative">
                    <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500" />
                    <input
                        type="text"
                        placeholder="Rechercher..."
                        className="w-full bg-slate-950/50 border border-slate-700 rounded-md py-2 pl-9 pr-9 text-sm text-slate-200 placeholder:text-slate-600 focus:outline-none focus:border-[#bfae85]/50 transition-colors"
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                    />
                    {searchTerm && (
                        <button
                            onClick={() => setSearchTerm('')}
                            className="absolute right-2 top-1/2 -translate-y-1/2 text-slate-500 hover:text-amber-500 transition-colors"
                        >
                            <X size={14} />
                        </button>
                    )}
                </div>

                <div className="flex gap-2">
                    <input
                        type="text"
                        placeholder={activeTab === 'skills' ? "Nouvelle compétence..." : "Nouvel historique..."}
                        className="flex-1 bg-slate-950/50 border border-slate-700 rounded-md py-2 px-3 text-sm text-slate-200 placeholder:text-slate-600 focus:outline-none focus:border-green-500/50 transition-colors"
                        value={customName}
                        onChange={(e) => setCustomName(e.target.value)}
                    />
                    <div
                        draggable={!!customName.trim()}
                        onDragStart={(e) => {
                            if (!customName.trim()) return;
                            const item: LibrarySkillEntry = {
                                id: `custom-${Date.now()}`,
                                name: customName.trim(),
                                description: 'Élément personnalisé',
                                isGlobal: false,
                                isActive: true
                            };
                            const payload = {
                                type: 'custom_lib_item',
                                data: item,
                                categoryType: activeTab === 'skills' ? 'skill' : 'background'
                            };
                            e.dataTransfer.setData('application/json', JSON.stringify(payload));
                        }}
                        title={customName.trim() ? "Glissez pour ajouter" : "Entrez un nom"}
                        className={`p-2 rounded-md flex items-center justify-center transition-all ${customName.trim()
                            ? 'bg-green-600/20 text-green-400 border border-green-500/30 cursor-grab active:cursor-grabbing hover:bg-green-600/30'
                            : 'bg-slate-800 text-slate-600 border border-slate-700 cursor-not-allowed'
                            }`}
                    >
                        <Plus size={18} />
                    </div>
                    <div
                        draggable
                        onDragStart={(e) => {
                            const payload = {
                                type: 'spacer',
                                data: { name: '', id: `spacer-${Date.now()}` },
                                categoryType: activeTab === 'skills' ? 'skill' : 'background'
                            };
                            e.dataTransfer.setData('application/json', JSON.stringify(payload));
                        }}
                        title="Glissez un espaceur vide"
                        className="p-2 rounded-md flex items-center justify-center transition-all bg-slate-700 text-slate-300 border border-slate-600 cursor-grab active:cursor-grabbing hover:bg-slate-600 hover:text-white"
                    >
                        <X size={18} className="rotate-45" />
                    </div>
                </div>
                {customName.trim() && (
                    <p className="text-[10px] text-green-500/70 italic animate-pulse px-1">
                        Glissez le bouton [+] vers une case vide
                    </p>
                )}
            </div>

            {/* List */}
            <div className="flex-1 overflow-y-auto p-3 space-y-2 custom-scrollbar">
                {availableItems.length === 0 ? (
                    <div className="text-center py-10">
                        <Target size={32} className="mx-auto text-slate-700 mb-2 opacity-50" />
                        <p className="text-sm text-slate-500 italic">Aucun résultat</p>
                    </div>
                ) : (
                    availableItems.map((item: LibrarySkillEntry) => (
                        <div
                            key={item.id}
                            draggable
                            onDragStart={(e) => handleDragStart(e, item)}
                            className="group bg-slate-800/40 border border-slate-700/50 rounded-md p-3 cursor-grab active:cursor-grabbing hover:border-[#bfae85]/40 hover:bg-slate-800/80 transition-all flex items-center justify-between"
                        >
                            <div className="flex items-center gap-3 overflow-hidden">
                                <GripVertical size={14} className="text-slate-600 shrink-0 group-hover:text-[#bfae85]/60 transition-colors" />
                                <div className="flex flex-col min-w-0">
                                    <span className="text-sm font-medium text-slate-200 truncate group-hover:text-white transition-colors">
                                        {item.name}
                                    </span>
                                    <div className="flex items-center gap-1.5 min-w-0 mt-0.5">
                                        {(item.isVariable || item.mysticAbilityId || item.isGlobal) && (
                                            <div className="flex items-center gap-1 shrink-0">
                                                {item.isVariable && (
                                                    <span title="Variations">
                                                        <Layers size={10} className="text-blue-400" />
                                                    </span>
                                                )}
                                                {item.mysticAbilityId && (
                                                    <span title="Mystique">
                                                        <Sparkles size={10} className="text-amber-400" />
                                                    </span>
                                                )}
                                                {item.isGlobal && (
                                                    <span title="Officiel">
                                                        <Globe size={10} className="text-indigo-400" />
                                                    </span>
                                                )}
                                            </div>
                                        )}
                                        {item.description && (
                                            <p className="text-[9px] text-slate-500 italic truncate opacity-70 group-hover:opacity-100 transition-opacity">
                                                {item.description}
                                            </p>
                                        )}
                                    </div>
                                </div>
                            </div>
                            <Plus size={14} className="text-slate-600 group-hover:text-[#bfae85] opacity-0 group-hover:opacity-100 transition-all" />
                        </div>
                    ))
                )}
            </div>

            {/* Footer Info */}
            <div className="p-3 bg-slate-800/50 border-t border-[#bfae85]/10 text-[10px] text-slate-500 leading-relaxed italic">
                Faites glisser les éléments vers les zones en surbrillance sur votre fiche.
            </div>
        </div>
    );
};

export default EditionSidebar;

import React from 'react';
import { UserPlus, PencilLine, Check } from 'lucide-react';
import { HeaderInput } from './Shared';

interface SheetHeaderProps {
    headerData: {
        name: string;
        player: string;
        chronicle: string;
        nature: string;
        conduct: string;
        status: string;
        age: string;
        sex: string;
        born: string;
        height: string;
        hair: string;
        eyes: string;
        campaignStartDate?: string;
        fictionCurrentDate?: string;
    };
    creationActive: boolean;
    onUpdateHeader: (field: any, value: string) => void;
    onToggleCreationMode: () => void;
    editModeActive: boolean;
    onToggleEditMode: () => void;
    isDateLocked?: boolean;
}

const SheetHeader: React.FC<SheetHeaderProps> = ({
    headerData,
    creationActive,
    onUpdateHeader,
    onToggleCreationMode,
    editModeActive,
    onToggleEditMode,
    isDateLocked = false
}) => {
    // Helper pour parser les dates de manière flexible (FR, ISO, ou Fictif)
    const parseFlexibleDate = (dateStr: string) => {
        if (!dateStr) return null;
        const trimmed = dateStr.trim();

        // 1. Format français : DD/MM/YYYY
        const frMatch = trimmed.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4,})$/);
        if (frMatch) {
            return { day: parseInt(frMatch[1]), month: parseInt(frMatch[2]), year: parseInt(frMatch[3]), type: 'standard' };
        }

        // 2. Format ISO : YYYY-MM-DD
        const isoMatch = trimmed.match(/^(\d{4,})-(\d{1,2})-(\d{1,2})$/);
        if (isoMatch) {
            return { year: parseInt(isoMatch[1]), month: parseInt(isoMatch[2]), day: parseInt(isoMatch[3]), type: 'standard' };
        }

        // 3. Format Fictif : "Jour Mois Année" (on prend le dernier nombre comme année)
        const yearMatch = trimmed.match(/(-?\d+)$/);
        if (yearMatch) {
            const year = parseInt(yearMatch[1]);
            const dayMatch = trimmed.match(/^(\d+)/);
            return { year, month: 1, day: dayMatch ? parseInt(dayMatch[1]) : 1, type: 'fictional' };
        }

        return null;
    };

    // Calcul automatique de l'âge
    const calculatedAge = React.useMemo(() => {
        if (!headerData.born || !headerData.fictionCurrentDate) return null;

        const birth = parseFlexibleDate(headerData.born);
        const current = parseFlexibleDate(headerData.fictionCurrentDate);

        if (!birth || !current) return null;

        // Calcul simplifié basé sur l'année
        let age = current.year - birth.year;

        // Si on a des infos de mois/jour pour les deux, on affine pour le calendrier standard
        if (birth.type === 'standard' && current.type === 'standard') {
            if (current.month < birth.month || (current.month === birth.month && current.day < birth.day)) {
                age--;
            }
        }

        return age >= 0 ? age.toString() : "0";
    }, [headerData.born, headerData.fictionCurrentDate]);

    // Effet pour mettre à jour l'âge dans les données si calculé
    React.useEffect(() => {
        if (calculatedAge !== null && calculatedAge !== headerData.age) {
            onUpdateHeader('age', calculatedAge);
        }
    }, [calculatedAge, headerData.age, onUpdateHeader]);

    const lockTitle = "Champ verrouillé (géré par le calendrier de la campagne)";

    return (
        <>
            {/* Main Title */}
            <div className="py-3 border-b-2 border-stone-800 bg-white relative flex justify-center items-center">
                <h1 className="text-2xl sm:text-3xl md:text-4xl font-black text-center uppercase tracking-[0.1em] sm:tracking-[0.2em] text-indigo-950 font-serif px-4">
                    Seigneurs des Mystères
                </h1>
                {/* Action Buttons */}
                <div className="absolute right-4 top-1/2 -translate-y-1/2 flex flex-col items-end gap-1 no-print">
                    {!editModeActive && (
                        <button
                            onClick={onToggleCreationMode}
                            className={`flex items-center gap-2 px-3 py-1 rounded-full text-[10px] font-bold transition-all shadow-sm ${creationActive
                                ? 'bg-green-100 text-green-700 border border-green-300'
                                : 'bg-stone-100 text-stone-500 border border-stone-300 hover:bg-stone-200'
                                }`}
                            title={creationActive ? "Désactiver le Mode Création" : "Activer le Mode Création (Réinitialise la fiche !)"}
                        >
                            <UserPlus size={14} />
                            <span>Creation</span>
                            <div className={`w-1.5 h-1.5 rounded-full ${creationActive ? 'bg-green-500 animate-pulse' : 'bg-stone-300'}`} />
                        </button>
                    )}

                    <button
                        onClick={onToggleEditMode}
                        className={`flex items-center gap-2 px-3 py-1 rounded-full text-[10px] font-bold transition-all shadow-sm ${editModeActive
                            ? 'bg-amber-100 text-amber-700 border border-amber-300'
                            : 'bg-stone-100 text-stone-500 border border-stone-300 hover:bg-stone-200'
                            }`}
                        title={editModeActive ? "Valider les modifications" : "Mode Édition (Ajout/Déplacement de compétences)"}
                    >
                        {editModeActive ? <Check size={14} /> : <PencilLine size={14} />}
                        <span>{editModeActive ? 'Édition' : 'Éditer'}</span>
                        <div className={`w-1.5 h-1.5 rounded-full ${editModeActive ? 'bg-amber-500 animate-pulse' : 'bg-stone-300'}`} />
                    </button>
                </div>
            </div>

            {/* Revised 2-Line Header Layout */}
            <div className="flex flex-col border-b-2 border-stone-800 text-xs">
                {/* Row 1: Identity & Campaign Start */}
                <div className="flex border-b border-stone-400 h-10 bg-white">
                    <HeaderInput label="Nom" value={headerData.name} onChange={(v) => onUpdateHeader('name', v)} className="flex-grow-[1.5] border-r border-stone-300" />
                    <HeaderInput label="Joueur" value={headerData.player} onChange={(v) => onUpdateHeader('player', v)} className="flex-grow border-r border-stone-300" />
                    <HeaderInput label="Chronique" value={headerData.chronicle} onChange={(v) => onUpdateHeader('chronicle', v)} className="flex-grow border-r border-stone-300" />
                    <HeaderInput label="Nature" value={headerData.nature} onChange={(v) => onUpdateHeader('nature', v)} className="flex-grow border-r border-stone-300" />
                    <HeaderInput label="Conduite" value={headerData.conduct} onChange={(v) => onUpdateHeader('conduct', v)} className="flex-grow border-r border-stone-300" />
                    <HeaderInput label="Statut" value={headerData.status} onChange={(v) => onUpdateHeader('status', v)} className="flex-grow border-r border-stone-300" />
                    <HeaderInput
                        label="Début"
                        value={headerData.campaignStartDate || ''}
                        onChange={(v) => onUpdateHeader('campaignStartDate', v)}
                        className={`flex-grow ${isDateLocked ? 'bg-stone-50' : ''}`}
                        readOnly={isDateLocked}
                        title={isDateLocked ? lockTitle : ""}
                    />
                </div>

                {/* Row 2: Physical / Dates / Details */}
                <div className="flex h-10 bg-white">
                    <div className={`flex items-baseline px-2 py-0.5 h-full w-[8%] border-r border-stone-300 ${calculatedAge !== null ? 'bg-amber-50/30' : ''}`}>
                        <span className="text-[10px] font-bold mr-1 whitespace-nowrap uppercase text-stone-500 tracking-wider shrink-0 leading-none">Age :</span>
                        <input
                            className={`sheet-input text-sm w-full min-w-0 ${calculatedAge !== null ? 'font-bold text-amber-800' : ''}`}
                            value={headerData.age}
                            onChange={(e) => calculatedAge === null && onUpdateHeader('age', e.target.value)}
                            readOnly={calculatedAge !== null}
                            title={calculatedAge !== null ? "Calculé automatiquement via Né(e) le et Date Fiction" : ""}
                        />
                    </div>
                    <HeaderInput label="Sexe" value={headerData.sex} onChange={(v) => onUpdateHeader('sex', v)} className="w-[8%] border-r border-stone-300" />
                    <HeaderInput label="Né(e) le" value={headerData.born} onChange={(v) => onUpdateHeader('born', v)} className="flex-grow border-r border-stone-300" />
                    <HeaderInput
                        label="Date Fiction"
                        value={headerData.fictionCurrentDate || ''}
                        onChange={(v) => onUpdateHeader('fictionCurrentDate', v)}
                        className={`flex-grow border-r border-stone-300 ${isDateLocked ? 'bg-stone-50' : ''}`}
                        readOnly={isDateLocked}
                        title={isDateLocked ? lockTitle : ""}
                    />
                    <HeaderInput label="Taille" value={headerData.height} onChange={(v) => onUpdateHeader('height', v)} className="w-[10%] border-r border-stone-300" />
                    <HeaderInput label="Cheveux" value={headerData.hair} onChange={(v) => onUpdateHeader('hair', v)} className="flex-grow border-r border-stone-300" />
                    <HeaderInput label="Yeux" value={headerData.eyes} onChange={(v) => onUpdateHeader('eyes', v)} className="flex-grow" />
                </div>
            </div>
        </>
    );
};

export default SheetHeader;

import React, { useState, useRef, useEffect } from 'react';
import { DotEntry } from '../../types';
import DotRating from '../ui/DotRating';
import { SectionHeader } from './Shared';
import { Info } from 'lucide-react';
import * as LucideIcons from 'lucide-react';
import { LucideIcon } from 'lucide-react';
import { logger } from '../../utils/logger';
import { useNotification } from '../../context/NotificationContext';
import { PortalTooltip } from '../ui/PortalTooltip';

const DotRow: React.FC<{
    entry: DotEntry;
    category: string;
    onUpdate: (section: 'skills', category: string, id: string, value: number) => void;
    specializations?: string[];
    theme?: { creationColor: string, xpColor: string, dotSymbol?: string, skillColors?: { variable?: string, mysticDefault?: string, mysticOverrides?: Record<string, string> } };
    imposedSpecs?: { name: string, minLevel: number }[];
    onDefineVariant?: (category: string, id: string, name: string) => void;
    allowExtendedSkills?: boolean;
    isEditing?: boolean;
    onRemove?: (category: string, id: string) => void;
    validateIncrease?: (id: string, newValue: number) => { allowed: boolean; reason?: string };
    blockedReason?: string;
}> = ({ entry, category, onUpdate, specializations = [], theme, imposedSpecs = [], onDefineVariant, allowExtendedSkills = false, isEditing = false, onRemove, validateIncrease, blockedReason }) => {
    const [isOpen, setIsOpen] = useState(false);
    const anchorRef = useRef<HTMLSpanElement>(null);
    const addLog = useNotification();

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (anchorRef.current && !anchorRef.current.contains(event.target as Node)) {
                setIsOpen(false);
            }
        };

        if (isOpen) {
            document.addEventListener('mousedown', handleClickOutside);
        }
        return () => {
            document.removeEventListener('mousedown', handleClickOutside);
        };
    }, [isOpen]);

    // Spacer logic
    if (!entry.name) {
        return (
            <div
                className={`h-5 border-b border-dotted transition-colors relative group ${isEditing ? 'border-[#bfae85]/40 bg-[#bfae85]/5 hover:bg-[#bfae85]/10 cursor-grab active:cursor-grabbing' : 'border-transparent'}`}
                draggable={isEditing}
                onDragStart={isEditing ? (e) => {
                    const payload = {
                        type: 'sheet_item',
                        originCategory: category,
                        data: entry,
                        categoryType: category === 'Arrière-plan' ? 'background' : 'skill'
                    };
                    e.dataTransfer.setData('application/json', JSON.stringify(payload));
                } : undefined}
            >
                {isEditing && (
                    <button
                        onClick={(e) => { e.stopPropagation(); onRemove?.(category, entry.id); }}
                        className="absolute -right-1 top-1/2 -translate-y-1/2 p-0.5 text-red-400 opacity-0 group-hover:opacity-100 bg-white/80 rounded-full shadow-sm hover:text-red-600 transition-all z-10"
                    >
                        <LucideIcons.Trash2 size={10} />
                    </button>
                )}
            </div>
        );
    }

    const visibleImposed = entry.value > 0
        ? imposedSpecs.filter(s => entry.value >= (s.minLevel || 0)).map(s => s.name)
        : [];

    const validUserSpecs = entry.value > 0
        ? specializations.filter(s => s && s.trim() !== '')
        : [];

    const combinedValidSpecs = [...visibleImposed, ...validUserSpecs];
    const hasSpecs = combinedValidSpecs.length > 0;
    const isUndefinedVariable = entry.variant === "";

    // Dynamic Max Logic
    // If not extended, max is 5.
    // If extended, we always show at least 5.
    // If rank is 5, we show 6 (5 filled + 1 empty).
    // If rank is 6, we show 7, etc.
    const effectiveMax = allowExtendedSkills && entry.value >= 5
        ? Math.min(entry.value + 1, 10)
        : 5;

    const handleClick = () => {
        if (isUndefinedVariable && onDefineVariant) {
            onDefineVariant(category, entry.id, entry.name);
        } else if (hasSpecs) {
            setIsOpen(!isOpen);
        }
    };

    const getTextColor = (): string | undefined => {
        const skill = entry as any;
        const colors = theme?.skillColors;

        // 1. Surcharge spécifique Habilité Mystique
        if (skill.mysticAbilityId && colors?.mysticOverrides?.[skill.mysticAbilityId]) {
            return colors.mysticOverrides[skill.mysticAbilityId];
        }

        // 2. Défaut Mystique
        if (skill.mysticAbilityId) {
            return colors?.mysticDefault || '#8b5cf6';
        }

        // 3. Compétence Variable
        // On considère variable si flag isVariable présent OU si un variant est défini (même vide)
        if (skill.isVariable || entry.variant !== undefined) {
            return colors?.variable || '#d97706';
        }

        return undefined;
    };

    const textColor = getTextColor();
    const isBlocked = !!blockedReason;

    // Validation Check for Interaction
    const handleUpdate = (val: number) => {
        if (validateIncrease && val > entry.value) {
            const check = validateIncrease(entry.id, val);
            if (!check.allowed) {
                if (check.reason) {
                    addLog(check.reason, 'danger', 'sheet', `block-${entry.id}`);
                }
                return;
            }
        }
        onUpdate('skills', category, entry.id, val);
    };

    return (
        <div
            className={`flex justify-between items-center px-2 border-b border-dotted border-stone-300 h-5 hover:bg-stone-50 transition-colors relative group ${isEditing ? 'cursor-grab active:cursor-grabbing select-none' : ''}`}
            draggable={isEditing}
            onDragStart={isEditing ? (e) => {
                const payload = {
                    type: 'sheet_item',
                    originCategory: category,
                    data: entry,
                    categoryType: category === 'Arrière-plan' ? 'background' : 'skill'
                };
                e.dataTransfer.setData('application/json', JSON.stringify(payload));
            } : undefined}
            onMouseLeave={() => setIsOpen(false)}
        >
            <span
                className={`text-xs truncate font-medium transition-all ${isUndefinedVariable
                    ? 'font-bold cursor-pointer hover:underline' // Removed text-color classes to let style override
                    : hasSpecs
                        ? 'font-semibold cursor-help underline underline-offset-2 decoration-blue-300' // Removed text-blue-900
                        : 'cursor-default'
                    } ${isBlocked ? 'line-through opacity-60 italic' : ''}`}
                // Dynamic width adjustment to avoid overlap with extra bubbles
                style={{
                    width: effectiveMax > 5 ? '45%' : '65%',
                    color: isBlocked ? '#71717a' : (textColor ? textColor : (isUndefinedVariable ? '#d97706' : (hasSpecs ? '#1e3a8a' : '#44403c'))) // Fallbacks: amber-600, blue-900, stone-700
                }}
                onClick={handleClick}
                ref={anchorRef}
                title={entry.description || (entry.variant ? `${entry.name} : ${entry.variant}` : entry.name)}
            >
                {entry.variant !== undefined ? (
                    <>
                        <span style={{ color: isBlocked ? '#71717a' : (textColor || '#d97706') }} className="font-bold">{entry.name}{' : '}</span>
                        <span className={`${isUndefinedVariable ? 'italic opacity-60' : 'font-normal'}`} style={{ color: isBlocked ? '#71717a' : (textColor ? textColor : (isUndefinedVariable ? 'inherit' : '#78716c')) }}>
                            {entry.variant || '...'}
                        </span>
                    </>
                ) : (
                    entry.name
                )}
                {hasSpecs && !isUndefinedVariable && <span className="text-[9px] align-top ml-0.5 text-blue-400">*</span>}
            </span>

            {/* Tooltip for Specializations */}
            <PortalTooltip
                isOpen={isOpen && hasSpecs}
                anchorRef={anchorRef}
                title={`${entry.name} : Spécialisations`}
                maxWidth={400}
            >
                <div className="flex flex-col gap-1 w-full min-w-[220px] py-1">
                    <div className={combinedValidSpecs.length > 5 ? "columns-2 gap-x-8" : "flex flex-col"}>
                        {combinedValidSpecs.map((s, i) => (
                            <div key={i} className="flex items-center text-[11px] mb-1.5 break-inside-avoid px-2 border-l border-slate-700/50 hover:border-amber-500/50 transition-colors ml-1">
                                <span className="text-slate-300 truncate font-medium flex-1 flex items-center pr-2" title={s}>
                                    <span className="text-amber-400/80 mr-2 shrink-0 text-base leading-none translate-y-[1px]">•</span>
                                    {s}
                                </span>
                            </div>
                        ))}
                    </div>
                </div>
            </PortalTooltip>

            <DotRating
                value={entry.value}
                creationValue={entry.creationValue}
                onChange={handleUpdate}
                className="scale-90 origin-right ml-auto"
                creationColor={theme?.creationColor}
                xpColor={theme?.xpColor}
                symbol={theme?.dotSymbol}
                max={effectiveMax}
                readOnly={isEditing}
                blockedReason={blockedReason}
            />

            {isEditing && (entry.value === 0 || !entry.name) && (
                <button
                    onClick={(e) => { e.stopPropagation(); onRemove?.(category, entry.id); }}
                    className="absolute -right-1 top-1/2 -translate-y-1/2 p-0.5 text-red-400 opacity-0 group-hover:opacity-100 bg-white/80 rounded-full shadow-sm hover:text-red-600 transition-all z-10"
                >
                    <LucideIcons.Trash2 size={10} />
                </button>
            )}
        </div >
    );
};

export const SkillBlock = React.memo<{
    title: string;
    items: DotEntry[];
    cat: string;
    onUpdate: (section: 'skills', category: string, id: string, value: number) => void;
    userSpecs?: Record<string, string[]>;
    imposedSpecs?: Record<string, { name: string, minLevel: number }[]>;
    theme?: { creationColor: string, xpColor: string, dotSymbol?: string, skillColors?: { variable?: string, mysticDefault?: string, mysticOverrides?: Record<string, string> } };
    onDefineVariant?: (category: string, id: string, name: string) => void;
    allowExtendedSkills?: boolean;
    description?: string;
    isEditing?: boolean;
    categoryBehavior?: 'Compétence' | 'Secondaire' | 'Arrière-plan' | 'Compteur';
    onDrop?: (category: string, item: any, targetIndex: number) => void;
    onRemove?: (category: string, id: string) => void;
    validateIncrease?: (id: string, newValue: number) => { allowed: boolean; reason?: string };
    blockedSkills?: Record<string, { isBlocked: boolean, sourceName: string }>;
}>(({ title, items, cat, onUpdate, userSpecs = {}, imposedSpecs = {}, theme, onDefineVariant, allowExtendedSkills = false, description, isEditing = false, onDrop, onRemove, validateIncrease, blockedSkills = {} }) => {
    const [showDesc, setShowDesc] = useState(false);
    const [isDragOver, setIsDragOver] = useState(false);
    const [dropIndex, setDropIndex] = useState<number>(-1);



    const handleDragOver = (e: React.DragEvent) => {
        if (!isEditing) return;
        e.preventDefault();
        setIsDragOver(true);
        e.dataTransfer.dropEffect = 'copy';

        // Calculate drop index based on mouse position
        const rect = e.currentTarget.getBoundingClientRect();
        const y = e.clientY - rect.top;
        const rowHeight = 20; // h-5 is 20px
        const headerPadding = 24; // approx height of SectionHeader + padding
        const relativeY = y - headerPadding;

        // Items start after header padding
        let index = Math.round(relativeY / rowHeight);
        index = Math.max(0, Math.min(index, items.length));
        setDropIndex(index);
    };

    const handleDragLeave = () => {
        setIsDragOver(false);
        setDropIndex(-1);
    };

    const handleDrop = (e: React.DragEvent) => {
        if (!isEditing) return;
        e.preventDefault();
        setIsDragOver(false);
        const finalDropIndex = dropIndex;
        setDropIndex(-1);
        try {
            const payload = JSON.parse(e.dataTransfer.getData('application/json'));
            onDrop?.(cat, payload, finalDropIndex);
        } catch (err) {
            logger.error('Failed to parse drop payload', err);
        }
    };

    return (
        <div
            className={`flex flex-col transition-all duration-200 ${isEditing ? 'relative' : ''} ${isDragOver ? 'bg-[#bfae85]/10 ring-2 ring-[#bfae85]/40 rounded-sm scale-[1.02] shadow-lg z-10' : ''}`}
            onDragOver={handleDragOver}
            onDragLeave={handleDragLeave}
            onDrop={handleDrop}
        >
            <div className="relative group/header">
                <SectionHeader
                    title={
                        <div className="flex items-center gap-1.5 justify-center">
                            {title}
                            {description && (
                                <button
                                    onMouseEnter={() => setShowDesc(true)}
                                    onMouseLeave={() => setShowDesc(false)}
                                    className="ml-1 text-[#bfae85]/40 hover:text-[#8b2e2e] transition-colors"
                                >
                                    <Info size={10} />
                                </button>
                            )}
                        </div>
                    }
                />

                {showDesc && description && (
                    <div className="absolute z-[101] left-1/2 -translate-x-1/2 bottom-full mb-1 w-48 bg-stone-800 text-white text-[9px] p-2 rounded shadow-xl animate-in fade-in slide-in-from-bottom-1 duration-200 pointer-events-none text-center">
                        {description}
                        <div className="absolute left-1/2 -translate-x-1/2 top-full w-0 h-0 border-l-[4px] border-l-transparent border-r-[4px] border-r-transparent border-t-[4px] border-t-stone-800"></div>
                    </div>
                )}
            </div>

            <div className="flex-grow py-1 relative">
                {/* Drop Indicator Logic */}
                {isEditing && isDragOver && dropIndex !== -1 && (
                    <div
                        className="absolute left-0 right-0 h-0.5 bg-[#bfae85] z-20 pointer-events-none"
                        style={{ top: `${(dropIndex * 20) + 4}px` }} // 4px padding in py-1? No, py-1 is 4px top/bottom.
                    >
                        <div className="absolute left-0 top-1/2 -translate-y-1/2 -translate-x-1 w-2 h-2 bg-[#bfae85] rotate-45"></div>
                        <div className="absolute right-0 top-1/2 -translate-y-1/2 translate-x-1 w-2 h-2 bg-[#bfae85] rotate-45"></div>
                    </div>
                )}

                {(items || []).map((item, idx) => {
                    const iSpecs = imposedSpecs[item.id] || [];
                    const uSpecs = userSpecs[item.id] || [];
                    const normalizedName = item.name.trim().toLowerCase();
                    const blockedInfo = blockedSkills[normalizedName];

                    return (
                        <DotRow
                            key={item.id}
                            entry={item}
                            category={cat}
                            onUpdate={onUpdate}
                            specializations={uSpecs}
                            imposedSpecs={iSpecs}
                            theme={theme}
                            onDefineVariant={onDefineVariant}
                            allowExtendedSkills={allowExtendedSkills}
                            isEditing={isEditing}
                            onRemove={onRemove}
                            validateIncrease={validateIncrease}
                            blockedReason={blockedInfo?.sourceName}
                        />
                    );
                })}

                {items.length === 0 && isEditing && (
                    <div className="h-20 flex items-center justify-center border border-dashed border-[#bfae85]/30 rounded text-[10px] text-[#bfae85]/50 italic">
                        Glissez ici
                    </div>
                )}
            </div>
        </div>
    );
});

import React, { useState, useMemo } from 'react';
import { ArrowUpRight, ArrowDownRight, RotateCcw, ChevronDown, Activity, BookOpen, User, Maximize2, Sparkles, Database, Zap, Wrench, Shield, Swords, Bookmark } from 'lucide-react';
import Tippy from '@tippyjs/react';
import 'tippy.js/dist/tippy.css';
import { ExperienceBreakdown } from '../../types';

interface XPReceiptViewProps {
    breakdown?: ExperienceBreakdown;
    totalGain: string;
    totalSpent: string;
    totalRest: string;
}

interface AggregatedEntry {
    name: string;
    amount: number;
    count?: number;
    type: 'earn' | 'spend' | 'refund';
}

interface GroupedTransaction {
    category: string;
    label: string;
    icon: React.ReactNode;
    colorClass: string;
    entries: AggregatedEntry[];
    total: number;
}

export const XPReceiptView: React.FC<XPReceiptViewProps> = ({ breakdown, totalGain, totalSpent, totalRest }) => {
    const [expandedCategory, setExpandedCategory] = useState<string | null>(null);

    const getCategorizedData = useMemo(() => {
        if (!breakdown) return { gains: [], spends: [] };

        const finalize = (key: string, label: string, icon: React.ReactNode, colorClass: string, items: any[] = [], type: 'earn' | 'spend' | 'refund'): GroupedTransaction => {
            const entries: AggregatedEntry[] = items.map(item => ({
                name: item.name,
                amount: Math.abs(item.amount),
                count: item.count,
                type
            })).sort((a, b) => b.amount - a.amount);

            return {
                category: key,
                label,
                icon,
                colorClass,
                entries,
                total: entries.reduce((sum, e) => sum + e.amount, 0)
            };
        };

        const gainsRaw = breakdown.gains || [];
        const sessionGains = gainsRaw.filter(g => g.name.startsWith('Base :'));
        const traitGains = gainsRaw.filter(g => g.name.startsWith('Bonus :'));
        const otherGains = gainsRaw.filter(g => !g.name.startsWith('Base :') && !g.name.startsWith('Bonus :'));

        const gains = [
            finalize('sessions', 'Sessions & Scénarios', <BookOpen size={16} />, 'text-emerald-700', sessionGains, 'earn'),
            finalize('traits_gain', 'Traits (Désavantages/Bonus)', <Database size={16} />, 'text-amber-600', traitGains, 'earn'),
            finalize('other_gain', 'Autres Gains', <Sparkles size={16} />, 'text-indigo-600', otherGains, 'earn')
        ].filter(c => c.entries.length > 0);

        const skillGroupsMap = new Map<string, any[]>();
        breakdown.skills.forEach(skill => {
            const catName = skill.category || 'Autres Compétences';
            if (!skillGroupsMap.has(catName)) {
                skillGroupsMap.set(catName, []);
            }
            skillGroupsMap.get(catName)!.push(skill);
        });

        const skillGroupSpends = Array.from(skillGroupsMap.entries()).map(([catName, items], index) => {
            let icon = <Activity size={16} />;
            let colorClass = 'text-rose-600';

            const lowerCat = catName.toLowerCase();
            if (lowerCat.includes('talent')) {
                icon = <Zap size={16} />;
                colorClass = 'text-orange-600';
            } else if (lowerCat.includes('connaissance') || lowerCat.includes('langue')) {
                icon = <BookOpen size={16} />;
                colorClass = 'text-sky-600';
            } else if (lowerCat.includes('savoir-faire') || lowerCat.includes('artisanat')) {
                icon = <Wrench size={16} />;
                colorClass = 'text-stone-500';
            } else if (lowerCat.includes('mêlée') || lowerCat.includes('combat') || lowerCat.includes('tir') || lowerCat.includes('arme')) {
                icon = <Swords size={16} />;
                colorClass = 'text-red-700';
            } else if (lowerCat.includes('arrière-plan') || lowerCat.includes('spécialisation')) {
                icon = <Bookmark size={16} />;
                colorClass = 'text-stone-600';
            }

            return finalize(`skills-${index}`, catName, icon, colorClass, items, 'spend');
        });

        const spends = [
            finalize('attributes', 'Attributs', <User size={16} />, 'text-amber-600', breakdown.attributes, 'spend'),
            ...skillGroupSpends,
            finalize('traits_spend', 'Traits (Avantages)', <Database size={16} />, 'text-purple-600', breakdown.traits, 'spend'),
            finalize('counters', 'Compteurs', <Maximize2 size={16} />, 'text-cyan-600', breakdown.counters, 'spend'),
            finalize('mystic', 'Habilités Mystiques', <Sparkles size={16} />, 'text-indigo-600', breakdown.mystic || [], 'spend')
        ].filter(c => c.entries.length > 0);

        return { gains, spends };
    }, [breakdown]);

    const renderTooltipContent = (group: GroupedTransaction) => {
        const topEntries = [...group.entries].slice(0, 5);
        return (
            <div className="p-2 min-w-64 max-w-sm">
                <div className="font-bold border-b border-stone-600 pb-1 mb-2 text-stone-200">{group.label} (Top Investissements)</div>
                {topEntries.length === 0 ? <div className="text-stone-400 italic text-sm">Aucune donnée</div> : null}
                <ul className="space-y-1.5 text-sm">
                    {topEntries.map((e, i) => (
                        <li key={i} className="flex justify-between items-start gap-3 text-stone-300">
                            <span className="grow line-clamp-2" title={e.name}>
                                {e.name} {e.count !== undefined && e.count > 1 && <span className="text-[10px] text-stone-500 font-normal"> (x{e.count})</span>}
                            </span>
                            <span className={`shrink-0 font-bold ${e.type === 'spend' ? 'text-red-400' : e.type === 'refund' ? 'text-blue-400' : 'text-green-400'}`}>
                                {e.type === 'spend' ? '-' : '+'}{e.amount}
                            </span>
                        </li>
                    ))}
                </ul>
                {group.entries.length > 5 && (
                    <div className="mt-2 pt-1 border-t border-stone-700 text-xs text-stone-400 text-center italic">
                        + {group.entries.length - 5} autres types de dépenses...
                    </div>
                )}
            </div>
        );
    };

    const renderExpandedTable = (group: GroupedTransaction) => {
        return (
            <div className="bg-stone-50 border-t border-stone-200 px-4 py-3 text-[13px] animate-in slide-in-from-top-2 duration-200">
                <div className="grid grid-cols-[1fr_80px] gap-4 mb-2 border-b border-stone-300 font-bold text-stone-500 uppercase tracking-wider text-[11px] py-1.5">
                    <div className="text-left">Sujet de l'Investissement</div>
                    <div className="text-right">Total XP</div>
                </div>
                <div className="max-h-64 overflow-y-auto pr-2 space-y-1">
                    {group.entries.map((e, i) => (
                        <div key={i} className="grid grid-cols-[1fr_80px] gap-4 py-2 border-b border-stone-100 last:border-0 hover:bg-stone-100/80 transition-colors">
                            <div className="text-stone-800 font-medium truncate flex items-center gap-2" title={e.name}>
                                {e.name}
                                {e.count !== undefined && e.count > 1 && <span className="bg-stone-200 text-stone-500 px-1.5 py-0.5 rounded text-[10px] font-bold">x{e.count}</span>}
                            </div>
                            <div className={`font-mono font-bold text-right flex items-center justify-end ${e.type === 'spend' ? 'text-red-600' : e.type === 'refund' ? 'text-blue-600' : 'text-green-600'}`}>
                                {e.type === 'spend' ? '-' : '+'}{e.amount}
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        );
    };

    const renderGroup = (group: GroupedTransaction) => {
        const isExpanded = expandedCategory === group.category;
        return (
            <div key={group.category} className={`border border-stone-200 rounded-lg overflow-hidden transition-all duration-200 ${isExpanded ? 'bg-white shadow-md my-2 ring-1 ring-stone-300' : 'bg-white/60 hover:bg-white mb-2'}`}>
                <Tippy
                    content={renderTooltipContent(group)}
                    placement="left"
                    theme="translucent"
                    arrow={true}
                    delay={[200, 0]}
                    disabled={isExpanded} // Disable tooltip when expanded
                    className="bg-stone-800/95 backdrop-blur-sm text-stone-100 rounded-lg shadow-xl border border-stone-700 font-sans"
                >
                    <button
                        type="button"
                        className="px-4 py-3 flex items-center justify-between cursor-pointer group select-none text-left w-full outline-none"
                        onClick={() => setExpandedCategory(isExpanded ? null : group.category)}
                    >
                        <div className="flex items-center gap-3">
                            <div className={`p-2 rounded-md bg-stone-100 border border-stone-200 ${group.colorClass} group-hover:scale-105 transition-transform`}>
                                {group.icon}
                            </div>
                            <div>
                                <div className="font-bold text-stone-800 text-sm">{group.label}</div>
                                <div className="text-[11px] text-stone-500">{group.entries.length} élément{group.entries.length > 1 ? 's' : ''} distinct{group.entries.length > 1 ? 's' : ''}</div>
                            </div>
                        </div>

                        <div className="flex items-center gap-4">
                            <div className={`font-mono font-bold text-lg ${group.colorClass}`}>
                                {group.total} XP
                            </div>
                            <div className={`text-stone-400 transition-transform duration-200 ${isExpanded ? 'rotate-180 text-stone-800' : 'group-hover:text-stone-800'}`}>
                                <ChevronDown size={20} />
                            </div>
                        </div>
                    </button>
                </Tippy>

                {isExpanded && renderExpandedTable(group)}
            </div>
        );
    };

    return (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-2 p-2 bg-stone-50/50 font-sans">

            {/* Colonne Gains */}
            <div className="flex flex-col gap-1">
                <div className="flex items-end justify-between mb-2 border-b border-stone-300 pb-1">
                    <h2 className="text-lg font-bold font-serif text-emerald-900 flex items-center gap-2">
                        <ArrowUpRight className="text-emerald-600" size={20} />
                        RECETTES & GAINS
                    </h2>
                    <div className="text-xl font-black text-emerald-700 tracking-tighter">
                        {totalGain} <span className="text-sm text-emerald-600 font-normal">XP</span>
                    </div>
                </div>

                <div className="flex-grow space-y-1">
                    {getCategorizedData.gains.length === 0 ? (
                        <div className="text-center p-8 text-stone-400 italic bg-white/50 border border-stone-200 border-dashed rounded-lg">
                            Aucun gain enregistré.
                        </div>
                    ) : (
                        getCategorizedData.gains.map(renderGroup)
                    )}
                </div>
            </div>

            {/* Colonne Dépenses */}
            <div className="flex flex-col gap-1">
                <div className="flex items-end justify-between mb-2 border-b border-stone-300 pb-1">
                    <h2 className="text-lg font-bold font-serif text-rose-900 flex items-center gap-2">
                        <ArrowDownRight className="text-rose-600" size={20} />
                        INVESTISSEMENTS
                    </h2>
                    <div className="text-xl font-black text-rose-700 tracking-tighter">
                        {totalSpent} <span className="text-sm text-rose-600 font-normal">XP</span>
                    </div>
                </div>

                <div className="flex-grow space-y-1">
                    {getCategorizedData.spends.length === 0 ? (
                        <div className="text-center p-8 text-stone-400 italic bg-white/50 border border-stone-200 border-dashed rounded-lg">
                            Aucune dépense enregistrée.
                        </div>
                    ) : (
                        getCategorizedData.spends.map(renderGroup)
                    )}
                </div>

            </div>

        </div>
    );
};

export default XPReceiptView;

import React, { useState, useEffect } from 'react';
import ThematicModal from '../../ui/ThematicModal';
import ThematicButton from '../../ui/ThematicButton';
import { TraitEntry } from '../../../types';
import { Save, X, Edit, Sparkles } from 'lucide-react';
import { useCharacter } from '../../../context/CharacterContext';
import { useRules } from '../../../context/RulesContext';
import { normalizeString } from '../../../utils/stringUtils';

interface TraitEditModalProps {
    isOpen: boolean;
    onClose: () => void;
    trait: TraitEntry | null;
    onSave: (updatedTrait: TraitEntry) => void;
    type: 'avantages' | 'desavantages';
}

const TraitEditModal: React.FC<TraitEditModalProps> = ({ isOpen, onClose, trait, onSave, type }) => {
    const [editedTrait, setEditedTrait] = useState<TraitEntry | null>(null);
    const { data, updateData: onChange, addLog: onAddLog } = useCharacter();
    const { rules } = useRules();

    useEffect(() => {
        if (isOpen && trait) {
            setEditedTrait({ ...trait });
        }
    }, [isOpen, trait]);

    const isPostCreation = !data.creationConfig?.active;
    const traitCostFactor = rules?.configurations?.xpCosts?.traitCost ?? (data.xpCosts?.traitCost ?? 5);

    const handleChange = (field: keyof TraitEntry, value: string) => {
        setEditedTrait(prev => prev ? { ...prev, [field]: value } : null);
    };

    const handleSave = () => {
        if (editedTrait) {
            onSave(editedTrait);
        }
    };

    const handleReduceTrait = () => {
        if (!editedTrait || !isPostCreation) return;

        const currentValue = parseInt(editedTrait.value) || 0;
        if (currentValue <= 0) return;

        const isFixedCost = editedTrait.value.toLowerCase().includes('pts') || !/^\d+$/.test(editedTrait.value.trim());
        const reductionAmount = isFixedCost ? currentValue : 1;
        const newValue = currentValue - reductionAmount;
        const xpCost = reductionAmount * traitCostFactor;

        // update object locally
        const updatedTrait = {
            ...editedTrait,
            value: newValue.toString(),
            creationValue: editedTrait.creationValue ?? editedTrait.value // Store initial if not set
        };

        setEditedTrait(updatedTrait);
        onSave(updatedTrait);
        onAddLog(`${isFixedCost ? 'Rachat' : 'Réduction'} du trait ${editedTrait.name} pour ${xpCost} XP.`, 'success', 'sheet');
    };

    const handleIncreaseTrait = () => {
        if (!editedTrait || !isPostCreation) return;

        const currentValue = parseInt(editedTrait.value) || 0;

        const updatedTrait = {
            ...editedTrait,
            value: (currentValue + 1).toString(),
            creationValue: editedTrait.creationValue ?? editedTrait.value // Preserve initial creation value
        };

        setEditedTrait(updatedTrait);
        onSave(updatedTrait);
        onAddLog(`Amélioration du trait ${editedTrait.name} pour ${traitCostFactor} XP.`, 'success', 'sheet');
    };

    if (!editedTrait) return null;

    const currentValue = parseInt(editedTrait.value) || 0;
    const isFixedCost = editedTrait.value.toLowerCase().includes('pts') || !/^\d+$/.test(editedTrait.value.trim());

    // Extract max value from library cost strings (e.g., "1-3", "2 à 5", "1, 2, 3")
    const extractMaxFromCost = (cost: string): number => {
        const matches = cost.match(/\d+/g);
        if (matches && matches.length >= 2) {
            return Math.max(...matches.map(Number));
        }
        return 0; // Not a range
    };

    // Check if the trait is variable in the library and get its max
    const libEntry = data.library?.find(e => e.id === editedTrait.definitionId);
    const libCost = libEntry?.pointsLabel || libEntry?.cost || '';
    const maxValue = extractMaxFromCost(libCost);
    const isActuallyVariable = maxValue > 0;

    const isImproved = !editedTrait.isPostCreation && editedTrait.creationValue !== undefined && currentValue > (parseInt(editedTrait.creationValue) || 0);

    // Check if upgradeable via new property (native to TraitEntry or LibraryEntry)
    const isUpgradeable = !!editedTrait.isXPUpgradeable || !!libEntry?.isXPUpgradeable ||
        !!rules?.libraries?.traits?.find(t => t.id === editedTrait.definitionId || normalizeString(t.name) === normalizeString(editedTrait.name))?.isXPUpgradeable;

    const canReduce = isPostCreation && type === 'desavantages' && currentValue > 0;
    const canIncrease = isPostCreation && type === 'avantages' && (isActuallyVariable || isUpgradeable) && currentValue > 0;

    return (
        <ThematicModal
            isOpen={isOpen}
            onClose={onClose}
            title={`Éditer ${type === 'avantages' ? 'l\'Avantage' : 'le Désavantage'}`}
            icon={<Edit size={24} />}
            size="md"
            footer={
                <div className="flex justify-between items-center w-full">
                    <div className="flex gap-2">
                        {canReduce && (
                            <ThematicButton
                                onClick={handleReduceTrait}
                                variant="primary"
                                size="sm"
                                className="bg-emerald-600 hover:bg-emerald-700 text-white"
                                leftIcon={<Sparkles size={16} />}
                            >
                                {isFixedCost
                                    ? `Racheter totalement (${currentValue * traitCostFactor} XP)`
                                    : `Réduire d'un niveau (${traitCostFactor} XP)`}
                            </ThematicButton>
                        )}
                        {canIncrease && (
                            <ThematicButton
                                onClick={handleIncreaseTrait}
                                variant="primary"
                                size="sm"
                                className="bg-emerald-600 hover:bg-emerald-700 text-white"
                                leftIcon={<Sparkles size={16} />}
                            >
                                Améliorer d'un niveau ({traitCostFactor} XP)
                            </ThematicButton>
                        )}
                    </div>
                    <div className="flex gap-2">
                        <ThematicButton onClick={onClose} variant="secondary" size="sm" leftIcon={<X size={16} />}>
                            Annuler
                        </ThematicButton>
                        <ThematicButton onClick={handleSave} variant="primary" size="sm" leftIcon={<Save size={16} />}>
                            Sauvegarder
                        </ThematicButton>
                    </div>
                </div>
            }
        >
            <div className="p-4 space-y-4">
                {editedTrait.isPostCreation && (
                    <div className="bg-emerald-50 border border-emerald-200 rounded-lg p-2 text-emerald-800 text-xs font-bold flex items-center gap-2">
                        <Sparkles size={14} /> Trait acquis post-création via XP
                    </div>
                )}
                {isImproved && (
                    <div className="bg-blue-50 border border-blue-200 rounded-lg p-2 text-blue-800 text-xs font-bold flex items-center gap-2">
                        <Sparkles size={14} /> Trait amélioré post-création via XP
                    </div>
                )}
                <div>
                    <label className="block text-sm font-bold text-slate-700 mb-1">Nom du trait</label>
                    <input
                        type="text"
                        value={editedTrait.name || ''}
                        onChange={(e) => handleChange('name', e.target.value)}
                        className="w-full border-2 border-stone-200 rounded-lg p-2 focus:border-stone-400 focus:outline-none bg-white font-handwriting text-lg"
                        placeholder="Ex: Chance..."
                    />
                </div>
                <div className="grid grid-cols-2 gap-4">
                    <div>
                        <label className="block text-sm font-bold text-slate-700 mb-1">Coût / Valeur</label>
                        <input
                            type="text"
                            value={editedTrait.value || ''}
                            onChange={(e) => handleChange('value', e.target.value)}
                            className="w-full border-2 border-stone-200 rounded-lg p-2 focus:border-stone-400 focus:outline-none bg-white"
                            placeholder="Ex: 5 PTS, 1/rang..."
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-bold text-slate-700 mb-1">Variante / Spécialité</label>
                        <input
                            type="text"
                            value={editedTrait.variant || ''}
                            onChange={(e) => handleChange('variant', e.target.value)}
                            className="w-full border-2 border-stone-200 rounded-lg p-2 focus:border-stone-400 focus:outline-none bg-white font-handwriting text-lg"
                            placeholder="Ex: Épée longue..."
                        />
                    </div>
                </div>
                <div>
                    <label className="block text-sm font-bold text-slate-700 mb-1">Description / Effet</label>
                    <textarea
                        value={editedTrait.description || ''}
                        onChange={(e) => handleChange('description', e.target.value)}
                        className="w-full border-2 border-stone-200 rounded-lg p-2 focus:border-stone-400 focus:outline-none bg-white min-h-[100px] resize-y"
                        placeholder="Saisissez la description du trait..."
                    />
                </div>
            </div>
        </ThematicModal>
    );
};

export default TraitEditModal;

import React from 'react';
import { TraitEntry } from '../../../types';
import { Edit, Trash2, Wand2, Sparkles, ArrowUp, ArrowDown } from 'lucide-react';

interface TraitRowProps {
    item: TraitEntry;
    type: 'avantages' | 'desavantages';
    onClick: () => void;
    onRemove: (e: React.MouseEvent) => void;
    onManageMystic?: (e: React.MouseEvent) => void;
}

const TraitRow: React.FC<TraitRowProps> = ({ item, type, onClick, onRemove, onManageMystic }) => {
    const isEmpty = !item.name.trim();
    const isResolved = item.value === '0' && item.creationValue !== undefined;

    const isPostCreation = item.isPostCreation && !isResolved;

    // Use internal trait type if defined, otherwise fall back to the component prop
    const internalTraitType = item.type;
    const isDisadvantage = internalTraitType ? (internalTraitType === 'desavantage') : (type === 'desavantages');
    const isAdvantage = internalTraitType ? (internalTraitType === 'avantage') : (type === 'avantages');

    const isImproved = !isPostCreation && item.creationValue !== undefined && parseInt(item.value) > parseInt(item.creationValue);
    const isReduced = !isPostCreation && item.creationValue !== undefined && parseInt(item.value) < parseInt(item.creationValue);

    const isPostCreationAdvantage = isPostCreation && isAdvantage;
    const isPostCreationDisadvantage = isPostCreation && isDisadvantage;

    return (
        <div
            onClick={onClick}
            className={`flex gap-1 items-center h-[22px] px-1 transition-all rounded-sm cursor-pointer group select-none ${isEmpty
                ? 'hover:bg-slate-50 border-b border-dotted border-stone-200'
                : (isPostCreationAdvantage || isImproved)
                    ? 'bg-emerald-50 hover:bg-emerald-100 border-b border-emerald-200 shadow-sm'
                    : (isPostCreationDisadvantage)
                        ? 'bg-red-50 hover:bg-red-100 border-b border-red-200 shadow-sm'
                        : (isReduced)
                            ? 'bg-amber-50 hover:bg-amber-100 border-b border-amber-200 shadow-sm'
                            : 'hover:bg-blue-50 bg-white/50 border-b border-stone-300 shadow-sm'
                }`}
        >
            <div className={`w-8 shrink-0 text-center font-bold text-xs h-full flex items-center justify-center border-r border-stone-300 ${isEmpty ? 'text-stone-300' : 'text-stone-800 font-handwriting bg-white'
                } ${isResolved ? 'line-through opacity-50' : ''}`} style={{ fontSize: '0.9rem' }}>
                {item.value || (isEmpty ? '-' : '')}
            </div>

            <div className={`flex-grow h-full flex items-center px-1 font-handwriting min-w-0 ${isEmpty ? 'text-stone-300 italic text-[10px]' : 'text-ink'
                } ${isResolved ? 'line-through opacity-50' : ''}`} style={{ fontSize: isEmpty ? '0.7rem' : '0.9rem' }}>
                <span className="truncate w-full block" title={!isEmpty ? (item.variant ? `${item.name} : ${item.variant}` : item.name) : undefined}>
                    <span className="inline-flex items-center gap-1 mr-1.5 leading-none">
                        {isPostCreationAdvantage && <span title="Acquis avec XP"><Sparkles size={11} className="text-emerald-600 fill-emerald-600/20" strokeWidth={2.5} /></span>}
                        {isPostCreationDisadvantage && <span title="Nouveau Désavantage (Gain XP)"><Sparkles size={11} className="text-red-500 fill-red-500/20" strokeWidth={2.5} /></span>}
                        {isImproved && <span title="Amélioré avec XP"><ArrowUp size={11} className="text-blue-600" strokeWidth={3} /></span>}
                        {isReduced && <span title="Racheté avec XP"><ArrowDown size={11} className="text-orange-600" strokeWidth={3} /></span>}
                    </span>
                    {item.name || "Vide"}
                    {item.variant && <span className="font-bold ml-1 text-slate-600">: {item.variant}</span>}
                </span>
            </div>

            {!isEmpty && item.mysticAbilityId && onManageMystic && (
                <div
                    onClick={(e) => {
                        e.stopPropagation();
                        onManageMystic(e);
                    }}
                    className="opacity-100 sm:opacity-0 group-hover:opacity-100 text-purple-400 hover:text-purple-600 scale-75 transition-all shrink-0 p-1 hover:bg-purple-50 rounded"
                    title="Gérer les compétences mystiques"
                >
                    <Wand2 size={14} />
                </div>
            )}

            {!isEmpty && (
                <div
                    onClick={onRemove}
                    className="opacity-0 group-hover:opacity-100 text-stone-400 hover:text-red-500 scale-75 transition-all shrink-0 p-1 hover:bg-red-50 rounded"
                    title="Supprimer"
                >
                    <Trash2 size={14} />
                </div>
            )}
            <div className="opacity-0 group-hover:opacity-100 text-stone-400 scale-75 transition-opacity shrink-0">
                <Edit size={14} />
            </div>
        </div>
    );
};

export default TraitRow;

import React, { useState, useMemo } from 'react';
import { CharacterSheetData, LibrarySkillEntry } from '../../../types';
import { RulesData } from '../../../types/rules';
import { Sparkles, CheckCircle2, ChevronRight, AlertCircle, Infinity as InfinityIcon } from 'lucide-react';
import { getMysticCapacity } from '../../../utils/mysticUtils';
import ThematicModal from '../../ui/ThematicModal';

interface MysticSkillWizardProps {
    isOpen: boolean;
    onClose: () => void;
    onConfirm: (selectedSkillIds: string[]) => void;
    mysticAbilityId: string;
    mysticAbilityName: string;
    sheet: CharacterSheetData;
    rules: RulesData;
}

const MysticSkillWizard: React.FC<MysticSkillWizardProps> = ({
    isOpen,
    onClose,
    onConfirm,
    mysticAbilityId,
    mysticAbilityName,
    sheet,
    rules
}) => {
    const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

    // Capacity Calculation
    const capacity = useMemo(() => getMysticCapacity(sheet, mysticAbilityId, rules), [sheet, mysticAbilityId, rules]);
    const { allowed, current, traitLevel } = capacity;
    const remainingSlots = Math.max(0, allowed - current - selectedIds.size);

    // Filter available skills
    const availableSkills = useMemo(() => {
        const allLibSkills = rules.libraries.skills || [];
        // Filter by mysticAbilityId
        return allLibSkills.filter(s => s.mysticAbilityId === mysticAbilityId)
            // Filter out already owned skills
            .filter(s => {
                const owned = Object.values(sheet.skills).flat().some(ownedSkill => ownedSkill.name === s.name && ownedSkill.value > 0);
                return !owned;
            })
            .sort((a, b) => a.name.localeCompare(b.name));
    }, [rules.libraries.skills, mysticAbilityId, sheet.skills]);

    const handleToggle = (id: string) => {
        const newSelected = new Set(selectedIds);
        if (newSelected.has(id)) {
            newSelected.delete(id);
        } else {
            if (remainingSlots > 0) {
                newSelected.add(id);
            }
        }
        setSelectedIds(newSelected);
    };

    const handleConfirm = () => {
        onConfirm(Array.from(selectedIds));
        onClose();
    };

    return (
        <ThematicModal
            isOpen={isOpen}
            onClose={onClose}
            title={`Habilitées Mystiques : ${mysticAbilityName}`}
            icon={<Sparkles className="text-purple-400" />}
            size="lg"
            footer={
                <>
                    <div className="flex-1 text-xs text-stone-400">
                        {selectedIds.size === 0 ? "Aucune sélection" : `${selectedIds.size} compétence(s) sélectionnée(s)`}
                    </div>
                    <button onClick={onClose} className="px-4 py-2 text-stone-400 hover:text-stone-200">
                        Passer
                    </button>
                    <button
                        onClick={handleConfirm}
                        disabled={selectedIds.size === 0}
                        className={`px-6 py-2 rounded font-bold shadow-lg flex items-center gap-2 transition-all ${selectedIds.size > 0 ? 'bg-purple-600 hover:bg-purple-700 text-white' : 'bg-stone-700 text-stone-500 cursor-not-allowed'}`}
                    >
                        <CheckCircle2 size={16} />
                        Valider la sélection
                    </button>
                </>
            }
        >
            <div className="space-y-4 bg-stone-900 p-6 rounded-lg border border-stone-700">
                {/* Capacity Info */}
                <div className="bg-purple-900/20 border border-purple-500/30 rounded p-4 flex items-center justify-between">
                    <div>
                        <div className="text-sm font-bold text-purple-200 mb-1">Capacité Mystique (Niveau {traitLevel})</div>
                        <div className="text-xs text-purple-300/80">
                            {allowed === 999 ? (
                                <>
                                    Vous avez un accès <span className="text-white font-bold">illimité</span> aux compétences liées.<br />
                                    Actuellement connues : <span className="text-white font-bold">{current}</span>.
                                </>
                            ) : (
                                <>
                                    Vous pouvez apprendre jusqu'à <span className="text-white font-bold">{allowed}</span> compétences liées.
                                    Actuellement connues : <span className="text-white font-bold">{current}</span>.
                                </>
                            )}
                        </div>
                    </div>
                    <div className="text-right">
                        {allowed === 999 ? (
                            <>
                                <div className="text-purple-400 flex justify-end mb-1"><InfinityIcon size={32} /></div>
                                <div className="text-[10px] uppercase tracking-wider text-purple-500 font-bold">SANS LIMITE</div>
                            </>
                        ) : (
                            <>
                                <div className="text-2xl font-bold text-purple-400">{remainingSlots}</div>
                                <div className="text-[10px] uppercase tracking-wider text-purple-500 font-bold">Slots Restants</div>
                            </>
                        )}
                    </div>
                </div>

                {remainingSlots === 0 && selectedIds.size === 0 && (
                    <div className="bg-amber-900/20 border border-amber-500/30 rounded p-3 flex gap-3 items-start">
                        <AlertCircle className="text-amber-500 shrink-0 mt-0.5" size={16} />
                        <div className="text-xs text-amber-200/80">
                            Vous avez atteint la limite de compétences pour ce niveau d'Avantage. Augmentez l'Avantage pour débloquer plus de slots.
                        </div>
                    </div>
                )}

                {/* Skill List */}
                <div className="space-y-2 max-h-[40vh] overflow-y-auto custom-scrollbar pr-2">
                    {availableSkills.length === 0 ? (
                        <div className="text-center py-10 text-stone-500 italic">
                            Toutes les compétences disponibles sont déjà apprises.
                        </div>
                    ) : (
                        availableSkills.map(skill => {
                            const isSelected = selectedIds.has(skill.id);
                            const isDisabled = !isSelected && remainingSlots === 0;

                            return (
                                <div
                                    key={skill.id}
                                    onClick={() => !isDisabled && handleToggle(skill.id)}
                                    className={`
                                        relative group flex items-center gap-3 p-3 rounded border transition-all cursor-pointer
                                        ${isSelected
                                            ? 'bg-purple-600/20 border-purple-500 shadow-[0_0_15px_-3px_rgba(147,51,234,0.3)]'
                                            : isDisabled
                                                ? 'bg-stone-900/20 border-stone-800 opacity-50 cursor-not-allowed'
                                                : 'bg-stone-800/40 border-stone-700 hover:border-purple-500/50 hover:bg-stone-800/80'}
                                    `}
                                >
                                    <div className={`
                                        w-5 h-5 rounded border flex items-center justify-center transition-colors shrink-0
                                        ${isSelected ? 'bg-purple-500 border-purple-500 text-white' : 'border-stone-600 bg-stone-900/50 text-transparent'}
                                    `}>
                                        <CheckCircle2 size={12} />
                                    </div>

                                    <div className="flex-grow">
                                        <div className={`font-bold text-sm ${isSelected ? 'text-purple-200' : 'text-stone-300'}`}>
                                            {skill.name}
                                        </div>
                                        {skill.description && (
                                            <div className="text-xs text-stone-500 line-clamp-1 group-hover:line-clamp-none transition-all">
                                                {skill.description}
                                            </div>
                                        )}
                                    </div>

                                    {skill.defaultCategory && (
                                        <div className="text-[10px] uppercase font-bold text-stone-600 px-2 py-1 bg-stone-900 rounded shrink-0">
                                            {skill.defaultCategory}
                                        </div>
                                    )}
                                </div>
                            );
                        })
                    )}
                </div>
            </div>
        </ThematicModal>
    );
};

