                                </span>
                                <span className={`text-[10px] uppercase font-black ${entry.version_reason === 'manual' ? 'text-blue-600' : 'text-amber-600'}`}>
                                    {entry.version_reason === 'manual' ? 'Sauvegarde manuelle' : 'Auto-save (1h)'}
                                </span>
                            </div>
                            <button
                                onClick={() => onRestore(entry)}
                                disabled={isRestoring}
                                className="px-3 py-1.5 bg-stone-100 hover:bg-[#8b2e2e] hover:text-white text-[#8b2e2e] text-xs font-bold rounded flex items-center gap-1.5 transition-all disabled:opacity-50"
                            >
                                <RotateCcw size={12} />
                                Restaurer
                            </button>
                        </div>
                    ))}
                    <p className="text-[10px] text-stone-400 italic mt-2 text-center">
                        Seules les 2 dernières versions sont conservées.
                    </p>
                </div>
            )}
        </div>
    );
};

export default SyncHistoryTab;

import React from 'react';
import { AlertTriangle, CheckCircle, RefreshCw, MessageSquare, UploadCloud } from 'lucide-react';
import { GameSettingSummary } from '../../../services/CampaignService';
import { CharacterSheetData } from '../../../types/character';
import SyncHistoryTab from './SyncHistoryTab';
import { CharacterHistoryEntry } from '../../../services/CharacterSyncService';

interface SyncViewTabProps {
    characterData: CharacterSheetData;
    campaigns: GameSettingSummary[];
    selectedCampaign: string;
    setSelectedCampaign: (id: string) => void;
    playerName: string;
    setPlayerName: (name: string) => void;
    characterName: string;
    setCharacterName: (name: string) => void;
    isAutoSync: boolean;
    setIsAutoSync: (enabled: boolean) => void;
    status: 'idle' | 'loading' | 'success' | 'error';
    errorMessage: string;
    isLoadingCampaigns: boolean;
    isOnlineMode: boolean;
    cloudVersion: { lastSynced: number, mjMessage?: string } | null;
    history: CharacterHistoryEntry[];
    isLoadingHistory: boolean;
    isRestoring: boolean;
    onRestore: (entry: CharacterHistoryEntry) => void;
}

const SyncViewTab: React.FC<SyncViewTabProps> = ({
    characterData,
    campaigns,
    selectedCampaign,
    setSelectedCampaign,
    playerName,
    setPlayerName,
    characterName,
    setCharacterName,
    isAutoSync,
    setIsAutoSync,
    status,
    errorMessage,
    isLoadingCampaigns,
    isOnlineMode,
    cloudVersion,
    history,
    isLoadingHistory,
    isRestoring,
    onRestore
}) => {
    return (
        <div className="space-y-5 animate-in fade-in duration-300 overflow-y-auto pr-1">
            {/* Cloud Update Status Indicator */}
            {cloudVersion && characterData.syncInfo && cloudVersion.lastSynced > (characterData.syncInfo.lastSynced || 0) && (
                <div className="bg-amber-50 border border-amber-200 rounded-md p-3">
                    <div className="flex items-center gap-2 text-amber-800 font-bold text-sm mb-1">
                        <AlertTriangle size={18} className="text-amber-600" />
                        Mise à jour disponible sur le Cloud
                    </div>
                    <p className="text-xs text-amber-700 leading-relaxed mb-2">
                        Le Gardien ou un autre dispositif a synchronisé une version plus récente ({new Date(cloudVersion.lastSynced).toLocaleString()}).
                        Il est recommandé de vérifier l'onglet <strong>Bibliothèque Cloud</strong> avant d'écraser.
                    </p>

                    {cloudVersion.mjMessage && (
                        <div className="bg-white/60 border border-amber-900/10 p-2 rounded-sm mt-2">
                            <div className="text-[10px] font-black uppercase text-amber-900/40 flex items-center gap-1 mb-1">
                                <MessageSquare size={10} /> Note du Gardien
                            </div>
                            <p className="text-[12px] italic text-stone-700">{cloudVersion.mjMessage}</p>
                        </div>
                    )}
                </div>
            )}

            {/* Info Banner */}
            <div className="bg-blue-50 border border-blue-200 rounded-md p-3 text-sm text-blue-800">
                <p>
                    Envoyer votre fiche actuelle au Maître de Jeu.
                    Vos données locales restent prioritaires.
                </p>
            </div>

            {/* Campaign Selector */}
            <div>
                <div className="flex justify-between items-center mb-1.5">
                    <label className="block text-sm font-bold text-[#4a3b32]">
                        Campagne
                    </label>
                    {isOnlineMode && (
                        <span className="text-[10px] bg-amber-100 text-amber-700 font-bold px-2 py-0.5 rounded border border-amber-200 uppercase flex items-center gap-1">
                            <span className="w-1.5 h-1.5 bg-amber-500 rounded-full animate-pulse"></span>
                            Verrouillé sur session active
                        </span>
                    )}
                </div>
                {isLoadingCampaigns ? (
                    <div className="text-gray-500 text-sm">Chargement des campagnes...</div>
                ) : campaigns.length === 0 ? (
                    <div className="text-amber-600 text-sm flex items-center gap-2">
                        <AlertTriangle size={16} />
                        Aucune campagne publique disponible
                    </div>
                ) : (
                    <select
                        value={selectedCampaign}
                        onChange={(e) => setSelectedCampaign(e.target.value)}
                        disabled={isOnlineMode}
                        className={`w-full px-3 py-2 border border-[#bfae85] rounded-md bg-white text-[#2c241b] focus:outline-none focus:ring-2 focus:ring-[#8b2e2e] ${isOnlineMode ? 'opacity-70 bg-stone-50 cursor-not-allowed' : ''}`}
                    >
                        {campaigns.map(campaign => (
                            <option key={campaign.id} value={campaign.id}>
                                {campaign.name} (v{campaign.version})
                            </option>
                        ))}
                    </select>
                )}
            </div>

            {/* Player Name */}
            <div>
                <label htmlFor="player-name-input" className="block text-sm font-bold text-[#4a3b32] mb-1.5">
                    Nom du Joueur
                </label>
                <input
                    id="player-name-input"
                    type="text"
                    value={playerName}
                    onChange={(e) => setPlayerName(e.target.value)}
                    placeholder="Votre nom"
                    className="w-full px-3 py-2 border border-[#bfae85] rounded-md bg-white text-[#2c241b] focus:outline-none focus:ring-2 focus:ring-[#8b2e2e]"
                />
            </div>

            {/* Character Name */}
            <div>
                <label htmlFor="character-name-input" className="block text-sm font-bold text-[#4a3b32] mb-1.5">
                    Nom du Personnage
                </label>
                <input
                    id="character-name-input"
                    type="text"
                    value={characterName}
                    onChange={(e) => setCharacterName(e.target.value)}
                    placeholder="Nom du personnage"
                    className="w-full px-3 py-2 border border-[#bfae85] rounded-md bg-white text-[#2c241b] focus:outline-none focus:ring-2 focus:ring-[#8b2e2e]"
                />
            </div>

            {/* Auto-sync Toggle */}
            <div className="flex items-center justify-between p-3 bg-indigo-50 border border-indigo-100 rounded-md">
                <div>
                    <div className="text-sm font-bold text-indigo-900 flex items-center gap-2">
                        <RefreshCw size={14} className={isAutoSync ? "animate-spin-slow" : ""} />
                        Synchronisation automatique
                    </div>
                    <p className="text-[11px] text-indigo-700 mt-0.5">
                        Sauvegarde vers le cloud après chaque modification (délai 10s).
                    </p>
                </div>
                <label className="relative inline-flex items-center cursor-pointer">
                    <input
                        type="checkbox"
                        className="sr-only peer"
                        checked={isAutoSync}
                        onChange={(e) => setIsAutoSync(e.target.checked)}
                    />
                    <div className="w-11 h-6 bg-gray-200 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-indigo-300 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-indigo-600"></div>
                </label>
            </div>

            {/* Error Message */}
            {errorMessage && (
                <div className="bg-red-50 border border-red-300 rounded-md p-3 text-sm text-red-700 flex items-center gap-2">
                    <AlertTriangle size={16} />
                    {errorMessage}
                </div>
            )}

            {/* Success Message */}
            {status === 'success' && (
                <div className="bg-green-50 border border-green-300 rounded-md p-3 text-sm text-green-700 flex items-center gap-2">
                    <CheckCircle size={16} />
                    Fiche synchronisée avec succès !
                </div>
            )}

            {/* Existing Sync Info */}
            {characterData.syncInfo && (
                <div className="text-xs text-gray-500 border-t border-[#bfae85]/30 pt-3 mt-3">
                    Dernière sync : {new Date(characterData.syncInfo.lastSynced || Date.now()).toLocaleString('fr-FR')}
                    <br />
                    Campagne : {characterData.syncInfo.settingName}
                </div>
            )}

            {/* Database Backups History */}
            {characterData.syncInfo?.syncId && (
                <SyncHistoryTab
                    history={history}
                    isLoading={isLoadingHistory}
                    isRestoring={isRestoring}
                    onRestore={onRestore}
                />
            )}
        </div>
    );
};

export default SyncViewTab;

import React, { useState, useRef } from 'react';
import { LibraryEntry } from '../../types';
import { Zap, Edit2, Trash2, Plus, CheckSquare, Square, Lock, Globe, Layers, Activity, TrendingUp } from 'lucide-react';
import { PortalTooltip } from '../ui/PortalTooltip';
import { ItemUsageDetail } from '../../types/usageTypes';
import { UsageLockedTooltip } from '../../admin/components/libraries/UsageLockedTooltip';

interface TraitCardProps {
    entry: LibraryEntry;
    isEditable: boolean;
    isSelected: boolean;
    onSelect?: (entry: LibraryEntry) => void;
    onMultiSelect?: (id: string) => void;
    onEdit: (entry: LibraryEntry) => void;
    onDelete: (id: string) => void;
    showMultiSelect: boolean;
    source?: 'local' | 'official' | 'modified';
    isLocked?: boolean;
    isPlaced?: boolean;
    isActive?: boolean;
    usageDetails?: ItemUsageDetail;
    onLoadUsageDetails?: (id: string) => void;
}

const TraitCardItemVariants: React.FC<{ entry: LibraryEntry; hasVariants: boolean }> = ({ entry, hasVariants }) => {
    const [showTooltip, setShowTooltip] = useState(false);
    const anchorRef = useRef<HTMLDivElement>(null);

    return (
        <div
            ref={anchorRef}
            className="relative"
            onMouseEnter={() => setShowTooltip(true)}
            onMouseLeave={() => setShowTooltip(false)}
            title={!hasVariants ? "Trait à variantes" : undefined}
        >
            <Layers
                size={14}
                className="text-blue-500"
            />

            {hasVariants && (
                <PortalTooltip
                    anchorRef={anchorRef}
                    isOpen={showTooltip}
                    title="Variantes suggérées"
                >
                    <div className="flex flex-wrap gap-1">
                        {entry.variants?.map((v, i) => (
                            <span key={i} className="bg-slate-700 px-1 rounded-sm border border-slate-600">{v}</span>
                        ))}
                    </div>
                </PortalTooltip>
            )}
        </div>
    );
};

const TraitCardItemEffects: React.FC<{ entry: LibraryEntry }> = ({ entry }) => {
    const [showTooltip, setShowTooltip] = useState(false);
    const anchorRef = useRef<HTMLDivElement>(null);

    const getEffectLabel = (eff: any) => {
        switch (eff.type || eff.effectType) {
            case 'formula': return `Equation : ${eff.target || '?'} = ${eff.formula}`;
            case 'free_skill_rank': return `Rang gratuit : ${eff.target || '?'} (+${eff.value})`;
            case 'master_skill': return `Maître : compétence au rang 5 (choix joueur)`;
            default: return 'Effet spécial actif';
        }
    };

    return (
        <div
            ref={anchorRef}
            className="relative flex items-center justify-center cursor-help"
            onMouseEnter={() => setShowTooltip(true)}
            onMouseLeave={() => setShowTooltip(false)}
        >
            <Zap size={14} className="text-amber-500 fill-amber-500" />

            <PortalTooltip
                anchorRef={anchorRef}
                isOpen={showTooltip}
                title="Effets mécaniques actifs"
            >
                <div className="flex flex-col gap-1 mt-1">
                    {entry.effects?.map((eff, i) => (
                        <div key={i} className={`text-[10px] text-white/90 whitespace-nowrap flex items-center gap-1.5 font-bold`}>
                            <span className="w-1 h-1 bg-amber-400 rounded-full inline-block"></span>
                            {getEffectLabel(eff)}
                        </div>
                    ))}
                </div>
            </PortalTooltip>
        </div>
    );
};

const TraitCardItemCounter: React.FC<{ entry: LibraryEntry }> = ({ entry }) => {
    const [showTooltip, setShowTooltip] = useState(false);
    const anchorRef = useRef<HTMLDivElement>(null);

    return (
        <div
            ref={anchorRef}
            className="relative flex items-center justify-center cursor-help"
            onMouseEnter={() => setShowTooltip(true)}
            onMouseLeave={() => setShowTooltip(false)}
        >
            <Activity size={14} className="text-blue-500" />

            <PortalTooltip
                anchorRef={anchorRef}
                isOpen={showTooltip}
                title="Compteur associé"
            >
                <div className="text-[10px] text-white/90">
                    Ce trait crée automatiquement un compteur "{entry.autoCounterName || entry.name}"
                </div>
            </PortalTooltip>
        </div>
    );
};

const TraitCardItemXP: React.FC<{ entry: LibraryEntry }> = ({ entry }) => {
    const [showTooltip, setShowTooltip] = useState(false);
    const anchorRef = useRef<HTMLDivElement>(null);

    return (
        <div
            ref={anchorRef}
            className="relative flex items-center justify-center cursor-help"
            onMouseEnter={() => setShowTooltip(true)}
            onMouseLeave={() => setShowTooltip(false)}
        >
            <TrendingUp size={14} className="text-emerald-500" />

            <PortalTooltip
                anchorRef={anchorRef}
                isOpen={showTooltip}
                title="Amélioration par XP"
            >
                <div className="text-[10px] text-white/90">
                    Ce trait peut être acquis ou amélioré avec de l'expérience.
                </div>
            </PortalTooltip>
        </div>
    );
};

const TraitCard: React.FC<TraitCardProps> = ({
    entry,
    isEditable,
    isSelected,
    onSelect,
    onMultiSelect,
    onEdit,
    onDelete,
    showMultiSelect,
    source = 'local',
    isLocked = false,
    isPlaced = false,
    isActive = true,
    usageDetails,
    onLoadUsageDetails
}) => {
    const [showDeleteTooltip, setShowDeleteTooltip] = useState(false);
    const [showLockTooltip, setShowLockTooltip] = useState(false);
    const deleteBtnRef = useRef<HTMLDivElement>(null);
    const lockIconRef = useRef<HTMLDivElement>(null);
    if (!entry) return null;

    const hasVariants = entry.variants && entry.variants.length > 0;

    return (
        <div
            className={`p-2 transition-colors group cursor-pointer select-none border-b border-slate-100 last:border-0 flex items-center gap-2 ${isSelected ? 'bg-amber-50/50 hover:bg-amber-100/50' : 'hover:bg-stone-50'} ${!isActive ? 'opacity-60 grayscale' : ''}`}
            onClick={() => {
                if (showMultiSelect && onMultiSelect) {
                    onMultiSelect(entry.id);
                } else if (onSelect) {
                    onSelect(entry);
                }
            }}
        >
            {/* 1. Toggle / Type Indicator (Fixed width) */}
            <div className="w-8 flex flex-col items-center justify-center shrink-0 gap-1">
                {showMultiSelect ? (
                    <div className="text-[#8b2e2e]">
                        {isSelected ? <CheckSquare size={16} /> : <Square size={16} className="text-[#bfae85]" />}
                    </div>
                ) : (
                    <div className={`w-2.5 h-2.5 rounded-full ${entry.type === 'avantage' ? 'bg-green-600' : 'bg-[#8b2e2e]'}`} title={entry.type === 'avantage' ? 'Avantage' : 'Désavantage'} />
                )}
            </div>

            {/* 2. Status Icons (Fixed width) */}
            <div className="w-16 flex items-center gap-1 shrink-0">
                {entry.isVariable && <TraitCardItemVariants entry={entry} hasVariants={!!hasVariants} />}
                {source === 'official' && <div title="Trait Officiel"><Globe size={14} className="text-indigo-500" /></div>}
                {entry.effects && entry.effects.length > 0 && <TraitCardItemEffects entry={entry} />}
                {entry.hasAutoCounter && <TraitCardItemCounter entry={entry} />}
                {entry.isXPUpgradeable && <TraitCardItemXP entry={entry} />}
                {isLocked && (
                    <div
                        ref={lockIconRef}
                        onMouseEnter={() => {
                            if (isLocked && !isPlaced && onLoadUsageDetails) {
                                onLoadUsageDetails(entry.id);
                            }
                            setShowLockTooltip(true);
                        }}
                        onMouseLeave={() => setShowLockTooltip(false)}
                        className="relative flex items-center"
                        title={isPlaced ? "Utilisé dans cette campagne" : undefined}
                    >
                        <Lock size={14} className="text-amber-600" />
                        <UsageLockedTooltip
                            anchorRef={lockIconRef}
                            isOpen={showLockTooltip}
                            isLocked={isLocked}
                            isPlaced={isPlaced}
                            usageDetails={usageDetails}
                        />
                    </div>
                )}
            </div>

            {/* 3. Content (Flexible) */}
            <div className="flex-grow overflow-hidden pr-2">
                <div className="flex justify-between items-baseline gap-2">
                    <span className={`font-bold text-sm truncate ${isSelected ? 'text-amber-900' : 'text-[#4a3b32]'} ${!isActive ? 'line-through text-slate-500' : ''}`} title={entry.name}>
                        {entry.name}
                    </span>
                    <span className="text-[10px] font-mono font-bold text-[#5c4d41] bg-[#bfae85]/20 px-1 rounded-sm border border-[#bfae85]/10 shrink-0">
                        {entry.pointsLabel || entry.cost} pts
                    </span>
                </div>
                {entry.description && (
                    <div className="text-[10px] text-[#5c4d41]/70 italic truncate" title={entry.description}>
                        {entry.description}
                    </div>
                )}
                {/* Tags displayed on hover or if space allows? Let's keep them compact */}
                {entry.tags && entry.tags.length > 0 && (
                    <div className="flex flex-wrap gap-1 mt-0.5">
                        {entry.tags.slice(0, 3).map(tag => (
                            <span key={tag} className="text-[8px] bg-stone-100 text-[#5c4d41]/60 px-1 rounded-sm border border-stone-200">
                                #{tag}
                            </span>
                        ))}
                    </div>
                )}
            </div>

            {/* 4. Actions (Fixed width) */}
            <div className="w-16 flex justify-end gap-1 opacity-0 group-hover:opacity-100 transition-opacity shrink-0">
                {isEditable && (
                    <>
                        <button
                            onClick={(e) => { e.stopPropagation(); onEdit(entry); }}
                            className="p-1 text-blue-600 hover:bg-blue-50 rounded"
                            title="Éditer"
                        >
                            <Edit2 size={14} />
                        </button>
                        <button
                            onClick={(e) => { e.stopPropagation(); onDelete(entry.id); }}
                            disabled={isLocked}
                            className={`p-1 rounded ${isLocked ? 'text-stone-300' : 'text-red-600 hover:bg-red-50'}`}
                            title={!isLocked ? "Supprimer" : undefined}
                        >
                            <Trash2 size={14} />
                        </button>
                    </>
                )}
                {onSelect && !showMultiSelect && (
                    <button
                        onClick={(e) => { e.stopPropagation(); onSelect(entry); }}
                        className="p-1 text-green-700 hover:bg-green-50 rounded border border-green-200 shadow-sm bg-white"
                        title="Ajouter à la fiche"
                    >
                        <Plus size={14} />
                    </button>
                )}
            </div>
        </div>
    );
};

export default TraitCard;

import React from 'react';
import { LibraryEntry, TraitEffect, LibraryFormulaEntry } from '../../types';
import { Edit2, Plus, X, AlignLeft, Save, AlertCircle, Coins, Info, Sparkles } from 'lucide-react';
import TraitEffectEditor from './TraitEffectEditor';
import ThematicModal from '../ui/ThematicModal';

interface TraitFormProps {
    editForm: LibraryEntry;
    library: LibraryEntry[];
    allSkills: { id: string, name: string }[];
    allAttributes: { id: string, name: string }[];
    allCounters: { id: string, name: string }[];
    allFormulas?: LibraryFormulaEntry[];
    tagInput: string;
    error: string | null;
    setEditForm: (entry: LibraryEntry | null) => void;
    setTagInput: (val: string) => void;
    onClose: () => void;
    onSave: (updatedTrait?: LibraryEntry) => void;
    addTag: () => void;
    removeTag: (tag: string) => void;
    addEffect: () => void;
    updateEffect: <K extends keyof TraitEffect>(id: string, field: K, value: TraitEffect[K]) => void;
    updateEffectFields?: (id: string, updates: Partial<TraitEffect>) => void;
    removeEffect: (id: string) => void;
}


const TraitForm: React.FC<TraitFormProps> = ({
    editForm,
    library,
    allSkills,
    allAttributes,
    allCounters,
    allFormulas,
    tagInput,
    error,
    setEditForm,
    setTagInput,
    onClose,
    onSave,
    addTag,
    removeTag,
    addEffect,
    updateEffect,
    updateEffectFields,
    removeEffect
}) => {
    const [variantDraft, setVariantDraft] = React.useState(editForm.variants?.join(', ') || '');

    // Logic for "Smart Cost Information"
    const parsedCostInfo = React.useMemo(() => {
        const val = editForm.pointsLabel?.toString() || '';
        if (!val.trim()) return { type: 'none', label: 'Aucun coût défini' };

        // 1. Simple Number (Fixed)
        if (/^\d+$/.test(val.trim())) {
            return { type: 'fixed', label: `Prix fixe : ${val} pts`, color: 'text-emerald-600' };
        }

        // 2. Range (1-5)
        if (/[-,–—]/.test(val) || val.includes('..')) {
            const nums = val.match(/\d+/g);
            if (nums && nums.length >= 2) {
                return { type: 'range', label: `Plage de ${nums[0]} à ${nums[1]} pts`, color: 'text-amber-600' };
            }
        }

        // 3. List (1, 3, 5)
        if (val.includes(',') || val.includes(';')) {
            const nums = val.match(/\d+/g);
            if (nums && nums.length > 0) {
                return { type: 'list', label: `Choix multiples : ${nums.join(', ')} pts`, color: 'text-blue-600' };
            }
        }

        return { type: 'text', label: 'Coût narratif / Spécial', color: 'text-stone-500' };
    }, [editForm.pointsLabel]);

    React.useEffect(() => {
        setVariantDraft(editForm.variants?.join(', ') || '');
    }, [editForm.id, editForm.variants?.join(',')]);

    const handleSave = () => {
        const cleaned = variantDraft.split(',').map(v => v.trim()).filter(Boolean);
        const finalForm = { ...editForm, variants: cleaned };

        // Update local state just in case, but pass final version to onSave immediately
        setEditForm(finalForm);
        onSave(finalForm);
    };
    const isNew = !library.some(l => l.id === editForm.id);

    return (
        <ThematicModal
            isOpen={true}
            onClose={onClose}
            title={isNew ? 'Nouveau Trait' : 'Éditer le Trait'}
            icon={isNew ? <Plus size={20} /> : <Edit2 size={20} />}
            size="md"
            footer={
                <>
                    <button
                        onClick={onClose}
                        className="px-5 py-2 text-[#5c4d41] hover:bg-stone-200/50 rounded-sm font-bold transition-colors"
                    >
                        Annuler
                    </button>
                    <button
                        onClick={handleSave}
                        className={`px-6 py-2 text-white rounded-sm font-bold shadow-md flex items-center gap-2 transition-transform hover:scale-105 ${editForm.type === 'avantage' ? 'bg-[#2d5a27] hover:bg-[#1e3d1a]' : 'bg-[#8b2e2e] hover:bg-[#6a2424]'}`}
                    >
                        <Save size={18} />
                        Enregistrer
                    </button>
                </>
            }
        >
            <div className="flex flex-col gap-6 py-2">

                {/* Type Switcher */}
                <div className="flex justify-center mb-2">
                    <div className="bg-stone-200/50 p-1 rounded-sm flex shadow-inner border border-[#bfae85]/30">
                        <button
                            onClick={() => setEditForm({ ...editForm, type: 'avantage' })}
                            className={`px-6 py-2 rounded-sm text-xs font-serif font-black uppercase tracking-widest transition-all ${editForm.type === 'avantage' ? 'bg-[#2d5a27] text-white shadow-md' : 'text-[#5c4d41] hover:text-stone-800'}`}
                        >
                            Avantage
                        </button>
                        <button
                            onClick={() => setEditForm({ ...editForm, type: 'desavantage' })}
                            className={`px-6 py-2 rounded-sm text-xs font-serif font-black uppercase tracking-widest transition-all ${editForm.type === 'desavantage' ? 'bg-[#8b2e2e] text-white shadow-md' : 'text-[#5c4d41] hover:text-stone-800'}`}
                        >
                            Désavantage
                        </button>
                    </div>
                </div>

                {/* Name & Cost (Smart Input) */}
                <div className="grid grid-cols-2 gap-4">
                    <div className="col-span-1">
                        <label className="block text-[10px] font-bold text-[#bfae85] uppercase mb-1.5 tracking-widest">Nom du Trait</label>
                        <input
                            className="w-full border border-[#bfae85]/50 rounded-sm px-3 py-2 font-serif font-black text-[#1c1917] bg-white/50 focus:border-amber-500 outline-none shadow-sm placeholder-stone-300"
                            value={editForm.name}
                            onChange={(e) => setEditForm({ ...editForm, name: e.target.value })}
                            placeholder="Ex: Chance, Ennemi..."
                        />
                    </div>
                    <div className="col-span-1 relative">
                        <label className="block text-[10px] font-bold text-[#bfae85] uppercase mb-1.5 tracking-widest flex items-center justify-between">
                            <span>Coût / Valeur</span>
                            <div className="group relative">
                                <Info size={12} className="text-[#bfae85] cursor-help" />
                                <div className="absolute right-0 bottom-full mb-2 w-48 bg-stone-800 text-white text-[9px] p-2 rounded shadow-lg opacity-0 group-hover:opacity-100 pointer-events-none transition-opacity z-10 font-sans normal-case tracking-normal leading-normal">
                                    Saisissez un nombre (ex: 3), une plage (ex: 1-5) ou une liste (ex: 1, 3, 5).
                                </div>
                            </div>
                        </label>
                        <div className="relative">
                            <input
                                className="w-full border border-[#bfae85]/50 rounded-sm pl-8 pr-3 py-2 font-mono focus:border-amber-500 outline-none text-[#1c1917] bg-white/50 shadow-sm font-bold"
                                value={editForm.pointsLabel}
                                onChange={(e) => {
                                    const val = e.target.value;
                                    const firstNumMatch = val.match(/\d+/);
                                    const firstNum = firstNumMatch ? firstNumMatch[0] : '0';
                                    const isVar = /[-,–—,;]/.test(val) || val.includes('..');

                                    setEditForm({
                                        ...editForm,
                                        pointsLabel: val,
                                        cost: firstNum,
                                        isVariableCost: isVar
                                    });
                                }}
                                placeholder="ex: 1-5"
                            />
                            <Coins size={14} className="absolute left-2.5 top-1/2 -translate-y-1/2 text-[#bfae85]" />
                        </div>

                        {/* Cost Helper Legend */}
                        <div className={`text-[9px] mt-1.5 font-bold flex items-center gap-1.5 ${parsedCostInfo.color} animate-in fade-in slide-in-from-left-1 duration-300`}>
                            <div className={`w-1.5 h-1.5 rounded-full bg-current opacity-40`} />
                            {parsedCostInfo.label}
                        </div>
                    </div>
                </div>

                {/* Description */}
                <div>
                    <label className="block text-[10px] font-bold text-[#bfae85] uppercase mb-1.5 tracking-widest flex items-center gap-1"><AlignLeft size={12} /> Description Narrative</label>
                    <textarea
                        className="w-full border border-[#bfae85]/50 rounded-sm px-3 py-3 text-sm text-[#1c1917] bg-white/50 min-h-[100px] focus:border-amber-500 outline-none resize-y placeholder-stone-300 italic leading-relaxed shadow-sm"
                        value={editForm.description || ""}
                        onChange={(e) => setEditForm({ ...editForm, description: e.target.value })}
                        placeholder="Décrivez les effets narratifs ou les conditions d'utilisation..."
                    />
                </div>

                {/* Tags */}
                <div>
                    <label className="block text-[10px] font-bold text-[#bfae85] uppercase mb-1.5 tracking-widest">Catégories (Tags)</label>
                    <div className="flex gap-2 mb-3">
                        <input
                            className="flex-grow border border-[#bfae85]/50 rounded-sm px-3 py-2 text-sm text-[#1c1917] bg-white/50 focus:border-amber-500 outline-none shadow-sm"
                            value={tagInput}
                            onChange={(e) => setTagInput(e.target.value)}
                            onKeyDown={(e) => e.key === 'Enter' && (e.preventDefault(), addTag())}
                            placeholder="Ajouter une catégorie..."
                        />
                        <button onClick={addTag} className="bg-stone-200 hover:bg-stone-300 text-[#5c4d41] px-4 py-2 rounded-sm text-sm font-bold transition-colors">
                            +
                        </button>
                    </div>
                    <div className="flex flex-wrap gap-1.5">
                        {(editForm.tags || []).map(tag => (
                            <span key={tag} className="bg-amber-100/50 text-[#845d3e] px-2.5 py-1 rounded-sm text-[10px] font-bold flex items-center gap-1.5 border border-amber-200/50 shadow-sm">
                                {tag}
                                <button onClick={() => removeTag(tag)} className="hover:text-[#8b2e2e] transition-colors"><X size={12} /></button>
                            </span>
                        ))}
                    </div>
                </div>

                {/* Configuration: Auto Counter */}
                <div className="border rounded-sm p-3 flex items-center gap-3 bg-[#bfae85]/10 border-[#bfae85]/30">
                    <div className="relative flex items-center">
                        <input
                            type="checkbox"
                            id="hasAutoCounter"
                            className="w-4 h-4 cursor-pointer accent-amber-600"
                            checked={editForm.hasAutoCounter || false}
                            onChange={(e) => setEditForm({ ...editForm, hasAutoCounter: e.target.checked })}
                        />
                    </div>
                    <label htmlFor="hasAutoCounter" className="cursor-pointer select-none flex-grow">
                        <span className="text-sm font-bold text-[#5c4d41]">Créer un compteur associé</span>
                        <span className="block text-[10px] text-[#5c4d41]/70 italic">
                            Ajoute automatiquement un compteur à "carrés" sur la fiche quand le trait est choisi.
                        </span>
                    </label>
                </div>

                {editForm.hasAutoCounter && (
                    <div className="animate-in fade-in slide-in-from-top-2 duration-200 -mt-4 px-1">
                        <label className="block text-[10px] font-bold text-[#bfae85] uppercase mb-1 tracking-widest">Nom du compteur (Optionnel)</label>
                        <input
                            className="w-full border border-[#bfae85]/50 rounded-sm px-3 py-2 text-xs text-[#1c1917] bg-[#fdfbf7] focus:border-amber-500 outline-none shadow-sm font-bold placeholder:italic placeholder:font-normal"
                            value={editForm.autoCounterName || ''}
                            onChange={(e) => setEditForm({ ...editForm, autoCounterName: e.target.value })}
                            placeholder="Laisser vide pour utiliser le nom du trait"
                        />
                    </div>
                )}

                {/* Configuration: XP Upgradeable */}
                <div className="border rounded-sm p-3 flex items-center gap-3 bg-[#bfae85]/10 border-[#bfae85]/30">
                    <div className="relative flex items-center">
                        <input
                            type="checkbox"
                            id="isXPUpgradeable"
                            className="w-4 h-4 cursor-pointer accent-amber-600"
                            checked={editForm.isXPUpgradeable || false}
                            onChange={(e) => setEditForm({ ...editForm, isXPUpgradeable: e.target.checked })}
                        />
                    </div>
                    <label htmlFor="isXPUpgradeable" className="cursor-pointer select-none flex-grow">
                        <span className="text-sm font-bold text-[#5c4d41]">Peut être acheté / amélioré avec XP</span>
                        <span className="block text-[10px] text-[#5c4d41]/70 italic">
                            Permet de dépenser de l'expérience pour acquérir ou augmenter ce trait.
                        </span>
                    </label>
                </div>

                {/* Configuration: Variable Trait */}
                {(() => {
                    const isForcedByFormula = (editForm.effects || []).some(ef => {
                        if (!ef.formulaId) return false;
                        const formula = (allFormulas || []).find(f => f.id === ef.formulaId);
                        return formula?.forceVariant;
                    });

                    return (
                        <div className={`border rounded-sm p-3 flex items-center gap-3 transition-all ${isForcedByFormula ? 'bg-indigo-50/50 border-indigo-200 shadow-sm' : 'bg-[#bfae85]/10 border-[#bfae85]/30'}`}>
                            <div className="relative flex items-center">
                                <input
                                    type="checkbox"
                                    id="isVariable"
                                    className={`w-4 h-4 cursor-pointer ${isForcedByFormula ? 'accent-indigo-600' : 'accent-amber-600'}`}
                                    checked={editForm.isVariable || false}
                                    disabled={isForcedByFormula}
                                    onChange={(e) => setEditForm({ ...editForm, isVariable: e.target.checked })}
                                />
                            </div>
                            <label htmlFor="isVariable" className="cursor-pointer select-none flex-grow">
                                <div className="flex items-center gap-2">
                                    <span className={`text-sm font-bold ${isForcedByFormula ? 'text-indigo-900' : 'text-[#5c4d41]'}`}>Trait à Complément / Variable</span>
                                    {isForcedByFormula && (
                                        <span className="flex items-center gap-1 px-1.5 py-0.5 rounded-full bg-indigo-600 text-[8px] text-white font-black tracking-tighter uppercase animate-in zoom-in-75">
                                            <Sparkles size={8} /> FORCÉ
                                        </span>
                                    )}
                                </div>
                                <span className="block text-[10px] text-[#5c4d41]/70 italic">
                                    {isForcedByFormula
                                        ? "Ce trait nécessite une variante car l'une de ses formules l'exige."
                                        : "Cochez si le joueur doit préciser quelque chose à la sélection (ex: \"Allergie : Chats\")."}
                                </span>
                            </label>
                        </div>
                    );
                })()}

                {editForm.isVariable && (
                    <div className="animate-in fade-in slide-in-from-top-2 duration-200 -mt-4 px-1">
                        <label className="block text-[10px] font-bold text-[#bfae85] uppercase mb-1 tracking-widest">Variantes suggérées (Réserve)</label>
                        <input
                            className="w-full border border-[#bfae85]/50 rounded-sm px-3 py-2 text-xs text-[#1c1917] bg-[#fdfbf7] focus:border-amber-500 outline-none shadow-sm font-bold placeholder:italic placeholder:font-normal"
                            value={variantDraft}
                            onChange={(e) => setVariantDraft(e.target.value)}
                            onBlur={() => {
                                const cleaned = variantDraft.split(',').map(v => v.trim()).filter(Boolean);
                                setEditForm({ ...editForm, variants: cleaned });
                            }}
                            placeholder="Ex: Chats, Pollen, Poussière..."
                        />
                        <p className="text-[9px] text-[#5c4d41]/70 mt-1 italic px-1">Séparez par des virgules. Ces options seront proposées lors de l'édition du trait sur la fiche perso.</p>
                    </div>
                )}

                {/* Effects Section */}
                <div className="border border-[#bfae85]/20 rounded-sm bg-white/30">
                    <TraitEffectEditor
                        effects={editForm.effects || []}
                        allSkills={allSkills}
                        allAttributes={allAttributes}
                        allCounters={allCounters}
                        allFormulas={allFormulas}
                        onAdd={addEffect}
                        onUpdate={updateEffect}
                        onUpdateFields={updateEffectFields}
                        onRemove={removeEffect}
                    />
                </div>

                {error && (
                    <div className="bg-[#8b2e2e]/5 border border-[#8b2e2e]/20 text-[#8b2e2e] px-4 py-3 rounded-sm flex items-center gap-3 text-xs font-bold animate-shake">
                        <AlertCircle size={18} />
                        <span>{error}</span>
                    </div>
                )}

            </div>
        </ThematicModal>
    );
};

export default TraitForm;

import React, { useState, useMemo } from 'react';
import { CharacterSheetData, LibraryEntry, TraitEntry } from '../../types';
import { Check, X, ArrowRight, RefreshCw, PlusCircle, AlertCircle } from 'lucide-react';

interface TraitImportModalProps {
    data: CharacterSheetData;
    onClose: () => void;
    onImport: (entries: LibraryEntry[]) => void;
}

const TraitImportModal: React.FC<TraitImportModalProps> = ({ data, onClose, onImport }) => {
    // Combine Avantages and Desavantages from sheet
    const sheetTraits = useMemo(() => {
        const traits: { entry: TraitEntry, type: 'avantage' | 'desavantage', id: string, status: 'new' | 'update' | 'same' }[] = [];

        const processList = (list: TraitEntry[], type: 'avantage' | 'desavantage') => {
            list.forEach((t, i) => {
                if (!t.name.trim()) return;

                // Check if exists in library (by name AND type)
                const existingLibEntry = (data.library || []).find(l =>
                    l.name.toLowerCase() === t.name.trim().toLowerCase() &&
                    l.type === type
                );

                let status: 'new' | 'update' | 'same' = 'new';
                if (existingLibEntry) {
                    // Check if content is different (Value, Description, Tag)
                    const isDifferent =
                        existingLibEntry.cost !== t.value ||
                        (existingLibEntry.description || '') !== (t.description || '') ||
                        (existingLibEntry.tags?.[0] || '') !== (t.tag || '');

                    status = isDifferent ? 'update' : 'same';
                }

                traits.push({
                    entry: t,
                    type,
                    id: `${type}-${i}`, // Temporary ID for selection
                    status
                });
            });
        };

        processList(data.page2.avantages, 'avantage');
        processList(data.page2.desavantages, 'desavantage');

        return traits;
    }, [data.page2, data.library]);

    const [selectedIds, setSelectedIds] = useState<string[]>([]);

    const toggleSelection = (id: string) => {
        setSelectedIds(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
    };

    const toggleAll = () => {
        if (selectedIds.length === sheetTraits.length) {
            setSelectedIds([]);
        } else {
            setSelectedIds(sheetTraits.map(t => t.id));
        }
    };

    const handleImport = () => {
        const selectedTraits = sheetTraits.filter(t => selectedIds.includes(t.id));

        const libraryEntries: LibraryEntry[] = selectedTraits.map(t => {
            // Find existing to reuse ID if updating
            const existing = (data.library || []).find(l => l.name.toLowerCase() === t.entry.name.toLowerCase() && l.type === t.type);

            return {
                id: existing ? existing.id : Math.random().toString(36).substr(2, 9),
                type: t.type,
                name: t.entry.name,
                cost: t.entry.value,
                pointsLabel: `${t.entry.value} points`,
                description: t.entry.description || '',
                tags: t.entry.tag ? [t.entry.tag] : [],
                effects: existing ? existing.effects : [] // Preserve effects on update? Or clear? Strategy: Preserve.
            };
        });

        onImport(libraryEntries);
        onClose();
    };

    return (
        <div className="fixed inset-0 bg-black/60 z-[100] flex items-center justify-center p-4 backdrop-blur-sm animate-in fade-in duration-200">
            <div className="bg-white rounded-xl shadow-2xl w-full max-w-2xl h-[80vh] flex flex-col overflow-hidden">
                <div className="p-4 bg-blue-700 text-white flex justify-between items-center shrink-0">
                    <h3 className="font-bold text-lg flex items-center gap-2"><ArrowRight size={20} /> Importer depuis la Fiche</h3>
                    <button onClick={onClose} className="hover:bg-white/20 p-1 rounded transition-colors"><X size={24} /></button>
                </div>

                <div className="p-4 bg-blue-50 border-b border-blue-100 text-blue-800 text-sm flex items-start gap-3">
                    <AlertCircle size={20} className="shrink-0 mt-0.5" />
                    <p>
                        Sélectionnez les traits présents sur votre fiche de personnage que vous souhaitez ajouter ou mettre à jour dans la bibliothèque.
                        Les traits marqués "<span className="font-bold">Mise à jour</span>" existent déjà mais ont des valeurs différentes sur votre fiche.
                    </p>
                </div>

                <div className="flex-grow overflow-y-auto p-2 bg-gray-50">
                    {sheetTraits.length === 0 ? (
                        <div className="text-center text-gray-400 py-10 italic">Aucun trait trouvé sur la fiche.</div>
                    ) : (
                        <div className="space-y-2">
                            <div className="flex items-center gap-2 px-3 py-2 bg-white border-b border-gray-200 sticky top-0 z-10 shadow-sm">
                                <input type="checkbox" checked={selectedIds.length === sheetTraits.length && sheetTraits.length > 0} onChange={toggleAll} className="w-4 h-4 rounded border-gray-300 text-blue-600 focus:ring-blue-500" />
                                <span className="text-sm font-bold text-gray-700">Tout sélectionner ({sheetTraits.length})</span>
                            </div>

                            {sheetTraits.map(item => (
                                <div key={item.id} onClick={() => toggleSelection(item.id)} className={`flex items-center gap-3 p-3 rounded border cursor-pointer transition-colors ${selectedIds.includes(item.id) ? 'bg-blue-50 border-blue-300 ring-1 ring-blue-300' : 'bg-white border-gray-200 hover:border-blue-300'}`}>
                                    <input type="checkbox" checked={selectedIds.includes(item.id)} onChange={() => { }} className="w-4 h-4 rounded border-gray-300 text-blue-600 focus:ring-blue-500 pointer-events-none" />

                                    <div className="flex-grow min-w-0">
                                        <div className="flex items-center gap-2 mb-1">
                                            <span className={`text-xs font-bold uppercase px-1.5 py-0.5 rounded ${item.type === 'avantage' ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'}`}>
                                                {item.type === 'avantage' ? 'AV' : 'DÉS'}
                                            </span>
                                            <span className="font-bold text-gray-900 truncate">{item.entry.name}</span>
                                            <span className="font-mono text-xs bg-gray-100 px-1.5 rounded border border-gray-200">{item.entry.value} pts</span>
                                        </div>
                                        {item.entry.description && <p className="text-xs text-gray-600 truncate">{item.entry.description}</p>}
                                        {item.entry.tag && <span className="inline-block mt-1 text-[10px] bg-slate-100 text-slate-600 px-1.5 rounded border border-slate-200">{item.entry.tag}</span>}
                                    </div>

                                    <div className="shrink-0">
                                        {item.status === 'new' && <span className="flex items-center gap-1 text-xs font-bold text-green-600 bg-green-50 px-2 py-1 rounded-full"><PlusCircle size={12} /> Nouveau</span>}
                                        {item.status === 'update' && <span className="flex items-center gap-1 text-xs font-bold text-amber-600 bg-amber-50 px-2 py-1 rounded-full"><RefreshCw size={12} /> Mise à jour</span>}
                                        {item.status === 'same' && <span className="text-xs text-gray-400 px-2">Identique</span>}
                                    </div>
                                </div>
                            ))}
                        </div>
                    )}
                </div>

                <div className="p-4 bg-gray-100 border-t border-gray-200 flex justify-end gap-3 shrink-0">
                    <button onClick={onClose} className="px-4 py-2 text-gray-700 font-medium hover:bg-gray-200 rounded-lg transition-colors">Annuler</button>
                    <button
                        onClick={handleImport}
                        disabled={selectedIds.length === 0}
                        className="px-6 py-2 bg-blue-600 text-white font-bold rounded-lg shadow hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2 transition-all"
                    >
                        <Check size={18} /> Importer ({selectedIds.length})
                    </button>
                </div>
            </div>
        </div>
    );
};

export default TraitImportModal;

import React, { useState, useMemo } from 'react';
import { X, Settings, Check, Sparkles } from 'lucide-react';
import { LibraryEntry, LibraryFormulaEntry } from '../../types';
import { normalizeString } from '../../utils/stringUtils';

interface TraitVariantPickerProps {
    variantPicker: LibraryEntry;
    onClose: () => void;
    onSelect: (entry: LibraryEntry, variant: string, cost?: string) => void;
    allFormulas?: LibraryFormulaEntry[];
    allSkills?: any[];
    allAttributes?: any[];
}

const TraitVariantPicker: React.FC<TraitVariantPickerProps> = ({
    variantPicker, onClose, onSelect,
    allFormulas = [], allSkills = [], allAttributes = []
}) => {
    const [customVariant, setCustomVariant] = useState('');
    const [selectedCost, setSelectedCost] = useState(variantPicker.pointsLabel || (variantPicker as any).points_label || variantPicker.cost);

    // Unified variable cost detection (hyphen, en-dash, em-dash, comma, semicolon, dots)
    const isVariableCost = useMemo(() => {
        if (variantPicker.isVariableCost || (variantPicker as any).is_variable_cost) return true;
        const label = variantPicker.pointsLabel || (variantPicker as any).points_label || variantPicker.cost;
        if (!label) return false;
        return /[-,–—,;]/.test(label) || label.includes('..');
    }, [variantPicker]);

    const isVariable = variantPicker.isVariable || (variantPicker as any).is_variable;

    // Suggestions for costs if it's a range (1-3) or list (1, 3, 5)
    const costSuggestions = useMemo(() => {
        if (!isVariableCost) return [];
        const label = variantPicker.pointsLabel || (variantPicker as any).points_label || variantPicker.cost;
        if (!label) return [];

        const numbers = label.match(/\d+/g);
        if (!numbers || numbers.length < 2) return [];

        // Handle Range: 1-3, 1..3, 1–3
        if (label.includes('-') || label.includes('..') || label.includes('–')) {
            const start = parseInt(numbers[0]);
            const end = parseInt(numbers[1]);
            // Limit range to 10 items to avoid UI clutter
            if (isNaN(start) || isNaN(end) || end < start || end - start > 10) return numbers;
            return Array.from({ length: end - start + 1 }, (_, i) => (start + i).toString());
        }

        // Handle List: 1, 3, 5
        return numbers;
    }, [isVariableCost, variantPicker.cost, variantPicker.pointsLabel, (variantPicker as any).points_label]);

    // New: Dynamic suggestions based on Force Variant formulas
    const dynamicSuggestions = useMemo(() => {
        const forceEffect = variantPicker.effects?.find(eff => {
            if (!eff.formulaId) return false;
            const formula = allFormulas.find(f => f.id === eff.formulaId);
            return formula?.forceVariant;
        });

        if (!forceEffect) return [];

        const formula = allFormulas.find(f => f.id === forceEffect.formulaId);
        const targetRaw = formula?.target || "";
        const targetClean = normalizeString(targetRaw);

        if (targetClean === 'competence') return allSkills.map(s => s.name);
        if (targetClean === 'attribut') return allAttributes.map(a => a.name);

        // Filter by category if target matches a category name
        const byCategory = allSkills.filter(s => normalizeString(s.category || "") === targetClean);
        if (byCategory.length > 0) return byCategory.map(s => s.name);

        return [];
    }, [variantPicker, allFormulas, allSkills, allAttributes]);

    // Combiner les variantes statiques du trait et les suggestions dynamiques
    const allVariantSuggestions = useMemo(() => {
        const statics = variantPicker.variants || [];
        const combined = [...statics, ...dynamicSuggestions];
        // Dédupliquer par nom
        return Array.from(new Set(combined));
    }, [variantPicker.variants, dynamicSuggestions]);

    const handleConfirm = (variant: string) => {
        let finalCost = selectedCost;

        // If user didn't change the range string (e.g. "1-3"), try to pick the first number
        const originalLabel = variantPicker.pointsLabel || (variantPicker as any).points_label || variantPicker.cost;
        if (isVariableCost && finalCost === originalLabel) {
            const match = finalCost.match(/\d+/);
            if (match) finalCost = match[0];
        }

        onSelect(variantPicker, variant.trim(), finalCost);
    };

    return (
        <div className="fixed inset-0 bg-black/40 z-[120] flex items-center justify-center p-4 backdrop-blur-[2px] animate-in fade-in duration-200">
            <div className="bg-white rounded-lg shadow-xl w-full max-w-sm overflow-hidden animate-in zoom-in-95 duration-200 border border-stone-200">
                <div className="p-4 border-b bg-stone-50 flex justify-between items-center">
                    <h4 className="font-bold text-stone-800 flex items-center gap-2">
                        <Settings size={18} className="text-blue-600" />
                        Configuration du Trait
                    </h4>
                    <button onClick={onClose} className="text-stone-400 hover:text-stone-600 transition-colors"><X size={20} /></button>
                </div>

                <div className="p-5 space-y-6">
                    {/* Trait Summary */}
                    <div className="bg-stone-50 p-3 rounded border border-stone-200">
                        <div className="text-sm font-bold text-stone-900">{variantPicker.name}</div>
                        <div className="text-[10px] text-stone-500 uppercase font-bold mt-1 tracking-tight">
                            {variantPicker.type === 'avantage' ? 'Avantage' : 'Désavantage'} • {selectedCost} {selectedCost === "1" ? "pt" : "pts"}
                        </div>
                    </div>

                    {/* Cost Selector (if variable) */}
                    {isVariableCost && (
                        <div className="space-y-3 bg-blue-50/50 p-3 rounded border border-blue-100">
                            <label className="block text-[10px] font-bold text-blue-800 uppercase tracking-wider">Valeur</label>

                            {/* Suggested costs as buttons */}
                            {costSuggestions.length > 0 && (
                                <div className="flex flex-wrap gap-1.5 mb-2">
                                    {costSuggestions.map((c: string) => (
                                        <button
                                            key={c}
                                            onClick={() => setSelectedCost(c)}
                                            className={`px-3 py-1 text-xs font-bold rounded border transition-all ${selectedCost === c ? 'bg-blue-600 text-white border-blue-600' : 'bg-white text-gray-600 border-gray-200 hover:border-blue-400'}`}
                                        >
                                            {c}
                                        </button>
                                    ))}
                                </div>
                            )}

                            <div className="flex gap-2">
                                <input
                                    type="text"
                                    placeholder="Valeur choisie..."
                                    className="flex-grow border border-stone-200 rounded px-3 py-1.5 text-sm focus:border-blue-500 outline-none font-mono"
                                    value={selectedCost}
                                    onChange={(e) => setSelectedCost(e.target.value)}
                                    autoFocus={isVariableCost}
                                />
                            </div>
                        </div>
                    )}

                    {/* Variant Section */}
                    {(isVariable || allVariantSuggestions.length > 0) ? (
                        <div className="space-y-3">
                            <label className="block text-[10px] font-bold text-stone-500 uppercase tracking-wider">Précision / Variant (Ex: Alcool, Chats...)</label>
                            <div className="flex gap-2">
                                <input
                                    type="text"
                                    className="flex-grow border border-stone-200 rounded px-3 py-1.5 text-sm focus:border-blue-500 outline-none"
                                    placeholder="Saisir un variant..."
                                    value={customVariant}
                                    onChange={(e) => setCustomVariant(e.target.value)}
                                    autoFocus={!isVariableCost}
                                    onKeyDown={(e) => {
                                        if (e.key === 'Enter') handleConfirm(customVariant);
                                        if (e.key === 'Escape') onClose();
                                    }}
                                />
                                <button
                                    onClick={() => handleConfirm(customVariant)}
                                    className="bg-blue-600 text-white px-4 py-1.5 rounded text-sm font-bold hover:bg-blue-700 transition-colors shadow-sm flex items-center gap-1"
                                >
                                    <Check size={16} /> OK
                                </button>
                            </div>

                            {/* Suggested Variants */}
                            {allVariantSuggestions.length > 0 && (
                                <div className="flex flex-wrap gap-2 mt-2 max-h-32 overflow-y-auto p-1 bg-stone-50/50 rounded border border-stone-100 no-scrollbar">
                                    {allVariantSuggestions.map(v => (
                                        <button
                                            key={v}
                                            onClick={() => {
                                                if (isVariableCost) {
                                                    setCustomVariant(v);
                                                } else {
                                                    handleConfirm(v);
                                                }
                                            }}
                                            className={`px-3 py-1.5 rounded-full text-xs font-medium transition-colors border ${customVariant === v ? 'bg-blue-100 text-blue-800 border-blue-300' : 'bg-stone-100 hover:bg-stone-200 text-stone-700 border-stone-200'}`}
                                        >
                                            {v}
                                        </button>
                                    ))}
                                </div>
                            )}
                        </div>
                    ) : (
                        /* No variants defined, but variable cost: Show a centered confirmation button */
                        isVariableCost && (
                            <div className="flex flex-col items-center gap-4 py-2">
                                <p className="text-[10px] text-stone-400 italic">Ce trait ne nécessite pas de variant, seulement le choix du coût.</p>
                                <button
                                    onClick={() => handleConfirm('')}
                                    className="w-full bg-blue-600 text-white px-6 py-2.5 rounded font-bold hover:bg-blue-700 transition-colors shadow-sm flex items-center justify-center gap-2 animate-in fade-in zoom-in duration-300"
                                >
                                    <Check size={18} /> Confirmer ce trait
                                </button>
                            </div>
                        )
                    )}
                </div>

                <div className="px-5 py-3 bg-stone-50 border-t flex justify-between items-center text-[10px] text-stone-500 italic">
                    <span>* Cliquer sur un bouton ou appuyer sur Entrée</span>
                    <button onClick={onClose} className="text-stone-400 hover:text-stone-600 py-1">Annuler</button>
                </div>
            </div>
        </div>
    );
};

export default TraitVariantPicker;

import React from 'react';
import { ChevronDown, Sparkles, Info, CheckCircle2, Calculator } from 'lucide-react';
import { TraitEffect, LibraryFormulaEntry } from '../../../types';

interface FormulaEffectFieldsProps {
    effect: TraitEffect;
    allFormulas: LibraryFormulaEntry[];
    allAttributes: { id: string; name: string }[];
    allCounters: { id: string; name: string }[];
    onUpdate: (id: string, field: keyof TraitEffect, value: any) => void;
    onUpdateFields?: (id: string, updates: Partial<TraitEffect>) => void;
}

export const FormulaEffectFields: React.FC<FormulaEffectFieldsProps> = ({
    effect,
    allFormulas,
    allAttributes,
    allCounters,
    onUpdate,
    onUpdateFields
}) => {
    const selectedFormulaEntry = allFormulas.find(f => f.id === effect.formulaId);

    return (
        <div className="flex flex-col gap-3">
            <div className="flex flex-col">
                <label className="block text-[9px] font-bold text-indigo-800 mb-1 uppercase tracking-widest flex justify-between items-center">
                    <span>Choisir la Formule Globale</span>
                    <span className="text-[8px] font-normal normal-case opacity-70 italic">Dictionnaire MJ</span>
                </label>
                <div className="relative">
                    <select
                        className="w-full text-xs border border-indigo-400/30 rounded-sm px-2 py-1.5 appearance-none focus:border-indigo-500 outline-none bg-white font-bold text-stone-800 shadow-sm"
                        value={effect.formulaId || ''}
                        onChange={(e) => {
                            const fid = e.target.value;

                            const entry = allFormulas.find(f => f.id === fid);
                            if (entry) {
                                const updates: Partial<TraitEffect> = {
                                    formulaId: fid,
                                    formula: entry.formula
                                };
                                if (entry.target) updates.target = entry.target;
                                if (entry.operator) updates.operator = entry.operator;

                                if (onUpdateFields) {
                                    onUpdateFields(effect.id, updates);
                                } else {
                                    onUpdate(effect.id, 'formulaId', fid);
                                    onUpdate(effect.id, 'formula', entry.formula);
                                    if (entry.target) onUpdate(effect.id, 'target', entry.target);
                                    if (entry.operator) onUpdate(effect.id, 'operator', entry.operator);
                                }
                            } else {
                                onUpdate(effect.id, 'formulaId', fid);
                            }
                        }}
                    >
                        <option value="" className="italic text-stone-500">-- Choisir une mécanique globale --</option>
                        {allFormulas.map(f => (
                            <option key={f.id} value={f.id}>
                                {f.type === 'variable' ? '⭐ ' : '⚙️ '}{f.name}
                                {f.forceVariant ? ' (Forcer Variante)' :
                                    f.effectType === 'block_skill_increase' ? ' (Blocage)' :
                                        f.effectType === 'master_skill' ? ' (Maîtrise)' :
                                            f.formula ? ` (${f.formula})` : ''}
                            </option>
                        ))}
                    </select>
                    <ChevronDown size={12} className="absolute right-2 top-1/2 -translate-y-1/2 pointer-events-none text-indigo-800/40" />
                </div>
            </div>

            {selectedFormulaEntry?.type === 'variable' ? (
                <div className="bg-amber-100/30 p-2 rounded border border-amber-200/50 flex items-start gap-2 animate-in fade-in duration-300">
                    <Info size={14} className="text-amber-700 shrink-0 mt-0.5" />
                    <p className="text-[9px] text-amber-800 leading-tight">
                        Cette formule étant de type <strong>Réserve Joueur</strong> (Automatique), elle s'affichera comme une jauge.
                    </p>
                </div>
            ) : (
                <div className="flex flex-col gap-3 animate-in fade-in duration-300">
                    {(selectedFormulaEntry?.target || selectedFormulaEntry?.forceVariant || (selectedFormulaEntry?.operator && selectedFormulaEntry?.effectType !== 'block_skill_increase' && selectedFormulaEntry?.effectType !== 'master_skill')) && (
                        <div className="bg-indigo-100/10 p-2 rounded border border-indigo-200/20 flex flex-wrap gap-2 items-center">
                            {selectedFormulaEntry.forceVariant ? (
                                <div className="flex flex-col">
                                    <span className="text-[8px] font-bold text-indigo-400 uppercase tracking-tighter">Cible Dynamique</span>
                                    <span className="text-[10px] font-bold text-indigo-700 bg-indigo-50 px-1.5 py-0.5 rounded border border-indigo-200/30 flex items-center gap-1.5">
                                        <Sparkles size={10} className="text-indigo-400" />
                                        Variante du Trait
                                        {selectedFormulaEntry.target && (
                                            <span className="text-[8px] font-normal text-indigo-400 italic">(Suggestions : {selectedFormulaEntry.target})</span>
                                        )}
                                    </span>
                                </div>
                            ) : selectedFormulaEntry.target && (
                                <div className="flex flex-col">
                                    <span className="text-[8px] font-bold text-indigo-400 uppercase tracking-tighter">Cible Héritée</span>
                                    <span className="text-[10px] font-bold text-indigo-700 bg-indigo-50 px-1.5 py-0.5 rounded border border-indigo-200/30">{selectedFormulaEntry.target}</span>
                                </div>
                            )}
                            {selectedFormulaEntry.operator && selectedFormulaEntry.effectType !== 'block_skill_increase' && selectedFormulaEntry.effectType !== 'master_skill' && (
                                <div className="flex flex-col">
                                    <span className="text-[8px] font-bold text-indigo-400 uppercase tracking-tighter">Opérateur Hérité</span>
                                    <span className="text-[10px] font-bold text-indigo-700 bg-indigo-50 px-1.5 py-0.5 rounded border border-indigo-200/30">
                                        {selectedFormulaEntry.operator === 'ADD' ? 'Ajoûter (+)' :
                                            selectedFormulaEntry.operator === 'SET' ? 'Remplacer (=)' :
                                                selectedFormulaEntry.operator === 'SUB' ? 'Soustraire (-)' : 'Standard'}
                                    </span>
                                </div>
                            )}
                            <div className="ml-auto text-[8px] font-black text-indigo-300/50 uppercase tracking-widest">Fixé MJ</div>
                        </div>
                    )}

                    <div className="grid grid-cols-2 gap-3">
                        {!selectedFormulaEntry?.target && (
                            <div>
                                <label className="block text-[9px] font-bold text-amber-800 mb-1 uppercase tracking-widest flex items-center gap-1">
                                    Cible <span className="text-amber-600/50 font-normal lowercase italic">(à définir)</span>
                                </label>
                                <div className="relative">
                                    <select
                                        className="w-full text-xs border border-amber-400/30 rounded-sm px-2 py-1.5 appearance-none focus:border-amber-500 outline-none bg-amber-50/20 font-bold text-stone-800 shadow-sm"
                                        value={effect.target || ''}
                                        onChange={(e) => onUpdate(effect.id, 'target', e.target.value)}
                                    >
                                        <option value="" className="italic text-stone-500">-- Choisir --</option>
                                        <option value="XP">Points d'Expérience</option>
                                        <optgroup label="Attributs">
                                            {allAttributes.map(a => <option key={a.id} value={a.name}>{a.name}</option>)}
                                        </optgroup>
                                        <optgroup label="Compteurs / Réserves">
                                            {allCounters.map(c => <option key={c.id} value={c.name}>{c.name}</option>)}
                                        </optgroup>
                                    </select>
                                    <ChevronDown size={12} className="absolute right-2 top-1/2 -translate-y-1/2 pointer-events-none text-amber-800/40" />
                                </div>
                            </div>
                        )}

                        {!selectedFormulaEntry?.operator &&
                            selectedFormulaEntry?.effectType !== 'block_skill_increase' &&
                            selectedFormulaEntry?.effectType !== 'master_skill' && (
                                <div>
                                    <label className="block text-[9px] font-bold text-amber-800 mb-1 uppercase tracking-widest flex items-center gap-1">
                                        Opération <span className="text-amber-600/50 font-normal lowercase italic">(à définir)</span>
                                    </label>
                                    <div className="relative">
                                        <select
                                            className="w-full text-xs border border-amber-400/30 rounded-sm px-2 py-1.5 appearance-none focus:border-amber-500 outline-none bg-amber-50/20 font-bold text-stone-800 shadow-sm"
                                            value={effect.operator || 'ADD'}
                                            onChange={(e) => onUpdate(effect.id, 'operator', e.target.value as any)}
                                        >
                                            <option value="ADD">Ajoûter (+)</option>
                                            <option value="SET">Remplacer (=)</option>
                                            <option value="SUB">Soustraire (-)</option>
                                        </select>
                                        <ChevronDown size={12} className="absolute right-2 top-1/2 -translate-y-1/2 pointer-events-none text-amber-800/40" />
                                    </div>
                                </div>
                            )}
                    </div>

                    {selectedFormulaEntry?.formula && selectedFormulaEntry?.effectType !== 'block_skill_increase' && selectedFormulaEntry?.effectType !== 'master_skill' ? (
                        <div className="p-2 bg-stone-100 rounded border border-stone-200">
                            <span className="text-[8px] font-bold text-stone-400 uppercase tracking-tighter block mb-1">Moteur Mathématique Hérité</span>
                            <code className="text-[10px] font-mono font-bold text-stone-600">{selectedFormulaEntry.formula}</code>
                        </div>
                    ) : selectedFormulaEntry?.effectType === 'block_skill_increase' || selectedFormulaEntry?.effectType === 'master_skill' ? (
                        <div className="p-2 bg-indigo-50/50 rounded border border-indigo-200/30 flex items-center gap-2">
                            <CheckCircle2 size={14} className="text-indigo-600" />
                            <span className="text-[9px] font-bold text-indigo-800 uppercase italic">
                                {selectedFormulaEntry.effectType === 'block_skill_increase' ? 'Logique de Blocage Active' : 'Logique de Maîtrise Active'}
                            </span>
                        </div>
                    ) : (selectedFormulaEntry?.effectType !== 'block_skill_increase' && selectedFormulaEntry?.effectType !== 'master_skill') ? (
                        <div className="flex flex-col p-2 bg-amber-50/50 rounded border border-amber-200/50 border-dashed">
                            <label className="block text-[9px] font-bold text-amber-800 mb-1 uppercase tracking-widest">Valeur Fixe pour l'Effet</label>
                            <div className="flex items-center gap-2">
                                <Calculator size={14} className="text-amber-600/50" />
                                <input
                                    type="text"
                                    className="flex-grow text-xs border border-amber-400/30 rounded-sm px-2 py-1 focus:border-amber-500 outline-none bg-white font-mono font-bold text-amber-900"
                                    value={effect.formula || ''}
                                    onChange={(e) => onUpdate(effect.id, 'formula', e.target.value)}
                                    placeholder="ex: 10"
                                />
                                <div className="flex gap-1">
                                    <button
                                        type="button"
                                        onClick={() => onUpdate(effect.id, 'formula', (parseInt(effect.formula || '0') - 1).toString())}
                                        className="w-6 h-6 flex items-center justify-center bg-white border border-stone-200 rounded hover:bg-stone-50 text-stone-600"
                                    >-</button>
                                    <button
                                        type="button"
                                        onClick={() => onUpdate(effect.id, 'formula', (parseInt(effect.formula || '0') + 1).toString())}
                                        className="w-6 h-6 flex items-center justify-center bg-white border border-stone-200 rounded hover:bg-stone-50 text-stone-600"
                                    >+</button>
                                </div>
                            </div>
                            <p className="text-[8px] text-amber-700/60 mt-1 italic">Saisissez un nombre ou une petite équation locale.</p>
                        </div>
                    ) : null}
                </div>
            )}
        </div>
    );
};

import React from 'react';
import { ChevronDown, GraduationCap, Trophy } from 'lucide-react';
import { TraitEffect } from '../../../types';

interface LegacyEffectFieldsProps {
    effect: TraitEffect;
    allSkills: { id: string, name: string }[];
    allAttributes: { id: string, name: string }[];
    onUpdate: (id: string, field: keyof TraitEffect, value: any) => void;
}

export const LegacyEffectFields: React.FC<LegacyEffectFieldsProps> = ({
    effect,
    allSkills,
    allAttributes,
    onUpdate
}) => {
    if (effect.type === 'free_skill_rank') {
        return (
            <div className="grid grid-cols-3 gap-3">
                <div className="col-span-2">
                    <label className="block text-[9px] font-bold text-[#bfae85] mb-1 uppercase tracking-widest">Compétence</label>
                    <div className="relative">
                        <select
                            className="w-full text-xs border border-[#bfae85]/30 rounded-sm px-2 py-1.5 appearance-none focus:border-blue-500 outline-none bg-white/80 text-[#1c1917] font-bold shadow-sm"
                            value={effect.target || ''}
                            onChange={(e) => onUpdate(effect.id, 'target', e.target.value)}
                        >
                            <option value="" className="text-stone-300">-- Choisir --</option>
                            {allSkills.map((s, si) => (
                                <option key={s.id || `skill-${si}`} value={s.name}>{s.name}</option>
                            ))}
                        </select>
                        <ChevronDown size={12} className="absolute right-2 top-1/2 -translate-y-1/2 pointer-events-none text-blue-800/40" />
                    </div>
                </div>
                <div>
                    <label className="block text-[9px] font-bold text-[#bfae85] mb-1 uppercase tracking-widest text-center">Rang Offert</label>
                    <input
                        type="number"
                        className="w-full text-xs border border-[#bfae85]/30 rounded-sm px-2 py-1.5 text-center focus:border-blue-500 outline-none bg-white/80 text-[#1c1917] font-bold shadow-sm font-mono"
                        value={effect.value}
                        onChange={(e) => onUpdate(effect.id, 'value', parseInt(e.target.value) || 0)}
                    />
                </div>
            </div>
        );
    }

    if (effect.type === 'block_skill_increase') {
        return (
            <div className="flex flex-col gap-2">
                <div className="flex flex-col">
                    <label className="block text-[9px] font-bold text-[#bfae85] mb-1 uppercase tracking-widest">Compétence à bloquer</label>
                    <div className="relative">
                        <select
                            className="w-full text-xs border border-[#bfae85]/30 rounded-sm px-2 py-1.5 appearance-none focus:border-red-500 outline-none bg-white/80 text-[#1c1917] font-bold shadow-sm"
                            value={effect.target || ''}
                            onChange={(e) => onUpdate(effect.id, 'target', e.target.value)}
                        >
                            <option value="" className="text-stone-300">-- Choisir --</option>
                            {allSkills.map((s, si) => (
                                <option key={s.id || `skill-${si}`} value={s.name}>{s.name}</option>
                            ))}
                        </select>
                        <ChevronDown size={12} className="absolute right-2 top-1/2 -translate-y-1/2 pointer-events-none text-red-800/40" />
                    </div>
                    <p className="text-[9px] text-[#8b2e2e]/60 mt-1 italic leading-tight">
                        Cette compétence ne pourra plus être augmentée par le joueur. Les points futurs seront masqués et le nom barré.
                    </p>
                </div>
            </div>
        );
    }


    if (effect.type === 'master_skill') {
        return (
            <div className="flex flex-col gap-2">
                <div className="flex items-start gap-2">
                    <Trophy size={14} className="text-purple-600 mt-0.5 shrink-0" />
                    <p className="text-[10px] text-purple-800 leading-tight">
                        Quand le joueur ajoute ce trait, il choisit une <strong>compétence à rang 0</strong>.<br />
                        Celle-ci est automatiquement mise au <strong>rang 5</strong>, gratuitement (sans coût XP).<br />
                        La compétence revient à 0 si le trait est supprimé.
                    </p>
                </div>
            </div>
        );
    }

    // Default: Attribute bonus
    return (
        <div className="grid grid-cols-3 gap-3">
            <div className="col-span-2">
                <label className="block text-[9px] font-bold text-[#bfae85] mb-1 uppercase tracking-widest">Attribut</label>
                <div className="relative">
                    <select
                        className="w-full text-xs border border-[#bfae85]/30 rounded-sm px-2 py-1.5 appearance-none focus:border-[#8b2e2e] outline-none bg-white/80 text-[#1c1917] font-bold shadow-sm"
                        value={effect.target || ''}
                        onChange={(e) => onUpdate(effect.id, 'target', e.target.value)}
                    >
                        <option value="" className="text-stone-300">-- Choisir --</option>
                        {allAttributes.map((a, ai) => (
                            <option key={a.id || `attr-${ai}`} value={a.name}>{a.name}</option>
                        ))}
                    </select>
                    <ChevronDown size={12} className="absolute right-2 top-1/2 -translate-y-1/2 pointer-events-none text-[#8b2e2e]/40" />
                </div>
            </div>
            <div>
                <label className="block text-[9px] font-bold text-[#bfae85] mb-1 uppercase tracking-widest text-center">Bonus (+)</label>
                <input
                    type="number"
                    className="w-full text-xs border border-[#bfae85]/30 rounded-sm px-2 py-1.5 text-center focus:border-[#8b2e2e] outline-none bg-white/80 text-[#1c1917] font-bold shadow-sm font-mono"
                    value={effect.value}
                    onChange={(e) => onUpdate(effect.id, 'value', parseInt(e.target.value) || 0)}
                />
            </div>
        </div>
    );
};

import React from 'react';
import { Zap, X, Star, GraduationCap, ChevronDown, Trophy, Calculator } from 'lucide-react';
import { TraitEffect, LibraryFormulaEntry } from '../../../types';
import { FormulaEffectFields } from './FormulaEffectFields';
import { LegacyEffectFields } from './LegacyEffectFields';

interface TraitEffectItemProps {
    effect: TraitEffect;
    index: number;
    allSkills: { id: string, name: string }[];
    allAttributes: { id: string, name: string }[];
    allCounters: { id: string, name: string }[];
    allFormulas: LibraryFormulaEntry[];
    onUpdate: <K extends keyof TraitEffect>(id: string, field: K, value: TraitEffect[K]) => void;
    onUpdateFields?: (id: string, updates: Partial<TraitEffect>) => void;
    onRemove: (id: string) => void;
}

export const TraitEffectItem: React.FC<TraitEffectItemProps> = ({
    effect,
    index,
    allSkills,
    allAttributes,
    allCounters,
    allFormulas,
    onUpdate,
    onUpdateFields,
    onRemove
}) => {
    // Configuration visuelle par type
    let typeIcon = <Star size={16} />;
    let themeColor = 'text-amber-700';
    let borderColor = 'border-amber-200';
    let bgColor = 'bg-white';

    if (effect.type === 'formula') {
        typeIcon = <Calculator size={14} />;
        themeColor = 'text-indigo-800';
        borderColor = 'border-indigo-400/30';
        bgColor = 'bg-indigo-50/40';
    } else if (effect.type === 'free_skill_rank') {
        typeIcon = <GraduationCap size={14} />;
        themeColor = 'text-blue-800';
        borderColor = 'border-blue-400/30';
        bgColor = 'bg-blue-50/40';
    } else if (effect.type === 'master_skill') {
        typeIcon = <Trophy size={14} />;
        themeColor = 'text-purple-800';
        borderColor = 'border-purple-400/30';
        bgColor = 'bg-purple-50/40';
    }

    return (
        <div className={`rounded-lg border ${borderColor} ${bgColor} shadow-sm overflow-hidden group`}>
            {/* Header Row: Type Selector & Delete */}
            <div className="flex items-center justify-between p-2 border-b border-black/5 bg-white/60">
                <div className="flex items-center gap-2 flex-grow relative">
                    <div className={themeColor}>{typeIcon}</div>

                    <div className="relative flex-grow">
                        <select
                            className={`appearance-none bg-white border border-gray-300 font-bold text-xs text-gray-900 w-full focus:outline-none focus:ring-1 focus:ring-blue-300 cursor-pointer pr-4 py-1 pl-2 rounded shadow-sm`}
                            value={effect.type}
                            onChange={(e) => onUpdate(effect.id, 'type', e.target.value as any)}
                        >
                            <option value="formula" className="text-gray-900 bg-white font-bold bg-indigo-50">Calcul par Formule</option>

                            {['free_skill_rank', 'master_skill', 'block_skill_increase'].includes(effect.type) && (
                                <optgroup label="Anciens Types (Hérités)">
                                    {effect.type === 'free_skill_rank' && <option value="free_skill_rank">Rang de Compétence Offert</option>}
                                    {effect.type === 'master_skill' && <option value="master_skill">Maîtrise (Rang 5 direct)</option>}
                                    {effect.type === 'block_skill_increase' && <option value="block_skill_increase">Bloquer une Progression</option>}
                                </optgroup>
                            )}
                        </select>
                        <ChevronDown size={12} className={`absolute right-2 top-1/2 -translate-y-1/2 pointer-events-none ${themeColor} opacity-50`} />
                    </div>
                </div>
                <button
                    onClick={() => onRemove(effect.id)}
                    className="text-gray-400 hover:text-red-500 hover:bg-red-50 p-1 rounded transition-colors ml-2"
                >
                    <X size={14} />
                </button>
            </div>

            {/* Content Row: Specific Inputs */}
            <div className="p-3">
                {effect.type === 'formula' ? (
                    <FormulaEffectFields
                        effect={effect}
                        allFormulas={allFormulas}
                        allAttributes={allAttributes}
                        allCounters={allCounters}
                        onUpdate={onUpdate}
                        onUpdateFields={onUpdateFields}
                    />
                ) : (
                    <LegacyEffectFields
                        effect={effect}
                        allSkills={allSkills}
                        allAttributes={allAttributes}
                        onUpdate={onUpdate}
                    />
                )}
            </div>
        </div>
    );
};

