describe('RulesReconciler', () => {
    it('should match skill IDs with counter IDs for behavior: Compteur', () => {
        const rules: RulesData = {
            definitions: {
                skillCategories: [
                    { id: 'cat_counter', label: 'Compteurs', behavior: 'Compteur', costConfig: { factor: 1, type: 'linear' } }
                ],
                skills: {
                    'cat_counter': ['Volonté']
                },
